INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2f617b01-e8af-4377-9f40-f5c505fe1a2e','Ambisonics','Ambisonics is a full-sphere surround technique that represents a sound field by its spherical-harmonic components rather than by feeds to specific loudspeakers. A scene is encoded once and then decoded to any compatible loudspeaker layout or to headphones, with spatial resolution set by the Ambisonic order.','Ambisonics records or builds sound coming from every direction. It stores the whole scene, not one speaker feed. You can then play it on any speaker setup or headphones. The same file adapts to each layout.','It provides a speaker-independent way to capture, manipulate, and reproduce a three-dimensional sound field.','A technician records with a first-order tetrahedral microphone, edits the four B-format channels, then decodes to a 5.1 rig or to binaural for headphones.','Spatial audio',ARRAY['Ambisonic order','Ambisonic normalization','Binaural synthesis','BRIR','Acoustic contrast control']::text[],ARRAY['Thinking each Ambisonic channel is one loudspeaker feed rather than a spherical-harmonic component.','Expecting perfect localization far from the central sweet spot.','Ignoring that a decoder must be matched to the actual loudspeaker geometry.']::text[],ARRAY['Producing 360-degree audio for a VR or 360 video.','Capturing an immersive ambience with a tetrahedral microphone.','Delivering one master that decodes to many playback layouts.']::text[],'beginner',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ambisonics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2f617b01-e8af-4377-9f40-f5c505fe1a2e','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2f617b01-e8af-4377-9f40-f5c505fe1a2e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2f617b01-e8af-4377-9f40-f5c505fe1a2e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd665eab6-7c8c-4505-baee-10592ab65ac0','Array gain','Array gain is the improvement in signal-to-noise ratio obtained by an array of sensors over a single element, achieved by combining elements so the coherent signal adds while incoherent noise partially cancels. For N elements with a plane-wave signal and spatially isotropic, uncorrelated noise, the ideal array gain is 10*log10(N) dB.','Combining many hydrophones beats using just one. The wanted signal lines up and adds. The random noise does not line up and partly cancels. So the array hears a target more clearly.','It quantifies how much a receiving array raises detectability, entering the sonar equation as the term that offsets noise.','For 100 elements with ideal isotropic noise, array gain = 10*log10(100) = 20 dB of SNR improvement.','Sonar',ARRAY['Beamformed sonar','Active sonar','Ambient-noise level','Acoustic contrast control']::text[],ARRAY['Assuming the ideal 10*log10(N) always holds, ignoring correlated noise that lowers real gain.','Confusing array gain (an SNR improvement) with directivity index for every noise field.','Forgetting that closely spaced elements can have correlated noise and reduced gain.']::text[],ARRAY['Sizing a towed hydrophone array for a required detection range.','Explaining why doubling elements adds only 3 dB under ideal noise.','Comparing measured gain against theory in a real ambient-noise field.']::text[],'advanced','AG = 10*log10( (S/N)_array / (S/N)_element );  AG_ideal = 10*log10(N)','Array gain is ten times the base-ten log of the array''s signal-to-noise ratio divided by a single element''s; for N elements in isotropic noise it equals ten log N.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Array gain');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd665eab6-7c8c-4505-baee-10592ab65ac0','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d665eab6-7c8c-4505-baee-10592ab65ac0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d665eab6-7c8c-4505-baee-10592ab65ac0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '30a90f0c-bd5b-4140-a38c-6d6e00746121','Auditory compression','Auditory compression is the nonlinear reduction of dynamic range in normal hearing, whereby a large range of input sound levels is mapped to a smaller range of internal response. It arises mainly from the active mechanics of the cochlea and lets the ear handle a range of about 120 dB.','The ear squeezes a huge range of loudness into a smaller inner response. Quiet sounds get boosted more than loud ones. This lets us hear a whisper and a shout with the same ears. The cochlea does most of this work.','It extends the ear''s usable dynamic range and helps keep soft sounds audible without loud sounds overwhelming the system.','An engineer notes that a 40 dB rise at the eardrum may map to a much smaller growth of basilar-membrane vibration, reflecting compressive gain.','Psychoacoustics',ARRAY['Cochlear compression','Auditory filter','Auditory excitation pattern','Binaural loudness']::text[],ARRAY['Confusing this natural hearing compression with an audio dynamic-range compressor plug-in.','Assuming compression is the same at all levels; it is strongest at moderate levels near the characteristic place.','Thinking loudness grows in direct proportion to sound pressure rather than compressively.']::text[],ARRAY['Explaining why loudness does not double when level doubles.','Understanding recruitment in hearing loss, where compression is lost.','Discussing why hearing aids apply frequency-dependent compression.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory compression');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '30a90f0c-bd5b-4140-a38c-6d6e00746121','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='30a90f0c-bd5b-4140-a38c-6d6e00746121') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='30a90f0c-bd5b-4140-a38c-6d6e00746121');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '348d56e3-e8b4-4d33-af76-f9f3669f9694','Auditory excitation pattern','An auditory excitation pattern is the internal representation of a sound''s spectrum as the output level of the auditory filters plotted against their center frequency (or critical-band rate). It is computed by passing the stimulus spectrum through the bank of overlapping auditory filters and is a key stage in models of loudness and masking.','This shows how a sound spreads across the ear''s frequency channels. Each channel reports how much energy it catches. Plotting these outputs gives the pattern. Loudness and masking models start from it.','It converts a physical spectrum into a perceptual one, forming the basis for predicting loudness and how one sound masks another.','A codec designer derives an excitation pattern to place quantization noise below the masking threshold it predicts.','Psychoacoustics',ARRAY['Auditory filter','Critical-band rate','Auditory compression','Binaural loudness']::text[],ARRAY['Reading the excitation pattern as the raw sound spectrum rather than the filtered internal one.','Ignoring the asymmetric, level-dependent spread of excitation toward higher frequencies.','Assuming a sharp cutoff instead of the smooth overlap of auditory filters.']::text[],ARRAY['Building a perceptual loudness model.','Predicting masking for a lossy audio codec.','Explaining upward spread of masking from a strong low tone.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory excitation pattern');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '348d56e3-e8b4-4d33-af76-f9f3669f9694','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='348d56e3-e8b4-4d33-af76-f9f3669f9694') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='348d56e3-e8b4-4d33-af76-f9f3669f9694');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3f677fc1-9d42-4e22-95d5-4aefd1e85290','Auditory filter','An auditory filter is a band-pass frequency channel in the auditory system, corresponding to a place on the basilar membrane, that passes a limited band of frequencies. Its bandwidth is commonly described by the equivalent rectangular bandwidth (ERB), which increases with center frequency.','The ear acts like a bank of overlapping band filters. Each one responds to a narrow range of pitches. A place on the inner ear maps to each filter. Higher filters are wider than lower ones.','It gives the ear its frequency selectivity, letting listeners separate and resolve components of complex sounds.','Using the Glasberg-Moore formula, the ERB at 1 kHz is 24.7*(4.37*1 + 1) = 132.6 Hz.','Psychoacoustics',ARRAY['Critical-band rate','Auditory excitation pattern','Auditory compression','Cochlear compression']::text[],ARRAY['Treating the filter as perfectly rectangular rather than rounded and overlapping.','Assuming a fixed bandwidth in Hz across frequency instead of one that grows with center frequency.','Using the older critical-band (Bark) width and the ERB width interchangeably without noting they differ.']::text[],ARRAY['Explaining frequency masking in a mix.','Modeling the front end of a hearing or loudness model.','Choosing analysis bandwidths that match hearing.']::text[],'intermediate','ERB(f) = 24.7*(4.37*f_kHz + 1)','The equivalent rectangular bandwidth in hertz equals 24.7 times the quantity 4.37 times the center frequency in kilohertz plus one.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory filter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3f677fc1-9d42-4e22-95d5-4aefd1e85290','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3f677fc1-9d42-4e22-95d5-4aefd1e85290') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3f677fc1-9d42-4e22-95d5-4aefd1e85290');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cdf04709-d447-4389-89ea-c38e7138ace2','Auditory object','An auditory object is the perceptual entity formed when the auditory system groups acoustic components that belong to a single physical source, so a listener hears one coherent sound rather than separate frequency parts. It is the product of auditory scene analysis, which uses cues such as common onset, harmonicity, and common fate to bind components.','The ear glues sound parts into one thing you can attend to. A single voice becomes one object, not many tones. The brain decides which parts belong together. This lets you follow one talker in a crowd.','It lets listeners parse a mixture into meaningful sources, supporting attention, recognition, and following one stream among many.','A mix engineer uses shared reverb and matched timing so layered parts fuse into one intended auditory object.','Psychoacoustics',ARRAY['Common-fate grouping','Auditory excitation pattern','Auditory filter','Binaural loudness']::text[],ARRAY['Equating an auditory object with a single frequency rather than a grouped set of components.','Assuming grouping is fixed, when attention and context can change what fuses.','Ignoring that mismatched cues can split one source into two perceived objects.']::text[],ARRAY['Explaining the cocktail-party ability to follow one talker.','Designing layers that either fuse or stay distinct in a mix.','Analyzing why a detuned partial pops out of a chord.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory object');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cdf04709-d447-4389-89ea-c38e7138ace2','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cdf04709-d447-4389-89ea-c38e7138ace2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cdf04709-d447-4389-89ea-c38e7138ace2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '23bff776-63b2-4e39-9e8f-cdb326479313','Auditory parallax','Auditory parallax refers to the way the apparent direction of sound sources changes at different rates as a listener moves, with nearer sources shifting angle faster than distant ones. This motion-induced change in interaural and directional cues can provide information about the relative distance and layout of sources.','As you move your head or walk, sounds shift direction. Close sounds swing across faster than far ones. This difference hints at how near each source is. It is the sound version of visual parallax.','It offers a dynamic distance and depth cue that supplements static loudness and spectral cues in spatial hearing.','A VR audio engineer preserves head-motion parallax so a nearby virtual source swings past faster than a distant one.','Spatial hearing',ARRAY['Binaural synthesis','BRIR','Binaural loudness','Ambisonics']::text[],ARRAY['Assuming distance is judged only by loudness, ignoring motion-based cues.','Expecting parallax to work when the source and listener move together with no relative change.','Confusing this dynamic cue with the static interaural differences of a fixed head.']::text[],ARRAY['Adding head-tracking so movement gives realistic depth in VR audio.','Explaining why walking helps resolve source distance.','Designing dynamic binaural rendering that updates with listener position.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory parallax');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '23bff776-63b2-4e39-9e8f-cdb326479313','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='23bff776-63b2-4e39-9e8f-cdb326479313') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='23bff776-63b2-4e39-9e8f-cdb326479313');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '09d58b29-bf93-4bb2-afe2-037c271d5e9c','Axial resolution','Axial resolution is the smallest separation between two reflectors along the beam (depth) direction that a pulse-echo system can display as distinct. It is set by the spatial pulse length and equals half of it, because two echoes must not overlap on the round trip.','This is how close two targets can be, front to back, and still look separate. It depends on how short the pulse is. A shorter pulse gives finer detail. It equals half the length of the pulse in space.','It defines depth-direction detail in ultrasound imaging and pulse-echo testing, driving the choice of frequency and pulse length.','At 5 MHz in tissue (c = 1540 m/s), lambda = 0.308 mm; a 2-cycle pulse gives spatial pulse length 0.616 mm and axial resolution 0.308 mm.','Ultrasound imaging',ARRAY['Acoustic matching layer','Backing layer','Continuous-wave Doppler','Acoustic radiation-force impulse']::text[],ARRAY['Confusing axial resolution (along the beam) with lateral resolution (across the beam).','Forgetting that a shorter pulse improves resolution but reduces penetration.','Setting axial resolution equal to the full spatial pulse length instead of half of it.']::text[],ARRAY['Choosing a higher frequency to resolve closely spaced tissue layers.','Explaining why heavy damping (short pulse) sharpens axial detail.','Comparing near-field resolution of two ultrasound probes.']::text[],'intermediate','AR = SPL/2 = (n*lambda)/2','Axial resolution equals half the spatial pulse length, which is half the number of cycles times the wavelength.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Axial resolution');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '09d58b29-bf93-4bb2-afe2-037c271d5e9c','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='09d58b29-bf93-4bb2-afe2-037c271d5e9c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='09d58b29-bf93-4bb2-afe2-037c271d5e9c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a2f3120d-78eb-4c9f-b77b-04613601d05c','BRIR','A binaural room impulse response (BRIR) is the pair of impulse responses measured from a source position to a listener''s two ears (or a dummy head) in a specific room, capturing both the head-related filtering and the room''s reflections and reverberation. Convolving anechoic audio with a BRIR reproduces how that source would sound at that seat over headphones.','A BRIR captures how a room and your two ears change a sound. It is measured at the left and right ears in that room. Playing dry audio through it recreates that seat on headphones. You hear the source with its real echoes.','It lets a technician recreate a specific room and seat over headphones, including externalization and realistic reverberation.','An engineer convolves a dry vocal with a hall BRIR so headphone listeners hear the singer positioned in that hall.','Spatial audio',ARRAY['Binaural synthesis','Binaural loudness','Ambisonics','Auditory parallax']::text[],ARRAY['Confusing a BRIR (includes the room) with a free-field HRTF (no room).','Reusing one BRIR for all head orientations, which breaks without head tracking.','Ignoring that a non-individual BRIR can cause front-back confusions.']::text[],ARRAY['Building a virtual monitoring room for headphone mixing.','Auralizing a concert-hall seat for a listening test.','Creating head-tracked binaural playback for VR.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='BRIR');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a2f3120d-78eb-4c9f-b77b-04613601d05c','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a2f3120d-78eb-4c9f-b77b-04613601d05c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a2f3120d-78eb-4c9f-b77b-04613601d05c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6b17a1b4-b91b-4012-b368-5129f28ae3e3','Backing layer','A backing layer (backing block) is the damping material bonded to the rear face of a piezoelectric transducer element to absorb energy radiated backward and to shorten the ringing of the element. Its acoustic impedance and attenuation set the trade-off between pulse length (bandwidth) and sensitivity.','This block sits behind the crystal in a probe. It soaks up sound going the wrong way. It also stops the crystal from ringing too long. That gives a short pulse and sharper images.','It damps the element to produce short, broadband pulses, improving axial resolution at some cost in efficiency.','A technician selects a heavily attenuating, impedance-matched backing to shorten the pulse when fine axial detail matters more than penetration.','Ultrasonic transducer',ARRAY['Acoustic matching layer','Axial resolution','CMUT']::text[],ARRAY['Confusing the rear backing layer with the front matching layer.','Assuming heavy backing is always best; it lowers sensitivity and output.','Ignoring that backing impedance, not just attenuation, controls the damping.']::text[],ARRAY['Designing a broadband imaging probe.','Trading penetration for axial resolution in transducer selection.','Diagnosing a long ring-down traced to a poor backing.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Backing layer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6b17a1b4-b91b-4012-b368-5129f28ae3e3','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6b17a1b4-b91b-4012-b368-5129f28ae3e3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6b17a1b4-b91b-4012-b368-5129f28ae3e3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2b0f119f-7dae-4475-aed0-0972d9db5f16','Beamformed sonar','Beamformed sonar is a sonar in which signals from an array of hydrophones are combined with element-specific delays (or phase shifts) so the array is steered to listen or transmit in a chosen direction while suppressing other directions. Beamforming provides the array gain and angular resolution used in both active and passive sonar.','Many hydrophones work as a team by adding delays. This points the array''s sensitivity in one direction. Sound from that way adds up strongly. Sound from other ways is rejected.','It gives directional listening and transmission, raising signal-to-noise ratio and letting a sonar estimate a target''s bearing.','A technician applies delay-and-sum weights to a hydrophone line, steering the main beam across bearing to find the angle of peak return.','Sonar',ARRAY['Array gain','Active sonar','Ambient-noise level','Convergence zone']::text[],ARRAY['Assuming a narrow beam at all frequencies; beam width widens as frequency drops for a fixed array length.','Ignoring grating lobes when element spacing exceeds half a wavelength.','Confusing beamforming (spatial filtering) with simple gain or equalization.']::text[],ARRAY['Steering a towed array to bearings without moving the ship.','Forming multiple simultaneous beams for a multibeam echosounder.','Rejecting a strong interferer off the main axis.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Beamformed sonar');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2b0f119f-7dae-4475-aed0-0972d9db5f16','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2b0f119f-7dae-4475-aed0-0972d9db5f16') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2b0f119f-7dae-4475-aed0-0972d9db5f16');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '23314890-e0f0-4d81-8fbe-41364f4eaf45','Binaural loudness','Binaural loudness is the loudness of a sound heard with both ears, which for a diotic (identical at both ears) signal is greater than the same sound heard with one ear. This binaural summation typically makes a diotic sound louder than a monaural one by an amount often cited near a factor approaching two, though less than a full doubling.','A sound heard with both ears seems louder than with one ear. The brain adds the two ears'' inputs. This is called binaural summation. It is why blocking one ear makes things quieter.','It explains how the two ears combine level information, which matters for loudness models and for calibrating headphone and hearing systems.','An engineer accounts for binaural summation when a diotic headphone signal is judged louder than the same signal in one earpiece.','Psychoacoustics',ARRAY['Auditory compression','Binaural synthesis','BRIR','Auditory excitation pattern']::text[],ARRAY['Assuming two ears make a sound exactly twice as loud; summation is less than a full doubling.','Ignoring that summation depends on whether the ear signals are identical or different.','Confusing binaural loudness (perceived) with a simple 6 dB level sum.']::text[],ARRAY['Calibrating headphone levels for both-ear listening.','Modeling loudness for a binaural render.','Explaining why one blocked ear lowers perceived loudness.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Binaural loudness');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '23314890-e0f0-4d81-8fbe-41364f4eaf45','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='23314890-e0f0-4d81-8fbe-41364f4eaf45') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='23314890-e0f0-4d81-8fbe-41364f4eaf45');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'db4ce3d5-038d-4290-9abe-c0ea121a320a','Binaural synthesis','Binaural synthesis is the rendering of virtual sources for headphone playback by filtering source signals with head-related transfer functions (HRTFs) for the desired directions, adding interaural time and level differences and spectral cues. Combined with head tracking and room responses, it can place sound anywhere around and externalize it outside the head.','This builds 3D sound for headphones. It filters audio with data about how ears hear each direction. That adds the timing and tone cues of real listening. The sound then seems to come from around you.','It reproduces spatial hearing over two headphone channels, enabling immersive audio for VR, gaming, and virtual monitoring.','An engineer convolves a mono source with left/right HRTFs for 30 degrees azimuth so it appears to the listener''s right.','Spatial audio',ARRAY['BRIR','Binaural loudness','Ambisonics','Auditory parallax']::text[],ARRAY['Expecting good externalization with generic HRTFs and no room reflections.','Omitting head tracking, which causes front-back confusions and in-head localization.','Confusing binaural synthesis (headphones, two ears) with multichannel loudspeaker panning.']::text[],ARRAY['Placing game sound sources around a headphone user.','Rendering an Ambisonic scene to binaural for VR.','Building a virtual surround mix room over headphones.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Binaural synthesis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'db4ce3d5-038d-4290-9abe-c0ea121a320a','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='db4ce3d5-038d-4290-9abe-c0ea121a320a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='db4ce3d5-038d-4290-9abe-c0ea121a320a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '81950f1a-b411-418b-ac92-8f674c54b4e4','Bottom bounce','Bottom bounce is an underwater propagation path in which sound reaches a distant receiver after reflecting off the sea floor, often together with surface reflections. It can extend detection beyond the direct path but incurs reflection loss that depends strongly on bottom composition and grazing angle.','Sound can travel by bouncing off the sea floor. This path reaches places the direct sound misses. But the bottom absorbs some energy on each bounce. Hard bottoms reflect better than soft, muddy ones.','It provides a propagation route that can reach targets in the shadow of the direct path, used deliberately in some sonar tactics.','A technician predicts detection over a hard, rocky bottom knowing reflection loss is lower than over soft sediment.','Underwater propagation',ARRAY['Convergence zone','Active sonar','Beamformed sonar','Ambient-noise level']::text[],ARRAY['Assuming the bottom reflects sound perfectly regardless of its material.','Ignoring that reflection loss changes strongly with grazing angle.','Confusing bottom bounce with the convergence zone (a refracted, not reflected, path).']::text[],ARRAY['Predicting detection where the direct path is blocked.','Choosing sonar geometry over a hard versus soft seabed.','Interpreting a delayed, weaker return as a bottom path.']::text[],'beginner',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bottom bounce');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '81950f1a-b411-418b-ac92-8f674c54b4e4','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='81950f1a-b411-418b-ac92-8f674c54b4e4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='81950f1a-b411-418b-ac92-8f674c54b4e4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bfa8adb5-3fa6-4144-ad78-13dd5941c54a','CMUT','A CMUT (capacitive micromachined ultrasonic transducer) is a micro-electro-mechanical ultrasonic transducer in which a thin membrane over a sealed cavity vibrates electrostatically to transmit and receive ultrasound. Fabricated with semiconductor processes, CMUTs offer wide bandwidth and easy array integration compared with bulk piezoelectric elements.','A CMUT is a tiny drum built on a chip. A voltage flexes its thin membrane to make ultrasound. The same membrane also senses returning sound. It is made like a computer chip, so many fit in an array.','It provides a broadband, mass-manufacturable ultrasonic transducer that integrates well with electronics for imaging and sensing.','A technician chooses a CMUT array probe for its wide bandwidth and on-chip integration in a portable ultrasound device.','Ultrasonic transducer',ARRAY['Capacitive micromachined ultrasonic transducer','Acoustic matching layer','Backing layer','Axial resolution']::text[],ARRAY['Thinking a CMUT is piezoelectric; it works by electrostatic (capacitive) force.','Forgetting that a DC bias voltage is needed for efficient operation.','Assuming CMUTs always outperform piezoelectrics; each has trade-offs in output and linearity.']::text[],ARRAY['Selecting a transducer for a compact, integrated ultrasound system.','Exploiting wide bandwidth for harmonic imaging.','Explaining why a bias supply is part of a CMUT front end.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='CMUT');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bfa8adb5-3fa6-4144-ad78-13dd5941c54a','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bfa8adb5-3fa6-4144-ad78-13dd5941c54a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bfa8adb5-3fa6-4144-ad78-13dd5941c54a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '431b2290-005b-48c1-86b5-23efaead3033','Capacitive micromachined ultrasonic transducer','A capacitive micromachined ultrasonic transducer is the full name of the CMUT, a micromachined device that generates and detects ultrasound through the electrostatic motion of a thin suspended membrane over a vacuum or gas cavity. It operates as a variable capacitor whose membrane deflects under an applied voltage and moves in response to incident pressure.','This is the full name for a CMUT. It is a chip-made ultrasound part with a thin flexing membrane. A voltage moves the membrane to send sound. Returning sound moves it back, which the circuit reads.','It is a semiconductor-fabricated alternative to piezoelectric transducers, valued for bandwidth and integration in ultrasound arrays.','A designer applies a DC bias plus a signal so the membrane radiates ultrasound, then reads capacitance changes as the echo.','Ultrasonic transducer',ARRAY['CMUT','Acoustic matching layer','Backing layer','Axial resolution']::text[],ARRAY['Assuming it uses a piezoelectric crystal rather than electrostatic membrane motion.','Overlooking the required DC bias for sensitive operation.','Treating CMUT and piezoelectric probes as interchangeable without weighing trade-offs.']::text[],ARRAY['Building an integrated array for a handheld scanner.','Comparing CMUT and PZT probes on bandwidth and output.','Explaining the electrostatic transduction to a trainee.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Capacitive micromachined ultrasonic transducer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '431b2290-005b-48c1-86b5-23efaead3033','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='431b2290-005b-48c1-86b5-23efaead3033') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='431b2290-005b-48c1-86b5-23efaead3033');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '327ffab5-5a9a-4fa3-8ecc-31d08b2463f1','Cavitation noise','Cavitation noise is the broadband acoustic emission produced when cavitation bubbles grow and collapse in a liquid under an intense sound field or rapid pressure drop. Its spectrum includes broadband components and, under stable (non-inertial) cavitation, harmonics and subharmonics of the drive frequency.','Strong sound or fast pressure drops can make bubbles form in water. When these bubbles collapse, they make a loud, hissy noise. This noise covers a wide range of pitches. It signals that cavitation is happening.','It is both a diagnostic sign that cavitation has begun and a source of noise that can limit sonar and damage propellers or equipment.','An engineer monitors a rising broadband hiss and subharmonic tones to confirm the cavitation threshold in a sonochemistry reactor.','Underwater noise',ARRAY['Ambient-noise level','Acoustic-emission sensor','Active sonar','Acoustic radiation-force impulse']::text[],ARRAY['Assuming cavitation noise is a pure tone rather than mostly broadband.','Overlooking subharmonics as a marker of stable cavitation.','UNSAFE: Treating intense cavitation as harmless; collapsing bubbles can erode surfaces and damage tissue or hardware.']::text[],ARRAY['Detecting the onset of propeller cavitation from radiated noise.','Confirming cavitation in an ultrasonic cleaning or sonochemistry bath.','Diagnosing pump damage from cavitation-related emissions.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cavitation noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '327ffab5-5a9a-4fa3-8ecc-31d08b2463f1','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='327ffab5-5a9a-4fa3-8ecc-31d08b2463f1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='327ffab5-5a9a-4fa3-8ecc-31d08b2463f1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f54dc47c-79ce-4b31-afc7-19432e5654b9','Cochlear compression','Cochlear compression is the level-dependent, nonlinear gain of the healthy cochlea, produced mainly by the electromotility of outer hair cells, that amplifies low-level sounds far more than high-level sounds. Near a place''s characteristic frequency the input-output function is strongly compressive, with a slope on the order of 0.2 dB per dB in the mid-level range.','The inner ear boosts soft sounds much more than loud ones. Outer hair cells act like tiny amplifiers. This shapes how loudness grows with level. Losing these cells removes the boost and raises the hearing threshold.','It gives the ear high sensitivity and sharp tuning at low levels while protecting against overload at high levels, underpinning normal loudness growth.','A clinician links loss of cochlear compression to loudness recruitment, where loudness grows abnormally fast above threshold.','Psychoacoustics',ARRAY['Auditory compression','Auditory filter','Auditory excitation pattern','Binaural loudness']::text[],ARRAY['Attributing cochlear amplification to inner hair cells rather than outer hair cells.','Assuming the input-output function is linear rather than compressive near characteristic frequency.','Confusing this biological compression with studio dynamic-range compression.']::text[],ARRAY['Explaining loudness recruitment in sensorineural hearing loss.','Understanding otoacoustic emissions as evidence of active mechanics.','Fitting hearing-aid compression to restore lost gain at low levels.']::text[],'advanced','slope = dL_out/dL_in ~ 0.2 (dB/dB) near CF, mid levels','Near the characteristic frequency and moderate levels, the output level rises about 0.2 dB for each 1 dB rise in input level.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cochlear compression');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f54dc47c-79ce-4b31-afc7-19432e5654b9','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f54dc47c-79ce-4b31-afc7-19432e5654b9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f54dc47c-79ce-4b31-afc7-19432e5654b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a9af0de5-3e24-4bce-8e75-17c4b12bc540','Common-fate grouping','Common-fate grouping is an auditory scene-analysis principle by which frequency components that change together over time (for example sharing the same onset, offset, or coordinated frequency and amplitude modulation) are grouped as coming from one source. It is a key cue the auditory system uses to bind partials into a single auditory object.','Sound parts that move together are heard as one thing. If tones start together or wobble together, the ear groups them. If one part behaves differently, it splits off. This helps separate voices and instruments.','It lets the auditory system decide which components belong to the same source, supporting source separation and object formation.','A synthesist applies shared vibrato so partials fuse into one voice, then detunes one partial to make it stand out.','Psychoacoustics',ARRAY['Auditory object','Auditory excitation pattern','Auditory filter','Binaural loudness']::text[],ARRAY['Thinking only pitch, not shared modulation and timing, controls grouping.','Assuming grouping is purely bottom-up, ignoring attention and expectation.','Confusing common fate (shared change) with mere frequency proximity.']::text[],ARRAY['Explaining why matched onsets make layers fuse in a mix.','Designing a partial that pops out via independent modulation.','Understanding source separation in a complex scene.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Common-fate grouping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a9af0de5-3e24-4bce-8e75-17c4b12bc540','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a9af0de5-3e24-4bce-8e75-17c4b12bc540') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a9af0de5-3e24-4bce-8e75-17c4b12bc540');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fa4604d2-242f-46de-a963-944c1b9e2a33','Continuous-wave Doppler','Continuous-wave (CW) Doppler is an ultrasound mode that transmits and receives sound continuously using separate transmit and receive elements, measuring the Doppler frequency shift caused by moving scatterers such as blood. Because it never stops transmitting, it can measure very high velocities without aliasing but cannot resolve the depth of the moving target (no range resolution).','This mode sends and listens to ultrasound at the same time. It reads the pitch change from moving blood. It can measure very fast flow without errors. But it cannot tell how deep the flow is.','It measures high blood-flow velocities accurately, as in stenotic jets, where pulsed Doppler would alias.','For f0 = 2 MHz, v = 1 m/s, angle = 0, c = 1540 m/s, the Doppler shift is f_d = 2*f0*v/c = 2*2e6*1/1540 = 2597 Hz.','Ultrasound imaging',ARRAY['Axial resolution','Acoustic radiation-force impulse','Backing layer','Acoustic matching layer']::text[],ARRAY['Expecting CW Doppler to show the depth of the moving target; it lacks range resolution.','Forgetting the angle term; a large beam-to-flow angle greatly underestimates velocity.','UNSAFE: Overlooking that continuous transmission raises time-averaged intensity, so thermal-index limits and exposure time must be respected.']::text[],ARRAY['Measuring a high-velocity jet across a stenotic heart valve.','Choosing CW over pulsed Doppler to avoid aliasing.','Estimating pressure gradients from peak velocity.']::text[],'intermediate','f_d = 2*f0*v*cos(theta)/c','The Doppler shift equals two times the transmit frequency times the target speed times the cosine of the beam-to-flow angle, divided by the sound speed.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Continuous-wave Doppler');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fa4604d2-242f-46de-a963-944c1b9e2a33','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fa4604d2-242f-46de-a963-944c1b9e2a33') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fa4604d2-242f-46de-a963-944c1b9e2a33');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '199130b1-19e4-435a-b1b0-f8bddb873cb9','Convergence zone','A convergence zone (CZ) is an annular region in the deep ocean where sound rays that refract downward through the deep sound channel and turn back toward the surface reconverge, producing a band of enhanced signal at long range. Successive zones recur at roughly regular ranges (order of tens of kilometers) under deep-water, downward-then-upward refracting conditions.','In deep water, sound bends down and then curves back up. It refocuses in rings far from the source. Inside these rings a target is much easier to hear. Between them lies a quieter shadow.','It enables long-range detection at focused ranges by exploiting deep-ocean refraction rather than direct or bottom paths.','A sonar operator expects strong returns near the convergence-zone ranges (recurring on the order of every 50 to 65 km in typical deep water) and weak returns between them.','Underwater propagation',ARRAY['Bottom bounce','Active sonar','Beamformed sonar','Ambient-noise level']::text[],ARRAY['Confusing the refracted convergence zone with a bottom-bounce (reflected) path.','Assuming detection is uniform with range instead of banded into zones and shadows.','Expecting convergence zones in shallow water, where the required deep channel is absent.']::text[],ARRAY['Planning long-range detection using CZ ranges.','Interpreting strong returns that recur at fixed range intervals.','Explaining shadow zones between convergence bands.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Convergence zone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '199130b1-19e4-435a-b1b0-f8bddb873cb9','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='199130b1-19e4-435a-b1b0-f8bddb873cb9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='199130b1-19e4-435a-b1b0-f8bddb873cb9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '70071165-27b7-484f-becc-3b2c85351952','Critical-band rate','The critical-band rate is a perceptual frequency scale, measured in Bark, on which one Bark corresponds to the width of one critical band of hearing. Spanning about 24 Barks over the audible range (roughly to 15.5 kHz), it maps physical frequency onto a scale where equal distances correspond to equal steps along the basilar membrane.','This is a hearing-based frequency scale, measured in Bark. One Bark is the width of one hearing band. About 24 Bark cover the range we hear. Equal Bark steps match equal steps inside the ear.','It provides a psychoacoustically meaningful frequency axis for models of masking, loudness, and roughness.','Using Zwicker''s approximation z = 13*atan(0.76*f/1000) + 3.5*atan((f/7500)^2), a 1 kHz tone maps to about 8.5 Bark.','Psychoacoustics',ARRAY['Auditory filter','Auditory excitation pattern','Auditory compression','Cochlear compression']::text[],ARRAY['Treating the Bark scale and the ERB scale as identical; they are related but not the same.','Assuming critical-band width is constant in Hz across frequency.','Confusing the critical-band rate (Bark axis) with the critical bandwidth (a width in Hz).']::text[],ARRAY['Setting analysis bands for a perceptual audio codec.','Computing loudness or masking on a Bark axis.','Explaining why low and high tones need different bandwidths.']::text[],'advanced','z = 13*atan(0.76*f/1000) + 3.5*atan((f/7500)^2)','The critical-band rate in Bark equals 13 times the arctangent of 0.76 times frequency in kilohertz, plus 3.5 times the arctangent of frequency over 7500 hertz, squared.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Critical-band rate');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '70071165-27b7-484f-becc-3b2c85351952','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='70071165-27b7-484f-becc-3b2c85351952') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='70071165-27b7-484f-becc-3b2c85351952');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f6772b43-a56f-421c-a865-09f1c3126474','Crosstalk cancellation','Crosstalk cancellation is a loudspeaker-playback technique that uses inverse filters to stop the sound each speaker radiates to the listener''s opposite (far) ear. This turns an ordinary two-speaker pair into a transaural system, so binaural, ear-specific signals reach the correct ear.','Two speakers each send sound to both of your ears. This method cancels the speaker sound meant for one ear from reaching the other. Then each ear hears only its own signal. That lets headphone-style 3D audio work over speakers.','It lets binaural recordings play correctly over loudspeakers by removing the acoustic crosstalk between the speakers and the far ear.','An engineer measures the two speaker-to-ear paths, then applies an inverse filter matrix so a listener at the sweet spot hears the intended left- and right-ear signals.','Transaural Audio',ARRAY['HRTF','HRIR','Externalization','Interaural cross-correlation','Front–back reversal']::text[],ARRAY['Assuming cancellation works anywhere in the room rather than only at a small sweet spot.','Confusing crosstalk cancellation with ordinary stereo channel separation.','Ignoring that head movement and room reflections quickly break the cancellation.']::text[],ARRAY['Playing a binaural mix over a pair of desktop speakers.','Building a single-listener transaural 3D-audio demo.','Designing a fixed-seat spatial-audio installation.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Crosstalk cancellation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f6772b43-a56f-421c-a865-09f1c3126474','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f6772b43-a56f-421c-a865-09f1c3126474') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f6772b43-a56f-421c-a865-09f1c3126474');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ac47308f-e99b-4776-b65f-f491a5dd8faf','Cymbal transducer','A cymbal transducer is a miniature Class V flextensional transducer made of a thin piezoelectric ceramic disk bonded between two shallow, cymbal-shaped metal end caps. The caps act as mechanical transformers, converting the disk''s small radial and thickness motion into a much larger axial displacement.','This small underwater device has a ceramic disk between two dome-shaped metal caps. Voltage makes the disk change shape a tiny amount. The curved caps turn that tiny motion into a much larger push. This makes strong low sound from a small part.','It produces or receives low-frequency underwater sound from a compact, low-cost package by amplifying the ceramic''s small motion.','A designer arrays several cymbals to build a lightweight low-frequency projector or hydrophone where a bulky stacked transducer would be impractical.','Underwater Transducer',ARRAY['Flextensional transducer','Electromechanical coupling coefficient','Hull-mounted array','Flank array','Huygens principle']::text[],ARRAY['Confusing the cymbal with the related ''moonie'' transducer, which uses a different cap cavity.','Treating the metal caps as mere protection rather than the motion-amplifying element.','Assuming it handles high drive power, when cap stress limits it.']::text[],ARRAY['Compact low-frequency sonar projector design.','Nodes in an underwater acoustic sensor network.','Miniature actuators and vibration energy harvesting.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cymbal transducer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ac47308f-e99b-4776-b65f-f491a5dd8faf','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ac47308f-e99b-4776-b65f-f491a5dd8faf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ac47308f-e99b-4776-b65f-f491a5dd8faf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '25270cb3-1196-44f3-85b0-b59395876a54','Dead zone','In echo sounding, the dead zone is a near-bottom or near-transducer region a sounder cannot resolve. Above the seabed it is the thin layer masked because the spreading beam''s edges strike the bottom later than its centre; near the transducer it is the blanked interval during pulse transmission and ring-down.','An echo sounder cannot see everything. Right below it, its own pulse blinds it for a moment. Just above the seabed, the wide beam hides a thin layer of water. Targets in these gaps are missed.','Naming these blind regions warns surveyors where the sounder''s data near the bottom are unreliable.','For range 100 m, half-beam angle 3.5 degrees, sound speed 1500 m/s and pulse 1 ms, dead-zone height = 100(1 - cos 3.5) + 1500 x 0.001 / 2, about 0.19 + 0.75 = 0.94 m.','Sonar Limitation',ARRAY['Echo sounder','Forward-looking sonar','Detection threshold','Directivity gain','Doppler shift']::text[],ARRAY['Confusing the near-transducer blanking with the separate near-bottom acoustic dead zone.','Assuming a narrower beam removes the dead zone entirely.','Forgetting that pulse length adds to the dead-zone thickness.']::text[],ARRAY['Fisheries acoustic survey counting fish near the seabed.','Shallow-water bathymetric sounding.','Setting a bottom-detection blanking window.']::text[],'intermediate','h_dz = R(1 - cos(theta/2)) + c*tau/2','The acoustic dead-zone height equals the range times one minus the cosine of the half-beam angle, plus half the pulse length expressed as distance.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dead zone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '25270cb3-1196-44f3-85b0-b59395876a54','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='25270cb3-1196-44f3-85b0-b59395876a54') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='25270cb3-1196-44f3-85b0-b59395876a54');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '17c41640-6a00-48ab-b2d7-a5c4ded7c36e','Deep sound channel','The deep sound channel (SOFAR channel) is a horizontal layer of the deep ocean centred on the depth of minimum sound speed, typically near 1000-1200 m at mid-latitudes. Because sound speed rises both above (warmer water) and below (higher pressure), rays refract back toward this axis, trapping low-frequency sound for very long ranges.','Deep in the ocean is a layer where sound travels slowest. Above and below it, sound moves faster. Sound bends back toward this slow layer instead of escaping. So low sounds stay trapped and travel very far.','It lets low-frequency sound propagate over thousands of kilometres, used for long-range signalling, monitoring and animal communication.','An analyst places a source and receiver near the channel axis so spreading loss follows cylindrical (10 log R) rather than spherical (20 log R) behaviour beyond the transition range.','Ocean Propagation',ARRAY['Directivity gain','Detection threshold','Flank array','Hull-mounted array','Huygens principle']::text[],ARRAY['Assuming the channel axis sits at the same depth everywhere in the ocean.','Thinking all frequencies are trapped equally, when low frequencies travel best.','Confusing the deep sound channel with a shallow surface duct.']::text[],ARRAY['Long-range passive acoustic monitoring.','Tracking low-frequency whale calls.','Historic SOFAR emergency-beacon location.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Deep sound channel');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '17c41640-6a00-48ab-b2d7-a5c4ded7c36e','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='17c41640-6a00-48ab-b2d7-a5c4ded7c36e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='17c41640-6a00-48ab-b2d7-a5c4ded7c36e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '96a43d0a-705a-4b78-b971-2799a7763f00','Detection threshold','In the sonar equation, the detection threshold (DT) is the signal-to-noise ratio required at the processor input to declare a target present at a chosen probability of detection and false alarm. It is a property of the processor and decision criterion, not of the ocean medium.','A sonar must decide if a faint echo is a real target or just noise. The detection threshold is the smallest signal-to-noise ratio needed to say yes. It depends on how sure you must be. A stricter rule needs a higher threshold.','It sets the minimum signal-to-noise ratio the system needs, letting the sonar equation predict detection range.','Closing the passive sonar equation, SL - TL - (NL - DI) = DT at the limit; if the predicted signal excess is positive, say 12 dB available against DT = 8 dB, a 4 dB margin means detection.','Sonar Metric',ARRAY['Directivity gain','Deep sound channel','Echo sounder','Flank array','Forward-looking sonar']::text[],ARRAY['Treating DT as a single fixed number rather than one set by the chosen detection and false-alarm rates.','Confusing the detection threshold with the detection range it helps predict.','Forgetting that longer integration time lowers the required DT.']::text[],ARRAY['Predicting a sonar''s detection range.','Comparing signal processors on a probability-of-detection curve.','Setting operator display and decision criteria.']::text[],'advanced','DT = (S/N)_required ; passive: SL - TL - (NL - DI) = DT','The detection threshold is the required signal-to-noise ratio; at the detection limit the source level minus transmission loss minus the noise level referred through the array gain equals it.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Detection threshold');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '96a43d0a-705a-4b78-b971-2799a7763f00','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='96a43d0a-705a-4b78-b971-2799a7763f00') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='96a43d0a-705a-4b78-b971-2799a7763f00');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '318992bc-1a93-4cd3-b12e-a4c0d29b0d34','Directivity gain','The directivity gain, or directivity index (DI), of a transducer or array is the decibel measure of how strongly it concentrates transmitted or received energy compared with an omnidirectional element in an isotropic field. It is defined as DI = 10 log10 Q, where Q is the directivity factor.','A directional transducer aims sound one way. Directivity gain is a decibel value. It tells you how tight that aim is. A bigger number means a narrower beam. A device that sends sound all ways has zero gain.','It quantifies the gain a directional array provides against isotropic noise, improving the signal-to-noise ratio in the sonar equation.','For a line array of N half-wavelength-spaced elements, DI is about 10 log10 N; with N = 10 elements, DI is roughly 10 dB against isotropic noise.','Array Metric',ARRAY['Detection threshold','Hull-mounted array','Flank array','Echo sounder','Deep sound channel']::text[],ARRAY['Confusing directivity index with array gain, which differ when the noise is not isotropic.','Mixing the decibel index with the linear directivity factor.','Ignoring that directivity changes strongly with frequency for a fixed aperture.']::text[],ARRAY['Specifying a sonar receiving array.','Comparing hydrophone directional performance.','Building a signal-to-noise budget in the sonar equation.']::text[],'advanced','DI = 10 log10 Q ,  Q = 4*pi / (integral of b(theta,phi) dOmega)','The directivity index is ten times the base-ten logarithm of the directivity factor, which is four pi divided by the beam pattern integrated over all solid angle.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Directivity gain');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '318992bc-1a93-4cd3-b12e-a4c0d29b0d34','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='318992bc-1a93-4cd3-b12e-a4c0d29b0d34') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='318992bc-1a93-4cd3-b12e-a4c0d29b0d34');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '47ba1eec-5769-4c40-b33c-49181dc5469c','Doppler shift','The Doppler shift is the change in observed frequency of a wave caused by relative motion between source and receiver, or, in active sonar, between the sonar and the scatterer. Approaching motion raises the frequency; receding motion lowers it.','When a sound source and a listener move toward each other, the pitch rises. When they move apart, the pitch falls. This change is the Doppler shift. Sonar uses it to measure how fast a target moves.','It enables velocity measurement in sonar and Doppler logs and must be compensated in coherent, matched-filter detection.','For active sonar the round-trip shift is about 2 v f / c; at f = 10 kHz, closing speed v = 5 m/s and c = 1500 m/s, the shift is about 2 x 5 x 10000 / 1500, roughly 67 Hz upward.','Wave Phenomenon',ARRAY['Echo sounder','Forward-looking sonar','Detection threshold','Deep sound channel','Directivity gain']::text[],ARRAY['Using the air sound speed of 343 m/s instead of about 1500 m/s in water.','Forgetting the factor of two for the round trip in active sonar.','Confusing the source-motion and observer-motion forms of the equation.']::text[],ARRAY['Estimating a sonar target''s radial speed.','Operating a Doppler velocity log.','Compensating the matched filter for a moving contact.']::text[],'intermediate','f'' = f * (c + v_r)/(c - v_s) ;  active sonar: delta_f ~= 2*v*f/c','The observed frequency equals the source frequency times sound speed plus receiver speed over sound speed minus source speed; for active sonar the round-trip shift is about twice the radial speed times frequency over sound speed.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Doppler shift');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '47ba1eec-5769-4c40-b33c-49181dc5469c','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='47ba1eec-5769-4c40-b33c-49181dc5469c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='47ba1eec-5769-4c40-b33c-49181dc5469c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6043b49e-1559-4455-ac21-1d6f9bbac362','Dynamic localization cue','A dynamic localization cue is a spatial-hearing cue that arises from change in the binaural and spectral cues over time, as the listener moves the head or the source moves, rather than from a single static acoustic snapshot. The direction and rate of change help resolve ambiguities such as front-back confusion.','When you turn your head, the sound at each ear changes. Your brain uses how it changes to place the sound. These moving clues are dynamic cues. They help tell front from back and up from down.','It resolves cone-of-confusion and front-back ambiguities that static cues alone cannot settle.','A VR audio engineer adds head tracking so turning the head updates the applied HRTF, restoring dynamic cues and cutting reversals.','Localization Cue',ARRAY['Head-motion cue','Front–back reversal','HRTF','Externalization','Interaural cross-correlation']::text[],ARRAY['Confusing dynamic cues with the static duplex (time and level) cues.','Ignoring that head-tracking latency weakens or breaks the cue.','Assuming they help only with left-right azimuth judgments.']::text[],ARRAY['Head-tracked VR and AR audio rendering.','Explaining why listeners turn toward a sound.','Reducing front-back errors in binaural playback.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dynamic localization cue');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6043b49e-1559-4455-ac21-1d6f9bbac362','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6043b49e-1559-4455-ac21-1d6f9bbac362') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6043b49e-1559-4455-ac21-1d6f9bbac362');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1f36df5e-d177-4399-aa69-dde701be8487','ERB','The equivalent rectangular bandwidth (ERB) is the bandwidth of an ideal rectangular filter that, with the same peak gain, passes the same power as a given auditory filter driven by a flat-spectrum input. It parameterises human frequency selectivity as a function of centre frequency.','The ear works like a bank of overlapping filters. Each filter has a rounded shape. The ERB is the width of a simple rectangle that would pass the same energy. It grows wider at higher frequencies.','It gives a single width for each auditory filter, forming the ERB frequency scale used in loudness and masking models.','Using Glasberg and Moore''s formula, at a centre frequency of 1 kHz the ERB is 24.7 x (4.37 x 1 + 1), about 133 Hz.','Auditory Filter',ARRAY['Energetic masking','Forward masking','Fluctuation strength','Equalization-cancellation model','Harmonicity cue']::text[],ARRAY['Confusing the ERB with the older critical band (Bark) scale, which is similar but not identical.','Mixing up the ERB bandwidth with the ERB-number (ERB-rate) scale.','Treating the ERB as constant instead of widening with frequency.']::text[],ARRAY['Designing a gammatone auditory filterbank.','Building a loudness or masking model.','Predicting the spread of masking around a tone.']::text[],'advanced','ERB(Hz) = 24.7*(4.37*F + 1) ,  ERB-number = 21.4*log10(4.37*F + 1)','The equivalent rectangular bandwidth in hertz equals 24.7 times the quantity 4.37 times the centre frequency in kilohertz plus one; the ERB-number is 21.4 times the base-ten log of that same bracket.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='ERB');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1f36df5e-d177-4399-aa69-dde701be8487','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1f36df5e-d177-4399-aa69-dde701be8487') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1f36df5e-d177-4399-aa69-dde701be8487');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '60e0e40d-bebd-4737-bbd9-0626c3270422','Echo sounder','An echo sounder is an active acoustic instrument that measures water depth, and detects targets in the water column, by transmitting a downward sound pulse and timing the echo returning from the seabed. Depth equals sound speed times round-trip time divided by two.','An echo sounder measures water depth with sound. It sends a ping straight down. It times how long the echo takes to return. Half that time times the sound speed gives the depth.','It charts water depth and finds fish or the bottom for navigation, surveying and fisheries.','If an echo returns in 0.13 s and the sound speed is 1500 m/s, depth = 1500 x 0.13 / 2 = 97.5 m.','Active Sonar Instrument',ARRAY['Dead zone','Doppler shift','Forward-looking sonar','Detection threshold','Directivity gain']::text[],ARRAY['Using an assumed sound speed that is wrong, causing a systematic depth error.','Forgetting the factor of two for the round trip.','UNSAFE: swimming or diving directly beneath a running high-power scientific sounder, which can expose a diver to intense pulses; keep clear and observe exposure limits.']::text[],ARRAY['Bathymetric depth survey.','Fish finding in fisheries acoustics.','Applying a sound-speed correction to logged depths.']::text[],'intermediate','d = c * t / 2','Depth equals the sound speed multiplied by the round-trip echo time, divided by two.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Echo sounder');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '60e0e40d-bebd-4737-bbd9-0626c3270422','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='60e0e40d-bebd-4737-bbd9-0626c3270422') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='60e0e40d-bebd-4737-bbd9-0626c3270422');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '33c7f924-3a91-48a6-8ca3-f943fe8bc0c7','Electromechanical coupling coefficient','The electromechanical coupling coefficient (k) is a dimensionless figure of merit for a piezoelectric material or transducer describing how effectively it converts energy between electrical and mechanical forms. Its square equals the fraction of input energy in one domain converted to and stored in the other during a loading cycle.','A piezoelectric part turns electricity into motion and back. The coupling coefficient shows how good it is at this swap. Its square is the share of energy converted each cycle. A higher value means a more efficient, wider-band device.','It rates a material''s energy-conversion effectiveness and helps predict a transducer''s usable bandwidth.','If a ceramic has k = 0.5, then k-squared = 0.25, so about 25 percent of the applied energy is converted to the other domain each cycle.','Piezoelectric Property',ARRAY['Cymbal transducer','Flextensional transducer','Electronic focusing','Focal law','Guided-wave inspection']::text[],ARRAY['Reading k as a power efficiency, when it measures energy conversion, not loss.','Confusing the material coupling k with the effective device coupling k-effective.','Mixing k up with the piezoelectric charge constant d.']::text[],ARRAY['Selecting a ceramic for a sonar projector.','Estimating transducer bandwidth from resonance and antiresonance.','Comparing PZT ceramic with single-crystal materials.']::text[],'advanced','k^2 = (converted mutual energy) / (total input energy)','The square of the coupling coefficient equals the energy converted between the electrical and mechanical domains divided by the total energy supplied in one cycle.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electromechanical coupling coefficient');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '33c7f924-3a91-48a6-8ca3-f943fe8bc0c7','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='33c7f924-3a91-48a6-8ca3-f943fe8bc0c7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='33c7f924-3a91-48a6-8ca3-f943fe8bc0c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7e22ad6a-e037-4ced-be3f-fa1549d68b58','Electronic focusing','Electronic focusing applies calculated time (or phase) delays to the individual elements of a phased array so their wavefronts arrive in phase at a chosen focal point, concentrating energy there without moving the array. Adjusting the delay law shifts the focus in depth or angle.','A phased array has many small elements. Each one can fire at a slightly different time. By timing them right, their waves meet at one point. That point gets a strong, sharp beam. Changing the timing moves the focus.','It steers and focuses beams electronically for imaging, inspection and therapy, replacing mechanical scanning or fixed lenses.','An inspector programs delays so the beam converges at a weld''s depth, sharpening the flaw echo. UNSAFE: in high-intensity focused ultrasound (HIFU) the focus deposits enough energy to burn or ablate tissue, so dose and beam path must be tightly controlled.','Phased-Array Technique',ARRAY['Focal law','Electromechanical coupling coefficient','Guided-wave inspection','Cymbal transducer','Huygens principle']::text[],ARRAY['Confusing focusing (converging the beam) with steering (angling the beam).','Assuming one delay law focuses correctly at every depth.','UNSAFE: underestimating the tissue heating produced at a HIFU focus.']::text[],ARRAY['Phased-array weld inspection.','Medical diagnostic ultrasound imaging.','High-intensity focused ultrasound therapy planning.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electronic focusing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7e22ad6a-e037-4ced-be3f-fa1549d68b58','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7e22ad6a-e037-4ced-be3f-fa1549d68b58') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7e22ad6a-e037-4ced-be3f-fa1549d68b58');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '20e2dfc6-7815-4840-a74e-a41168cf3d25','Energetic masking','Energetic masking occurs when the physical excitation of a target sound within an auditory filter is overpowered by that of a competing sound, reducing or preventing its detection at the cochlea. It is distinguished from informational masking, which arises more centrally despite adequate peripheral representation.','A loud sound can hide a quieter one in the same pitch region. This happens in the inner ear itself. The target signal is buried by the masker''s energy. This is called energetic masking.','It explains threshold shifts when sounds overlap in time and frequency, underpinning perceptual coding and speech-in-noise models.','A codec designer uses the auditory filter width to predict how much a narrowband masker raises a nearby tone''s threshold, then hides coding noise beneath it.','Masking',ARRAY['Forward masking','ERB','Equalization-cancellation model','Harmonicity cue','Fluctuation strength']::text[],ARRAY['Confusing energetic masking with informational (central) masking.','Assuming masking happens only at exactly the same frequency, ignoring the spread of masking.','Overlooking the temporal component of masking.']::text[],ARRAY['Perceptual audio coding such as MP3 and AAC.','Predicting speech intelligibility in noise.','Designing office sound-masking systems.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Energetic masking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '20e2dfc6-7815-4840-a74e-a41168cf3d25','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='20e2dfc6-7815-4840-a74e-a41168cf3d25') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='20e2dfc6-7815-4840-a74e-a41168cf3d25');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4365adab-24b4-404f-b1ae-3d7f92cfe1a3','Equalization-cancellation model','The equalization-cancellation model, due to Durlach, explains binaural unmasking (the binaural masking level difference). The auditory system equalises the masker at the two ears by adjusting level and delay, then subtracts them to cancel the masker, improving detection of a target that has different interaural parameters.','Your two ears hear noise a little differently. The brain lines up the noise at both ears, then subtracts it. This cancels much of the noise. A signal that differs between the ears then stands out.','It accounts for the binaural masking level difference and predicts the detection advantage of listening with two ears.','It explains why an out-of-phase tone in in-phase noise (the NoS-pi condition) is easier to hear, giving up to about 15 dB of release at low frequencies.','Binaural Model',ARRAY['Energetic masking','Interaural cross-correlation','Forward masking','ERB','Harmonicity cue']::text[],ARRAY['Assuming the internal cancellation is perfect, when internal noise limits it.','Confusing the binaural masking level difference with a simple loudness difference.','Assuming the release is equal at all frequencies, when it is largest below about 500 Hz.']::text[],ARRAY['Explaining the binaural masking level difference.','Modelling spatial release from masking.','Cocktail-party and hearing-in-noise research.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Equalization-cancellation model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4365adab-24b4-404f-b1ae-3d7f92cfe1a3','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4365adab-24b4-404f-b1ae-3d7f92cfe1a3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4365adab-24b4-404f-b1ae-3d7f92cfe1a3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4920d4c1-7dba-46bd-8492-98c7e8bdc645','Externalization','Externalization is the perception that a sound originates from a location outside the head and at a distance, rather than inside it. It depends on realistic spectral and reverberation cues, especially individualised HRTFs and plausible room reflections; poor cues cause in-head localization over headphones.','Over headphones, sounds often seem to come from inside your head. Externalization is when they instead seem to come from out in the room. Good ear-shape filters and room echoes create this. Without them, sound stays inside.','It is a central goal of binaural rendering: making headphone audio sound like real, out-there sources.','A binaural engineer adds individualised HRTFs, head tracking and a little reverberation to move a mix out of the head.','Spatial Perception',ARRAY['HRTF','HRIR','Front–back reversal','Dynamic localization cue','Head-motion cue']::text[],ARRAY['Thinking loudness or stereo width alone produces externalization.','Assuming any generic HRTF externalises well, when individualisation matters.','Ignoring the role of reverberation and reflections.']::text[],ARRAY['VR and AR headphone audio.','Binaural music mixing.','Evaluating headphone spatial-audio quality.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Externalization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4920d4c1-7dba-46bd-8492-98c7e8bdc645','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4920d4c1-7dba-46bd-8492-98c7e8bdc645') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4920d4c1-7dba-46bd-8492-98c7e8bdc645');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'aa43bc4b-67e5-4339-a12b-a80b299262f0','Flank array','A flank array is a conformal sonar array mounted along the side (flank) of a submarine or ship hull, providing broadband passive detection and bearing estimation over a wide sector to port or starboard. Its long horizontal aperture gives high directivity and good low-frequency sensitivity.','A flank array is a line of hydrophones along a submarine''s side. It listens quietly for other vessels. Its length makes it good at hearing low sounds and finding their direction. Each side covers a wide arc.','It gives passive, wide-sector detection and bearing with better low-frequency directivity than a compact bow dome.','A sonar operator reads bearings from the flank array''s beams to track a contact abeam, complementing the bow and towed arrays.','Sonar Array',ARRAY['Hull-mounted array','Directivity gain','Detection threshold','Deep sound channel','Forward-looking sonar']::text[],ARRAY['Confusing the passive, side-mounted flank array with an active bow or hull array.','Assuming it gives target range directly, when it yields bearings only.','Overlooking platform self-noise that limits its performance.']::text[],ARRAY['Submarine passive tracking.','Bearing-only target-motion analysis.','Comparing array apertures on a platform.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Flank array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'aa43bc4b-67e5-4339-a12b-a80b299262f0','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='aa43bc4b-67e5-4339-a12b-a80b299262f0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='aa43bc4b-67e5-4339-a12b-a80b299262f0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1ff319c8-4ab8-4c03-adff-2e57b52789f1','Flextensional transducer','A flextensional transducer is a class of underwater sound transducer in which a stiff active driver (a piezoelectric or magnetostrictive stack) is coupled to a compliant metal shell that transforms the driver''s small, high-force motion into larger radiating displacement. The shell''s flexural resonance yields efficient low-frequency radiation from a compact body.','A flextensional transducer uses a stiff driver inside a springy shell. The driver moves a tiny amount with great force. The shell bends and turns that into a big surface motion. This makes strong low sound from a small unit.','It gives efficient low-frequency underwater projection where the wavelength is large but the device must stay compact.','An engineer selects a Class IV oval-shell flextensional projector for a low-frequency active sonar needing high power below about 1 kHz.','Underwater Transducer',ARRAY['Cymbal transducer','Electromechanical coupling coefficient','Hull-mounted array','Flank array','Directivity gain']::text[],ARRAY['Treating the shell as purely structural, when it is the motion transformer and radiator.','Ignoring depth limits, since static water pressure loads the shell.','Assuming it is a high-frequency device, when it is used for low frequencies.']::text[],ARRAY['Low-frequency active sonar projector.','Ocean-acoustic tomography sound source.','Deep-water acoustic source design.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Flextensional transducer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1ff319c8-4ab8-4c03-adff-2e57b52789f1','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1ff319c8-4ab8-4c03-adff-2e57b52789f1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1ff319c8-4ab8-4c03-adff-2e57b52789f1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2dd28069-2344-48eb-a55d-5938d9572aaf','Fluctuation strength','Fluctuation strength is a psychoacoustic sensation magnitude describing the perceived slow amplitude or frequency modulation of a sound, greatest for modulation rates near 4 Hz. It is measured in vacil, where 1 vacil is defined by a 1 kHz tone at 60 dB that is 100 percent amplitude-modulated at 4 Hz.','Some sounds seem to slowly wax and wane. Fluctuation strength measures that slow throbbing feeling. It is strongest when the sound changes about four times a second. Its unit is the vacil.','It quantifies slow modulation for sound-quality and annoyance evaluation of products and signals.','A sound-quality engineer computes fluctuation strength in vacil to judge the warble of an idling engine or the throb of a warning tone.','Sound Quality Metric',ARRAY['Energetic masking','ERB','Forward masking','Harmonicity cue','Equalization-cancellation model']::text[],ARRAY['Confusing fluctuation strength (slow, near 4 Hz) with roughness (fast, near 70 Hz).','Assuming a steady, unmodulated tone has fluctuation strength.','Forgetting that both amplitude and frequency modulation produce it.']::text[],ARRAY['Product sound-quality engineering.','Designing alarms and warning signals.','Assessing engine or HVAC noise annoyance.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fluctuation strength');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2dd28069-2344-48eb-a55d-5938d9572aaf','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2dd28069-2344-48eb-a55d-5938d9572aaf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2dd28069-2344-48eb-a55d-5938d9572aaf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '25616420-99a0-47c3-95f2-6f1bbf656234','Focal law','In phased-array ultrasonics, a focal law is the set of per-element time delays (and often amplitudes) that steers and/or focuses the array''s beam to a chosen angle and depth. The calculated delays align each element''s contribution so the wavefronts add in phase at the target point.','A phased array fires many elements. A focal law is the list of tiny delays for each one. The right delays make all the waves meet at one spot. It sets where the beam points and focuses.','It defines the delay pattern that shapes, steers and focuses a phased-array beam.','An inspector loads a focal-law set to sweep angles across a weld, each law timing the elements to focus at the inspection depth. UNSAFE: therapeutic focal laws (HIFU) concentrate enough intensity to ablate tissue, requiring strict dose and beam-path control.','Phased-Array Technique',ARRAY['Electronic focusing','Guided-wave inspection','Electromechanical coupling coefficient','Cymbal transducer','Huygens principle']::text[],ARRAY['Treating a focal law as a single delay value rather than a full per-element set.','Assuming one law suits all angles and depths.','UNSAFE: mismanaging dose when focal laws are used for HIFU therapy.']::text[],ARRAY['Phased-array ultrasonic weld scanning.','Total focusing method and full-matrix-capture imaging.','High-intensity focused ultrasound treatment planning.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Focal law');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '25616420-99a0-47c3-95f2-6f1bbf656234','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='25616420-99a0-47c3-95f2-6f1bbf656234') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='25616420-99a0-47c3-95f2-6f1bbf656234');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9c6266d2-3569-47d6-8f15-9c1a27a2e26c','Forward masking','Forward masking is a temporal masking effect in which a masker raises the detection threshold of a target that follows it in time, after the masker has ended. The threshold shift is largest just after masker offset and decays over roughly 100 to 200 milliseconds.','A loud sound can hide a quieter sound that comes right after it. This is forward masking. The effect is strongest just after the loud sound stops. It fades within about a fifth of a second.','It describes how a preceding sound reduces the audibility of a following sound, important for coding and hearing tests.','A codec designer exploits forward masking to hide quantisation noise in the brief interval right after a loud transient.','Temporal Masking',ARRAY['Energetic masking','ERB','Equalization-cancellation model','Fluctuation strength','Harmonicity cue']::text[],ARRAY['Confusing forward masking with backward masking, where the masker comes after the target.','Assuming it lasts as long as simultaneous masking.','Ignoring its nonlinear growth with masker level.']::text[],ARRAY['Perceptual audio coding.','Gap-detection and temporal-resolution tests.','Transient handling in audio processing.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Forward masking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9c6266d2-3569-47d6-8f15-9c1a27a2e26c','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9c6266d2-3569-47d6-8f15-9c1a27a2e26c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9c6266d2-3569-47d6-8f15-9c1a27a2e26c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '82ed4660-ba72-48f2-bb12-4edb219c6e9e','Forward-looking sonar','Forward-looking sonar is an active sonar that transmits and images ahead of a moving platform to detect obstacles, seabed features or targets in the path. It typically forms a fan of beams to build a forward, often near-real-time, acoustic image.','Forward-looking sonar points ahead of a boat or vehicle, not down. It sends pings forward and listens for echoes. It builds a picture of what lies in the path. It warns of obstacles or the rising bottom.','It provides obstacle avoidance and forward situational awareness for vessels and underwater vehicles.','An AUV pilot uses forward-looking sonar to spot rising terrain and steer around it before a collision. UNSAFE: high-power active sonar can expose nearby divers to hazardous sound pressure, so keep divers clear and observe exposure limits.','Active Sonar',ARRAY['Echo sounder','Dead zone','Doppler shift','Detection threshold','Directivity gain']::text[],ARRAY['Confusing forward-looking sonar with downward echo sounders or side-scan sonar.','Assuming fine detail at long range, when resolution falls with distance.','UNSAFE: running high power near divers in the water.']::text[],ARRAY['Autonomous or remotely operated vehicle navigation.','Harbour and shallow-water obstacle avoidance.','Diver-held navigation sonar.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Forward-looking sonar');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '82ed4660-ba72-48f2-bb12-4edb219c6e9e','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='82ed4660-ba72-48f2-bb12-4edb219c6e9e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='82ed4660-ba72-48f2-bb12-4edb219c6e9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'adba7392-1489-4024-9544-423b416bef04','Front–back reversal','A front-back reversal is a localization error in which a listener judges a sound coming from the front as arriving from the rear, or vice versa, because both positions produce nearly identical interaural time and level differences (the cone of confusion). Spectral (pinna) cues and head movement normally resolve it.','A sound in front and the same sound behind can reach the two ears almost identically. So the brain can mix them up. Hearing a front sound as if behind is a front-back reversal. Ear-shape cues and head turns usually fix it.','It names a common spatial-hearing ambiguity used to evaluate localization accuracy and HRTF quality.','A spatial-audio tester counts front-back reversals to judge an HRTF set or head-tracking system; adding head tracking sharply reduces them.','Localization Error',ARRAY['Dynamic localization cue','Head-motion cue','HRTF','Externalization','Interaural cross-correlation']::text[],ARRAY['Blaming reversals on level errors rather than missing spectral (pinna) cues.','Assuming good time and level differences alone prevent reversals.','Overlooking that head movement resolves most reversals.']::text[],ARRAY['Evaluating binaural rendering quality.','Testing VR and AR audio.','Studying HRTF individualisation.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Front–back reversal');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'adba7392-1489-4024-9544-423b416bef04','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='adba7392-1489-4024-9544-423b416bef04') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='adba7392-1489-4024-9544-423b416bef04');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1223dc5f-a81c-4a69-a17c-9c9663e096be','Guided-wave inspection','Guided-wave inspection is a non-destructive testing method that launches low-frequency ultrasonic waves guided by a structure''s boundaries, such as Lamb waves in plates or longitudinal, torsional and flexural modes in pipes, to screen long lengths from a single location. Reflections from corrosion, cracks or welds reveal defects far from the transducer ring.','This test sends ultrasound along a pipe or plate, not just into it. The wave travels guided by the walls for many metres. Echoes come back from cracks or corrosion. One sensor ring can check a long run of pipe.','It gives rapid, long-range screening of pipes and plates for corrosion and cracking from one access point.','An inspector clamps a transducer collar on a pipe and sends torsional guided waves, reading echoes to locate corrosion tens of metres away, then follows up with local inspection.','NDT Method',ARRAY['Focal law','Electronic focusing','Electromechanical coupling coefficient','Huygens principle','Cymbal transducer']::text[],ARRAY['Confusing guided waves with bulk-wave thickness gauging.','Assuming unlimited range, when attenuation, coatings and features limit it.','Ignoring mode dispersion, where velocity varies with frequency.']::text[],ARRAY['Long-range pipeline corrosion screening.','Inspecting buried or insulated pipe from one point.','Rail and plate defect screening.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Guided-wave inspection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1223dc5f-a81c-4a69-a17c-9c9663e096be','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1223dc5f-a81c-4a69-a17c-9c9663e096be') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1223dc5f-a81c-4a69-a17c-9c9663e096be');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5784248b-81ae-4d78-970d-aa177a6cd8b1','HRIR','The head-related impulse response (HRIR) is the time-domain response, measured at the ear (typically the ear-canal entrance or eardrum), to an impulsive sound from a specific direction, capturing how the head, torso and pinna filter the sound. It is the time-domain counterpart of the head-related transfer function, its Fourier transform.','The HRIR is the sound your ear receives from a quick click at one direction. It captures how your head and outer ear reshape that click. It is a short time signal. Its frequency version is the HRTF.','It provides the per-direction filter used to render binaural audio by convolution.','A binaural engineer convolves a dry source with the left and right HRIRs for the wanted direction to place it in 3D over headphones.','Binaural Filter',ARRAY['HRTF','Externalization','Crosstalk cancellation','Front–back reversal','Dynamic localization cue']::text[],ARRAY['Confusing the HRIR (time domain) with the HRTF (frequency domain); they are a transform pair.','Forgetting that it includes torso and pinna effects, not just the head.','Swapping the ipsilateral and contralateral ear responses.']::text[],ARRAY['Binaural rendering by convolution.','Measuring an HRTF/HRIR dataset.','Interpolating between measured directions.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='HRIR');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5784248b-81ae-4d78-970d-aa177a6cd8b1','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5784248b-81ae-4d78-970d-aa177a6cd8b1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5784248b-81ae-4d78-970d-aa177a6cd8b1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '92ac8603-5e81-4252-b4d6-ecbc080c4c49','HRTF','The head-related transfer function (HRTF) is the direction- and frequency-dependent ratio of the sound pressure at a listener''s ear to that at the head centre in the listener''s absence, describing the filtering by head, torso and pinna. It encodes the interaural and spectral cues the brain uses to localise sound.','The HRTF describes how your head and outer ears change a sound before it reaches your eardrum. It differs by direction and frequency. Your brain reads these changes to place sounds. It is the key filter for 3D audio.','It supplies the localization cues needed to synthesise or analyse spatial hearing.','An engineer applies each ear''s HRTF as a filter so a mono source appears at a chosen azimuth and elevation over headphones.','Binaural Filter',ARRAY['HRIR','Externalization','Crosstalk cancellation','Front–back reversal','Interaural cross-correlation']::text[],ARRAY['Assuming one generic HRTF suits every listener.','Thinking the HRTF encodes only time and level differences, when spectral cues matter too.','Ignoring that it changes with distance in the near field.']::text[],ARRAY['Binaural synthesis for headphones.','VR and AR spatial audio.','HRTF personalisation research.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='HRTF');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '92ac8603-5e81-4252-b4d6-ecbc080c4c49','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='92ac8603-5e81-4252-b4d6-ecbc080c4c49') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='92ac8603-5e81-4252-b4d6-ecbc080c4c49');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd1957a74-59c8-4264-be5e-4bb23eb77d20','Harmonicity cue','The harmonicity cue is a grouping cue in auditory scene analysis by which the auditory system fuses frequency components that are approximately integer multiples of a common fundamental into a single perceived source. Components that are inharmonic or mistuned tend to segregate and be heard separately.','Musical and vocal sounds have partials at whole-number multiples of a base pitch. The ear groups such matching partials as one sound. A partial that does not fit is heard separately. This grouping is the harmonicity cue.','It helps the listener separate concurrent sounds, such as competing voices, by their common fundamental frequency.','A source-separation designer groups harmonically related partials to isolate one voice from a mixture.','Auditory Grouping',ARRAY['Energetic masking','ERB','Forward masking','Fluctuation strength','Equalization-cancellation model']::text[],ARRAY['Confusing the harmonicity cue with simple pitch perception.','Assuming perfect harmonicity is required, when small mistuning is tolerated.','Ignoring onset-time cues that also group components.']::text[],ARRAY['Cocktail-party listening.','Computational auditory scene analysis.','Music and voice source separation.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Harmonicity cue');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd1957a74-59c8-4264-be5e-4bb23eb77d20','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d1957a74-59c8-4264-be5e-4bb23eb77d20') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d1957a74-59c8-4264-be5e-4bb23eb77d20');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '88e35123-7ce9-46d8-9a52-055259a99f85','Head-motion cue','The head-motion cue is a dynamic localization cue in which voluntary head rotation systematically changes the interaural time and level differences, whose rate and direction of change disambiguate source position, especially resolving front-back and up-down confusions. It is a specific mechanism producing dynamic cues.','When you turn your head, the sound clues at your ears shift. The way they shift tells you where the sound is. This is the head-motion cue. It helps sort out front from back and up from down.','It resolves cone-of-confusion ambiguities using the listener''s own self-generated motion.','A VR audio system tracks head rotation and updates the HRTF in real time so head-motion cues work and reversals drop.','Localization Cue',ARRAY['Dynamic localization cue','Front–back reversal','HRTF','Externalization','HRIR']::text[],ARRAY['Confusing head-motion cues with the static duplex cues.','Ignoring tracking latency, which breaks the cue.','Assuming only large head movements help.']::text[],ARRAY['Head-tracked VR and AR audio.','Explaining natural listening behaviour.','Reducing front-back errors in binaural playback.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Head-motion cue');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '88e35123-7ce9-46d8-9a52-055259a99f85','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='88e35123-7ce9-46d8-9a52-055259a99f85') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='88e35123-7ce9-46d8-9a52-055259a99f85');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fdac3c86-dcf0-4cee-bbb4-8490914153fd','Hull-mounted array','A hull-mounted array is a sonar transducer array fixed to a ship''s or submarine''s hull, commonly in a bow dome or along the keel, used for active transmission and/or passive reception. Rigid mounting fixes its position and orientation relative to the platform, and a large aperture provides directivity.','A hull-mounted array is a sonar built into a ship''s hull. It can send pings and listen for echoes. Its fixed position keeps its aim steady with the ship. Its size gives it a focused, directional beam.','It is the primary organic sonar for detection, ranging and classification from the platform itself.','An operator runs the hull-mounted sonar in active mode to get target range and bearing near the ship. UNSAFE: powerful hull sonar can expose nearby divers to dangerous sound levels; divers must stay clear and follow exposure limits.','Sonar Array',ARRAY['Flank array','Directivity gain','Detection threshold','Forward-looking sonar','Echo sounder']::text[],ARRAY['Confusing a hull-mounted array with a towed array.','Assuming it only works actively, when it also serves passive reception.','UNSAFE: operating high-power active sonar with divers nearby.']::text[],ARRAY['Naval anti-submarine-warfare sonar.','Comparing hull-mounted with towed arrays.','Diver-safety planning around active sonar.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hull-mounted array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fdac3c86-dcf0-4cee-bbb4-8490914153fd','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fdac3c86-dcf0-4cee-bbb4-8490914153fd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fdac3c86-dcf0-4cee-bbb4-8490914153fd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5dabf97d-9b31-4529-99af-9a983461fc6e','Huygens principle','Huygens'' principle states that every point on a wavefront acts as a source of secondary spherical wavelets, and the new wavefront at a later time is the envelope (coherent sum) of those wavelets. It explains rectilinear propagation, reflection, refraction and diffraction, and underpins wavefront-synthesis methods.','Huygens'' idea says each point on a wave sends out tiny new waves. These tiny waves add up to form the next wavefront. This explains how sound bends, spreads and reflects. It is the basis of wave field synthesis.','It gives a constructive model of how wavefronts advance, explaining diffraction and enabling wavefront synthesis.','A wave-field-synthesis designer treats a line of loudspeakers as Huygens secondary sources, driving them to reconstruct a desired wavefront.','Wave Principle',ARRAY['Electronic focusing','Focal law','Guided-wave inspection','Directivity gain','Flextensional transducer']::text[],ARRAY['Assuming secondary wavelets radiate equally backward, when an obliquity factor suppresses the back wave.','Treating the construction as exact, when the Kirchhoff-Helmholtz integral makes it rigorous.','Confusing bare Huygens construction with the Huygens-Fresnel version that adds interference.']::text[],ARRAY['Explaining diffraction and refraction.','Designing wave-field-synthesis loudspeaker arrays.','Modelling array wavefronts.']::text[],'intermediate','new wavefront = envelope of secondary spherical wavelets from all points of the present wavefront','Each point of a wavefront emits a secondary spherical wavelet, and the surface tangent to all those wavelets a moment later is the new wavefront; the Kirchhoff-Helmholtz integral is its rigorous form.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Huygens principle');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5dabf97d-9b31-4529-99af-9a983461fc6e','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5dabf97d-9b31-4529-99af-9a983461fc6e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5dabf97d-9b31-4529-99af-9a983461fc6e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fea11254-bf3d-4baa-a362-f15d85bca85d','Interaural cross-correlation','Interaural cross-correlation is the normalised cross-correlation between the sound-pressure signals at a listener''s two ears, evaluated over interaural delays within about plus or minus 1 ms. Its peak value, the interaural cross-correlation coefficient (IACC), ranges from 0 to 1 and indicates how similar the two ear signals are.','Your two ears receive slightly different signals. This measure compares how alike they are. A value near one means the ears hear almost the same thing. A low value means the sound feels wide and enveloping.','It quantifies binaural similarity, used both to model source lateralization and to rate concert-hall spaciousness and listener envelopment.','An acoustician measures IACC with a dummy head to rate a hall''s spaciousness; a lower early IACC corresponds to greater apparent source width.','Binaural Metric',ARRAY['HRTF','Externalization','Equalization-cancellation model','Front–back reversal','Crosstalk cancellation']::text[],ARRAY['Confusing the IACC (a similarity measure) with the interaural time difference (a delay).','Assuming higher IACC is always better, when spaciousness wants lower values.','Ignoring the analysis window and frequency band (early versus late, per octave).']::text[],ARRAY['Rating concert-hall acoustics.','Measuring apparent source width and envelopment.','Binaural models of lateralization.']::text[],'advanced','IACC = max over |tau|<=1ms of [ integral pL(t)*pR(t+tau) dt / sqrt(integral pL^2 dt * integral pR^2 dt) ]','The coefficient is the largest value, over interaural delays up to about one millisecond, of the two ear signals'' cross-correlation normalised by the square root of the product of their energies.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Interaural cross-correlation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fea11254-bf3d-4baa-a362-f15d85bca85d','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fea11254-bf3d-4baa-a362-f15d85bca85d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fea11254-bf3d-4baa-a362-f15d85bca85d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '34249f49-e759-4f09-82bc-500b1b55bb51','Intracranial localization','Intracranial (in-head) localization is the auditory phenomenon in which a sound image is perceived inside the head, positioned along the interaural axis rather than externalized in the surrounding space. It typically arises during headphone listening when the reproduced binaural cues lack the spectral and reverberant information needed for externalization.','Sometimes a sound seems to come from inside your head. This often happens with headphones. The brain cannot place the sound outside because key cues are missing. Adding ear-shape filtering and room echo helps push the image outside.','The concept explains why headphone stereo can fail to sound external, guiding designers of binaural and virtual-audio systems toward realistic out-of-head imaging.','A technician rendering binaural audio applies individualized head-related transfer functions and a little reverberation so the image sits outside the head instead of collapsing between the ears.','Spatial Hearing',ARRAY['Lateralization','Externalization','Head-related transfer function','Binaural reproduction','Interaural time difference']::text[],ARRAY['Assuming in-head localization only comes from cheap headphones rather than from missing spatial cues.','Confusing intracranial localization with simple left-right lateralization.','Believing louder playback fixes the lack of externalization.']::text[],ARRAY['Diagnosing why a binaural mix sounds trapped between the ears on headphones.','Comparing loudspeaker imaging with headphone imaging.','Designing a virtual-reality audio engine that must externalize sources.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Intracranial localization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '34249f49-e759-4f09-82bc-500b1b55bb51','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='34249f49-e759-4f09-82bc-500b1b55bb51') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='34249f49-e759-4f09-82bc-500b1b55bb51');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7ce12812-d8d4-45db-9edd-313a5f5a53cd','Kirchhoff–Helmholtz integral','The Kirchhoff-Helmholtz integral expresses the sound pressure at any point inside a source-free region as a surface integral of the pressure and its normal gradient over the region''s boundary, weighted by the free-space Green''s function. It is the mathematical basis for acoustic holography and wave field synthesis.','This equation rebuilds the sound inside a space from values on its surface. You need the pressure and its flow across that surface. From those boundary values you can compute the field everywhere inside. It underpins wave field synthesis and acoustic holography.','It formalizes how a bounding surface of sources can recreate a target sound field, providing the theory behind wave field synthesis loudspeaker arrays.','In a wave field synthesis install, the integral is discretized so a line of loudspeakers on the room boundary reconstructs a virtual source''s wavefront for listeners inside.','Spatial Audio',ARRAY['Wave field synthesis','Nearfield acoustical holography','Rayleigh integral','Green''s function','Boundary integral']::text[],ARRAY['Forgetting that both pressure and its normal derivative on the boundary are required.','Assuming it holds when sources lie inside the region of interest.','Ignoring that real arrays only approximate the continuous surface integral.']::text[],ARRAY['Deriving driving signals for a wave field synthesis array.','Performing nearfield acoustical holography on a vibrating panel.','Explaining the theory linking boundary sources to interior fields.']::text[],'advanced','p(r) = ∮_S [ G(r|r_s) ∂p(r_s)/∂n - p(r_s) ∂G(r|r_s)/∂n ] dS','The pressure at an interior point equals a closed surface integral over the boundary of the Green''s function times the normal gradient of pressure, minus the pressure times the normal gradient of the Green''s function.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Kirchhoff–Helmholtz integral');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7ce12812-d8d4-45db-9edd-313a5f5a53cd','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7ce12812-d8d4-45db-9edd-313a5f5a53cd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7ce12812-d8d4-45db-9edd-313a5f5a53cd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e9fdaa6f-c4f0-4256-b20f-758844ebde8e','Langevin transducer','A Langevin transducer is a bolt-clamped sandwich transducer in which piezoelectric ceramic rings are pre-stressed between two metal end masses to form a half-wavelength resonator for high-power, relatively low-frequency ultrasound. Developed by Paul Langevin for early sonar, it remains the standard driver for ultrasonic cleaning, welding, and sonar projectors.','This transducer bolts piezo ceramic rings between two metal masses. The clamp keeps the brittle ceramic under squeeze so it can be driven hard. It resonates to make strong low-frequency ultrasound. It powers sonar, cleaning tanks, and ultrasonic welders.','It produces high-intensity ultrasound at kilohertz-to-low-megahertz frequencies while protecting the ceramic with mechanical pre-load, enabling durable high-power sources.','A technician tunes the drive frequency to the stack''s mechanical resonance so an ultrasonic cleaning or welding horn delivers maximum vibration amplitude.','Ultrasonic Transducer',ARRAY['Piezoelectric stack','Piezoelectric element','Sonar projector','Ultrasonic cleaning','Resonant frequency']::text[],ARRAY['Thinking the bolt is structural only, not a pre-stress that keeps ceramic in compression.','Driving it off resonance and losing most of the output amplitude.','UNSAFE: touching or immersing a hand near a high-power ultrasonic horn, where cavitation and heating can burn or damage tissue.']::text[],ARRAY['Servicing an ultrasonic cleaning tank driver.','Designing a low-frequency sonar projector.','Tuning an ultrasonic plastic-welding stack to resonance.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Langevin transducer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e9fdaa6f-c4f0-4256-b20f-758844ebde8e','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e9fdaa6f-c4f0-4256-b20f-758844ebde8e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e9fdaa6f-c4f0-4256-b20f-758844ebde8e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f289872f-65e4-4ac3-9ba4-f8aee7772415','Lateral mode','A lateral mode is a vibration of a piezoelectric element in a direction perpendicular to its intended thickness (through-thickness) mode, driven by the element''s width or radial dimensions. In array transducers these lateral resonances are spurious, stealing energy and creating unwanted responses near the operating band.','A piezo plate is meant to vibrate through its thickness. Its width can also ring at its own frequency. That sideways motion is a lateral mode. In arrays it is unwanted and blurs the response. Designers shape element size to push it away.','Understanding lateral modes lets transducer designers dimension elements so spurious width resonances do not interfere with the desired thickness-mode output.','An array designer sets a small element width-to-thickness ratio and adds kerf cuts so lateral modes fall outside the imaging bandwidth.','Ultrasonic Transducer',ARRAY['Thickness mode','Piezoelectric element','Phased-array ultrasonics','Resonant frequency','Piezoelectric micromachined ultrasonic transducer']::text[],ARRAY['Assuming a piezo element vibrates only in its thickness direction.','Ignoring width-mode coupling when dicing array elements.','Confusing the spurious lateral mode with useful lateral resolution.']::text[],ARRAY['Diagnosing spurious peaks in a transducer impedance sweep.','Choosing element aspect ratio for a phased array.','Explaining crosstalk between array elements.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lateral mode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f289872f-65e4-4ac3-9ba4-f8aee7772415','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f289872f-65e4-4ac3-9ba4-f8aee7772415') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f289872f-65e4-4ac3-9ba4-f8aee7772415');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b2fa812d-ac3c-403d-bfb8-b707c3c961ed','Lateral resolution','Lateral resolution is the smallest separation, measured perpendicular to the beam axis, at which two reflectors can be distinguished in an ultrasonic image. It is governed by the beam width at the target depth, which at the focus is approximately the f-number multiplied by the wavelength.','Lateral resolution is side-to-side detail in an ultrasound image. Two points can be told apart only if the beam is narrower than their spacing. A narrow beam gives fine detail. Higher frequency and a wider aperture make the beam narrower.','It quantifies the side-to-side sharpness of an ultrasound or sonar image, setting the limit on how close two targets can be and still be resolved.','At a focus with f-number 2 and a 5 MHz beam in tissue (wavelength about 0.31 mm), lateral resolution is roughly 2 x 0.31 = 0.6 mm.','Ultrasonic Imaging',ARRAY['Axial resolution','Near-field length','Phased-array ultrasonics','Beamforming','Pulse-echo mode']::text[],ARRAY['Confusing lateral resolution (across the beam) with axial resolution (along the beam).','Assuming resolution is constant with depth rather than best near the focus.','Believing higher frequency helps resolution without cost to penetration depth.']::text[],ARRAY['Selecting a transducer frequency for a small target.','Setting the focal depth on a scanner.','Explaining why an image blurs away from the focal zone.']::text[],'intermediate','R_lat ≈ F# × λ = (F / D) × λ','Lateral resolution at the focus is approximately the f-number times the wavelength, where the f-number is the focal length divided by the aperture diameter.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lateral resolution');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b2fa812d-ac3c-403d-bfb8-b707c3c961ed','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b2fa812d-ac3c-403d-bfb8-b707c3c961ed') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b2fa812d-ac3c-403d-bfb8-b707c3c961ed');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e14cf8d5-d715-41fd-a0b4-84df6aeffa73','Loudness level','Loudness level, expressed in phons, is the sound pressure level in decibels of a 1 kHz free-field pure tone judged equally loud as the sound in question. Equal-loudness contours (ISO 226) map how sound pressure level must change with frequency to preserve a given loudness level.','Loudness level rates how loud a sound seems, in units called phons. It equals the level of a 1000 Hz tone that sounds just as loud. Two sounds at the same phon value seem equally loud. The ear needs different levels at different pitches.','It provides a perceptual loudness reference that accounts for the ear''s frequency-dependent sensitivity, unlike a plain decibel sound pressure level.','A tone rated 60 phons converts to loudness in sones by N = 2^((60 - 40)/10) = 4 sones, a useful check when setting perceived-loudness targets.','Psychoacoustics',ARRAY['Loudness summation','Equal-loudness contour','Sone','Phon','A-weighting']::text[],ARRAY['Treating phons as decibels, when they only coincide at 1 kHz.','Assuming equal decibel levels at different frequencies sound equally loud.','Confusing loudness level in phons with loudness in sones.']::text[],ARRAY['Reading equal-loudness contours when choosing EQ.','Comparing perceived loudness of tones at different frequencies.','Explaining why bass needs more level to match a midrange tone.']::text[],'intermediate','N = 2^((L_N - 40) / 10) sones','Loudness in sones equals two raised to the loudness level in phons minus forty, all divided by ten; loudness doubles for each 10-phon increase above 40 phons.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Loudness level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e14cf8d5-d715-41fd-a0b4-84df6aeffa73','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e14cf8d5-d715-41fd-a0b4-84df6aeffa73') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e14cf8d5-d715-41fd-a0b4-84df6aeffa73');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '154a182f-7da1-4e1a-a9b3-804fb372fbef','Loudness summation','Loudness summation is the way the auditory system combines partial loudness contributions across frequency and time to yield a single perceived loudness. In Zwicker''s model the total loudness in sones is the integral of specific loudness over the critical-band-rate (Bark) scale.','The ear adds up loudness from all frequencies to get one overall loudness. Sound spread across many critical bands seems louder than the same energy in one band. Zwicker''s model sums loudness across the frequency bands. It also builds up over short times.','It models how spectral spread and duration affect perceived loudness, forming the core of standardized loudness meters.','Total loudness is computed as N = the integral of specific loudness N''(z) over the 0 to 24 Bark scale, the calculation standardized in ISO 532-1.','Psychoacoustics',ARRAY['Loudness level','Critical band','Specific loudness','Sone','Masking']::text[],ARRAY['Assuming loudness sums like acoustic energy in decibels.','Ignoring that wideband sound is louder than narrowband sound of equal energy.','Overlooking temporal summation for short sounds.']::text[],ARRAY['Predicting the loudness of a broadband noise.','Using a Zwicker loudness meter on product sound.','Explaining why spreading energy across bands raises loudness.']::text[],'advanced','N = ∫_0^{24 Bark} N''(z) dz','Total loudness in sones equals the integral of the specific loudness over the critical-band-rate scale from zero to twenty-four Bark.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Loudness summation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '154a182f-7da1-4e1a-a9b3-804fb372fbef','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='154a182f-7da1-4e1a-a9b3-804fb372fbef') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='154a182f-7da1-4e1a-a9b3-804fb372fbef');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '92a92f1f-1427-451b-b028-158a9a4c868d','Matched-field processing','Matched-field processing is an array method that localizes an underwater source by correlating the measured acoustic field across a hydrophone array with replica fields predicted by an ocean acoustic propagation model. Peaks in the correlation over trial range, depth, and bearing indicate the source location.','This method finds an underwater sound source using a whole array. A computer models how sound would travel from many trial positions. It compares each model to the real measured field. The best match reveals the source range and depth.','It extends beamforming from direction-only to full range-and-depth localization by exploiting a physics-based model of sound propagation in the ocean.','An operator runs a propagation model for a grid of ranges and depths, then reads the ambiguity surface peak to estimate a quiet source''s position.','Underwater Acoustics',ARRAY['Beamforming','Passive sonar','Multipath propagation','Planar sonar array','Normal modes']::text[],ARRAY['Treating it as plain beamforming without a propagation model.','Ignoring environmental mismatch, which smears or shifts the location estimate.','Assuming a single unambiguous peak in a complex waveguide.']::text[],ARRAY['Localizing a quiet submarine in a shallow-water channel.','Estimating source depth from a bottom-mounted array.','Studying sensitivity to sound-speed-profile errors.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Matched-field processing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '92a92f1f-1427-451b-b028-158a9a4c868d','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='92a92f1f-1427-451b-b028-158a9a4c868d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='92a92f1f-1427-451b-b028-158a9a4c868d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5b7bdfd8-3aa2-47aa-a76e-4525636e253e','Mel scale','The mel scale is a perceptual pitch scale on which listeners judge pitches to be equal in distance from one another, anchored so that 1000 mels equals a 1 kHz tone at 40 dB above threshold. A widely used approximation maps frequency to mels with a logarithmic relation.','The mel scale measures pitch the way people hear it. Equal steps in mels sound like equal pitch jumps. By definition 1000 Hz equals 1000 mels. Above about 500 Hz the scale grows slower than frequency. Speech systems use it a lot.','It provides a pitch scale matched to perception, widely used to space filter banks in speech recognition and audio feature extraction.','Using the common formula, 1000 Hz maps to 2595 x log10(1 + 1000/700) = 1000 mels, matching the scale''s anchor point.','Psychoacoustics',ARRAY['Bark scale','Critical band','Pitch','Loudness level','Equivalent rectangular bandwidth']::text[],ARRAY['Assuming the mel scale is exactly logarithmic across all frequencies.','Treating mels as a physical rather than perceptual unit.','Using a single formula constant as if it were universally standardized.']::text[],ARRAY['Designing a mel filter bank for speech features.','Comparing perceptual pitch scales.','Explaining why pitch spacing compresses at high frequency.']::text[],'intermediate','m = 2595 × log10(1 + f / 700)','The mel value equals 2595 times the base-ten logarithm of one plus the frequency in hertz divided by 700.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mel scale');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5b7bdfd8-3aa2-47aa-a76e-4525636e253e','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5b7bdfd8-3aa2-47aa-a76e-4525636e253e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5b7bdfd8-3aa2-47aa-a76e-4525636e253e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '845fe83d-259f-4bc0-85be-0b4b123453da','Multibeam sonar','A multibeam sonar (multibeam echosounder) transmits a wide fan of sound and uses beamforming on a receiver array to form many narrow beams across a swath, measuring water depth or target range in each beam. It maps the seafloor efficiently in a single pass rather than one point at a time.','A multibeam sonar sends out a fan of sound across the seabed. Its receiver splits the returns into many narrow beams. Each beam measures depth in a different direction. One pass maps a wide strip of seafloor at once.','It provides fast, wide-swath bathymetric mapping by resolving many across-track directions simultaneously through receive beamforming.','A survey technician mounts the array athwartships, applies roll and sound-speed corrections, and stitches successive swaths into a seafloor depth map.','Underwater Acoustics',ARRAY['Beamforming','Planar sonar array','Pulse-echo mode','Multipath propagation','Pinger']::text[],ARRAY['Neglecting sound-speed profile correction, which bends the beams and distorts depths.','Confusing across-track beam count with along-track resolution.','Ignoring motion (roll and heave) compensation.']::text[],ARRAY['Hydrographic seafloor mapping surveys.','Locating a wreck or pipeline across a swath.','Calibrating a multibeam system against a reference surface.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Multibeam sonar');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '845fe83d-259f-4bc0-85be-0b4b123453da','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='845fe83d-259f-4bc0-85be-0b4b123453da') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='845fe83d-259f-4bc0-85be-0b4b123453da');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bb54aade-3e80-49a0-94d0-557d6cddcb86','Multipath propagation','Multipath propagation is the arrival of sound at a receiver by more than one path, such as direct, surface-reflected, bottom-reflected, and refracted rays, producing multiple time-delayed copies that interfere. Underwater it causes signal spreading, fading, and echo structure that complicates detection and communication.','Sound can reach a receiver by several routes at once. Some rays go straight, others bounce off the surface or seabed. These copies arrive at slightly different times. They add and cancel, smearing or fading the signal.','The concept explains interference, fading, and delay spread in real acoustic channels, guiding equalization and array design that manage or exploit the extra paths.','In an acoustic modem link, a technician measures the channel delay spread and sets an equalizer or guard interval long enough to absorb the multipath echoes.','Underwater Acoustics',ARRAY['Multibeam sonar','Transmission loss','Matched-field processing','Sound speed profile','Reverberation']::text[],ARRAY['Assuming only the direct path carries the signal.','Ignoring surface and bottom bounces when predicting arrivals.','Treating multipath purely as noise rather than exploitable structure.']::text[],ARRAY['Designing an underwater acoustic communication link.','Interpreting multiple arrivals on a sonar display.','Modeling a shallow-water channel with ray tracing.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Multipath propagation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bb54aade-3e80-49a0-94d0-557d6cddcb86','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bb54aade-3e80-49a0-94d0-557d6cddcb86') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bb54aade-3e80-49a0-94d0-557d6cddcb86');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'db5027cf-e52b-43e6-acac-540175d87f03','Multizone reproduction','Multizone reproduction uses a shared loudspeaker array and signal processing to create different, independently controlled sound fields in separate spatial zones of a room. Each zone can receive its own program (a bright zone) while other zones are kept quiet (dark zones).','Multizone reproduction plays different audio in different parts of one room. One shared set of speakers serves all zones. Signal processing steers sound into each target zone. Other zones are kept quiet at the same time.','It lets one loudspeaker system deliver distinct audio to different listeners without headphones, by controlling the sound field zone by zone.','An engineer defines control points in each zone and solves for the loudspeaker filters that maximize the bright-zone level while minimizing dark-zone leakage.','Spatial Audio',ARRAY['Personal sound zone','Pressure matching','Acoustic contrast control','Beamforming','Wave field synthesis']::text[],ARRAY['Expecting perfect isolation between zones, which real arrays only approximate.','Ignoring the trade-off between bright-zone accuracy and dark-zone quiet.','Assuming performance holds across all frequencies equally.']::text[],ARRAY['Delivering separate audio to front and rear car seats.','Creating a quiet zone beside a listening zone in a room.','Prototyping headphone-free personal audio.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Multizone reproduction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'db5027cf-e52b-43e6-acac-540175d87f03','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='db5027cf-e52b-43e6-acac-540175d87f03') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='db5027cf-e52b-43e6-acac-540175d87f03');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e31b02be-cfb2-4c6b-bcf2-31b69bd0c6bd','Near-field compensation','Near-field compensation, in near-field-compensated higher-order Ambisonics (NFC-HOA), is a set of filters that correct for the finite distance of real loudspeakers, which radiate curved rather than plane wavefronts. It stabilizes the encoded distance and curvature of virtual sources during Ambisonic decoding.','Real speakers sit a finite distance away, so their waves curve. Ideal Ambisonics assumes flat waves from infinitely far away. Near-field compensation adds filters that fix this gap. It keeps virtual source distance and curvature correct.','It reconciles the point-source behavior of physical loudspeakers with Ambisonic theory, preventing unstable bass boost and distance errors in higher-order decoding.','A technician sets the decoder''s loudspeaker-radius parameter so the near-field compensation filters match the actual speaker distance, taming low-frequency gain.','Spatial Audio',ARRAY['Ambisonics','Spherical harmonics','Wave field synthesis','Kirchhoff-Helmholtz integral','Higher-order Ambisonics']::text[],ARRAY['Confusing this Ambisonic filter with the ultrasonic transducer near field.','Omitting the compensation and getting extreme low-frequency boost.','Entering the wrong loudspeaker radius, which mis-scales source distance.']::text[],ARRAY['Configuring a higher-order Ambisonic decoder.','Rendering near virtual sources over a speaker ring.','Debugging excessive bass in an Ambisonic playback rig.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Near-field compensation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e31b02be-cfb2-4c6b-bcf2-31b69bd0c6bd','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e31b02be-cfb2-4c6b-bcf2-31b69bd0c6bd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e31b02be-cfb2-4c6b-bcf2-31b69bd0c6bd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0950d0ab-1d1f-4b11-8731-c040b4f7444e','Near-field length','The near-field length (near-field distance) of an ultrasonic transducer is the axial distance from the face to the last on-axis pressure maximum, marking the boundary between the near field (Fresnel zone) and the far field (Fraunhofer zone). For a circular piston it is approximately the square of the diameter divided by four wavelengths.','Near a transducer the sound pressure swings up and down along the axis. The near-field length is the distance to the last of these peaks. Beyond it the beam settles and spreads out. This point is also the transducer''s natural focus.','It tells the technician where the beam is most collimated and best focused, which sets the optimal working range for inspection or imaging.','For a 10 mm disc at 5 MHz in water (wavelength 0.296 mm), the near-field length is about 10^2 / (4 x 0.296) = 84 mm.','Ultrasonic Transducer',ARRAY['Far field','Beam divergence','Lateral resolution','Piezoelectric element','Phased-array ultrasonics']::text[],ARRAY['Confusing near-field length with beam divergence in the far field.','Applying the circular-piston formula directly to rectangular elements without correction.','Assuming best resolution occurs at the transducer face rather than near the near-field length.']::text[],ARRAY['Choosing a transducer so a flaw sits at the natural focus.','Setting up an ultrasonic thickness gauge.','Explaining on-axis pressure oscillations in the near field.']::text[],'intermediate','N = D^2 / (4λ) = D^2 f / (4c)','The near-field length equals the transducer diameter squared divided by four times the wavelength, equivalently the diameter squared times frequency divided by four times the sound speed.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Near-field length');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0950d0ab-1d1f-4b11-8731-c040b4f7444e','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0950d0ab-1d1f-4b11-8731-c040b4f7444e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0950d0ab-1d1f-4b11-8731-c040b4f7444e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3dc52c76-5fda-4c0b-a805-9bf1a1d958e4','Onset synchrony','Onset synchrony is an auditory grouping cue whereby frequency components that begin at the same time are perceived as belonging to one sound source. Conversely, a component with an asynchronous onset tends to segregate and be heard as a separate event.','Sounds that start together tend to fuse into one source. The brain uses shared start time as a grouping clue. A tone that starts late stands out on its own. This helps us separate overlapping sounds.','It is one of the cues the auditory system uses to organize a mixture into separate sources, central to auditory scene analysis.','A mix engineer slightly staggers the onset of a layered instrument so it separates from the rest, or aligns onsets tightly to fuse layers into one voice.','Psychoacoustics',ARRAY['Auditory scene analysis','Harmonicity','Common fate','Masking','Timbre']::text[],ARRAY['Assuming pitch alone determines grouping, ignoring onset timing.','Overlooking that a mistuned or late-starting harmonic pops out.','Confusing onset synchrony with simple loudness balance.']::text[],ARRAY['Explaining why an instrument blends or stands out in a mix.','Studying stream segregation in a lab task.','Designing a source-separation algorithm.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Onset synchrony');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3dc52c76-5fda-4c0b-a805-9bf1a1d958e4','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3dc52c76-5fda-4c0b-a805-9bf1a1d958e4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3dc52c76-5fda-4c0b-a805-9bf1a1d958e4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3054cd61-9ff0-4602-bc76-757b184ee33c','PMUT','A PMUT (piezoelectric micromachined ultrasonic transducer) is a MEMS device in which a thin piezoelectric film deposited on a flexible diaphragm vibrates in a flexural (bending) mode to transmit and receive ultrasound. Fabricated with semiconductor processes, PMUTs are small, low-voltage, and easily formed into arrays.','A PMUT is a tiny chip-based ultrasound transducer. A thin piezo layer sits on a small drum-like membrane. The membrane bends to make and sense ultrasound. Many can be built together on one chip at low voltage.','It brings ultrasound generation onto a microchip, enabling compact, low-power, array-friendly sensors for fingerprint readers, rangefinders, and medical imaging.','A designer integrates a PMUT array with drive electronics on a small module to build an in-display ultrasonic fingerprint sensor.','Ultrasonic Transducer',ARRAY['Piezoelectric micromachined ultrasonic transducer','Piezoelectric element','Lateral mode','Phased-array ultrasonics','Pulse-echo mode']::text[],ARRAY['Assuming a PMUT vibrates in thickness mode like a bulk element, when it bends.','Confusing PMUTs with capacitive micromachined transducers (CMUTs).','Expecting bulk-transducer power levels from a thin-film device.']::text[],ARRAY['Building an ultrasonic fingerprint sensor.','Making a compact time-of-flight rangefinder.','Prototyping a wearable ultrasound patch.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='PMUT');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3054cd61-9ff0-4602-bc76-757b184ee33c','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3054cd61-9ff0-4602-bc76-757b184ee33c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3054cd61-9ff0-4602-bc76-757b184ee33c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b94cbd4b-4d07-473a-b506-bfa0a17aeaea','Particle-velocity hydrophone','A particle-velocity hydrophone (velocity sensor) measures the vector acoustic particle velocity of the water rather than the scalar pressure sensed by a conventional hydrophone. Combined with a pressure sensor it forms an acoustic vector sensor that can resolve source direction from a single point.','Most hydrophones measure sound pressure only. A particle-velocity hydrophone measures how the water particles move. Because motion has direction, it senses which way sound comes from. Paired with a pressure sensor it finds bearing from one spot.','It captures the directional (vector) part of the sound field, giving direction-finding capability that a single pressure sensor cannot provide.','A technician deploys a vector sensor that combines pressure and three velocity components to estimate a source bearing without a large array.','Underwater Acoustics',ARRAY['Pressure hydrophone','Acoustic vector sensor','Sound intensity','Passive sonar','Beamforming']::text[],ARRAY['Assuming any hydrophone senses direction, when a pressure sensor does not.','Ignoring that velocity sensors are sensitive to flow and vibration noise.','Confusing particle velocity with the propagation speed of sound.']::text[],ARRAY['Compact single-point bearing estimation.','Measuring underwater sound intensity vectors.','Building a low-element-count direction finder.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Particle-velocity hydrophone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b94cbd4b-4d07-473a-b506-bfa0a17aeaea','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b94cbd4b-4d07-473a-b506-bfa0a17aeaea') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b94cbd4b-4d07-473a-b506-bfa0a17aeaea');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8d980e41-545f-424e-a268-bf889f75b04b','Passive sonar','Passive sonar detects, tracks, or classifies a target by listening to the sound it radiates, without transmitting any acoustic energy of its own. Its performance is described by the passive sonar equation, balancing source level and noise against detection threshold over the propagation path.','Passive sonar only listens; it never pings. It picks up the noise a ship or submarine makes. Because it stays silent, it does not reveal itself. Its range depends on target noise and background noise.','It enables covert detection by exploiting target-radiated noise, trading the range advantage of active sonar for stealth.','An operator applies the passive sonar equation, subtracting noise level and adding array gain, to judge whether a contact''s radiated level exceeds the detection threshold.','Underwater Acoustics',ARRAY['Active sonar','Processing gain','Pressure hydrophone','Planar sonar array','Matched-field processing']::text[],ARRAY['Confusing passive sonar with active sonar that transmits pings.','Forgetting that array gain and integration improve passive detection.','Assuming detection depends only on target loudness, not on ambient noise.']::text[],ARRAY['Listening for a quiet submarine''s radiated noise.','Monitoring shipping traffic acoustically.','Estimating detection range from the passive sonar equation.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Passive sonar');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8d980e41-545f-424e-a268-bf889f75b04b','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8d980e41-545f-424e-a268-bf889f75b04b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8d980e41-545f-424e-a268-bf889f75b04b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '38a1f894-6553-4d16-9923-801d2c6f7b16','Personal sound zone','A personal sound zone is a region of space in which a listener receives an intended audio program at useful level while the same program is suppressed elsewhere, produced by a loudspeaker array and dedicated signal processing. It is the single-listener case of multizone sound-field control.','A personal sound zone gives one person their own audio in open space. A speaker array focuses their sound to that spot. Nearby areas stay much quieter. No headphones are needed.','It delivers private or individualized listening without headphones by concentrating acoustic energy in one zone and reducing leakage to others.','An engineer places control points around a seat and computes array filters that raise level in that seat while minimizing energy at neighboring seats.','Spatial Audio',ARRAY['Multizone reproduction','Pressure matching','Acoustic contrast control','Beamforming','Wave field synthesis']::text[],ARRAY['Expecting total silence outside the zone rather than a level reduction.','Ignoring how zone isolation degrades at low frequencies.','Assuming a single speaker can form a tight zone without an array.']::text[],ARRAY['Giving each car seat its own audio program.','Creating a personal listening spot at a museum exhibit.','Comparing contrast-control and pressure-matching designs.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Personal sound zone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '38a1f894-6553-4d16-9923-801d2c6f7b16','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='38a1f894-6553-4d16-9923-801d2c6f7b16') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='38a1f894-6553-4d16-9923-801d2c6f7b16');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '54a76c9c-eb64-4262-8255-aa056d67cbc8','Phased-array ultrasonics','Phased-array ultrasonics uses a transducer made of many small elements driven with individually controlled time delays, so the combined beam can be electronically steered and focused without moving the probe. It is used in nondestructive testing, medical imaging, and high-intensity focused ultrasound therapy.','A phased array has many small ultrasound elements in one probe. Each element fires with its own tiny time delay. Those delays steer and focus the beam electronically. The probe stays still while the beam sweeps and focuses.','It replaces mechanical scanning with electronic beam steering and focusing, giving fast, flexible control of the ultrasound beam.','A nondestructive-testing technician sets element delay laws to sweep the beam through a weld and image flaws at multiple angles from one probe position.','Ultrasonic Imaging',ARRAY['Beamforming','Lateral resolution','Piezoelectric element','Pulse-echo mode','Near-field length']::text[],ARRAY['Assuming the whole array fires simultaneously rather than with a delay law.','Ignoring grating lobes from too-large element spacing.','UNSAFE: operating high-intensity focused ultrasound near tissue without dosimetry, since the focus can cause thermal burns and cavitation damage.']::text[],ARRAY['Weld inspection with electronic beam sweeps.','Cardiac or vascular medical imaging.','Delivering focused thermal therapy in HIFU treatment.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phased-array ultrasonics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '54a76c9c-eb64-4262-8255-aa056d67cbc8','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='54a76c9c-eb64-4262-8255-aa056d67cbc8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='54a76c9c-eb64-4262-8255-aa056d67cbc8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4beffbd2-b016-4499-b92a-d474218466e7','Piezoelectric element','A piezoelectric element is a piece of piezoelectric ceramic or crystal that converts electrical energy to mechanical strain and vice versa, serving as the active core of an ultrasonic transducer. Driven near its thickness-mode resonance, it radiates ultrasound and, on receiving echoes, generates a voltage.','A piezoelectric element turns voltage into motion and motion into voltage. Apply voltage and it changes shape slightly. That motion makes ultrasound. When echoes push back, it makes a small voltage the system reads.','It is the transduction heart of most ultrasonic devices, linking the electrical drive circuit to the acoustic wave in both transmit and receive.','A technician selects an element whose thickness sets a half-wavelength at the desired frequency, since resonance occurs when thickness equals half the acoustic wavelength.','Ultrasonic Transducer',ARRAY['Piezoelectric stack','Thickness mode','Lateral mode','Langevin transducer','Resonant frequency']::text[],ARRAY['Assuming any ceramic is piezoelectric before it has been poled, that is, aligned by a strong electric field during manufacture; without poling it gives no useful signal.','Ignoring the Curie temperature, the heat level above which the material loses both its poling (that alignment) and its piezoelectric behavior.','Confusing the element''s useful thickness (front-to-back) resonance with its lateral modes, which are unwanted side-to-side vibrations.']::text[],ARRAY['Choosing element thickness for a target frequency.','Replacing a cracked element in a transducer.','Explaining transmit and receive transduction.']::text[],'beginner',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Piezoelectric element');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4beffbd2-b016-4499-b92a-d474218466e7','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4beffbd2-b016-4499-b92a-d474218466e7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4beffbd2-b016-4499-b92a-d474218466e7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '25dc1a4d-8935-4e2f-a1c4-c8a47f038879','Piezoelectric micromachined ultrasonic transducer','A piezoelectric micromachined ultrasonic transducer (PMUT) is a microelectromechanical (MEMS) ultrasonic device in which a thin piezoelectric film on a suspended diaphragm vibrates in flexure to emit and detect ultrasound. Batch-fabricated on wafers, PMUTs enable compact, low-voltage transducer arrays.','This is the full name for a PMUT. It is a tiny chip-made ultrasound transducer. A thin piezo film on a small membrane bends to make ultrasound. Wafer fabrication lets many be made together cheaply.','It miniaturizes ultrasonic transduction using semiconductor manufacturing, allowing dense, low-power arrays integrated with electronics.','An engineer specifies a PMUT array module for an ultrasonic fingerprint reader or a short-range time-of-flight sensor.','Ultrasonic Transducer',ARRAY['PMUT','Piezoelectric element','Lateral mode','Phased-array ultrasonics','Pulse-echo mode']::text[],ARRAY['Assuming flexural (bending) motion is the same as bulk thickness-mode vibration.','Confusing it with a capacitive micromachined transducer (CMUT).','Expecting high-power output from a thin-film diaphragm device.']::text[],ARRAY['Under-display fingerprint sensing.','Compact gesture or proximity sensing.','Wearable ultrasound monitoring patches.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Piezoelectric micromachined ultrasonic transducer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '25dc1a4d-8935-4e2f-a1c4-c8a47f038879','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='25dc1a4d-8935-4e2f-a1c4-c8a47f038879') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='25dc1a4d-8935-4e2f-a1c4-c8a47f038879');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8255daad-17ae-4e88-aa40-12f39dba50be','Piezoelectric stack','A piezoelectric stack is an assembly of multiple thin piezoelectric layers mechanically in series and electrically in parallel, so that a modest drive voltage produces a summed displacement larger than a single layer could. Stacks provide the high force and displacement used in actuators and in bolt-clamped ultrasonic transducers.','A piezo stack layers many thin piezo plates together. Each layer adds a little motion. Together they move much more than one plate. This gives strong push at a lower drive voltage. Actuators and ultrasonic horns use them.','It multiplies displacement and force at practical voltages by stacking many thin layers, enabling precise actuators and powerful ultrasonic drivers.','A technician pre-loads a stack in compression inside a Langevin transducer so it can be driven hard without tensile cracking.','Ultrasonic Transducer',ARRAY['Langevin transducer','Piezoelectric element','Actuator','Resonant frequency','Thickness mode']::text[],ARRAY['Assuming thicker single elements match a multilayer stack''s low-voltage displacement.','Applying tension to a stack, which cracks the brittle ceramic.','UNSAFE: handling the drive leads of an energized high-voltage piezo stack, which can deliver a dangerous electric shock.']::text[],ARRAY['Driving an ultrasonic welding or cleaning horn.','Precision nanopositioning actuators.','Pre-stressing ceramic in a sandwich transducer.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Piezoelectric stack');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8255daad-17ae-4e88-aa40-12f39dba50be','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8255daad-17ae-4e88-aa40-12f39dba50be') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8255daad-17ae-4e88-aa40-12f39dba50be');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f8db7cf9-0994-44e7-901f-93c1991147a5','Pinger','A pinger is an underwater acoustic beacon that emits short, repetitive sound pulses at a fixed interval for locating, tracking, or positioning. Common examples include underwater locator beacons on aircraft flight recorders, which ping near 37.5 kHz, and pingers used in acoustic positioning of towed or moored equipment.','A pinger is a small underwater beacon. It sends out short beeps at a steady rate. Receivers use the beeps to find or track it. Flight recorder beacons and survey markers use pingers.','It provides a simple, detectable acoustic signature so a receiver can locate or range on the beacon underwater.','A search team listens for a flight recorder''s 37.5 kHz pulses with a directional hydrophone to home in on the wreckage.','Underwater Acoustics',ARRAY['Transponder','Pulse-echo mode','Passive sonar','Pressure hydrophone','Multibeam sonar']::text[],ARRAY['Confusing a pinger (transmit only) with a transponder that replies to interrogation.','Assuming detection range is unaffected by battery life and duty cycle.','UNSAFE: divers approaching a high-source-level acoustic source, since underwater sound exposure has recognized safe-distance limits.']::text[],ARRAY['Locating a downed aircraft''s flight recorder.','Positioning a towed sonar array.','Marking a moored instrument for recovery.']::text[],'beginner',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pinger');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f8db7cf9-0994-44e7-901f-93c1991147a5','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f8db7cf9-0994-44e7-901f-93c1991147a5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f8db7cf9-0994-44e7-901f-93c1991147a5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f7664ed3-58c8-4bd2-9056-5c8271570e8d','Planar sonar array','A planar sonar array is a two-dimensional arrangement of hydrophone (or projector) elements on a flat surface, allowing beamforming and beam steering in both azimuth and elevation. The flat geometry supports full two-axis directional control and higher array gain than a line array.','A planar sonar array lays many sensors on a flat panel. Because it is two-dimensional, it can steer beams left-right and up-down. A single line can only steer in one plane. The flat grid gives finer direction control.','It provides two-axis directivity and increased array gain, enabling three-dimensional bearing estimation and stronger rejection of off-axis noise.','A designer sets element spacing to about half a wavelength across the panel so beams steer in azimuth and elevation without grating lobes.','Underwater Acoustics',ARRAY['Beamforming','Multibeam sonar','Passive sonar','Matched-field processing','Pressure hydrophone']::text[],ARRAY['Spacing elements more than half a wavelength apart and creating grating lobes.','Assuming a planar array behaves like a single line array.','Ignoring mutual coupling between closely packed elements.']::text[],ARRAY['Hull-mounted two-axis steering arrays.','Three-dimensional bearing estimation.','Designing element spacing to suppress grating lobes.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Planar sonar array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f7664ed3-58c8-4bd2-9056-5c8271570e8d','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f7664ed3-58c8-4bd2-9056-5c8271570e8d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f7664ed3-58c8-4bd2-9056-5c8271570e8d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '25f9ce8f-19b8-4cc7-bf8f-48562258bf24','Pressure hydrophone','A pressure hydrophone is an underwater microphone that converts acoustic pressure into an electrical signal, typically using a piezoelectric sensing element. Its sensitivity is stated in decibels relative to 1 volt per micropascal, and it is calibrated against reference standards for accurate underwater sound measurement.','A pressure hydrophone is a microphone for use underwater. It turns sound pressure into a voltage. Its rating shows how much voltage each tiny pressure gives. Labs check it so readings stay correct.','It is the standard sensor for measuring underwater sound pressure, from ocean noise studies to sonar and calibration work.','A technician reads the calibration chart, then converts a measured voltage to sound pressure level in decibels relative to 1 micropascal using the stated sensitivity.','Underwater Acoustics',ARRAY['Particle-velocity hydrophone','Passive sonar','Planar sonar array','Sound pressure level','Pinger']::text[],ARRAY['Comparing underwater levels to the airborne 20 micropascal reference instead of 1 micropascal.','Ignoring the frequency limits of the calibrated response.','Assuming a pressure hydrophone senses direction, which it does not.']::text[],ARRAY['Measuring ambient ocean noise.','Calibrating a sonar projector''s source level.','Logging underwater sound for an environmental survey.']::text[],'beginner',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure hydrophone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '25f9ce8f-19b8-4cc7-bf8f-48562258bf24','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='25f9ce8f-19b8-4cc7-bf8f-48562258bf24') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='25f9ce8f-19b8-4cc7-bf8f-48562258bf24');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '24418383-8a36-4317-a6eb-489064f0116d','Pressure matching','Pressure matching is a sound-field control method that computes loudspeaker driving signals so the reproduced pressure at a set of control points best matches a desired target field, usually in a least-squares sense. It is a core technique for sound-zone and personal-audio systems.','Pressure matching picks speaker signals to hit a target sound at chosen points. It compares the reproduced pressure with the desired pressure. Then it solves for the speaker signals that fit best. Sound-zone systems rely on it.','It turns a desired sound field into concrete loudspeaker signals by solving a least-squares fit at control points, enabling multizone and personal audio.','An engineer measures transfer functions to each control point, then solves a regularized least-squares problem for the loudspeaker filters that match the target pressures.','Spatial Audio',ARRAY['Personal sound zone','Multizone reproduction','Acoustic contrast control','Wave field synthesis','Kirchhoff-Helmholtz integral']::text[],ARRAY['Omitting regularization, which yields huge, unstable filter gains.','Placing too few control points to constrain the field.','Assuming an exact match is possible at all frequencies and positions.']::text[],ARRAY['Designing filters for a personal sound zone.','Matching a target wavefront over a listening area.','Comparing pressure matching with acoustic contrast control.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure matching');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '24418383-8a36-4317-a6eb-489064f0116d','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='24418383-8a36-4317-a6eb-489064f0116d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='24418383-8a36-4317-a6eb-489064f0116d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dcbbdbea-4b44-4ad8-8626-d29347ead222','Processing gain','Processing gain is the improvement in signal-to-noise ratio a receiver obtains by coherently integrating a signal over time and bandwidth, relative to a single sample. For a signal integrated over time T with bandwidth B, the gain in decibels is ten times the base-ten logarithm of the time-bandwidth product.','Processing gain is the boost in signal clarity from listening longer and using bandwidth well. Averaging a signal over time raises it above the noise. The longer the integration, the bigger the boost. It is set by the time-bandwidth product.','It quantifies how much detection benefit comes from integration and coding, a key term in the sonar and communications equations.','Integrating for T = 10 s over a B = 1 kHz band gives a time-bandwidth product of 10,000, so processing gain is 10 x log10(10,000) = 40 dB.','Underwater Acoustics',ARRAY['Passive sonar','Matched-field processing','Beamforming','Signal-to-noise ratio','Detection threshold']::text[],ARRAY['Assuming gain grows without limit regardless of signal coherence time.','Confusing processing gain with amplifier voltage gain.','Ignoring that only coherent integration realizes the full time-bandwidth gain.']::text[],ARRAY['Estimating passive sonar detection improvement.','Designing integration time for a weak signal.','Analyzing spread-spectrum underwater communications.']::text[],'intermediate','PG = 10 log10(B × T)','Processing gain in decibels equals ten times the base-ten logarithm of the bandwidth multiplied by the integration time.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Processing gain');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dcbbdbea-4b44-4ad8-8626-d29347ead222','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dcbbdbea-4b44-4ad8-8626-d29347ead222') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dcbbdbea-4b44-4ad8-8626-d29347ead222');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5aa47df3-780e-42fc-8d4d-76bc89d51429','Pulse-echo mode','Pulse-echo mode is an operating scheme in which a single transducer transmits a short acoustic pulse and then receives the echo reflected from a target, with target range found from the round-trip travel time. It underlies ultrasonic flaw detection, medical B-mode imaging, and active sonar ranging.','In pulse-echo mode one transducer sends a short pulse, then listens for its echo. The time until the echo returns gives the distance. Halve the round trip because sound travels there and back. Flaw detectors, scanners, and sonar all use this.','It measures distance to reflectors using a single transducer for both transmit and receive, the basis of ranging and imaging.','In steel (sound speed 5900 m/s), an echo returning in 20 microseconds indicates a reflector at 5900 x 20e-6 / 2 = 0.059 m, about 59 mm deep.','Ultrasonic Imaging',ARRAY['Active sonar','Lateral resolution','Phased-array ultrasonics','Pulsed-wave Doppler']::text[],ARRAY['Forgetting to halve the round-trip time when computing range.','Using the wrong sound speed for the medium.','Confusing pulse-echo (one transducer) with through-transmission (two transducers).']::text[],ARRAY['Ultrasonic thickness gauging of a pipe wall.','Medical B-mode imaging.','Active sonar ranging on a target.']::text[],'beginner','d = c × t / 2','The distance to the reflector equals the sound speed times the round-trip echo time, divided by two.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pulse-echo mode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5aa47df3-780e-42fc-8d4d-76bc89d51429','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5aa47df3-780e-42fc-8d4d-76bc89d51429') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5aa47df3-780e-42fc-8d4d-76bc89d51429');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '94639db2-95e3-4322-879b-0a88c179cb93','Pulsed-wave Doppler','Pulsed-wave Doppler is an ultrasound technique that transmits repeated pulses and range-gates the echoes to measure blood or target velocity from a specific depth via the Doppler frequency shift. Because it samples at the pulse repetition frequency, the maximum unambiguous Doppler shift is limited to half that frequency (the Nyquist limit).','Pulsed-wave Doppler measures speed at a chosen depth with ultrasound. It sends pulses and reads the echo only from a set range. Motion shifts the echo frequency, revealing velocity. Sampling by pulses caps the top speed before aliasing.','It provides depth-specific velocity measurement, unlike continuous-wave Doppler, at the cost of a maximum measurable velocity set by the pulse repetition frequency.','At f0 = 5 MHz, blood at v = 0.5 m/s along the beam (theta = 0) in tissue (c = 1540 m/s) gives a Doppler shift of 2 x 5e6 x 0.5 / 1540 = about 3.2 kHz.','Ultrasonic Imaging',ARRAY['Pulse-echo mode','Nyquist frequency','Lateral resolution','Phased-array ultrasonics','Multipath propagation']::text[],ARRAY['Ignoring the cosine of the beam-to-flow angle, which underestimates velocity at steep angles.','Exceeding the Nyquist limit and misreading aliased velocity.','Confusing depth-selective pulsed-wave with non-selective continuous-wave Doppler.']::text[],ARRAY['Measuring blood-flow velocity at a chosen vessel depth.','Diagnosing aliasing when velocity exceeds the Nyquist limit.','Setting the angle-correction cursor along the flow direction.']::text[],'intermediate','f_d = 2 f_0 v cosθ / c ; |f_d| ≤ PRF / 2','The Doppler shift equals twice the transmit frequency times the velocity times the cosine of the beam-to-flow angle, divided by the sound speed; the measurable shift cannot exceed half the pulse repetition frequency.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pulsed-wave Doppler');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '94639db2-95e3-4322-879b-0a88c179cb93','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='94639db2-95e3-4322-879b-0a88c179cb93') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='94639db2-95e3-4322-879b-0a88c179cb93');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd01e860a-ec36-48e8-9c61-da3b7219bce2','Quarter-wave matching layer','A quarter-wave matching layer is a layer one quarter-wavelength thick at the operating frequency, placed between an ultrasonic transducer and its load medium. Its acoustic impedance is set near the geometric mean of the two adjoining impedances so reflections cancel and energy transfer is maximized at that frequency.','A thin coating sits on the face of an ultrasound probe. Its thickness is one quarter of the sound wavelength. It helps sound pass from the hard crystal into tissue or water. Without it, most of the sound would bounce back.','It reduces the large impedance mismatch between a stiff piezoelectric element and a lighter load, improving sensitivity and bandwidth.','For a crystal of Z1 = 30 MRayl coupling to water Z2 = 1.5 MRayl, the ideal single-layer impedance is sqrt(30 x 1.5) = 6.7 MRayl, made a quarter-wavelength thick in that material.','Ultrasonic Transducers',ARRAY['Shear mode','Sonotrode','Acoustic impedance','Backing layer']::text[],ARRAY['Assuming one layer perfectly matches any pair of media, when a single layer only works at its design frequency.','Confusing the geometric-mean impedance rule with a simple arithmetic average of the two impedances.','Measuring the quarter-wavelength in water or tissue instead of inside the layer material.']::text[],ARRAY['Designing a medical imaging probe to couple efficiently into skin.','Building an immersion transducer for nondestructive testing.','Explaining why probe bandwidth falls away from the design frequency.']::text[],'advanced','Z_m = sqrt(Z1 * Z2);  t = lambda_m / 4','The matching-layer impedance equals the square root of the product of the two bounding impedances, and its thickness is one quarter of the wavelength inside the layer.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Quarter-wave matching layer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd01e860a-ec36-48e8-9c61-da3b7219bce2','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d01e860a-ec36-48e8-9c61-da3b7219bce2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d01e860a-ec36-48e8-9c61-da3b7219bce2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2ea9157b-487f-4efd-b303-bb98c4efd25d','Radial filter','In spherical-microphone-array and Ambisonic processing, a radial filter is a frequency- and order-dependent equalization applied to each spherical-harmonic component to invert the array''s mode strength (its radial response), so every order contributes a flat response over frequency.','A spherical microphone splits sound into pattern layers called orders. Each order responds differently across frequency. A radial filter boosts or cuts each order to fix this. It lets the array rebuild the sound field correctly.','It equalizes the array''s mode strength so the decoded sound field or beam has a flat, order-independent frequency response.','When processing a rigid-sphere array recording, the engineer applies one radial filter per harmonic order and soft-limits its low-frequency gain to avoid amplifying microphone self-noise.','Spherical Array Processing',ARRAY['Spherical harmonic decomposition','Sound-field synthesis','Sound-zone control','Mode strength']::text[],ARRAY['Applying unlimited high gain at low frequency, which badly amplifies sensor noise.','Thinking the radial filter changes direction rather than the order-versus-frequency balance.','Using the same radial function for rigid and open sphere arrays, which need different ones.']::text[],ARRAY['Rendering a higher-order Ambisonic recording from a rigid-sphere microphone.','Diagnosing bright or noisy playback from a spherical array.','Setting soft-limiting on radial-filter gains.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Radial filter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2ea9157b-487f-4efd-b303-bb98c4efd25d','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2ea9157b-487f-4efd-b303-bb98c4efd25d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2ea9157b-487f-4efd-b303-bb98c4efd25d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5f375b95-17b9-4161-b7ec-e5dbbd9e94db','Residue pitch','Residue pitch is the low pitch heard at the fundamental frequency of a harmonic complex tone even when that fundamental component is physically absent, arising from the auditory system''s analysis of the spacing and periodicity of the higher harmonics.','Play several high harmonics of a tone but leave out the lowest one. You still hear a low pitch as if the low tone were there. The ear works out the pitch from the spacing of the harmonics. This is residue pitch.','It explains why the perceived pitch of a complex tone does not depend on energy actually being present at the fundamental frequency.','A small earbud that cannot reproduce a 100 Hz bass note can still convey its pitch, because listeners hear the residue pitch from the audible upper harmonics.','Pitch Perception',ARRAY['Spectral pitch','Temporal pitch','Missing fundamental','Virtual pitch']::text[],ARRAY['Assuming the pitch disappears when the fundamental is filtered out.','Confusing residue pitch with a distortion product created inside the loudspeaker.','Believing the ear inserts real energy at the missing fundamental frequency.']::text[],ARRAY['Explaining bass perception on small earbuds and phones.','Designing psychoacoustic bass enhancement that adds harmonics.','Teaching why telephone speech still sounds full.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Residue pitch');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5f375b95-17b9-4161-b7ec-e5dbbd9e94db','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5f375b95-17b9-4161-b7ec-e5dbbd9e94db') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5f375b95-17b9-4161-b7ec-e5dbbd9e94db');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '39581ffd-43f5-4a4e-9ed5-2b1ca71f367f','Reverberation level','In underwater sonar, reverberation level is the level of the unwanted scattered return reaching the receiver from scatterers in the water volume, at the surface, or on the bottom, expressed in dB re 1 microPascal. It is the interference term in the reverberation-limited sonar equation.','When a sonar pings, some sound scatters back from the sea itself. It bounces off the surface, seabed, bubbles, and marine life. This clutter is the reverberation level. It can hide a real target echo.','It quantifies the self-generated clutter from a sonar''s own transmission, which sets the detection limit in reverberation-limited conditions.','In the sonar equation, an echo is just detectable when SL - 2TL + TS = RL + DT; if reverberation dominates, raising source level does not help because reverberation level rises too.','Sonar Performance',ARRAY['Source level','Target strength','Surface duct','Sound-speed profile']::text[],ARRAY['Confusing reverberation with ambient sea noise; reverberation exists only while your own pulse scatters back.','Thinking a louder ping always helps, when it raises reverberation as much as the echo.','Treating reverberation level as fixed rather than decaying with time after transmit.']::text[],ARRAY['Setting pulse length and bandwidth to reduce reverberation.','Explaining why shallow-water sonar suffers heavy bottom reverberation.','Choosing between reverberation-limited and noise-limited detection analysis.']::text[],'advanced','SL - 2TL + TS = RL + DT  (reverberation-limited detection)','A target is just detectable when source level minus two-way transmission loss plus target strength equals reverberation level plus the detection threshold.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reverberation level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '39581ffd-43f5-4a4e-9ed5-2b1ca71f367f','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='39581ffd-43f5-4a4e-9ed5-2b1ca71f367f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='39581ffd-43f5-4a4e-9ed5-2b1ca71f367f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8a81fe16-54e4-4cd6-93ea-e10ce2aad2d3','Roughness','Roughness is a hearing sensation produced by rapid amplitude or frequency modulation, roughly in the 15-300 Hz modulation range and peaking near 70 Hz. It is measured in asper, where 1 asper is a 1 kHz tone at 60 dB fully amplitude-modulated at 70 Hz.','Fast wobble in a sound makes it feel rough or harsh. The wobble is too quick to hear as separate beats. Roughness is strongest when the sound changes about seventy times a second. Its unit is the asper.','It quantifies a key component of perceived harshness and of sensory (dis)pleasantness.','A product-sound engineer measures roughness in asper to judge whether a motor whine or alarm sounds harsh, then targets design changes that lower it.','Psychoacoustic Metrics',ARRAY['Sensory pleasantness','Simultaneous masking','Specific loudness','Fluctuation strength']::text[],ARRAY['Confusing roughness with fluctuation strength, which peaks at much slower modulation near 4 Hz.','Assuming roughness depends mainly on level, when it depends chiefly on modulation rate and depth.','Mixing up acoustic roughness with the surface roughness of a material.']::text[],ARRAY['Sound-quality tuning of vehicle or appliance noise.','Judging harshness of a distorted guitar tone.','Evaluating warning-signal designs for annoyance.']::text[],'intermediate',NULL,'One asper is defined as the roughness of a 1 kHz tone at 60 dB that is fully amplitude-modulated at a 70 Hz rate; roughness rises with modulation depth and is largest near a 70 Hz modulation rate.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Roughness');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8a81fe16-54e4-4cd6-93ea-e10ce2aad2d3','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8a81fe16-54e4-4cd6-93ea-e10ce2aad2d3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8a81fe16-54e4-4cd6-93ea-e10ce2aad2d3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6d395337-6220-41e5-9d09-7d132bf7b583','SOFAR channel','The SOFAR (Sound Fixing and Ranging) channel is a deep-ocean sound waveguide centered on the depth of minimum sound speed (the sound-channel axis, typically near 1000 m). Refraction repeatedly bends sound back toward this axis, letting low-frequency sound travel thousands of kilometers with little loss.','Deep in the ocean there is a layer where sound travels slowest. Sound bends back toward this layer instead of escaping. So low sounds get trapped and carried very far. This natural pipe is the SOFAR channel.','It provides a long-range propagation path exploited for signaling, acoustic tomography, whale communication, and historically for locating downed aircrew.','A hydrophone near the channel axis can detect a low-frequency source thousands of kilometers away, because axial energy stays trapped and spreads cylindrically instead of spherically.','Ocean Waveguides',ARRAY['Sound-speed profile','Surface duct','Transmission loss','Deep sound channel']::text[],ARRAY['Thinking the channel is at the surface; it sits at the depth of minimum sound speed.','Assuming all frequencies travel equally far, when only low frequencies escape strong absorption.','Confusing the SOFAR channel with a shallow surface duct.']::text[],ARRAY['Planning long-range ocean acoustic tomography.','Explaining trans-basin propagation of whale calls.','Understanding historic SOFAR rescue beacons.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='SOFAR channel');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6d395337-6220-41e5-9d09-7d132bf7b583','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6d395337-6220-41e5-9d09-7d132bf7b583') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6d395337-6220-41e5-9d09-7d132bf7b583');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '088813e7-645b-44e4-a6d9-7338511c4446','Sensory pleasantness','Sensory pleasantness is a psychoacoustic judgment of how agreeable a sound is. In the Fastl and Zwicker model it increases as loudness, sharpness, and roughness fall and also depends on tonalness, combining these partial sensations multiplicatively relative to a reference.','Some sounds simply feel nicer to hear than others. This pleasant feeling drops when a sound is too loud, too sharp, or too rough. Researchers combine these factors into one score. It is called sensory pleasantness.','It gives designers a single perceptual measure of how comfortable or unpleasant a sound is, built from measurable sub-metrics.','An engineer estimates sensory pleasantness from measured loudness, sharpness, and roughness to compare two appliance designs and choose the more agreeable one.','Psychoacoustic Metrics',ARRAY['Roughness','Specific loudness','Sharpness','Fluctuation strength']::text[],ARRAY['Assuming quieter always means more pleasant, when sharpness and roughness also matter.','Treating pleasantness as objective rather than a modeled perceptual judgment.','Ignoring that the same sound can be pleasant or annoying depending on context.']::text[],ARRAY['Comparing the sound quality of two vacuum-cleaner designs.','Tuning an electric-vehicle warning sound.','Rating annoyance in a product-acoustics lab.']::text[],'intermediate',NULL,'Sensory pleasantness rises as roughness, sharpness, and loudness fall and also varies with tonalness; the Fastl and Zwicker model combines these partial sensations multiplicatively relative to a reference sound.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sensory pleasantness');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '088813e7-645b-44e4-a6d9-7338511c4446','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='088813e7-645b-44e4-a6d9-7338511c4446') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='088813e7-645b-44e4-a6d9-7338511c4446');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '397f9d6c-ed86-4c66-b4fa-bf7709d769f6','Shear mode','Shear (transverse) mode refers to elastic waves or piezoelectric vibration in which particle motion is perpendicular to the propagation direction. Shear waves propagate in solids but not in inviscid fluids, and they travel slower than longitudinal waves in the same solid.','In a shear wave the material moves side to side. This motion is across the travel direction, not along it. Solids can carry shear waves, but still liquids and gases cannot. Shear waves also move slower than the push-pull kind.','It distinguishes transverse elastic motion from longitudinal compression, which matters for material testing, transducer design, and elastography.','A technician selects a shear-wave angle-beam probe for weld inspection because shear waves reflect strongly from cracks and cannot travel in the liquid couplant.','Elastic Wave Modes',ARRAY['Shear-wave elastography','Quarter-wave matching layer','Longitudinal wave','Mode conversion']::text[],ARRAY['Believing shear waves travel through water or air; fluids support no shear stress.','Assuming shear and longitudinal waves travel at the same speed in a solid.','Confusing a crystal''s shear vibration mode with its thickness (longitudinal) mode.']::text[],ARRAY['Choosing an angle-beam probe for ultrasonic weld testing.','Interpreting shear-wave speed in elastography.','Designing a shear-mode piezoelectric sensor.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Shear mode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '397f9d6c-ed86-4c66-b4fa-bf7709d769f6','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='397f9d6c-ed86-4c66-b4fa-bf7709d769f6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='397f9d6c-ed86-4c66-b4fa-bf7709d769f6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '608c9a3c-a7df-49fc-b50b-40503d22ffd2','Shear-wave elastography','Shear-wave elastography is an ultrasound technique that uses an acoustic radiation-force push pulse to generate transverse shear waves in tissue, then tracks their speed to estimate stiffness. The shear modulus is mu = rho*cs^2 and, for near-incompressible tissue, Young''s modulus is E ~ 3*rho*cs^2.','An ultrasound probe pushes tissue with a strong pulse. This creates a sideways wave that spreads through the tissue. Stiffer tissue makes the wave travel faster. Measuring that speed tells doctors how stiff the tissue is.','It gives a quantitative, noninvasive map of tissue stiffness, widely used to stage liver fibrosis and characterize lesions.','If shear-wave speed is cs = 2 m/s in tissue of density rho = 1000 kg/m^3, then mu = 1000 x 2^2 = 4 kPa and Young''s modulus E ~ 3 x 4 = 12 kPa.','Medical Ultrasound',ARRAY['Shear mode','Acoustic radiation force','Young''s modulus','Ultrasound imaging']::text[],ARRAY['Assuming stiffness maps come from the imaging beam itself, not from a separate push pulse.','Reporting the shear modulus where Young''s modulus (about three times larger) is expected, or vice versa.','Forgetting the near-incompressible assumption that makes E about three times the shear modulus.','Ignoring that push pulses raise acoustic output, so settings must stay within regulatory thermal and mechanical index limits.']::text[],ARRAY['Staging liver fibrosis noninvasively.','Characterizing a breast or thyroid lesion by stiffness.','Explaining why elastography needs a strong push pulse.']::text[],'advanced','mu = rho * cs^2 ;  E ~ 3 * rho * cs^2','The shear modulus equals tissue density times the square of shear-wave speed; Young''s modulus is about three times that, assuming near-incompressible tissue.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Shear-wave elastography');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '608c9a3c-a7df-49fc-b50b-40503d22ffd2','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='608c9a3c-a7df-49fc-b50b-40503d22ffd2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='608c9a3c-a7df-49fc-b50b-40503d22ffd2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a1bd2754-9bda-4d6b-8447-ebb37bdce23e','Side-scan sonar','Side-scan sonar is an active sonar that projects fan-shaped beams to port and starboard from a towed or hull-mounted transducer, building a high-resolution acoustic image of the seabed from the strength and timing of backscattered returns as the platform moves along track.','A towed sonar sends sound sideways to the left and right. The seabed reflects this sound back. As the boat moves, the returns build a picture of the bottom. It looks like a photo made from sound.','It maps seabed features, wrecks, pipelines, and debris over wide swaths for survey, search, and inspection.','A survey technician sets range scale and tow height (often about a tenth of the range) so shadows stay sharp, then reads bright returns and dark shadows to identify targets.','Sonar Imaging',ARRAY['Synthetic-aperture sonar','Target strength','Sound-speed profile','Multibeam sonar']::text[],ARRAY['Reading a dark shadow as an object; the shadow behind a target carries its height clue.','Ignoring layback, so the towfish position is plotted at the boat instead of behind it.','Assuming resolution stays constant across the swath when it degrades with range.']::text[],ARRAY['Searching for a wreck or lost equipment on the seabed.','Inspecting a pipeline route for exposure.','Producing a habitat map of the bottom.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Side-scan sonar');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a1bd2754-9bda-4d6b-8447-ebb37bdce23e','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a1bd2754-9bda-4d6b-8447-ebb37bdce23e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a1bd2754-9bda-4d6b-8447-ebb37bdce23e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '11a4e048-c78d-46e2-b39f-e824dbd42ac9','Simultaneous masking','Simultaneous (spectral) masking is the rise in a signal''s audibility threshold caused by another sound present at the same time. It is strongest when masker and signal are close in frequency, and it spreads more toward higher frequencies (the upward spread of masking).','A loud sound can hide a quieter sound played at the same moment. This works best when the two sounds are close in pitch. Louder maskers also hide sounds above them more than below. This is simultaneous masking.','It explains audibility limits within one instant and underpins perceptual audio coding, which discards masked detail.','An audio-codec designer computes a masking threshold from the signal spectrum, then hides quantization noise below that threshold so listeners cannot hear it.','Masking',ARRAY['Specific loudness','Spectral notch','Roughness','Critical band']::text[],ARRAY['Assuming masking is symmetric, when a masker hides higher tones more than lower ones.','Confusing simultaneous masking with temporal (forward or backward) masking across time.','Thinking a masked sound is removed from the signal rather than just made inaudible.']::text[],ARRAY['Designing a perceptual audio codec such as AAC.','Explaining why a soft detail vanishes under a loud instrument.','Setting noise floors in a mix relative to masking.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Simultaneous masking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '11a4e048-c78d-46e2-b39f-e824dbd42ac9','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='11a4e048-c78d-46e2-b39f-e824dbd42ac9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='11a4e048-c78d-46e2-b39f-e824dbd42ac9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '762750bc-fdc0-42d6-93f5-4e38639e4cbf','Sonobuoy','A sonobuoy is an expendable, air- or ship-deployed sonar device that floats on the surface, lowers a hydrophone (passive) or transducer (active) to a preset depth, and radios the received acoustic data to a receiving platform.','A sonobuoy is a small floating listening device. It is dropped from a plane or ship. A microphone hangs below it underwater. It hears sounds and sends them back by radio.','It extends acoustic detection over wide areas, mainly for anti-submarine warfare and ocean monitoring, without a manned platform staying on station.','An operator drops a pattern of passive sonobuoys set to different depths, then compares bearings from their radio channels to detect and localize a target.','Sonar Systems',ARRAY['Hydrophone','Source level','SOFAR channel','Sound-speed profile']::text[],ARRAY['Assuming all sonobuoys are active pingers; most are passive listeners.','Ignoring that hydrophone depth must be set relative to the sound-speed profile.','Treating sonobuoys as reusable when they are expendable and scuttle themselves.']::text[],ARRAY['Laying a sonobuoy field for submarine search.','Monitoring marine-mammal calls from aircraft.','Setting hydrophone depth to reach below a thermocline.']::text[],'beginner',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonobuoy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '762750bc-fdc0-42d6-93f5-4e38639e4cbf','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='762750bc-fdc0-42d6-93f5-4e38639e4cbf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='762750bc-fdc0-42d6-93f5-4e38639e4cbf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '124c7487-74fb-4f50-a76f-ebc8e3b3280e','Sonotrode','A sonotrode (ultrasonic horn) is the tuned metal tool that transfers high-amplitude ultrasonic vibration, typically at 20-40 kHz, from a transducer and booster to the workpiece in ultrasonic welding, cutting, or machining. Its length is set to resonate at the operating frequency.','A sonotrode is a metal tool that vibrates very fast. It carries ultrasound from the machine to the parts being joined. The vibration makes heat that welds plastics or metals. It is shaped to ring at one exact frequency.','It concentrates and delivers ultrasonic energy to the joint, and its geometry sets the vibration amplitude applied to the work.','A technician fits a sonotrode tuned to the welder''s frequency and never touches its face while active, because contact with a vibrating horn causes instant burns and injury.','Ultrasonic Tools',ARRAY['Quarter-wave matching layer','Shear mode','Ultrasonic welding','Piezoelectric transducer']::text[],ARRAY['UNSAFE: Touching or holding a vibrating sonotrode; contact causes immediate frictional burns and tissue injury.','UNSAFE: Working near an active welder without hearing protection; strong subharmonic noise near 10 kHz can harm hearing and cause discomfort.','UNSAFE: Placing fingers in the horn-to-anvil gap, a crush point that closes under force.','Assuming any horn works at any frequency, when it must be tuned to resonate at the machine''s frequency.']::text[],ARRAY['Setting up an ultrasonic plastic-welding station.','Replacing a worn horn tip and retuning the stack.','Fitting hearing protection around an ultrasonic welder.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonotrode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '124c7487-74fb-4f50-a76f-ebc8e3b3280e','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='124c7487-74fb-4f50-a76f-ebc8e3b3280e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='124c7487-74fb-4f50-a76f-ebc8e3b3280e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5eb051b8-d9dc-4d60-9e7b-dc78c5d3d66c','Sound-field synthesis','Sound-field synthesis is a class of spatial-audio methods (notably Wave Field Synthesis and higher-order Ambisonics) that drive many loudspeakers to physically reconstruct a target acoustic field over an extended listening area, rather than creating an illusion only at a single sweet spot.','This method uses many speakers to rebuild a whole sound field. It aims to recreate the real wavefronts of a scene. Then the effect works across a large area, not just one seat. Wave Field Synthesis is one example.','It seeks physically correct spatial reproduction over a listening zone, giving stable source directions as listeners move.','An installer feeds a loudspeaker array with driving signals derived from the desired field, so a virtual source stays fixed as the audience walks along the array.','Spatial Audio Reproduction',ARRAY['Wave Field Synthesis','Radial filter','Sound-zone control','Ambisonics']::text[],ARRAY['Confusing sound-field synthesis with two-speaker panning, which only works at the sweet spot.','Ignoring spatial aliasing above a frequency set by loudspeaker spacing.','Assuming any surround setup is field synthesis; it needs a dense, individually driven array.']::text[],ARRAY['Designing a Wave Field Synthesis theatre array.','Reproducing a large, stable soundstage for many listeners.','Comparing Ambisonic and WFS rendering approaches.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound-field synthesis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5eb051b8-d9dc-4d60-9e7b-dc78c5d3d66c','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5eb051b8-d9dc-4d60-9e7b-dc78c5d3d66c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5eb051b8-d9dc-4d60-9e7b-dc78c5d3d66c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '632b9f9b-2046-4b8a-b87c-690b307336fb','Sound-speed profile','A sound-speed profile is the variation of sound speed with depth in the ocean, governed by temperature, salinity, and pressure. Its shape controls refraction and creates features such as the surface duct, the deep sound channel, and shadow zones.','Sound speed in the sea changes with depth. Temperature, salt, and pressure all affect it. A graph of speed against depth is the sound-speed profile. Its shape decides how sound bends and where it travels.','It is the key environmental input for predicting sonar range, ray paths, and detection zones.','Using Medwin''s formula at T = 10 C, S = 35 ppt, and z = 100 m gives c ~ 1449.2 + 46 - 5.5 + 0.29 + 1.6 ~ 1492 m/s.','Ocean Environment',ARRAY['SOFAR channel','Surface duct','Transmission loss','Thermocline']::text[],ARRAY['Assuming sound speed depends only on temperature and ignoring pressure at depth.','Reading a single surface value as if it applied through the whole water column.','Confusing a sound-speed profile with a temperature profile; they differ because of pressure.']::text[],ARRAY['Predicting sonar range before a survey.','Locating the deep sound-channel axis.','Explaining a surface shadow zone to trainees.']::text[],'intermediate','c ~ 1449.2 + 4.6T - 0.055T^2 + 0.00029T^3 + (1.34 - 0.010T)(S - 35) + 0.016z','Seawater sound speed rises with temperature, salinity, and depth, following Medwin''s empirical relation within its stated ranges.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound-speed profile');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '632b9f9b-2046-4b8a-b87c-690b307336fb','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='632b9f9b-2046-4b8a-b87c-690b307336fb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='632b9f9b-2046-4b8a-b87c-690b307336fb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2d9a7bfc-8f46-4668-b1be-ad5f04661bad','Sound-zone control','Sound-zone control is a set of loudspeaker-array signal-processing methods that create distinct listening zones in one space, delivering different or private audio to each while minimizing leakage, using approaches such as acoustic contrast control and pressure matching.','This method makes separate audio areas in one room. Each zone hears its own sound. A bright zone gets the wanted audio; a dark zone stays quiet. Many speakers and careful processing keep them apart.','It enables personal or multi-user audio without headphones, for cars, exhibitions, and shared living spaces.','An engineer designs filters that maximize level in a bright zone while suppressing it in a dark zone, trading contrast against loudness and array effort.','Spatial Audio Reproduction',ARRAY['Sound-field synthesis','Radial filter','Beamforming','Acoustic contrast control']::text[],ARRAY['Expecting perfect silence in the dark zone; real systems achieve only limited contrast.','Ignoring that contrast falls at high frequencies and away from the design position.','Assuming a single directional speaker equals true multi-zone control.']::text[],ARRAY['Giving driver and passenger different audio in a car.','Providing separate soundtracks at adjacent museum exhibits.','Reducing spill from a personal-audio zone.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound-zone control');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2d9a7bfc-8f46-4668-b1be-ad5f04661bad','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2d9a7bfc-8f46-4668-b1be-ad5f04661bad') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2d9a7bfc-8f46-4668-b1be-ad5f04661bad');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c4856b33-1f19-42fc-b2b9-2599cc7268c0','Source level','Source level is the acoustic level of an underwater source referenced to the level that would exist at 1 m on the acoustic axis, expressed in dB re 1 microPascal at 1 m. It is the transmit term of the sonar equation.','Source level says how loud an underwater source is. It is measured as if you stood one metre away. The reference is one micropascal of pressure. Louder sources have higher source levels.','It sets the transmitted-power term of the sonar equation and lets sources be compared on a common reference.','For a projector radiating acoustic power P_ac with directivity index DI, SL = 170.8 + 10 log(P_ac) + DI; 1 W radiated omnidirectionally gives SL ~ 170.8 dB re 1 uPa at 1 m.','Sonar Performance',ARRAY['Target strength','Reverberation level','Sonobuoy','Transmission loss']::text[],ARRAY['Reporting source level without the 1 uPa at 1 m reference, making it ambiguous.','Comparing an underwater dB figure directly to airborne dB SPL; the references differ by about 62 dB.','Assuming the source truly reaches that level at 1 m, when it is a back-extrapolated reference.']::text[],ARRAY['Rating a sonar projector''s output.','Assessing marine-mammal noise exposure from a source.','Filling the transmit term of a sonar-equation budget.']::text[],'intermediate','SL = 170.8 + 10 log10(P_ac) + DI  (dB re 1 uPa @ 1 m)','Source level equals a reference constant plus ten times the log of radiated acoustic power in watts, plus the directivity index.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Source level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c4856b33-1f19-42fc-b2b9-2599cc7268c0','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c4856b33-1f19-42fc-b2b9-2599cc7268c0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c4856b33-1f19-42fc-b2b9-2599cc7268c0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a35e479f-c779-4e21-a3e2-baec4e091410','Specific loudness','Specific loudness is the loudness contributed per critical band, expressed in sone per Bark. Total loudness is the integral (area) of the specific-loudness pattern across the critical-band-rate scale, as in Zwicker''s loudness model.','Loudness can be split across frequency bands. Each band adds its own share of loudness. This share per band is the specific loudness. Adding up all the bands gives the total loudness.','It is the intermediate quantity in loudness models, letting total loudness be computed by summing contributions across critical bands.','A loudness meter builds the specific-loudness pattern from the excitation in each critical band, then integrates it to report total loudness in sone per ISO 532-1.','Loudness',ARRAY['Spectral loudness summation','Simultaneous masking','Sensory pleasantness','Critical band']::text[],ARRAY['Confusing specific loudness (per band) with total loudness (the whole area).','Assuming loudness adds in decibels rather than by integrating specific loudness.','Ignoring masking, which reshapes the specific-loudness pattern.']::text[],ARRAY['Computing loudness to ISO 532-1 (Zwicker).','Explaining why broadband sound is louder than a tone of equal level.','Analyzing a loudness meter''s internal stages.']::text[],'advanced','N = integral of N''(z) dz over the Bark scale','Total loudness is the integral of specific loudness over the critical-band-rate (Bark) scale.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Specific loudness');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a35e479f-c779-4e21-a3e2-baec4e091410','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a35e479f-c779-4e21-a3e2-baec4e091410') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a35e479f-c779-4e21-a3e2-baec4e091410');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2be38563-7d24-4305-bac7-2a5b2ba1cc95','Spectral loudness summation','Spectral loudness summation is the increase in perceived loudness when sound energy is spread across more critical bands, so a broadband sound is louder than a narrowband sound of the same sound pressure level. It follows from summing specific loudness across bands.','Spread the same energy over a wide range of pitches. It sounds louder than the same energy in a narrow band. This is because each separate band adds loudness. The effect is called spectral loudness summation.','It explains why bandwidth, not just level, affects loudness, and it is built into loudness models.','When a signal''s bandwidth exceeds one critical band at fixed SPL, its loudness rises; engineers use this so wideband program can sound louder without a higher meter level.','Loudness',ARRAY['Specific loudness','Simultaneous masking','Sensory pleasantness','Critical band']::text[],ARRAY['Assuming equal SPL always means equal loudness regardless of bandwidth.','Confusing loudness summation across frequency with adding levels in decibels.','Expecting summation within a single critical band, where it does not occur.']::text[],ARRAY['Explaining why noise sounds louder than a tone at equal level.','Predicting loudness changes from equalization that widens the spectrum.','Interpreting loudness-model outputs.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral loudness summation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2be38563-7d24-4305-bac7-2a5b2ba1cc95','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2be38563-7d24-4305-bac7-2a5b2ba1cc95') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2be38563-7d24-4305-bac7-2a5b2ba1cc95');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '842e2627-9c9a-4c43-80fc-d4a5f00d6d6f','Spectral notch','A spectral notch is a sharp dip in the received sound spectrum produced by the outer ear (pinna) at frequencies that depend on source elevation. Embedded in the head-related transfer function, these direction-dependent notches serve as cues for vertical localization and front/back discrimination.','The folds of your outer ear filter incoming sound. They cut a deep dip at certain high frequencies. Where this dip sits changes with a source''s height. Your brain uses the dip to judge up and down.','It provides the main single-ear (monaural) cue for elevation and helps resolve front-back confusions.','A binaural engineer preserves the pinna notch, typically between about 6 and 10 kHz, when designing HRTF filters so virtual sources have convincing elevation.','Spatial Hearing',ARRAY['Head-related transfer function','Spectral pitch','Binaural rendering','Pinna cue']::text[],ARRAY['Assuming elevation comes from timing cues, when it relies on spectral notches.','Equalizing away the pinna notch and flattening elevation perception.','Treating one fixed notch frequency as universal, when it varies with person and angle.']::text[],ARRAY['Designing HRTF filters for virtual-reality audio.','Explaining front-back confusion in headphone listening.','Personalizing binaural rendering to a listener''s ears.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral notch');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '842e2627-9c9a-4c43-80fc-d4a5f00d6d6f','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='842e2627-9c9a-4c43-80fc-d4a5f00d6d6f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='842e2627-9c9a-4c43-80fc-d4a5f00d6d6f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '60e56d76-50e8-4305-bfba-4d407f980edc','Spectral pitch','Spectral pitch is the pitch assigned to an individual resolved frequency component, such as a pure tone or a resolved harmonic, as distinct from the virtual (residue) pitch derived from the pattern of several harmonics. It reflects place (tonotopic) coding of that component.','Each pure tone has its own pitch. This pitch matches the place it excites in the inner ear. When a single harmonic is heard alone, its pitch is a spectral pitch. It differs from the overall pitch of a complex tone.','It distinguishes the pitch of a single resolved component from the fused pitch of a whole harmonic complex.','When listeners hear out a single harmonic of a complex tone, they report its spectral pitch, which an analyst matches to that harmonic''s frequency.','Pitch Perception',ARRAY['Residue pitch','Temporal pitch','Spectral notch','Virtual pitch']::text[],ARRAY['Confusing the spectral pitch of one harmonic with the virtual pitch of the whole tone.','Assuming only the fundamental has a pitch, when each resolved harmonic can carry one.','Mixing spectral pitch (place-based) with temporal pitch (timing-based) cues.']::text[],ARRAY['Explaining how listeners hear out partials of a chord.','Comparing place and timing theories of pitch.','Analyzing pitch of resolved versus unresolved harmonics.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral pitch');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '60e56d76-50e8-4305-bfba-4d407f980edc','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='60e56d76-50e8-4305-bfba-4d407f980edc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='60e56d76-50e8-4305-bfba-4d407f980edc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '501470ad-b493-4090-8dd1-cd94756ef66a','Spectral spread','Spectral spread is the second central moment (bandwidth) of the power spectrum about its spectral centroid, measuring how widely energy is distributed in frequency. It correlates with perceived timbral width or noisiness and is standardized as the MPEG-7 AudioSpectrumSpread descriptor.','Spectral spread measures how wide a sound''s frequency content is. A pure tone has a small spread. Noise or a rich sound has a large spread. It is the spread of energy around the spectrum''s centre.','It gives a compact timbral descriptor used in audio analysis, classification, and music information retrieval.','An analyst computes spectral spread as the energy-weighted standard deviation of frequency about the centroid, using it to tell tonal sounds from noisy ones.','Timbre Descriptors',ARRAY['Spectral centroid','Temporal envelope','Roughness','Spectral pitch']::text[],ARRAY['Confusing spectral spread (bandwidth) with the spectral centroid (mean frequency).','Computing an unweighted frequency variance instead of weighting by power.','Assuming a high centroid implies a high spread; they are independent.']::text[],ARRAY['Extracting timbre features for instrument classification.','Distinguishing tonal from noisy sounds automatically.','Building an MPEG-7 audio descriptor set.']::text[],'intermediate','spread = sqrt( sum_k (f_k - centroid)^2 * P_k / sum_k P_k )','Spectral spread is the square root of the power-weighted mean squared distance of each frequency bin from the spectral centroid.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral spread');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '501470ad-b493-4090-8dd1-cd94756ef66a','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='501470ad-b493-4090-8dd1-cd94756ef66a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='501470ad-b493-4090-8dd1-cd94756ef66a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2e799f2d-078e-4a8b-936c-2cc9eeb9adb6','Spherical harmonic decomposition','Spherical harmonic decomposition expresses a function on the sphere, such as a sound field''s directional pressure or a microphone array''s output, as a weighted sum of spherical harmonics Y_n^m: orthonormal angular basis functions of order n and degree m. It underlies Ambisonics and spherical array processing.','Any pattern spread over all directions can be broken into simple shapes. These building-block shapes are the spherical harmonics. Adding them with the right weights rebuilds the pattern. This is the basis of Ambisonic sound.','It provides an efficient, rotatable representation of directional sound fields, enabling Ambisonic encoding, decoding, and beamforming.','An engineer projects a spherical-array recording onto spherical harmonics up to order N, obtaining (N+1)^2 Ambisonic channels that can be rotated and decoded to any loudspeaker layout.','Spherical Array Processing',ARRAY['Radial filter','Spherical sonar array','Sound-field synthesis','Ambisonics']::text[],ARRAY['Confusing order (angular detail) with the radial part of the field.','Assuming infinite orders are usable; real arrays truncate and alias above a frequency.','Mixing spherical-harmonic conventions (N3D, SN3D, real vs complex) between tools.']::text[],ARRAY['Encoding higher-order Ambisonics from a sphere microphone.','Rotating a scene by transforming harmonic coefficients.','Designing modal beamformers on a spherical array.']::text[],'advanced','f(theta,phi) = sum_{n=0}^{N} sum_{m=-n}^{n} f_n^m * Y_n^m(theta,phi)','A directional function equals the sum over orders and degrees of its spherical-harmonic coefficients times the corresponding spherical harmonics.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spherical harmonic decomposition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2e799f2d-078e-4a8b-936c-2cc9eeb9adb6','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2e799f2d-078e-4a8b-936c-2cc9eeb9adb6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2e799f2d-078e-4a8b-936c-2cc9eeb9adb6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3493cd1f-c586-4088-a388-5f8c984e4693','Spherical sonar array','A spherical sonar array is a sonar transducer array arranged on or within a sphere, giving nearly uniform beam-steering over all directions. Large bow-mounted spherical arrays are used in submarines for wide-angle passive and active sonar.','This sonar places many transducers over a ball shape. The round layout lets it aim beams in almost any direction equally well. Submarines carry big spherical arrays in the bow. They listen and ping all around.','The spherical geometry provides symmetric, wide-angle beamforming and steering without the edge effects of a flat array.','A sonar operator electronically forms and steers beams across the sphere''s elements to search all bearings around the boat, then focuses on a contact.','Sonar Arrays',ARRAY['Beamforming','Spherical harmonic decomposition','Sonobuoy','Source level']::text[],ARRAY['Assuming only the front hemisphere is usable; the sphere covers wide angles.','Confusing a physical spherical transducer array with an Ambisonic microphone.','Ignoring that only a portion of the elements form each beam at a time.']::text[],ARRAY['Operating a submarine bow sonar.','Comparing spherical and planar array coverage.','Steering beams across many bearings quickly.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spherical sonar array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3493cd1f-c586-4088-a388-5f8c984e4693','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3493cd1f-c586-4088-a388-5f8c984e4693') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3493cd1f-c586-4088-a388-5f8c984e4693');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5e51c29e-e369-430c-a1c2-57b53eb13c00','Stream segregation','Stream segregation (auditory streaming) is the perceptual grouping of a sequence of sounds into separate streams or sources. When tones alternate with sufficient frequency separation and speed, listeners hear two parallel streams instead of one alternating sequence.','The ear sorts a run of sounds into separate lines. Sounds close in pitch stay in one stream. Sounds far apart, played fast, split into two streams. This sorting is called stream segregation.','It underlies how listeners follow one voice or instrument among many, a core part of auditory scene analysis.','A composer or sound designer uses wide pitch jumps at a fast tempo so a single instrument splits into two perceived melodic lines.','Auditory Scene Analysis',ARRAY['Temporal envelope','Simultaneous masking','Spectral pitch','Auditory stream']::text[],ARRAY['Assuming segregation depends only on pitch distance, when tempo matters too.','Confusing sequential streaming with simultaneous (spectral) masking.','Treating streaming as instant, when it builds up over a few seconds.']::text[],ARRAY['Explaining how listeners follow one talker in a crowd.','Designing implied polyphony in music.','Analyzing source separation by hearing.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Stream segregation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5e51c29e-e369-430c-a1c2-57b53eb13c00','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5e51c29e-e369-430c-a1c2-57b53eb13c00') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5e51c29e-e369-430c-a1c2-57b53eb13c00');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2cf9d65e-b4fb-40e1-b197-70ad41d7f875','Surface duct','A surface duct is a near-surface sound channel formed when sound speed increases with depth in a mixed layer, refracting sound upward so it repeatedly reflects off the sea surface and travels beyond the direct path. A shadow zone forms just below the duct.','Near the surface the sea is often well mixed. There sound speed rises with depth. Sound bends upward and bounces off the surface. This traps it in a shallow layer called a surface duct.','It provides an extended-range propagation path for sources and receivers inside the mixed layer, while leaving a shadow zone below.','If both sonar and target sit within the mixed layer, a technician expects longer detection ranges through the duct; a target just below the layer may hide in the shadow zone.','Ocean Waveguides',ARRAY['Sound-speed profile','SOFAR channel','Transmission loss','Shadow zone']::text[],ARRAY['Confusing the shallow surface duct with the deep SOFAR channel.','Assuming the duct traps all frequencies, when low frequencies leak out below a cutoff.','Forgetting the shadow zone that forms just beneath the duct.']::text[],ARRAY['Predicting sonar range in a well-mixed layer.','Explaining why a target below the layer disappears.','Choosing sensor depth relative to the mixed layer.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Surface duct');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2cf9d65e-b4fb-40e1-b197-70ad41d7f875','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2cf9d65e-b4fb-40e1-b197-70ad41d7f875') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2cf9d65e-b4fb-40e1-b197-70ad41d7f875');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '39b9291c-f7ad-4f7f-8985-fb764ed6436a','Synthetic-aperture sonar','Synthetic-aperture sonar (SAS) coherently combines successive echoes recorded as a sonar moves along a track to synthesize a long effective aperture. This yields along-track resolution finer than a physical array and, ideally, independent of range and frequency.','A moving sonar records many pings along its path. Combining them acts like one very long antenna. This gives very sharp images of the seabed. The sharpness stays the same at all ranges.','It delivers high, range-independent resolution seabed imagery from a compact moving platform, for mapping and mine-hunting.','An AUV survey planner keeps platform motion accurate and speed low enough that the sonar pings densely along track, letting the processor coherently sum echoes into a fine image.','Sonar Imaging',ARRAY['Side-scan sonar','Target strength','Beamforming','Sound-speed profile']::text[],ARRAY['Confusing SAS with side-scan sonar, which does not synthesize an aperture.','Ignoring that SAS demands precise platform-motion estimation.','Assuming resolution worsens with range, when SAS along-track resolution is range-independent.']::text[],ARRAY['High-resolution mapping of a debris field.','Mine-countermeasure surveys from an AUV.','Comparing SAS and multibeam imagery.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Synthetic-aperture sonar');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '39b9291c-f7ad-4f7f-8985-fb764ed6436a','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='39b9291c-f7ad-4f7f-8985-fb764ed6436a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='39b9291c-f7ad-4f7f-8985-fb764ed6436a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '52a41137-b6a8-4523-a9c6-f210eebbba33','Target strength','Target strength is a measure of how strongly an underwater object reflects incident sound back toward the source, defined as ten times the base-10 logarithm of the ratio of the echo intensity (referred to 1 m from the target) to the incident intensity, in decibels.','Target strength says how well an object echoes sound. It compares the echo to the sound that hit it. A big, hard object has a high target strength. A small, soft one has a low value.','It is the target-dependent term of the active sonar equation, setting how detectable an object is.','If echo intensity referred to 1 m is one hundredth of the incident intensity, TS = 10 log(0.01) = -20 dB; a large hard sphere may instead show a positive target strength.','Sonar Performance',ARRAY['Source level','Reverberation level','Side-scan sonar','Transmission loss']::text[],ARRAY['Forgetting that the echo intensity is referred to 1 m from the target, not at the receiver.','Assuming target strength is a single number, when it varies with aspect angle and frequency.','Confusing target strength with source level; target strength describes a reflector, not an emitter.']::text[],ARRAY['Estimating detectability of a submarine or mine.','Sizing fish by acoustic backscatter.','Filling the target term of a sonar budget.']::text[],'intermediate','TS = 10 log10(I_r / I_i)  (dB; I_r referred to 1 m from target)','Target strength is ten times the log of the echo intensity at one metre from the target divided by the incident intensity at the target.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Target strength');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '52a41137-b6a8-4523-a9c6-f210eebbba33','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='52a41137-b6a8-4523-a9c6-f210eebbba33') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='52a41137-b6a8-4523-a9c6-f210eebbba33');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c3de915c-2a18-43b1-8c11-4b95b7cd587d','Temporal envelope','The temporal envelope is the relatively slow variation of a signal''s amplitude over time (its outline), separate from the fast temporal fine structure of the waveform. It carries key cues for loudness dynamics, rhythm, and speech intelligibility.','The temporal envelope is the shape of a sound''s loudness over time. It rises and falls slowly, like the outline of the waveform. It carries rhythm and the beat of speech. The fast wiggles inside are a separate detail.','It provides the amplitude-modulation cues the ear uses for speech understanding and rhythm, and it drives envelope-based coding in cochlear implants.','A cochlear-implant processor extracts the temporal envelope in each frequency band and uses it to modulate electrical stimulation, since implant users rely on envelope more than fine structure.','Temporal Processing',ARRAY['Temporal pitch','Stream segregation','Spectral spread','Amplitude modulation']::text[],ARRAY['Confusing the temporal envelope with the fine structure carried inside it.','Assuming pitch always comes from the envelope; it often comes from fine structure.','Thinking the envelope alone gives full speech quality in noise.']::text[],ARRAY['Designing cochlear-implant sound coding.','Explaining speech intelligibility from amplitude modulation.','Analyzing rhythm and onsets in music.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Temporal envelope');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c3de915c-2a18-43b1-8c11-4b95b7cd587d','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c3de915c-2a18-43b1-8c11-4b95b7cd587d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c3de915c-2a18-43b1-8c11-4b95b7cd587d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '112d3d3e-b9fd-42d8-8a12-73666ee8ba62','Temporal pitch','Temporal pitch is a pitch percept derived from the timing (periodicity) of a sound - the repetition rate of the waveform or its envelope - rather than from resolved spectral place. It explains the pitch of unresolved harmonics and periodic noise.','Some pitch comes from timing, not from a place in the ear. The ear tracks how often the wave repeats. That repetition rate gives a temporal pitch. It works even when the ear cannot separate the harmonics.','It accounts for the pitch of complex or unresolved sounds through periodicity coding, complementing place theory.','A researcher uses amplitude-modulated noise or high unresolved harmonics to elicit a temporal pitch matched to the repetition rate, isolating timing cues from place cues.','Pitch Perception',ARRAY['Spectral pitch','Residue pitch','Temporal envelope','Virtual pitch']::text[],ARRAY['Assuming all pitch comes from place coding along the cochlea.','Confusing temporal pitch (timing) with spectral pitch (place).','Thinking envelope repetition gives as strong a pitch as resolved harmonics; it is usually weaker.']::text[],ARRAY['Explaining pitch of unresolved harmonics.','Studying periodicity pitch with modulated noise.','Comparing place and temporal theories of pitch.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Temporal pitch');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '112d3d3e-b9fd-42d8-8a12-73666ee8ba62','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='112d3d3e-b9fd-42d8-8a12-73666ee8ba62') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='112d3d3e-b9fd-42d8-8a12-73666ee8ba62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cbb62c23-ac24-48f5-8bdf-92ab95b0c5c1','Thermocline','A thermocline is an ocean layer in which water temperature falls sharply with increasing depth, producing a steep negative sound-speed gradient. Because sound speed depends strongly on temperature, this layer bends acoustic rays downward and helps form sonar shadow zones and ducts.','A thermocline is a depth band where the sea gets colder fast. Sound moves slower in colder water. So sound rays bend downward through this layer. This bending can hide targets from a sonar.','It is a natural feature of the water column that governs how sound rays refract, so acousticians model it to predict sonar range, ducting, and shadow zones.','A sonar operator reads a temperature-depth (bathythermograph) profile and expects a below-layer target to fall into a shadow zone, then adjusts sensor depth to search beneath the thermocline.','Underwater Acoustics',ARRAY['Sound-speed profile','Shadow zone','SOFAR channel','Refraction','Towed array']::text[],ARRAY['Assuming sound speed tracks only depth/pressure and ignoring the dominant temperature effect inside the thermocline.','Believing the thermocline blocks sound; it refracts and redirects energy rather than absorbing it.','Treating the sound-speed profile as fixed, when the thermocline shifts with season, time of day, and location.']::text[],ARRAY['Predicting a sonar shadow zone before a search for a submerged target.','Interpreting a bathythermograph cast to plan sensor deployment depth.','Explaining why a surface ship loses contact with a target that dives below the layer.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Thermocline');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cbb62c23-ac24-48f5-8bdf-92ab95b0c5c1','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cbb62c23-ac24-48f5-8bdf-92ab95b0c5c1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cbb62c23-ac24-48f5-8bdf-92ab95b0c5c1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c50c1023-8a76-4953-9f24-5689b9f3cfbb','Thickness mode','Thickness mode is the fundamental thickness-direction vibration of a piezoelectric plate, in which the plate thickness equals one half acoustic wavelength at resonance. Its resonant frequency is set by the plate thickness and the longitudinal sound speed in the material, f = c/(2d).','A flat crystal can vibrate through its thickness. It resonates when its thickness equals half a wavelength. A thinner plate resonates at a higher frequency. This mode sets the working frequency of many ultrasonic probes.','It is the primary resonance that determines the operating frequency of most thickness-driven ultrasonic transducers, so designers pick plate thickness to hit a target frequency.','For a PZT plate with longitudinal velocity about 4000 m/s and thickness 1 mm, the thickness-mode resonance is f = 4000 / (2 x 0.001) = 2 MHz.','Ultrasonic Transducer',ARRAY['Piezoelectric effect','Ultrasonic attenuation','Ultrasonic horn','Resonance','Matching layer']::text[],ARRAY['Using the full wavelength instead of the half wavelength, which doubles the predicted frequency.','Inserting the bulk longitudinal velocity of the surrounding medium rather than the piezo material''s own velocity.','Confusing the thickness mode with lateral or radial modes of the same disc.']::text[],ARRAY['Selecting a crystal thickness to build a 5 MHz flaw-detection probe.','Explaining why grinding a transducer thinner raises its frequency.','Diagnosing an unexpected resonance caused by a competing plate mode.']::text[],'intermediate','f = c / (2d)','Thickness-mode resonant frequency equals the material''s longitudinal sound speed divided by twice the plate thickness.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Thickness mode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c50c1023-8a76-4953-9f24-5689b9f3cfbb','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c50c1023-8a76-4953-9f24-5689b9f3cfbb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c50c1023-8a76-4953-9f24-5689b9f3cfbb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ed97766b-4e2a-46d8-82c6-841c41272ce1','Through-transmission mode','Through-transmission is an ultrasonic testing arrangement using two separate transducers on opposite faces of a part, one transmitting and one receiving. A flaw is inferred from a drop in the received signal amplitude rather than from a reflected echo.','One probe sends sound through the part. A second probe on the far side receives it. A hidden flaw blocks or scatters the sound. So the received signal gets weaker where a defect lies.','It exists to detect flaws by monitoring transmitted energy loss, which suits highly attenuating or thin materials where pulse-echo returns are hard to read.','A technician scans a composite panel with aligned probes on both faces and marks any area where the through-transmitted amplitude drops sharply as a suspected delamination.','Ultrasonic NDT',ARRAY['Pulse-echo','Ultrasonic attenuation','Time-of-flight diffraction','Thickness mode','Immersion testing']::text[],ARRAY['Expecting a flaw depth reading; through-transmission shows a flaw exists but not how deep it sits.','Failing to keep the two probes aligned and coupled, which mimics a defect by dropping the signal.','Confusing normal amplitude variation from surface roughness with a genuine defect indication.']::text[],ARRAY['Inspecting a bonded honeycomb panel for delamination.','Screening cast parts where scattering makes pulse-echo echoes unreliable.','Automated in-line testing of sheet or plate for gross porosity.']::text[],'beginner',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Through-transmission mode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ed97766b-4e2a-46d8-82c6-841c41272ce1','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ed97766b-4e2a-46d8-82c6-841c41272ce1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ed97766b-4e2a-46d8-82c6-841c41272ce1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ee6c9136-d420-42e7-8bf7-af9b94d1b94b','Time-of-flight diffraction','Time-of-flight diffraction (TOFD) is an ultrasonic weld-inspection technique that uses two angled longitudinal-wave probes in a transmit-receive pair and measures the arrival times of waves diffracted from the tips of a defect. Because it times diffracted signals rather than measuring echo amplitude, TOFD sizes and locates flaws largely independent of their orientation.','Two angled probes face each other across a weld. A crack scatters sound from its tips. The scanner times when these signals arrive. Those arrival times reveal how deep and how tall the crack is.','It exists to size and locate weld defects accurately, especially their through-wall height, using signal timing instead of amplitude so results are less sensitive to defect angle.','With probe centre separation 100 mm (half-separation S = 0.05 m) and steel velocity c = 5900 m/s, a tip signal at t = 20 microseconds gives depth z = sqrt((c t/2)^2 - S^2) = sqrt(0.059^2 - 0.05^2) = about 31 mm.','Ultrasonic NDT',ARRAY['Through-transmission mode','Pulse-echo','Phased array ultrasonics','Diffraction','Lateral wave']::text[],ARRAY['Reading defect severity from amplitude; TOFD judges size from time of flight, not echo height.','Ignoring the near-surface dead zone under the lateral wave, where shallow flaws are easily missed.','Misidentifying phase; upper and lower tip signals are opposite in phase, and swapping them mis-sizes the flaw.']::text[],ARRAY['Sizing the through-wall height of a crack in a pipeline girth weld.','Monitoring known flaw growth between in-service inspection intervals.','Providing a permanent recorded scan for code-compliant weld acceptance.']::text[],'advanced','z = sqrt( (c*t/2)^2 - S^2 )','Defect depth equals the square root of the squared half-path travelled (sound speed times time of flight divided by two) minus the squared half probe separation.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Time-of-flight diffraction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ee6c9136-d420-42e7-8bf7-af9b94d1b94b','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ee6c9136-d420-42e7-8bf7-af9b94d1b94b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ee6c9136-d420-42e7-8bf7-af9b94d1b94b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fff40668-b94e-43d3-9773-e56aa1f5ad63','Tonpilz transducer','A Tonpilz transducer is a longitudinal-resonator underwater sound projector built from a light radiating head mass, a stack of piezoelectric (or magnetostrictive) drive elements, and a heavy tail mass held together by a central stress bolt. The name is German for singing mushroom, and the design radiates efficiently over roughly the low-kilohertz to tens-of-kilohertz sonar band.','A Tonpilz projector makes loud underwater sound. A light front piece pushes on the water. A driving crystal stack sits behind it. A heavy back mass makes most of the motion go forward. A bolt clamps the parts together.','It exists to convert electrical drive into strong low-frequency underwater sound, forming the active element of many sonar transmit arrays.','An engineer tunes the head and tail masses so the stack resonates at the wanted sonar frequency, then packs many Tonpilz elements into a transmit array for a projector.','Sonar Transducer',ARRAY['Hydrophone','Piezoelectric effect','Towed array','Transponder','Underwater acoustic modem']::text[],ARRAY['Thinking the head mass should be heavy; a light head and heavy tail direct most motion into the water.','Ignoring the stress bolt''s preload, which keeps brittle ceramics in compression under high drive.','Assuming one element is broadband; a single Tonpilz is fairly narrowband around its designed resonance.']::text[],ARRAY['Designing the transmit stave of an active sonar array.','Choosing head and tail masses to set a projector''s resonant frequency.','Explaining why a projector element must stay under compressive preload at high power.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tonpilz transducer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fff40668-b94e-43d3-9773-e56aa1f5ad63','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fff40668-b94e-43d3-9773-e56aa1f5ad63') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fff40668-b94e-43d3-9773-e56aa1f5ad63');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8564a053-3c56-4329-8859-aa299b279c32','Towed array','A towed array is a long line of hydrophones housed in a flexible cable that a vessel tows behind it, well astern of its own machinery noise. Its length gives high directional gain at low frequencies for passive detection and bearing estimation.','A towed array is a long cable of underwater microphones. A ship pulls it far behind itself. That distance keeps it clear of the ship''s own noise. Its length helps it hear faint, low sounds and find their direction.','It exists to give a moving platform a large, quiet, low-frequency listening aperture that a hull-mounted sensor cannot match.','An operator deploys the array astern and combines the hydrophone signals by beamforming to detect a distant low-frequency source and estimate its bearing.','Sonar Array',ARRAY['Hydrophone','Beamforming','Vector hydrophone','Thermocline','Passive sonar']::text[],ARRAY['Forgetting the left-right bearing ambiguity a single straight line array produces.','Ignoring flow and tow noise that rises with speed and degrades low-frequency detection.','Assuming the array is straight; turns and currents bend it and distort beam directions.']::text[],ARRAY['Passively searching for a quiet low-frequency source from a moving vessel.','Resolving a bearing ambiguity by manoeuvring the tow platform.','Trading tow speed against self-noise during a search.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Towed array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8564a053-3c56-4329-8859-aa299b279c32','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8564a053-3c56-4329-8859-aa299b279c32') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8564a053-3c56-4329-8859-aa299b279c32');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '97801489-b081-4b12-9f31-aeebc17e8e06','Transponder','An acoustic transponder is an underwater device that listens for a coded interrogation pulse and, on recognising it, transmits a reply pulse. The two-way travel time of the interrogate-reply exchange yields range, which underpins acoustic positioning systems such as long-baseline navigation.','A transponder waits underwater for a coded ping. When it hears the right ping, it answers with its own ping. The round-trip time gives the distance. Several transponders let a vehicle work out where it is.','It exists to provide a controllable acoustic range reference, enabling underwater positioning, navigation, and ranging without radio, which does not travel far in water.','A survey team drops seabed transponders, then a vehicle interrogates them and uses each measured round-trip time to fix its position by long-baseline navigation.','Underwater Acoustics',ARRAY['Transducer','Hydrophone','Underwater acoustic modem','Tonpilz transducer','Range']::text[],ARRAY['Confusing a transponder, which replies only when interrogated, with a beacon that pings on its own schedule.','Using a single sound-speed value for range when the real sound-speed profile bends the ray path.','Overlapping interrogations so replies collide and ranges are misassigned.']::text[],ARRAY['Positioning a remotely operated vehicle with a long-baseline seabed network.','Ranging to a moored subsea asset for recovery.','Time-stamping interrogate-reply exchanges to log a survey track.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transponder');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '97801489-b081-4b12-9f31-aeebc17e8e06','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='97801489-b081-4b12-9f31-aeebc17e8e06') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='97801489-b081-4b12-9f31-aeebc17e8e06');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7718aa41-f240-4261-9b61-3668e77a13be','Ultrasonic attenuation','Ultrasonic attenuation is the progressive loss of ultrasonic wave amplitude with propagation distance, caused by absorption (conversion to heat) and scattering from grain boundaries and inhomogeneities. Amplitude typically decays exponentially, A = A0 exp(-alpha x), where alpha is the attenuation coefficient in nepers or decibels per unit length and usually rises with frequency.','Ultrasound gets weaker as it travels. Some energy turns to heat inside the material. Some scatters off grains and flaws. Higher frequencies fade faster. Engineers describe this fade with an attenuation number per unit length.','It quantifies how far ultrasound can penetrate a material, guiding the choice of frequency and setting limits on inspection depth and material characterization.','If a material attenuates at alpha = 1 dB/cm and the sound travels 4 cm one way, the amplitude falls by about 1 x 4 = 4 dB along that path.','Ultrasonic Physics',ARRAY['Through-transmission mode','Thickness mode','Scattering','Absorption','Ultrasonic horn']::text[],ARRAY['Confusing attenuation, an amplitude loss per unit length, with simple geometric spreading of the beam.','Forgetting the strong frequency dependence, so a high-frequency probe is chosen for a thick, coarse-grained part.','Mixing nepers and decibels, which differ by the factor 8.686.']::text[],ARRAY['Selecting a lower test frequency to penetrate a thick, coarse-grained casting.','Estimating grain size from measured attenuation versus frequency.','Correcting echo amplitudes for material loss before flaw sizing.']::text[],'intermediate','A = A0 * exp(-alpha * x)','Amplitude at distance x equals the initial amplitude times the exponential of minus the attenuation coefficient times distance.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasonic attenuation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7718aa41-f240-4261-9b61-3668e77a13be','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7718aa41-f240-4261-9b61-3668e77a13be') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7718aa41-f240-4261-9b61-3668e77a13be');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b67a85c1-55a9-4543-b4f8-83db477028e2','Ultrasonic horn','An ultrasonic horn, or sonotrode, is a resonant metal velocity transformer that concentrates the small vibration of a power-ultrasonic driver into a large-amplitude output at its tip. For a stepped horn the amplitude magnification is approximately the ratio of the input cross-sectional area to the smaller output area, and the horn is machined to a half-wavelength length so it resonates at the drive frequency.','An ultrasonic horn is a shaped metal tool. It takes a tiny fast vibration and makes it much bigger at the tip. A narrower tip moves further than the wide end. It is used for welding, cutting, and cleaning with intense ultrasound.','It exists to amplify and deliver high-intensity vibration to a workpiece or liquid for ultrasonic welding, machining, cutting, and cavitation-based cleaning or processing.','If a stepped horn''s input face has four times the area of its output face, the tip amplitude is roughly four times the driver amplitude; a technician tunes the horn length so it resonates at the generator frequency.','Power Ultrasonics',ARRAY['Piezoelectric effect','Thickness mode','Resonance','Cavitation','Ultrasonic attenuation']::text[],ARRAY['UNSAFE: Touching or bridging a live horn tip; the high-amplitude vibration can cut, abrade, or burn skin instantly.','UNSAFE: Running an unloaded or wrongly tuned horn near people; intense airborne/contact ultrasound and heat can injure and can crack the tool.','UNSAFE: Reaching into an operating ultrasonic bath or process liquid; cavitation and heating can damage tissue and cause burns.','Assuming any length works; the horn must be a half-wavelength resonant design at the drive frequency.']::text[],ARRAY['Setting up a plastic ultrasonic welder for a production joint.','Selecting horn gain to reach the tip amplitude a process needs.','Tuning horn length so it resonates with the transducer and generator.']::text[],'intermediate','M = S_in / S_out','For a stepped horn, amplitude gain approximately equals the input cross-sectional area divided by the output cross-sectional area.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasonic horn');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b67a85c1-55a9-4543-b4f8-83db477028e2','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b67a85c1-55a9-4543-b4f8-83db477028e2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b67a85c1-55a9-4543-b4f8-83db477028e2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5160d0ea-db69-4fdb-9b76-898fcce93fdd','Underwater acoustic modem','An underwater acoustic modem is a device that transmits and receives digital data through water using modulated sound, because radio waves attenuate rapidly underwater. Long delays, strong multipath, and Doppler spread limit practical data rates, so these links are far slower and higher-latency than terrestrial radio.','This device sends data through water using sound. Radio does not travel far underwater. So the modem codes bits onto acoustic signals. Echoes and slow sound speed keep the data rate low.','It exists to give underwater vehicles, sensors, and divers a wireless data link where electromagnetic communication is impractical.','An operator programs a seabed sensor to acknowledge commands and send readings acoustically to a surface buoy, accepting a low data rate to avoid a physical cable.','Underwater Communications',ARRAY['Transponder','Hydrophone','Tonpilz transducer','Multipath','Thermocline']::text[],ARRAY['Expecting radio-like bandwidth; acoustic links deliver far lower data rates and much higher latency.','Ignoring multipath and Doppler, which corrupt the signal unless the modem equalizes them.','Overlooking the sound-speed profile, which refracts the link and can drop connectivity.']::text[],ARRAY['Retrieving data from a seabed observatory without recovering it.','Commanding an autonomous underwater vehicle during a mission.','Networking several subsea nodes into an acoustic sensor field.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Underwater acoustic modem');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5160d0ea-db69-4fdb-9b76-898fcce93fdd','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5160d0ea-db69-4fdb-9b76-898fcce93fdd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5160d0ea-db69-4fdb-9b76-898fcce93fdd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '15d66caa-2416-49ba-a265-113676fb1435','Vector hydrophone','A vector hydrophone (acoustic vector sensor) measures the directional components of the acoustic field, typically the three-axis particle velocity or pressure gradient, often alongside scalar pressure. Combining these components lets a single compact sensor estimate a source''s bearing without needing a large array.','A normal hydrophone hears sound pressure only. A vector hydrophone also senses which way the water is moving. That motion has direction. So one small sensor can point toward a sound source.','It exists to obtain source direction from a single compact device by sensing the vector particle-motion field rather than pressure alone.','A technician combines the pressure and particle-velocity channels of one vector sensor to estimate a source bearing, avoiding a long hydrophone array.','Underwater Sensor',ARRAY['Hydrophone','Towed array','Beamforming','Particle velocity','Transponder']::text[],ARRAY['Assuming any hydrophone gives direction; a scalar pressure sensor alone cannot resolve bearing.','Neglecting sensor self-noise and flow noise, which strongly degrade the velocity channels.','Forgetting careful channel calibration and alignment, without which the estimated bearing is biased.']::text[],ARRAY['Estimating a source bearing where a large array will not fit.','Adding directionality to a compact drifting or moored sensor.','Improving array gain by using pressure and particle-velocity data together.']::text[],'advanced',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vector hydrophone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '15d66caa-2416-49ba-a265-113676fb1435','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='15d66caa-2416-49ba-a265-113676fb1435') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='15d66caa-2416-49ba-a265-113676fb1435');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c9296114-6bf1-4813-97fd-eda119c88b94','AES EtherType','The AES EtherType is a two-octet EtherType value registered to the Audio Engineering Society that labels the payload of an Ethernet frame as carrying an AES-defined protocol, so a receiver can route it to the correct handler. It is used by AES51 to carry ATM cells over an Ethernet physical layer, with the AES protocol identifier selecting the specific AES protocol within that EtherType.','An EtherType is a small code near the start of an Ethernet packet. It tells the receiver what kind of data is inside. The Audio Engineering Society owns one such code. It marks packets that carry AES audio-networking protocols like AES51.','It gives AES a reserved label in Ethernet frames so its transport protocols can share a network without being confused with other traffic.','A technician bridging AES51 audio over standard Ethernet relies on switches passing frames tagged with the AES EtherType unchanged to the endpoint.','Network transport',ARRAY['AES Organizationally Unique Identifier','AES protocol identifier','AES3 frame','ATM interworking']::text[],ARRAY['Confusing the EtherType (what protocol) with the MAC address (which device).','Assuming every audio-over-Ethernet system uses the AES EtherType; Dante and AES67 use standard IP/UDP instead.','Thinking the EtherType carries audio data itself rather than just identifying the protocol.']::text[],ARRAY['Configuring a managed switch to pass AES51 traffic between studios.','Capturing packets to verify AES51 frames are correctly tagged.','Troubleshooting why a non-IP audio transport is dropped by a router.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='AES EtherType');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c9296114-6bf1-4813-97fd-eda119c88b94','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c9296114-6bf1-4813-97fd-eda119c88b94') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c9296114-6bf1-4813-97fd-eda119c88b94');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd82665dd-a2f1-47e8-8894-913e1c940ff6','AES Organizationally Unique Identifier','The AES Organizationally Unique Identifier (OUI) is the 24-bit block 00-0B-5E assigned to the Audio Engineering Society by the IEEE Registration Authority. It forms the first three octets of MAC addresses and other identifiers used by AES networking protocols such as AES51.','An OUI is a three-byte code that names an organisation on a network. The IEEE hands these out. The Audio Engineering Society owns 00-0B-5E. Its networking protocols build addresses that start with those bytes.','It gives AES a globally unique prefix so the addresses and identifiers its protocols create cannot collide with those of other vendors or bodies.','A technician reading a packet capture can recognise AES-originated multicast MAC addresses because they begin with the 00-0B-5E prefix.','Network identifier',ARRAY['AES EtherType','AES protocol identifier','AES3 frame','ATM interworking']::text[],ARRAY['Confusing an OUI (identifies an organisation) with a full MAC address (identifies one interface).','Assuming the OUI is proprietary to one manufacturer rather than to the AES standards body.','Believing the OUI carries audio; it only forms part of an address.']::text[],ARRAY['Identifying AES51 multicast addresses in a network trace.','Explaining how globally unique MAC addresses are constructed.','Documenting addressing for an AES-based interconnect.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='AES Organizationally Unique Identifier');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd82665dd-a2f1-47e8-8894-913e1c940ff6','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d82665dd-a2f1-47e8-8894-913e1c940ff6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d82665dd-a2f1-47e8-8894-913e1c940ff6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ecc06785-3e28-45ac-a19c-a35e24dd65dd','AES protocol identifier','The AES protocol identifier is a value carried in the first octet of the MAC client data of an Ethernet frame that uses the AES EtherType, selecting which AES-defined protocol the frame carries. AES51 (transmission of ATM cells over Ethernet) is assigned protocol identifier value 02 (hexadecimal).','Several AES protocols can share the one AES EtherType label. A single byte after that label says which protocol it is. AES51 uses the value 02. The receiver reads this byte to pick the right decoder.','It multiplexes more than one AES protocol under a single registered EtherType, so each can be told apart at the receiver.','When debugging AES51, an engineer confirms the protocol identifier octet is 02 before assuming the frame should be parsed as ATM-over-Ethernet.','Network transport',ARRAY['AES EtherType','AES Organizationally Unique Identifier','AES3 frame','ATM interworking']::text[],ARRAY['Confusing the protocol identifier with the EtherType; the EtherType selects the family and the identifier selects the member.','Assuming the identifier value is the same across all AES protocols.','Overlooking that the identifier sits in the payload, not in the Ethernet header.']::text[],ARRAY['Parsing AES51 frames in a protocol analyser.','Distinguishing two AES protocols that share the AES EtherType.','Writing bridge firmware that dispatches AES frames by protocol.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='AES protocol identifier');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ecc06785-3e28-45ac-a19c-a35e24dd65dd','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ecc06785-3e28-45ac-a19c-a35e24dd65dd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ecc06785-3e28-45ac-a19c-a35e24dd65dd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1ac325c4-189a-4f1a-b46c-ff8ae8f0bbd5','AES3 block','In AES3, a block is a group of 192 consecutive frames that aligns the channel status data of the stream. The start of each block is signalled by a distinct preamble (the Z or B preamble), and the collected channel status bits from the 192 frames form one 24-byte channel status word per subframe channel.','AES3 groups its audio frames into blocks of 192. The first frame of a block carries a special marker. Across those 192 frames, one status bit per frame is collected. Together they form the channel status message describing the signal.','The block boundary lets a receiver assemble the channel status word, which describes sample rate, use, and other properties of the AES3 stream.','At 48 kHz a block spans 192 / 48000 = 4 ms, so channel status updates arrive 250 times per second.','Digital interface',ARRAY['AES3 frame','Channel status','S/PDIF','Word clock']::text[],ARRAY['Confusing a block (192 frames) with a frame (two subframes).','Thinking the block marker changes the audio data; it only marks channel status alignment.','Assuming block length scales with sample rate; it is fixed at 192 frames.']::text[],ARRAY['Decoding channel status to read a stream''s sample rate.','Diagnosing why a receiver misreads AES3 metadata.','Explaining AES3 framing during interface training.']::text[],'intermediate','T_block = 192 / f_s','The duration of one AES3 block equals 192 frames divided by the sampling frequency.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='AES3 block');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1ac325c4-189a-4f1a-b46c-ff8ae8f0bbd5','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1ac325c4-189a-4f1a-b46c-ff8ae8f0bbd5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1ac325c4-189a-4f1a-b46c-ff8ae8f0bbd5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '934c603f-8a52-4fbd-85ba-6388d2356d6f','AES3 frame','An AES3 frame is the basic unit of the AES3 serial format, consisting of two 32-bit subframes (channel A followed by channel B) for a total of 64 time slots. Each frame carries one audio sample per channel, so the frame rate equals the audio sampling frequency.','AES3 sends audio as a stream of frames. Each frame holds two subframes, one per channel. Each subframe is 32 bits long. One frame carries a single sample for each of the two channels.','The frame packages one sample of each channel together with sync preambles and status bits so two audio channels travel on one self-clocking link.','At 48 kHz the gross bit rate is 64 x 48000 = 3.072 Mbit/s for the two-channel stream.','Digital interface',ARRAY['AES3 block','Channel status','S/PDIF','Word clock']::text[],ARRAY['Thinking a subframe holds only audio; it also carries preamble, validity, user, channel status and parity bits.','Assuming the 24-bit audio field is always full; AES3 supports 20-bit and 24-bit words.','Confusing the frame rate with the bit rate.']::text[],ARRAY['Calculating link bandwidth for an AES3 run.','Explaining how two channels share one cable.','Interpreting a bitstream analyser view of AES3.']::text[],'intermediate','R = 64 * f_s','The gross AES3 bit rate equals 64 bits per frame times the sampling frequency.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='AES3 frame');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '934c603f-8a52-4fbd-85ba-6388d2356d6f','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='934c603f-8a52-4fbd-85ba-6388d2356d6f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='934c603f-8a52-4fbd-85ba-6388d2356d6f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e3d74029-df45-43a5-8193-61dc90f61838','ATM adaptation-layer parameter','An ATM (Asynchronous Transfer Mode) adaptation-layer parameter is a setting of the ATM Adaptation Layer (AAL) that governs how audio is segmented into and reassembled from 48-byte ATM cell payloads, including timing and error-handling behaviour. AES47 defines the AAL mapping used to carry AES3-format audio across an ATM network.','ATM (Asynchronous Transfer Mode) sends data in tiny fixed cells. The adaptation layer chops audio to fit those cells and rebuilds it at the far end. Its parameters set how that chopping, timing, and error checking work. AES47 defines these for audio.','The parameters let audio of a given channel count and sample rate be packed efficiently into ATM cells while preserving timing at the receiver.','When provisioning an AES47 link, an engineer selects AAL parameters that match the audio''s sample rate and channel count so cells fill and drain without under-run.','Network transport',ARRAY['ATM audio call','ATM interworking','Audio call-setup signaling','AES3 frame']::text[],ARRAY['Assuming ATM cells carry whole audio frames; a frame usually spans several cells.','Ignoring reassembly timing, which can cause clicks if under-run occurs.','Confusing the adaptation layer with the physical layer beneath it.']::text[],ARRAY['Setting up an AES47 circuit between broadcast sites.','Diagnosing dropouts traced to adaptation timing.','Documenting the AAL configuration of a legacy audio-over-ATM link.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='ATM adaptation-layer parameter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e3d74029-df45-43a5-8193-61dc90f61838','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e3d74029-df45-43a5-8193-61dc90f61838') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e3d74029-df45-43a5-8193-61dc90f61838');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8820d2f4-5b91-4aec-accc-2cf0e2764d94','ATM audio call','An ATM audio call is a virtual connection established across an ATM network to carry digital audio under AES47, set up either as a switched virtual connection through signalling or provisioned as a permanent virtual connection. Once established, AES3-format audio flows through the connection as a stream of ATM cells.','ATM makes a connection before it sends data, like placing a phone call. For audio, that connection is an ATM audio call. It reserves a path across the network. AES3 audio then streams through it as cells.','It reserves a defined path and bandwidth for audio so delivery is predictable, unlike best-effort packet forwarding.','To move a live feed between facilities over ATM, an operator sets up an audio call to the far endpoint before the programme starts.','Network transport',ARRAY['Audio call-setup signaling','ATM adaptation-layer parameter','ATM interworking','AES3 frame']::text[],ARRAY['Treating ATM as connectionless like IP; ATM is connection-oriented.','Assuming audio flows before the call is established.','Confusing a switched virtual connection with a permanent one.']::text[],ARRAY['Establishing a point-to-point audio link over a telecom ATM backbone.','Explaining connection-oriented transport in training.','Migrating an audio-over-ATM service to modern IP transport.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='ATM audio call');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8820d2f4-5b91-4aec-accc-2cf0e2764d94','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8820d2f4-5b91-4aec-accc-2cf0e2764d94') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8820d2f4-5b91-4aec-accc-2cf0e2764d94');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8c7bf7de-ca52-451b-82d0-4cddcd1d9539','ATM interworking','ATM interworking is the interoperation between an AES47 audio-over-ATM connection and another transport or network, so audio can pass between them. A common case is AES51, which carries ATM cells over an Ethernet physical layer, letting ATM-format audio traverse Ethernet infrastructure.','Interworking means letting two different network types cooperate. Audio carried in ATM cells sometimes has to cross other networks. AES51, for example, wraps ATM cells inside Ethernet. That lets ATM audio ride ordinary Ethernet links.','It bridges ATM audio to other infrastructures so equipment built for different transports can still exchange audio.','A facility keeping AES47 gear but wiring Ethernet uses AES51 interworking to carry the ATM cells over the Ethernet plant.','Network transport',ARRAY['ATM audio call','ATM adaptation-layer parameter','AES EtherType','Audio call-setup signaling']::text[],ARRAY['Assuming interworking converts the audio samples; it usually re-encapsulates the same cells.','Believing ATM and Ethernet cannot coexist.','Overlooking clocking differences between the two networks.']::text[],ARRAY['Carrying legacy ATM audio over an Ethernet backbone.','Bridging two facilities using different transports.','Planning a phased migration away from ATM.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='ATM interworking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8c7bf7de-ca52-451b-82d0-4cddcd1d9539','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8c7bf7de-ca52-451b-82d0-4cddcd1d9539') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8c7bf7de-ca52-451b-82d0-4cddcd1d9539');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1088b626-f2fb-41a3-b8c9-2ffd0a87382d','AXML Chunk','An axml chunk is a chunk within a Broadcast Wave Format (BWF) file that stores arbitrary XML metadata as text. It is most often used to embed an Audio Definition Model (ADM) description of the file''s channels, objects, and scene structure.','A BWF audio file is built from labelled chunks. The axml chunk holds free-form XML text. It usually carries an Audio Definition Model description. That describes how the file''s audio channels and objects are arranged.','It lets rich, extensible metadata such as ADM travel inside the audio file itself, so descriptive information stays attached to the samples.','A technician delivering an object-based mix as a BW64 file inspects the axml chunk to confirm the ADM correctly lists every audioObject.','File metadata',ARRAY['Audio Essence','Alternative Value Set','Audio element','Accessibility metadata']::text[],ARRAY['Confusing the axml chunk with the bext (Broadcast Extension) chunk, which holds fixed fields.','Assuming any XML is valid ADM; the XML must conform to the ADM schema.','Editing the chunk without keeping RIFF chunk sizes consistent.']::text[],ARRAY['Embedding ADM metadata in a deliverable master.','Validating object-based audio before hand-off.','Reading channel assignments from a broadcast file.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='AXML Chunk');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1088b626-f2fb-41a3-b8c9-2ffd0a87382d','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1088b626-f2fb-41a3-b8c9-2ffd0a87382d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1088b626-f2fb-41a3-b8c9-2ffd0a87382d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7be73193-3ef0-4160-b75f-a40b96b1448a','Access unit','In MPEG systems, an access unit is the coded representation of a single presentation unit, and it is the smallest data element to which decoding and presentation timestamps can be attached. Audio and video streams are divided into access units so a decoder knows exactly what to decode and when to present it.','MPEG breaks a media stream into access units. Each one is the coded data for one piece to be shown or heard. Time stamps attach to whole access units. This tells the decoder when to decode and play each unit.','It defines a clean boundary for timing and buffering, letting a decoder synchronise audio and video accurately.','When multiplexing, an engineer ensures each audio access unit gets a correct presentation timestamp so lip-sync holds.','Coding systems',ARRAY['Audio access unit','Audio Data Transport Stream','Arithmetic-coded spectral data','Audio Essence']::text[],ARRAY['Confusing an access unit (coded) with a presentation unit (decoded output).','Assuming an access unit always equals one packet; it may span several.','Thinking every access unit carries its own timestamp; only some do.']::text[],ARRAY['Setting timestamps during transport-stream multiplexing.','Explaining decoder buffering models.','Diagnosing audio-video sync errors.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Access unit');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7be73193-3ef0-4160-b75f-a40b96b1448a','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7be73193-3ef0-4160-b75f-a40b96b1448a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7be73193-3ef0-4160-b75f-a40b96b1448a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a6ab29e3-6973-4d41-9688-4fd6b9094d1d','Accessibility metadata','Accessibility metadata is descriptive information that identifies accessibility-related versions or features of audio content, such as audio description, spoken subtitles, clean dialogue, or sign-language presentation. It lets a player or user select the version that meets a listener''s needs.','Some audio versions help people with sight or hearing needs. Accessibility metadata labels these versions. It might mark an audio description track or clear-speech dialogue. A player uses these labels to offer the right choice.','It exposes accessibility options in a machine-readable way so devices can present and switch to suitable versions automatically.','A broadcast technician tags an audio-description mix with the correct accessibility metadata so set-top boxes list it for visually impaired viewers.','Content metadata',ARRAY['Audio element','Alternative audio element','Accessibility','AXML Chunk']::text[],ARRAY['Assuming the metadata itself provides the accessible content rather than just labelling it.','Confusing audio description (narration of visuals) with subtitles.','Forgetting to signal accessibility versions, so they stay hidden from users.']::text[],ARRAY['Labelling an audio-description track for broadcast.','Signalling clean-dialogue audio in a streaming manifest.','Meeting regulatory accessibility requirements.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Accessibility metadata');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a6ab29e3-6973-4d41-9688-4fd6b9094d1d','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a6ab29e3-6973-4d41-9688-4fd6b9094d1d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a6ab29e3-6973-4d41-9688-4fd6b9094d1d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a61f691d-ddf6-42c1-8700-dae7138f3aab','Adaptation control','In an MPEG-2 transport stream, adaptation control is the two-bit adaptation_field_control field in each transport packet header that indicates whether the packet carries an adaptation field, a payload, or both. The adaptation field itself conveys timing references and stuffing needed to keep the stream aligned.','MPEG-2 transport data travels in fixed 188-byte packets. A two-bit code in each header says what the packet holds. It signals whether there is an adaptation field, a payload, or both. The adaptation field carries timing and padding.','It lets a demultiplexer know how to parse each packet and where to find clock references used to lock the decoder.','When analysing a transport stream, an engineer reads the adaptation control bits to locate packets carrying the program clock reference.','Coding systems',ARRAY['Access unit','Audio access unit','Audio Data Transport Stream','Audio Essence']::text[],ARRAY['Confusing the adaptation control bits with the adaptation field they signal.','Assuming every packet has both an adaptation field and a payload.','Overlooking that the adaptation field can carry clock references, not just stuffing.']::text[],ARRAY['Parsing a broadcast transport stream.','Locating clock references for decoder sync.','Diagnosing packet-level stream errors.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Adaptation control');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a61f691d-ddf6-42c1-8700-dae7138f3aab','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a61f691d-ddf6-42c1-8700-dae7138f3aab') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a61f691d-ddf6-42c1-8700-dae7138f3aab');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e22857f8-4250-429b-932a-2da307996d88','All Frame','In the serial representation of the Audio Definition Model (S-ADM, ITU-R BS.2125), an all frame is a frame type that carries the complete metadata for an entire audio programme, including metadata describing past, present, and future audio. It suits static or fully pre-produced content whose metadata is known in advance.','Serial ADM sends audio metadata in frames. An all frame holds the metadata for a whole programme at once. That includes parts describing earlier and later audio. It fits finished content whose description is already complete.','It lets a whole programme''s metadata be delivered in one frame when the content is not being streamed frame by frame.','For a finished file-based mix, an engineer chooses the all frame type so the entire ADM travels in a single serial frame.','Serial metadata',ARRAY['Alternative Value Set','Audio element','Audio Essence','AXML Chunk']::text[],ARRAY['Confusing an all frame with a full frame, which describes only the current audio.','Using an all frame for live streaming, where per-frame types fit better.','Assuming an all frame omits future metadata; it may include it.']::text[],ARRAY['Delivering ADM metadata for a completed programme.','Choosing an S-ADM frame type for file exchange.','Interfacing serial ADM with a broadcast codec.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='All Frame');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e22857f8-4250-429b-932a-2da307996d88','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e22857f8-4250-429b-932a-2da307996d88') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e22857f8-4250-429b-932a-2da307996d88');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4615aa60-f504-46ef-be87-6d5c67545cb2','Alternative Value Set','In the Audio Definition Model (ITU-R BS.2076), an alternativeValueSet is an element inside an audioObject that provides an alternative set of parameter values. These values are applied in place of the object''s defaults when an audioProgramme or audioContent references the alternative value set by its identifier.','An ADM audio object has default settings such as position and gain. An alternative value set offers a second set of those values. Another part of the description can point to it. When it does, the alternative values are used instead.','It lets one audio object support more than one rendering variant without duplicating the whole object.','A mixer defines an alternative value set to move an object and lower its gain for a home-friendly version, selectable by the programme that references it.','Content metadata',ARRAY['Audio element','All Frame','AXML Chunk','Alternative audio element']::text[],ARRAY['Assuming the alternative values apply automatically rather than only when referenced.','Confusing an alternative value set with a separate audio object.','Forgetting to give the set a unique identifier for referencing.']::text[],ARRAY['Creating a home-optimised variant of an object mix.','Offering multiple renderings from one ADM object.','Authoring interactive object metadata.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Alternative Value Set');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4615aa60-f504-46ef-be87-6d5c67545cb2','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4615aa60-f504-46ef-be87-6d5c67545cb2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4615aa60-f504-46ef-be87-6d5c67545cb2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c307fde6-3710-4958-a47d-e4fec4a1e357','Alternative audio element','An alternative audio element is one of a set of mutually exclusive audio elements in a next-generation audio scene, of which a renderer or user selects exactly one at a time. In MPEG-H 3D Audio such alternatives are organised as a switch group, commonly used for language or commentary variants.','A scene may offer several versions of the same element. These are alternative audio elements. Only one plays at a time. A listener might switch between languages, for example, and the player picks one.','It lets content offer interchangeable choices, such as languages, while ensuring only one alternative is active.','An engineer groups English and Spanish commentary as alternative audio elements so a viewer hears only the chosen language.','Object audio',ARRAY['Audio element','Audio element group','Audio element dependency','Accessibility metadata']::text[],ARRAY['Playing more than one alternative at once, which defeats the switch behaviour.','Confusing alternatives (choose one) with a group (control together).','Assuming alternatives must have equal channel counts.']::text[],ARRAY['Offering multiple commentary languages in a broadcast.','Building a switch group for accessibility variants.','Authoring interactive personalised audio.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Alternative audio element');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c307fde6-3710-4958-a47d-e4fec4a1e357','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c307fde6-3710-4958-a47d-e4fec4a1e357') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c307fde6-3710-4958-a47d-e4fec4a1e357');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f4267176-764c-4902-a877-690af9bc8ba8','Arithmetic-coded spectral data','Arithmetic-coded spectral data are the frequency-domain (spectral) coefficients of an audio signal that have been losslessly compressed using arithmetic entropy coding. This technique appears in MPEG-4 audio, including the Unified Speech and Audio Coding (USAC) tool set, as an alternative to Huffman coding for the quantised spectrum.','Audio coders transform sound into frequency values. Those values are then packed as tightly as possible without loss. Arithmetic coding is one packing method. It can squeeze the spectral values more efficiently than simple table coding.','It reduces the number of bits needed to store quantised spectral coefficients, improving coding efficiency at a given quality.','A codec engineer comparing bitrates notes that arithmetic coding of the spectrum can lower the bits per frame versus Huffman tables at the same quality.','Coding systems',ARRAY['Access unit','Audio Data Transport Stream','Audio access unit','Audio Essence']::text[],ARRAY['Confusing lossless entropy coding of coefficients with the lossy quantisation that precedes it.','Assuming arithmetic coding changes the audio; the entropy step is reversible.','Thinking every AAC profile uses arithmetic coding; many use Huffman coding.']::text[],ARRAY['Analysing an MPEG-4 audio bitstream.','Comparing entropy-coding tools in a codec.','Explaining where compression gains arise in modern audio coders.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Arithmetic-coded spectral data');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f4267176-764c-4902-a877-690af9bc8ba8','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f4267176-764c-4902-a877-690af9bc8ba8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f4267176-764c-4902-a877-690af9bc8ba8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5df4a759-7c66-4b15-9e9b-67891541045e','Audio Data Transport Stream','The Audio Data Transport Stream (ADTS) is a self-framing byte-stream format for Advanced Audio Coding (AAC). Each ADTS frame begins with a header carrying a sync word plus fields such as profile, sampling-frequency index, channel configuration, and frame length, letting a decoder parse the stream without a separate container.','ADTS is a simple way to stream AAC audio. It puts a small header in front of every audio frame. The header includes a sync marker and basic settings. A decoder can lock on and play without any wrapper file.','It allows AAC to be streamed or stored as a raw sequence that is decodable from any point once a header is found.','An AAC audio frame lasts 1024 / f_s seconds; at 48 kHz that is 1024 / 48000 = 21.3 ms per ADTS frame.','Coding systems',ARRAY['Access unit','Audio access unit','Arithmetic-coded spectral data','Audio Essence']::text[],ARRAY['Confusing ADTS with the MPEG-2 transport stream; ADTS is an AAC framing format.','Assuming ADTS and raw LATM/LOAS framings are interchangeable.','Ignoring that the header repeats on every frame, adding overhead.']::text[],ARRAY['Streaming AAC over a simple byte channel.','Splicing AAC where each frame must self-describe.','Debugging a decoder that fails to find sync.']::text[],'intermediate','T_frame = N / f_s','The duration of one AAC frame equals the number of samples per frame divided by the sampling frequency.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio Data Transport Stream');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5df4a759-7c66-4b15-9e9b-67891541045e','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5df4a759-7c66-4b15-9e9b-67891541045e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5df4a759-7c66-4b15-9e9b-67891541045e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a594ddcb-f555-4950-82d9-82a132812453','Audio Essence','Audio essence is the actual audio content, that is, the coded or uncompressed audio samples, as distinct from the metadata that describes it. The term is used in professional file and streaming formats such as the Material Exchange Format (MXF), where essence and metadata are stored and carried separately.','In pro media files, the real audio samples are called the essence. Everything that describes the audio is metadata. Formats like MXF keep the two apart. This lets tools handle content and description separately.','Separating essence from metadata lets systems rewrap, index, or edit descriptive data without touching the audio content.','An operator rewrapping an MXF file moves the audio essence into a new container while updating only the surrounding metadata.','File formats',ARRAY['AXML Chunk','Access unit','Audio access unit','Accessibility metadata']::text[],ARRAY['Confusing essence (the content) with metadata (the description).','Assuming essence is always uncompressed; it may be coded.','Thinking rewrapping re-encodes the essence; it usually does not.']::text[],ARRAY['Rewrapping audio between MXF operational patterns.','Ingesting broadcast files into an archive.','Explaining the split between content and metadata.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio Essence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a594ddcb-f555-4950-82d9-82a132812453','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a594ddcb-f555-4950-82d9-82a132812453') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a594ddcb-f555-4950-82d9-82a132812453');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '12d9614b-927a-4f5a-bed3-d1ab7cbb84de','Audio Feature Ontology','The Audio Feature Ontology is a Semantic Web ontology, expressed in RDF/OWL, for describing audio features and the computational workflows and algorithms that extract them. It was developed within the semantic-audio research community to make feature data shareable and interoperable across tools.','Software can measure many traits of a sound. These traits are called features. This shared list gives each feature a clear name. It also notes how the feature was found. Then other tools can read the results.','It provides a common, machine-readable vocabulary so audio-analysis results from different tools can be compared and reused.','A music-information researcher publishes extracted features tagged with Audio Feature Ontology terms so others can interpret them without the original code.','Semantic metadata',ARRAY['Audio descriptor','Accessibility metadata','Audio element','AXML Chunk']::text[],ARRAY['Confusing the ontology (a vocabulary) with a feature-extraction tool.','Assuming it stores audio; it stores descriptions of features.','Treating it as an ISO standard rather than a research-community ontology.']::text[],ARRAY['Publishing reproducible audio-analysis datasets.','Linking feature data across research tools.','Annotating music collections with computed features.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio Feature Ontology');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '12d9614b-927a-4f5a-bed3-d1ab7cbb84de','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='12d9614b-927a-4f5a-bed3-d1ab7cbb84de') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='12d9614b-927a-4f5a-bed3-d1ab7cbb84de');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1585afcb-ac5c-460c-9ce7-028ff506090e','Audio access unit','An audio access unit is the access unit of an audio elementary stream: the block of coded data representing one audio frame that can be independently decoded and assigned decoding and presentation timestamps. It is the audio-specific case of the general MPEG access unit.','MPEG splits an audio stream into access units. Each one is the coded data for a single audio frame. It decodes on its own. Time stamps attach to it so it plays at the right moment.','It gives audio a clean, timestamped unit for buffering and synchronisation within a multiplexed stream.','During multiplexing, each audio access unit receives a presentation timestamp so its playback aligns with the matching video.','Coding systems',ARRAY['Access unit','Audio Data Transport Stream','Arithmetic-coded spectral data','Adaptation control']::text[],ARRAY['Confusing an audio access unit (coded) with the decoded audio samples.','Assuming one access unit always equals one transport packet.','Thinking access-unit boundaries match arbitrary byte offsets.']::text[],ARRAY['Timestamping audio during transport multiplexing.','Explaining audio buffering in a decoder model.','Splicing audio at frame boundaries.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio access unit');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1585afcb-ac5c-460c-9ce7-028ff506090e','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1585afcb-ac5c-460c-9ce7-028ff506090e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1585afcb-ac5c-460c-9ce7-028ff506090e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '72a152fd-5456-425a-bfa1-7f50b9f1e90e','Audio call-setup signaling','Audio call-setup signalling is the exchange of control messages that establishes an ATM connection for audio before any audio data is sent, as used by AES47. The signalling negotiates the connection and its parameters using ATM signalling procedures such as those of ITU-T Q.2931.','Before audio flows over ATM, the two ends must agree to connect. Control messages set this up. They negotiate the path and its settings. Only after the setup succeeds does audio start.','It reserves the connection and agrees parameters such as bandwidth and adaptation so the audio path is ready before transfer.','To open an AES47 link, equipment sends a setup message to the far end and waits for a connect response before streaming audio.','Network transport',ARRAY['ATM audio call','ATM adaptation-layer parameter','ATM interworking','AES3 frame']::text[],ARRAY['Assuming audio can flow before setup completes.','Confusing signalling messages with the audio bearer traffic.','Overlooking parameter negotiation, which can cause a mismatch.']::text[],ARRAY['Establishing a switched audio connection over ATM.','Diagnosing why an AES47 call fails to connect.','Explaining connection-oriented setup in training.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio call-setup signaling');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '72a152fd-5456-425a-bfa1-7f50b9f1e90e','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='72a152fd-5456-425a-bfa1-7f50b9f1e90e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='72a152fd-5456-425a-bfa1-7f50b9f1e90e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0ebd06ad-afff-43ea-95d3-448c0a953612','Audio chunk interleaving','Audio chunk interleaving is the arrangement of audio data so that it can be read sequentially without seeking, either by interleaving the samples of multiple channels sample by sample within a data chunk, or by interspersing audio data chunks with other media chunks in a file. Interleaved layout is central to streaming-friendly RIFF-based formats.','Interleaving lays data out in a set order. In multi-track audio, the samples take turns, one channel then the next. In movie files, audio blocks sit between video blocks. So a player can read straight through the file.','It keeps related data physically close so playback can stream from disk or network in one pass, avoiding costly seeks.','When authoring an audio-video file for streaming, an editor keeps chunks interleaved so audio never starves while video loads.','File formats',ARRAY['Audio Essence','AXML Chunk','Audio Data Transport Stream','Access unit']::text[],ARRAY['Confusing sample interleaving (within a channel group) with chunk interleaving (across the file).','Assuming interleaving changes the audio data; it only changes its ordering.','Delivering non-interleaved files for streaming, causing stalls.']::text[],ARRAY['Preparing a file for progressive streaming.','Writing multichannel PCM into a WAV data chunk.','Diagnosing playback stalls from poor interleave.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio chunk interleaving');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0ebd06ad-afff-43ea-95d3-448c0a953612','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0ebd06ad-afff-43ea-95d3-448c0a953612') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0ebd06ad-afff-43ea-95d3-448c0a953612');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fa47e0cb-92c6-4f7b-a20c-1d9295d6814b','Audio clip node','An audio clip node is a source node in an audio processing graph that plays back a stored, in-memory audio clip and feeds it into the graph. In the W3C Web Audio API this role is filled by the AudioBufferSourceNode, which plays samples held in an AudioBuffer.','An audio graph links processing blocks together. A clip node is a starting block. It holds a short sound already loaded in memory. When triggered, it plays that clip into the rest of the graph.','It lets short, pre-loaded sounds be triggered and routed through effects and mixing within a real-time audio graph.','A web developer loads a sound effect into a buffer and starts an AudioBufferSourceNode to play it on a user click.','Audio graph',ARRAY['Audio delay node','Audio element','Audio Essence','Access unit']::text[],ARRAY['Reusing a single source node after it has stopped; a new node is needed per playback.','Confusing an in-memory clip node with a streaming media source.','Assuming the node loops by default; looping must be enabled.']::text[],ARRAY['Triggering game or UI sound effects in a browser.','Building an interactive audio graph.','Sequencing short samples in a web app.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio clip node');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fa47e0cb-92c6-4f7b-a20c-1d9295d6814b','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fa47e0cb-92c6-4f7b-a20c-1d9295d6814b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fa47e0cb-92c6-4f7b-a20c-1d9295d6814b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0e7c5ad5-4acc-4c5c-9c7a-6801a5dbe63c','Audio conformance point','An audio conformance point is a defined, testable subset of a specification, such as a required codec, profile, level, and set of constraints, that an audio stream or decoder must satisfy to claim interoperability. Interoperability frameworks use conformance points so a device that meets one can be trusted to play any compliant stream at that point.','A big standard allows many options. A conformance point picks a fixed subset that must be supported. If a stream and a player both meet the same point, they will work together. It is a promise of compatibility.','It turns an open, flexible specification into a concrete interoperability target that content and devices can both aim at.','A device maker certifies a player against a named audio conformance point so any content authored to that point plays back correctly.','Coding systems',ARRAY['Audio Data Transport Stream','Audio element','Access unit','Arithmetic-coded spectral data']::text[],ARRAY['Confusing a conformance point (a requirements subset) with a full standard.','Assuming meeting one point implies meeting a higher one.','Ignoring that both content and device must target the same point.']::text[],ARRAY['Certifying a decoder for a streaming ecosystem.','Authoring content to a required interoperability target.','Comparing device capabilities across profiles.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio conformance point');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0e7c5ad5-4acc-4c5c-9c7a-6801a5dbe63c','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0e7c5ad5-4acc-4c5c-9c7a-6801a5dbe63c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0e7c5ad5-4acc-4c5c-9c7a-6801a5dbe63c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c895cecd-28f0-4042-bac7-eb40fff26d03','Audio delay node','An audio delay node is a processing node in an audio graph that applies a controllable time delay to the audio passing through it. In the W3C Web Audio API this is the DelayNode, whose delayTime parameter can be automated and whose maximum delay is set when the node is created (up to a defined limit).','A delay node holds the sound back for a set time before passing it on. The delay amount can be changed while playing. It is used to line up signals or to build echo effects. The maximum delay is fixed when you create it.','It introduces a defined time offset used for alignment, echo and comb-filter effects, or feedback loops within an audio graph.','A developer sets a DelayNode delayTime to 0.25 s and feeds its output back with gain to create a repeating echo.','Audio graph',ARRAY['Audio clip node','Audio element','Word clock','Audio Essence']::text[],ARRAY['Requesting a delay larger than the node''s maximum, which was fixed at creation.','Confusing signal delay with sample-rate or latency changes.','Forgetting that feedback around a delay needs gain control to stay stable.']::text[],ARRAY['Building an echo effect in a web audio app.','Time-aligning two signal paths.','Constructing a feedback delay network.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio delay node');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c895cecd-28f0-4042-bac7-eb40fff26d03','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c895cecd-28f0-4042-bac7-eb40fff26d03') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c895cecd-28f0-4042-bac7-eb40fff26d03');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cd54ddd4-0724-4262-bde8-ee845b171534','Audio element','An audio element is an individually addressable component of an object-based or next-generation audio scene, such as an audio object, a channel-based bed, or a higher-order Ambisonics group, carried with metadata that controls its rendering and any user interaction. Standards such as MPEG-H 3D Audio and the Audio Definition Model use audio elements as the building blocks of a scene.','A modern audio scene is built from parts. Each part is an audio element. It might be a moving object, a fixed channel bed, or a spatial group. Metadata says how to render each element and whether a listener can adjust it.','It lets a scene be described as separable components so a renderer can position, mix, and personalise them for the playback system.','A mixer defines dialogue as one audio element and ambience as another so a viewer can raise the dialogue independently.','Object audio',ARRAY['Audio element group','Alternative audio element','Audio element dependency','Alternative Value Set']::text[],ARRAY['Assuming an audio element is always a single channel; it may be an object, bed, or group.','Confusing the element (content plus metadata) with the raw audio alone.','Thinking elements always render identically regardless of playback layout.']::text[],ARRAY['Authoring an object-based immersive mix.','Enabling dialogue-level personalisation.','Mapping an ADM description to a renderer.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio element');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cd54ddd4-0724-4262-bde8-ee845b171534','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cd54ddd4-0724-4262-bde8-ee845b171534') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cd54ddd4-0724-4262-bde8-ee845b171534');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bd0105eb-67b6-42c0-934a-cf22e69f3808','Audio element group','An audio element group is a set of audio elements gathered together so that they can be selected, controlled, or interacted with as a unit. In MPEG-H 3D Audio, such groups let a renderer or user act on several related elements at once, for example adjusting or enabling them together.','Sometimes several audio elements belong together. A group ties them into one bundle. A listener or renderer can then act on the whole group at once. For example, all crowd microphones might form one group.','It simplifies control and interaction by letting related elements be handled collectively rather than one by one.','A mixer places all stadium crowd objects in one audio element group so a viewer can raise crowd level with a single control.','Object audio',ARRAY['Audio element','Alternative audio element','Audio element dependency','Alternative Value Set']::text[],ARRAY['Confusing a group (control together) with a switch of alternatives (choose one).','Assuming grouping merges the elements into one signal.','Overlooking that group membership drives the user-interaction controls.']::text[],ARRAY['Grouping crowd microphones for one-touch control.','Exposing a simple interaction control to viewers.','Organising a complex object scene for personalisation.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio element group');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bd0105eb-67b6-42c0-934a-cf22e69f3808','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bd0105eb-67b6-42c0-934a-cf22e69f3808') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bd0105eb-67b6-42c0-934a-cf22e69f3808');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8a7ff10e-e354-4a69-871a-d91633777638','Audio element identifier','In object-based and next-generation audio, an audio element identifier is a unique label that names one audio component — an object, channel bed, or group — within a program''s metadata, so a renderer can address, group, and control that element. It appears as ID attributes in the ITU-R Audio Definition Model (e.g., audioObject/audioContent IDs) and as metadata-audio-element IDs in MPEG-H 3D Audio.','Modern audio splits a program into parts, like dialogue or crowd. Each part gets its own ID number. The playback system uses that ID to find and control the part. This lets it raise dialogue or move a sound.','To let renderers and interactive controls address one specific audio element unambiguously among many in a program.','An engineer authoring an ADM WAV assigns each object a unique audioObjectID so downstream renderers apply the correct position and gain.','Object-Based Metadata',ARRAY['Audio Definition Model','Audio object','Metadata audio element','Renderer','audioContent']::text[],ARRAY['Confusing the identifier with the audio content itself; it labels, it is not the audio.','Assuming IDs are global, when they are usually unique only within one program or file.','Reusing one ID for two elements, which breaks rendering and interaction.']::text[],ARRAY['Authoring an ADM master for immersive delivery.','Mapping objects to an MPEG-H interactivity menu.','Debugging why a renderer applies the wrong gain to an object.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio element identifier');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8a7ff10e-e354-4a69-871a-d91633777638','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8a7ff10e-e354-4a69-871a-d91633777638') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8a7ff10e-e354-4a69-871a-d91633777638');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '437677c8-9aed-490a-b5a4-30d57501e2c2','Audio element interaction','Audio element interaction is metadata-governed user control over an individual audio element at playback — such as changing its level, position, on/off state, or language — within limits the content author sets. MPEG-H 3D Audio defines this through element-interaction metadata that a decoder exposes to the listener.','Some programs let you change parts of the sound. You might raise the voices or pick a language. The maker sets what you may change and by how much. The player follows those rules.','To give listeners controlled personalization while keeping the mix within the author''s intended bounds.','A broadcaster enables dialogue boost so a viewer can raise commentary by a permitted amount on an MPEG-H receiver.','Interactive Audio',ARRAY['MPEG-H 3D Audio','Dialogue enhancement','Audio object','Interactivity range','Renderer']::text[],ARRAY['Thinking interaction rewrites the master; it applies allowed, reversible changes at playback only.','Assuming every device exposes the same controls, when support varies.','Ignoring author-set limits and expecting unlimited adjustment.']::text[],ARRAY['Offering accessible dialogue boost on television.','Letting viewers choose home or away commentary.','Personalizing object levels on a soundbar.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio element interaction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '437677c8-9aed-490a-b5a4-30d57501e2c2','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='437677c8-9aed-490a-b5a4-30d57501e2c2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='437677c8-9aed-490a-b5a4-30d57501e2c2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f14832e2-9610-4d1b-a9a9-7fc1d6edf388','Audio elementary stream','An audio elementary stream is the raw, continuous output of a single audio encoder — one coded audio signal, such as an AAC or MP3 bitstream — before it is packetized or multiplexed. In MPEG systems it is the unit a decoder consumes, wrapped and synchronized by the systems layer.','An encoder turns one audio signal into a stream of coded data. That bare stream is the elementary stream. Systems layers wrap it for storage or sending. A decoder unwraps it and plays the audio.','To define the basic coded-audio data unit that transport and file layers wrap, carry, and synchronize.','When muxing to an MPEG-2 transport stream, an engineer maps each audio elementary stream to a PID with its own stream type.','Coded Bitstream',ARRAY['Packetized elementary stream','MPEG-2 Transport Stream','AAC','Access unit','Elementary stream descriptor']::text[],ARRAY['Confusing the elementary stream with the multiplexed transport stream that carries it.','Assuming it includes timing and sync, which come from the systems layer.','Thinking a program can carry only one audio elementary stream.']::text[],ARRAY['Demuxing a transport stream to extract audio.','Assigning PIDs during broadcast muxing.','Inspecting stream types in an MP4 or TS analyzer.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio elementary stream');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f14832e2-9610-4d1b-a9a9-7fc1d6edf388','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f14832e2-9610-4d1b-a9a9-7fc1d6edf388') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f14832e2-9610-4d1b-a9a9-7fc1d6edf388');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b77ab166-49cb-4038-85b6-b6b41336934f','Audio frame','An audio frame is the smallest independently coded block of audio a codec produces, carrying a fixed number of time-domain samples per channel (for example 1152 for MP3, 1024 for AAC) plus the side information needed to decode them. Its playback duration equals the sample count divided by the sampling frequency.','A codec cuts audio into small blocks called frames. Each frame holds a set number of samples. The player decodes one frame at a time. Frame size and sample rate set how long each frame lasts.','To package audio into decodable, seekable units and to bound coding delay and the spread of errors.','For AAC, N = 1024 samples at f_s = 48000 Hz gives a frame duration of 1024 / 48000 = 0.0213 s, about 21.3 ms.','Coded Bitstream',ARRAY['Sample rate','AAC','MP3','Frame header','Coding delay']::text[],ARRAY['Confusing a coded audio frame with a single PCM sample.','Assuming all codecs use the same frame length.','Forgetting that frame duration depends on sample rate, not just sample count.']::text[],ARRAY['Estimating codec latency for live monitoring.','Aligning audio frames to video for AV sync.','Parsing frame headers in a bitstream analyzer.']::text[],'intermediate','t_frame = N / f_s','Frame duration in seconds equals the number of samples per channel in the frame divided by the sampling frequency in hertz.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio frame');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b77ab166-49cb-4038-85b6-b6b41336934f','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b77ab166-49cb-4038-85b6-b6b41336934f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b77ab166-49cb-4038-85b6-b6b41336934f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f056dae9-5669-4a7e-b376-025115146408','Audio fundamental frequency','Audio fundamental frequency (f0) is the lowest, periodic repetition rate of a quasi-periodic audio signal, perceived as its pitch. In MPEG-7 (ISO/IEC 15938-4) the AudioFundamentalFrequency descriptor stores an estimated f0 contour over time, with a confidence measure, for content description and retrieval.','Many sounds repeat a basic pattern over and over. How often it repeats each second is the fundamental frequency. We hear it as pitch. A metadata system can store this value to describe the sound.','To describe pitch content over time so audio can be searched, classified, and analyzed.','A vowel that repeats every 5 ms has a fundamental frequency of f0 = 1 / 0.005 = 200 Hz.','Audio Descriptor',ARRAY['Pitch','Harmonicity','MPEG-7','Spectral analysis','Period']::text[],ARRAY['Confusing the fundamental frequency with the loudest harmonic.','Assuming pitch always equals a physically present f0 (the ''missing fundamental'').','Treating noisy or polyphonic signals as having one clear f0.']::text[],ARRAY['Melody-based music search.','Tagging speech pitch for prosody analysis.','Auto-classifying instrument recordings.']::text[],'intermediate','f_0 = 1 / T_0','The fundamental frequency in hertz equals one divided by the period of one repetition in seconds.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio fundamental frequency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f056dae9-5669-4a7e-b376-025115146408','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f056dae9-5669-4a7e-b376-025115146408') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f056dae9-5669-4a7e-b376-025115146408');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '688e1660-c58b-4d3d-bfe7-aa7ccc547531','Audio harmonicity','Audio harmonicity measures how strongly a signal''s spectrum consists of components at integer multiples of a fundamental — that is, how tonal and periodic versus noise-like it is. In MPEG-7 (ISO/IEC 15938-4) the AudioHarmonicity descriptor reports a HarmonicRatio and an UpperLimitOfHarmonicity.','Some sounds are clean and musical. Others are noisy, like a cymbal or hiss. Harmonicity scores how orderly and tonal a sound is. Metadata can store this to sort or search sounds.','To quantify tonal-versus-noisy character for classification, segmentation, and retrieval.','A sound-effects library uses harmonicity to separate pitched instruments from noise-like effects.','Audio Descriptor',ARRAY['Harmonic ratio','Fundamental frequency','MPEG-7','Spectral flatness','Timbre']::text[],ARRAY['Reading high harmonicity as ''loud''; it describes structure, not level.','Assuming one number covers a whole clip, when it varies over time.','Confusing harmonicity with harmonic distortion.']::text[],ARRAY['Sorting instrument versus noise samples.','Speech and music discrimination.','Feeding features into an audio classifier.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio harmonicity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '688e1660-c58b-4d3d-bfe7-aa7ccc547531','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='688e1660-c58b-4d3d-bfe7-aa7ccc547531') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='688e1660-c58b-4d3d-bfe7-aa7ccc547531');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8ca0b58a-a1e5-42e5-99e5-224a10cfbbe8','Audio identification','Audio identification is the automatic recognition of a specific recording by extracting a compact, robust fingerprint from the audio and matching it against a reference database. MPEG-7 (ISO/IEC 15938-4) standardizes a fingerprint for this purpose through the AudioSignature description scheme.','A system can name a song from a short clip. It makes a small fingerprint of the sound. Then it compares that to a big database. A match tells it which recording it is.','To recognize and track content for search, rights, and monitoring, even after compression or added noise.','A broadcast-monitoring service fingerprints airchecks and matches them to identify which tracks aired.','Content Identification',ARRAY['Audio signature','Audio fingerprint','MPEG-7','Watermarking','Content recognition']::text[],ARRAY['Confusing fingerprinting (reads the audio) with watermarking (embeds data).','Assuming identification needs the exact original file; robust fingerprints tolerate coding.','Thinking it recognizes any performance, when it matches the specific recording.']::text[],ARRAY['Music recognition apps.','Broadcast play-out logging for royalties.','De-duplicating an audio archive.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio identification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8ca0b58a-a1e5-42e5-99e5-224a10cfbbe8','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8ca0b58a-a1e5-42e5-99e5-224a10cfbbe8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8ca0b58a-a1e5-42e5-99e5-224a10cfbbe8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ecff9f47-ad4b-4852-a507-36e8f75a8a4f','Audio interactivity','Audio interactivity is the general capability of a next-generation audio system to let the listener alter the presentation at playback — selecting alternative mixes, boosting dialogue, choosing languages, or adjusting object levels — governed by author-supplied metadata and rendered locally. It is a defining feature of object-based systems such as MPEG-H 3D Audio.','Interactive audio lets the listener change the sound. They may pick a language or a mix. Or they raise the voices. Rules from the maker keep it within limits.','To support personalization and accessibility without shipping many separate finished mixes.','A sports feed offers ''stadium only'' versus ''with commentary'' presentations the viewer switches on a next-generation-audio receiver.','Interactive Audio',ARRAY['MPEG-H 3D Audio','Object-based audio','Dialogue enhancement','Preset','Accessibility']::text[],ARRAY['Assuming interactivity means unlimited control, when authors constrain it.','Confusing it with simple fixed channel selection.','Expecting identical features across all playback devices.']::text[],ARRAY['Accessible dialogue enhancement on television.','Alternate commentary selection.','Personalized immersive music mixes.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio interactivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ecff9f47-ad4b-4852-a507-36e8f75a8a4f','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ecff9f47-ad4b-4852-a507-36e8f75a8a4f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ecff9f47-ad4b-4852-a507-36e8f75a8a4f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9ef1d467-b54e-42ef-a914-b144cb4bc537','Audio manifestation','In FRBR-derived metadata models such as EBUCore (EBU Tech 3293), a manifestation is a specific physical or digital embodiment of an audio expression — for example a particular encoded file, tape, or disc — as distinct from the abstract work or its performance. It carries the technical attributes (format, codec, carrier) of that concrete instance.','The same recording can exist in many forms. There may be a WAV file, an MP3, and a CD. Each concrete form is a manifestation. Archives track each one with its own details.','To separate the abstract work from its concrete encodings so archives can catalog each carrier and format precisely.','An archivist records a WAV master and its MP3 access copy as two manifestations of one recording.','Metadata Model',ARRAY['EBUCore','Work','Expression','FRBR','Media asset management']::text[],ARRAY['Confusing the manifestation (a format or carrier) with the abstract work.','Treating two file formats of one recording as identical entities.','Mixing up a manifestation with a single physical item (the copy).']::text[],ARRAY['Cataloging masters and access copies.','Modeling holdings in an archive database.','Mapping EBUCore into a media-asset-management system.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio manifestation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9ef1d467-b54e-42ef-a914-b144cb4bc537','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9ef1d467-b54e-42ef-a914-b144cb4bc537') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9ef1d467-b54e-42ef-a914-b144cb4bc537');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd14cdd40-7f60-41bc-8b1e-3f223620088f','Audio media timescale','In the ISO base media file format (ISO/IEC 14496-12), the media timescale is the integer number of time units that pass in one second for a track; all sample times and durations in that track are expressed in these units. For audio it is typically set to the sampling rate (e.g., 48000) so one tick equals one sample period.','A media file needs a clock to place sounds in time. The timescale says how many ticks make one second. Sample times use these ticks. Setting it to the sample rate makes one tick one sample.','To express all timing in a track as exact integers, avoiding rounding while allowing precise conversion to seconds.','With a timescale of 48000, a duration of 1024 ticks equals 1024 / 48000 = 0.0213 s, about 21.3 ms.','File Format Timing',ARRAY['ISO base media file format','Sample duration','Movie header','Edit list','Sampling rate']::text[],ARRAY['Confusing the movie timescale with each track''s media timescale.','Assuming the timescale equals the frame rate rather than a chosen tick rate.','Forgetting to divide by the timescale when converting ticks to seconds.']::text[],ARRAY['Authoring fragmented MP4 for streaming.','Computing sample timestamps in a parser.','Aligning audio and video edit lists.']::text[],'intermediate','t = n / timescale','Time in seconds equals a duration expressed in timescale ticks divided by the timescale in ticks per second.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio media timescale');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd14cdd40-7f60-41bc-8b1e-3f223620088f','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d14cdd40-7f60-41bc-8b1e-3f223620088f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d14cdd40-7f60-41bc-8b1e-3f223620088f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c57e23c0-9251-498e-86ab-5c46d690235c','Audio metadata code point','An audio metadata code point is a specific value drawn from a standardized, enumerated codespace that encodes a defined metadata meaning — for example a numeric type or format identifier in the ITU-R Audio Definition Model, or a registered key in a SMPTE metadata register. A decoder interprets the number by looking it up in the controlling registry.','Metadata often uses numbers as shorthand. Each number has a fixed, agreed meaning. That agreed value is a code point. Systems read the number and look up what it means.','To carry metadata meanings compactly and unambiguously by referencing a shared registry instead of free text.','An ADM tool sets an object''s typeDefinition code point to the value meaning ''Objects'' so renderers treat it correctly.','Metadata Coding',ARRAY['Audio Definition Model','SMPTE metadata register','typeDefinition','Enumeration','Registry']::text[],ARRAY['Inventing an unregistered value that no decoder can interpret.','Assuming a code point''s meaning is universal across standards, when it is per-registry.','Confusing the code point (the number) with its human-readable label.']::text[],ARRAY['Setting ADM type and format identifiers.','Mapping metadata into a SMPTE register.','Validating that metadata values are registered.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio metadata code point');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c57e23c0-9251-498e-86ab-5c46d690235c','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c57e23c0-9251-498e-86ab-5c46d690235c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c57e23c0-9251-498e-86ab-5c46d690235c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8fbd40cc-14ef-4261-b6b2-5a45e75eda78','Audio metadata enhancement','Audio metadata enhancement is the process of enriching a recording''s metadata — adding or refining descriptive, technical, and structural fields such as loudness, format, rights, and content descriptors — so the asset is easier to find, manage, and process. It is applied within frameworks such as EBUCore and PREMIS rather than being a single coded field.','Files carry facts about the audio, called metadata. To enhance it, you add or fix that data. Good data makes files easy to find and sort. Archives do this to keep their audio useful.','To improve discoverability, interoperability, and long-term management of audio assets.','An archive runs loudness analysis and adds the result, plus rights and format fields, to each file''s EBUCore record.','Metadata Management',ARRAY['EBUCore','PREMIS','Metadata enrichment','Cataloging','Descriptive metadata']::text[],ARRAY['Confusing metadata enhancement with audio-signal enhancement, such as dialogue boost.','Assuming automated tags need no human review.','Adding fields without following a schema, which breaks interoperability.']::text[],ARRAY['Enriching archive catalog records.','Adding loudness and technical metadata during ingest.','Preparing assets for a media-asset-management system.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio metadata enhancement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8fbd40cc-14ef-4261-b6b2-5a45e75eda78','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8fbd40cc-14ef-4261-b6b2-5a45e75eda78') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8fbd40cc-14ef-4261-b6b2-5a45e75eda78');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1c93829b-2352-4396-818f-0b3380b6c10e','Audio metadata invalidation','Audio metadata invalidation is the condition in which stored metadata no longer correctly describes the associated audio — typically after editing, gain changes, transcoding, or sample-rate conversion — so values such as integrated loudness, peak level, checksums, or timecode become stale and must be recomputed or flagged as no longer valid.','Metadata must match the audio it describes. If you edit or change the audio, old metadata can go stale. Then it is wrong and should not be trusted. You must recompute it or mark it invalid.','To signal that derived metadata is out of date and to stop downstream systems from trusting stale values.','After trimming a file, an engineer re-runs loudness measurement because the old EBU R128 value no longer matches the shorter program.','Metadata Management',ARRAY['Loudness metadata','EBU R128','Checksum','Broadcast Wave Format','Transcoding']::text[],ARRAY['Trusting old loudness or peak values after editing the audio.','Copying bext or timecode metadata to an edited file unchanged.','Assuming transcoding preserves all technical metadata.']::text[],ARRAY['Re-measuring loudness after an edit.','Regenerating checksums after processing.','Validating metadata before delivery QC.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio metadata invalidation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1c93829b-2352-4396-818f-0b3380b6c10e','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1c93829b-2352-4396-818f-0b3380b6c10e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1c93829b-2352-4396-818f-0b3380b6c10e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7ae4f3aa-5827-4c10-9abe-eeaadc0ee913','Audio mixing node','An audio mixing node is a processing point in an audio signal-flow graph where two or more input signals are summed, with defined channel up/down-mixing rules, into a single combined output. In the W3C Web Audio API any node input performs this mixing when several sources connect to it, and a GainNode is commonly used to sum and level inputs.','Audio systems can be drawn as a graph of connected boxes. A mixing point is where several signals meet and add together. Rules decide how channels combine. The result is one blended output.','To combine multiple audio sources into one signal within a routing or processing graph.','In a browser app, a developer connects several sources to one GainNode input so they mix before reaching the output.','Audio Routing',ARRAY['Web Audio API','Audio node','Signal graph','Summing','Up-mixing']::text[],ARRAY['Assuming mixing rescales to avoid clipping; simple summing can overload.','Ignoring channel up/down-mix rules when inputs differ in channel count.','Confusing a mixing node with a physical mixing-console channel.']::text[],ARRAY['Building a browser-based audio app.','Summing stems in a processing graph.','Designing a modular DSP signal chain.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio mixing node');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7ae4f3aa-5827-4c10-9abe-eeaadc0ee913','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7ae4f3aa-5827-4c10-9abe-eeaadc0ee913') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7ae4f3aa-5827-4c10-9abe-eeaadc0ee913');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4e95ce58-7960-4bb0-bc75-772ca8ba5a35','Audio multiplex element','In MPEG-4 Audio''s Low-overhead Audio Transport Multiplex (LATM, ISO/IEC 14496-3), the AudioMuxElement is the top-level syntactic unit that packages one or more coded audio payloads, optionally together with the multiplex configuration (StreamMuxConfig), for transport. It is the element a LATM/LOAS parser reads to recover the audio.','One transport format can carry several audio streams together. The multiplex element is the block that holds them. It may also carry the setup information. A parser reads this block to get the audio.','To carry MPEG-4 audio, and optionally its configuration, efficiently over channels that lack their own framing.','A streaming encoder wraps AAC in LATM AudioMuxElements (LOAS) for carriage inside an MPEG-2 transport stream.','Audio Transport',ARRAY['LATM','LOAS','StreamMuxConfig','AAC','MPEG-2 Transport Stream']::text[],ARRAY['Confusing LATM (self-configuring) with plain ADTS framing.','Assuming every AudioMuxElement carries the config, when it can be sent out of band.','Mixing up the multiplex element with a single audio frame.']::text[],ARRAY['Encapsulating AAC for broadcast transport.','Parsing LOAS/LATM in a stream analyzer.','Configuring HE-AAC delivery.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio multiplex element');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4e95ce58-7960-4bb0-bc75-772ca8ba5a35','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4e95ce58-7960-4bb0-bc75-772ca8ba5a35') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4e95ce58-7960-4bb0-bc75-772ca8ba5a35');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ef088610-89f2-497e-938b-1bef1dca2665','Audio over asynchronous transfer mode','Audio over asynchronous transfer mode is the transport of professional digital audio across ATM networks, standardized as AES47, which maps AES3-formatted audio into ATM adaptation-layer cells for low-latency, connection-oriented delivery over studio and wide-area ATM links. AES51 defines carrying these ATM cells over 100BASE-TX Ethernet physical layers.','ATM is an older network that sends data in small fixed cells. AES47 packs digital audio into these cells. This gave studios low-delay audio over long links. A related standard sends the cells over Ethernet wiring.','To move professional audio with low, predictable latency over connection-oriented ATM telecom networks.','A broadcaster links two facilities over an ATM circuit using AES47 to carry multichannel AES3 audio.','Digital Audio Transport',ARRAY['AES47','AES51','AES3','ATM adaptation layer','Circuit-based audio']::text[],ARRAY['Confusing ATM (Asynchronous Transfer Mode) with modern packet audio like Dante or AES67.','Assuming ATM is packet-switched IP, when it is cell-based and connection-oriented.','Expecting current gear to support it, as ATM audio is largely legacy.']::text[],ARRAY['Legacy inter-facility audio links.','Maintaining older broadcast ATM circuits.','Studying the history of audio transport standards.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio over asynchronous transfer mode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ef088610-89f2-497e-938b-1bef1dca2665','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ef088610-89f2-497e-938b-1bef1dca2665') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ef088610-89f2-497e-938b-1bef1dca2665');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f376a185-982e-4a82-b4da-714978edc9e9','Audio preroll','Audio pre-roll is a mechanism, defined for MPEG-D USAC (ISO/IEC 23003-3) and used in MPEG-H 3D Audio, that carries the decoder configuration plus one or more prior audio frames at a stream access point. The decoder consumes these frames to warm up its internal state, so output is correct immediately from the access point during tune-in or splicing.','When you jump into a stream, the decoder starts cold. Pre-roll sends a few earlier frames first. The decoder runs them silently to warm up. Then playback from the join point sounds correct at once.','To enable clean random access and splicing without startup artifacts by preloading decoder state and configuration.','In DASH streaming, a segment begins with an audio pre-roll so a decoder tuning in mid-stream outputs correct audio from the first frame.','Coded Bitstream',ARRAY['Immediate playout frame','USAC','MPEG-H 3D Audio','Stream access point','Random access']::text[],ARRAY['Thinking pre-roll frames are played out, when they are decoded silently to prime state.','Assuming any frame allows clean tune-in without pre-roll.','Confusing pre-roll with an ordinary playback buffer.']::text[],ARRAY['Tuning into a live DASH audio stream.','Ad splicing in broadcast.','Seeking within a coded audio file.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio preroll');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f376a185-982e-4a82-b4da-714978edc9e9','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f376a185-982e-4a82-b4da-714978edc9e9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f376a185-982e-4a82-b4da-714978edc9e9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8d84dd67-4179-4251-bba4-ebe7e02182a6','Audio preroll recovery','Audio pre-roll recovery refers to a decoder reaching correct, steady-state output after consuming the pre-roll frames provided at a stream access point. Because codecs such as USAC carry state — overlap-add windows, prediction, and filter memories — across frames, the preloaded frames let that internal state converge so the first output frame at the access point is artifact-free.','Some codecs remember data from past frames. If you jump in, that memory is missing. Pre-roll frames refill it. Once refilled, the decoder recovers and output is clean.','To ensure decoder state converges before playout begins at a random-access or splice point.','A player seeks to a new position, decodes the pre-roll frames silently, and starts output only once state has recovered.','Coded Bitstream',ARRAY['Audio pre-roll','Overlap-add','Decoder state','Random access','USAC']::text[],ARRAY['Assuming recovery is instant regardless of codec memory.','Outputting the pre-roll frames instead of discarding them.','Providing too few pre-roll frames, leaving state unconverged.']::text[],ARRAY['Gapless seeking in a media player.','Clean stream tune-in.','Splice points in adaptive streaming.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio preroll recovery');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8d84dd67-4179-4251-bba4-ebe7e02182a6','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8d84dd67-4179-4251-bba4-ebe7e02182a6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8d84dd67-4179-4251-bba4-ebe7e02182a6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'aab6c008-810a-497d-9f9e-7b88d2697e94','Audio preservation event','An audio preservation event is a recorded action in the digital-preservation lifecycle of an audio object — such as ingest, fixity (checksum) verification, format migration, or normalization — documented under the PREMIS Data Dictionary (Library of Congress) Event entity with its type, date and time, responsible agent, and outcome.','Archives must prove they cared for a file over time. Each action, like a copy or a check, is logged. That logged action is a preservation event. It records what happened, when, by whom, and the result.','To create an auditable history that proves an audio file''s integrity and authenticity over time.','An archive logs a monthly fixity check as a PREMIS event, recording the checksum result and the tool used.','Preservation Metadata',ARRAY['PREMIS','Fixity','Checksum','Ingest','Format migration']::text[],ARRAY['Confusing a preservation event (an action log) with descriptive metadata.','Recording outcomes without the agent or date, which breaks the audit trail.','Assuming one ingest event is enough, when ongoing events are needed.']::text[],ARRAY['Logging ingest and fixity checks.','Documenting a format migration.','Building an audit trail for an audio archive.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio preservation event');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'aab6c008-810a-497d-9f9e-7b88d2697e94','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='aab6c008-810a-497d-9f9e-7b88d2697e94') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='aab6c008-810a-497d-9f9e-7b88d2697e94');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e821a6fc-4e59-4d48-8072-18f4eb66d8f1','Audio profile-level compatibility','Audio profile-level compatibility describes whether a coded audio stream can be decoded by a given decoder, based on matching the codec profile (a defined toolset) and level (bounds on complexity such as channel count and sample rate). A decoder built to a profile at a level can decode streams that require that profile at that level or lower.','Codecs come in versions called profiles, each with limits called levels. A player supports certain profiles and levels. A file plays only if the player''s profile and level cover it. This match is compatibility.','To let makers guarantee interoperability by declaring which streams a decoder can handle.','An engineer checks that a delivery''s AAC profile and level fall within the target device''s supported profile@level before shipping.','Conformance',ARRAY['Profile','Level','audioProfileLevelIndication','AAC','Conformance']::text[],ARRAY['Assuming any decoder plays any stream of the same codec family.','Matching only the profile while ignoring level limits like channels and sample rate.','Confusing profile (tools) with level (limits).']::text[],ARRAY['Selecting an encode target for a set-top box.','QC of a deliverable against a spec.','Troubleshooting a stream that will not decode.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio profile-level compatibility');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e821a6fc-4e59-4d48-8072-18f4eb66d8f1','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e821a6fc-4e59-4d48-8072-18f4eb66d8f1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e821a6fc-4e59-4d48-8072-18f4eb66d8f1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e42930e1-776a-400e-a69f-2a9664fc4879','Audio profile-level indication','In MPEG-4 Systems (ISO/IEC 14496-1), audioProfileLevelIndication is a single-byte field, carried in the InitialObjectDescriptor, that signals the audio profile and level a terminal must support to decode the content''s audio. A decoder reads it to decide whether it can handle the stream before attempting to decode.','A file can announce what a player needs to decode its audio. One code byte states the required profile and level. The player reads it first. If it cannot meet it, it will not try.','To advertise the decoding capability a stream requires so players can accept or reject it upfront.','A muxer writes the correct audioProfileLevelIndication (for example, for AAC LC) into the file''s object descriptor so compliant players know what is needed.','Conformance',ARRAY['Initial object descriptor','Profile','Level','Audio profile-level compatibility','MPEG-4 Systems']::text[],ARRAY['Leaving the value at a wrong or default code, causing rejection.','Confusing the audio indication byte with the visual profile-level byte.','Assuming the field decodes audio, when it only signals requirements.']::text[],ARRAY['Setting descriptors during MP4 muxing.','Diagnosing a rejected stream.','Validating an MPEG-4 file''s signaling.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio profile-level indication');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e42930e1-776a-400e-a69f-2a9664fc4879','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e42930e1-776a-400e-a69f-2a9664fc4879') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e42930e1-776a-400e-a69f-2a9664fc4879');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c3c6cc61-0fc7-4549-a9e0-9f159fea4921','Audio protocol discriminator','A protocol discriminator is the first octet of a Q.931/ISDN layer-3 signaling message that identifies which signaling protocol the message belongs to — for example the call control used to set up voice- or audio-bearing calls. It lets a receiver route each message to the correct protocol handler. ITU-T Q.931 defines the field and its coded values.','Phone networks send control messages to set up calls. The first byte says which rulebook the message follows. That byte is the protocol discriminator. The receiver uses it to read the message correctly.','To let signaling endpoints identify each message and dispatch it to the correct protocol handler.','An ISDN analyzer reads the protocol discriminator to confirm a message is Q.931 call control before decoding it.','Signaling',ARRAY['Q.931','ISDN','Information element','Call control','Message type']::text[],ARRAY['Assuming it identifies the audio codec, when it identifies the signaling protocol.','Confusing the protocol discriminator with the message-type octet.','Thinking it carries media, when it is control-plane only.']::text[],ARRAY['Debugging ISDN call setup.','Decoding signaling captures.','Interworking legacy telephony with VoIP.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio protocol discriminator');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c3c6cc61-0fc7-4549-a9e0-9f159fea4921','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c3c6cc61-0fc7-4549-a9e0-9f159fea4921') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c3c6cc61-0fc7-4549-a9e0-9f159fea4921');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '05ee150e-a9ff-444a-bf8f-bcce91ac3d76','Audio sample description','In the ISO base media file format (ISO/IEC 14496-12), the sample description (SampleDescriptionBox, ''stsd'') holds one or more sample entries that tell a decoder how the track''s samples are coded. For audio, its AudioSampleEntry records the codec type, channel count, sample size, and sample rate.','A media file must say how its audio is coded. The sample description holds those details. It names the codec and lists channels, bit depth, and rate. A player reads it before decoding.','To provide the format parameters a decoder needs to interpret a track''s samples.','A parser reads the ''stsd'' AudioSampleEntry to learn a track is 48 kHz stereo AAC before setting up the decoder.','File Format Structure',ARRAY['Audio sample entry','Sample table','ISO base media file format','Codec configuration','stsd']::text[],ARRAY['Confusing the sample description (format info) with the sample data itself.','Assuming one entry always covers the whole track.','Overlooking codec-specific configuration boxes inside the entry.']::text[],ARRAY['Initializing a decoder from an MP4.','Repairing a broken ''stsd''.','Inspecting track format in an analyzer.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio sample description');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '05ee150e-a9ff-444a-bf8f-bcce91ac3d76','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='05ee150e-a9ff-444a-bf8f-bcce91ac3d76') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='05ee150e-a9ff-444a-bf8f-bcce91ac3d76');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1f125e25-ffed-42f9-98a8-d4ea8edcc715','Audio sample duration','In the ISO base media file format (ISO/IEC 14496-12), a sample''s duration is the number of media-timescale units it occupies before the next sample, recorded in the TimeToSample box (''stts'') or as a track-fragment default. Summed durations define each sample''s decode time; the value in seconds is the duration divided by the media timescale.','A file must know how long each audio piece lasts. Sample duration gives this in clock ticks. Divide by the timescale to get seconds. Adding durations places each sample in time.','To define per-sample timing so decode and presentation times can be computed exactly.','An AAC frame of 1024 samples in a track with timescale 48000 has duration 1024, so 1024 / 48000 = 21.3 ms.','File Format Timing',ARRAY['Media timescale','Time-to-sample','Decode time','Sample table','Track fragment']::text[],ARRAY['Reading the raw tick duration as seconds without dividing by the timescale.','Assuming all audio samples share one duration, when they may vary.','Confusing sample duration with sample size in bytes.']::text[],ARRAY['Computing timestamps in a demuxer.','Building fragmented MP4 timing.','Diagnosing AV drift.']::text[],'intermediate','delta_t = d / timescale','A sample''s duration in seconds equals its duration in timescale ticks divided by the media timescale in ticks per second.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio sample duration');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1f125e25-ffed-42f9-98a8-d4ea8edcc715','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1f125e25-ffed-42f9-98a8-d4ea8edcc715') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1f125e25-ffed-42f9-98a8-d4ea8edcc715');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '00f3f4fd-f208-4d64-9014-122ee3d6277d','Audio sample entry','An audio sample entry (AudioSampleEntry) is the structure inside an ISO base media file format (ISO/IEC 14496-12) sample description that describes one coding format for an audio track, carrying its four-character codec type plus fields such as channel count, sample size, and sample rate, and usually a codec-specific configuration box (for example ''esds'' for AAC).','Inside the format section sits a block for the audio codec. It states the codec name and basic settings. It may also hold extra codec setup data. A decoder uses it to start correctly.','To specify, per coding format, the parameters and configuration a decoder needs for an audio track.','A muxer writes an ''mp4a'' AudioSampleEntry with 2 channels, 16-bit, 48000, plus an ''esds'' AAC configuration.','File Format Structure',ARRAY['Audio sample description','AAC configuration','esds','ISO base media file format','Codec fourCC']::text[],ARRAY['Omitting the codec-specific configuration box, leaving decoders unable to initialize.','Trusting the sample-rate field for tools like SBR where the true output rate differs.','Confusing the sample entry with the sample data.']::text[],ARRAY['Muxing AAC into MP4.','Reading codec setup in a parser.','Fixing files that will not initialize a decoder.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio sample entry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '00f3f4fd-f208-4d64-9014-122ee3d6277d','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='00f3f4fd-f208-4d64-9014-122ee3d6277d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='00f3f4fd-f208-4d64-9014-122ee3d6277d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fa24eae9-0212-44ee-8674-1614a5b1d15a','Audio sample group','In the ISO base media file format (ISO/IEC 14496-12), a sample group associates selected samples with shared properties using the SampleToGroup (''sbgp'') and SampleGroupDescription (''sgpd'') boxes. For audio, the ''roll'' grouping marks how many preceding samples must be decoded before output is correct at a random-access point.','Sometimes certain samples share a special property. Sample groups tag those samples and store the property once. For audio, a roll group says how many earlier frames a decoder needs. This supports clean seeking.','To attach shared, non-per-sample properties — such as roll/pre-roll distance or encryption — to sets of samples efficiently.','A packager writes a ''roll'' sample group so players know how many AAC frames to pre-decode when seeking.','File Format Structure',ARRAY['Sample table','Roll distance','Audio pre-roll','Random access','sgpd']::text[],ARRAY['Ignoring the ''roll'' group and getting artifacts after a seek.','Confusing the grouping box (''sbgp'') with the group-description box (''sgpd'').','Assuming every sample must belong to a group.']::text[],ARRAY['Enabling clean seek points in streaming.','Signaling encryption on selected samples.','Handling AAC roll distance for random access.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio sample group');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fa24eae9-0212-44ee-8674-1614a5b1d15a','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fa24eae9-0212-44ee-8674-1614a5b1d15a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fa24eae9-0212-44ee-8674-1614a5b1d15a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3e8aad2b-d949-4642-b736-4fc17258a4c0','Audio sample packet','In IEC 61883-6 (audio and music data transmission over IEEE 1394), an audio sample packet is an isochronous common-isochronous-packet (CIP) that carries a block of audio, and optionally MIDI, data — commonly in the AM824 format — across a FireWire bus once per 125 microsecond cycle. It transports one or more channels of samples with a label per quadlet.','FireWire moved audio in small timed packets. Each packet carries a group of audio samples. This standard defines how those packets are built. Studio interfaces once used it to send many channels.','To carry multichannel professional audio, and MIDI, with timing over IEEE 1394 buses.','An mLAN interface sends 8 channels of 24-bit audio as IEC 61883-6 sample packets over FireWire.','Digital Audio Transport',ARRAY['IEEE 1394','AM824','Common isochronous packet','mLAN','Isochronous transfer']::text[],ARRAY['Confusing IEC 61883-6 audio packets with IP audio like Dante or AES67.','Assuming it uses asynchronous transfers, when audio uses isochronous cycles.','Mixing up the CIP header with the sample data payload.']::text[],ARRAY['Maintaining legacy FireWire audio rigs.','Debugging mLAN channel counts.','Studying IEEE 1394 audio transport.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio sample packet');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3e8aad2b-d949-4642-b736-4fc17258a4c0','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3e8aad2b-d949-4642-b736-4fc17258a4c0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3e8aad2b-d949-4642-b736-4fc17258a4c0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '554f234e-45fb-4b36-918b-909299c1e357','Audio sample table','In the ISO base media file format (ISO/IEC 14496-12), the sample table (SampleTableBox, ''stbl'') is the container holding all the indexing tables — sample description, timing, sizes, chunk offsets, and sync/grouping — needed to locate, time, and decode every sample in a track. It is the map that turns byte offsets into timed samples.','A track''s audio is stored as many samples. The sample table indexes them all. It lists where each is, how big, and when it plays. A player reads it to find and time samples.','To provide the complete index that lets a reader randomly access and time a track''s samples.','A demuxer walks the ''stbl'' child boxes to find the byte offset and timestamp of a target audio sample.','File Format Structure',ARRAY['Audio sample description','Time-to-sample','Sample size','Chunk offset','ISO base media file format']::text[],ARRAY['Assuming samples are stored inside ''stbl'', when it only indexes them.','Ignoring 64-bit offsets (''co64'') for large files.','Confusing the sample table with a fragment''s track run.']::text[],ARRAY['Random-access seeking in an MP4.','Repairing a corrupt index.','Understanding non-fragmented MP4 layout.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio sample table');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '554f234e-45fb-4b36-918b-909299c1e357','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='554f234e-45fb-4b36-918b-909299c1e357') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='554f234e-45fb-4b36-918b-909299c1e357');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e85ce233-5783-4558-a52b-54ed8d85199f','Audio sampling clock traceability','Audio sampling-clock traceability is the property whereby a system''s sample-clock frequency can be related, through an unbroken chain of comparisons, to a recognized reference — in studios typically an AES11 digital audio reference signal (DARS), and ultimately a national or international frequency standard. AES11 grade 1 sets a long-term accuracy of one part per million relative to such a reference.','Every digital audio device runs on a clock. Traceability means that clock ties back to a trusted reference. Studios lock devices to one house reference. That reference can trace to a national standard. This keeps gear in sync and on speed.','To guarantee that distributed audio clocks share a common, verifiable frequency so devices stay synchronized and sample-accurate.','A facility locks all converters to an AES11 grade-1 DARS whose generator is disciplined to a GPS-traceable reference.','Synchronization',ARRAY['AES11','Word clock','Digital audio reference signal','PTP (IEEE 1588)','Sample rate']::text[],ARRAY['Assuming a free-running internal crystal is traceable; it is not without a reference.','Confusing frequency traceability (speed) with absolute time-of-day synchronization.','Believing ''locked to house clock'' guarantees a documented traceability chain.']::text[],ARRAY['Setting up a studio house clock.','Meeting delivery specs that require clock accuracy.','Syncing audio to video and GPS-referenced timing.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio sampling clock traceability');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e85ce233-5783-4558-a52b-54ed8d85199f','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e85ce233-5783-4558-a52b-54ed8d85199f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e85ce233-5783-4558-a52b-54ed8d85199f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ac167e30-7b56-4c62-9481-0ae4e69e04b2','Audio signature','An audio signature is a compact, robust representation — a fingerprint — derived from a recording''s spectral features that identifies it despite compression, added noise, or level changes. MPEG-7 (ISO/IEC 15938-4) standardizes one as the AudioSignature description scheme, built from spectral-flatness features, for scalable audio identification.','An audio signature is a small fingerprint of a sound. It captures the recording''s key features. It survives compression and noise. Systems match it to name the recording.','To enable fast, robust recognition of recordings against large reference databases.','A monitoring service stores MPEG-7 audio signatures for its catalog and matches broadcast audio against them.','Content Identification',ARRAY['Audio identification','Audio fingerprint','MPEG-7','Spectral flatness','Content recognition']::text[],ARRAY['Confusing a signature (extracted from audio) with a watermark (embedded in it).','Assuming it captures musical meaning, when it captures statistical features.','Expecting it to match a different performance of the same song.']::text[],ARRAY['Broadcast play-out monitoring.','Content-ID matching.','Archive de-duplication.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio signature');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ac167e30-7b56-4c62-9481-0ae4e69e04b2','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ac167e30-7b56-4c62-9481-0ae4e69e04b2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ac167e30-7b56-4c62-9481-0ae4e69e04b2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dc99a60c-815c-481e-883c-1cbfd6a498a0','Audio source node','In the MPEG-4 scene-description (BIFS) framework, the AudioSource node is the scene-graph node that connects a decoded elementary audio stream into an audio sub-graph, exposing that stream''s samples so downstream nodes can mix, switch, or process them.','This is a building block in an MPEG-4 media scene. It brings decoded sound into the scene. Other blocks can then mix or process that sound. MPEG-4 means Moving Picture Experts Group standard 4.','It exists to feed a decoded audio stream into a composited audio scene so that sound can be combined with other sounds and with visual objects.','A technician building an interactive MPEG-4 presentation wires an AudioSource node to a decoder output, then routes it through mixing nodes to a Sound node for playback.','Scene Nodes',ARRAY['Audio switch node','Audio spatialization node','Audio-specific configuration','Audio stream configuration']::text[],ARRAY['Confusing the MPEG-4 AudioSource scene node with a physical input jack on a mixer.','Assuming it performs decoding; it references an already-decoded elementary stream.','Expecting it to place sound in 3D space, which is the job of the Sound or DirectiveSound node.']::text[],ARRAY['Authoring an interactive MPEG-4 audio-visual scene.','Routing a decoded stream into an AudioMix or AudioSwitch node.','Studying MPEG-4 BIFS audio node graphs for certification.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio source node');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dc99a60c-815c-481e-883c-1cbfd6a498a0','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dc99a60c-815c-481e-883c-1cbfd6a498a0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dc99a60c-815c-481e-883c-1cbfd6a498a0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1c4f271b-afc7-44c9-a7b0-3e7c225742cf','Audio spatialization node','A scene-graph node that positions a sound in a listener''s 3D space; in MPEG-4 Advanced AudioBIFS this role is served by the Sound and DirectiveSound nodes, which carry a source''s location, orientation, directivity, and (with AcousticScene) environmental reverberation.','This block places a sound somewhere around the listener. It sets where the sound is and which way it points. It can also add room echo. In MPEG-4 the DirectiveSound block does this.','It exists to render immersive, positioned audio so that a sound object appears at a chosen point and direction in a virtual acoustic space.','A technician sets a DirectiveSound node''s location and direction so a voice appears to come from a character on screen, adding reverberation via the AcousticScene node.','Scene Nodes',ARRAY['Audio source node','Audio switch node','Audio stream configuration']::text[],ARRAY['Treating spatialization as simple left-right panning rather than 3D positioning with directivity.','Forgetting that room reverberation is set separately in the AcousticScene node.','Assuming every renderer produces identical results, since rendering detail is non-normative.']::text[],ARRAY['Placing a virtual sound source in an MPEG-4 3D audio scene.','Adding environmental reverberation to a game or VR audio object.','Comparing physical and perceptual spatialization approaches.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio spatialization node');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1c4f271b-afc7-44c9-a7b0-3e7c225742cf','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1c4f271b-afc7-44c9-a7b0-3e7c225742cf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1c4f271b-afc7-44c9-a7b0-3e7c225742cf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '190a9525-3716-4379-ac11-be3d159f0923','Audio spectrum basis','An MPEG-7 low-level audio descriptor (AudioSpectrumBasis) holding a set of basis functions, derived by singular value decomposition or independent component analysis of a normalized log-frequency spectrogram, used to project high-dimensional spectra into a compact low-dimensional feature space.','This is a small set of spectral patterns learned from sound. It captures the main shapes in a sound''s spectrum. Those patterns then shrink the data for search and sorting. MPEG-7 is a content-description standard.','It exists to reduce the size of spectral data while keeping the features that best separate different sounds, aiding classification and retrieval.','An engineer computes an AudioSpectrumBasis from a training set, then reuses those basis vectors to project new recordings into a compact feature set for a sound classifier.','Spectral Descriptors',ARRAY['Audio spectrum projection','Audio spectrum envelope','Audio-source classification','Audio-content indexing']::text[],ARRAY['Confusing the basis functions with the projected features (AudioSpectrumProjection) themselves.','Assuming a basis from one dataset is optimal for unrelated audio.','Ignoring the normalization and log-frequency steps that precede the decomposition.']::text[],ARRAY['Building a compact feature set for automatic sound recognition.','Reducing spectrogram dimensionality before machine learning.','Indexing a sound-effects library by spectral content.']::text[],'advanced','X = U S V^T ;  basis = leading columns of V','Decompose the normalized log-spectrogram matrix by singular value decomposition; the basis is the set of leading right-singular vectors that capture the most spectral variance.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio spectrum basis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '190a9525-3716-4379-ac11-be3d159f0923','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='190a9525-3716-4379-ac11-be3d159f0923') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='190a9525-3716-4379-ac11-be3d159f0923');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7fb8a00d-7048-4015-b419-776c309e3492','Audio spectrum centroid','An MPEG-7 low-level descriptor (AudioSpectrumCentroid) giving the power-weighted mean of a signal''s log-frequency power spectrum, expressed in octaves relative to 1 kHz, which indicates whether spectral energy sits toward low or high frequencies.','This value shows where a sound''s energy sits in pitch. A high number means the sound is bright. A low number means it is dark or bassy. It is measured in octaves from 1000 hertz.','It exists to summarize spectral brightness in a single number so sounds can be compared, sorted, and classified by timbre.','For two equal-power bins at 500 Hz and 2000 Hz, log2(500/1000) = -1 and log2(2000/1000) = +1, so the centroid is (-1+1)/2 = 0 octaves, i.e. 1 kHz.','Spectral Descriptors',ARRAY['Audio spectrum spread','Audio spectrum envelope','Audio spectrum flatness','Audio waveform descriptor']::text[],ARRAY['Reporting the centroid in hertz when MPEG-7 defines it in octaves relative to 1 kHz.','Forgetting that coefficients below 62.5 Hz are grouped into a single low-frequency term.','Confusing spectral centroid (brightness) with fundamental pitch.']::text[],ARRAY['Measuring perceived brightness of an instrument sample.','Feeding a timbre feature into a music-classification system.','Comparing bright versus dark synthesizer patches.']::text[],'intermediate','ASC = ( Σ_k log2(f_k / 1000) · P_k ) / ( Σ_k P_k )','The centroid is the sum over spectral coefficients of the log-frequency position times the power, divided by the total power.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio spectrum centroid');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7fb8a00d-7048-4015-b419-776c309e3492','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7fb8a00d-7048-4015-b419-776c309e3492') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7fb8a00d-7048-4015-b419-776c309e3492');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '66f0838b-0cf2-44de-a7d9-a774e32d77bd','Audio spectrum envelope','An MPEG-7 low-level descriptor (AudioSpectrumEnvelope) representing short-term signal power summed into logarithmically spaced (octave-fraction) frequency bands between a low and high edge, plus one coefficient below the low edge and one above the high edge.','This is a coarse picture of a sound''s spectrum over time. It adds up energy inside log-spaced frequency bands. Default bands run from 62.5 to 16000 hertz. It gives a compact spectral shape. MPEG-7 is a content-description standard.','It exists to give a compact, perceptually spaced spectral description that other MPEG-7 audio features and classifiers are built upon.','Using default 62.5 Hz to 16 kHz edges at 1/8-octave resolution, an engineer derives a band vector per frame to summarize how a recording''s energy is distributed across frequency.','Spectral Descriptors',ARRAY['Audio spectrum centroid','Audio spectrum spread','Audio spectrum basis','Audio spectrum flatness']::text[],ARRAY['Assuming linear frequency bands instead of logarithmic octave-fraction bands.','Forgetting the extra out-of-band coefficients below the low edge and above the high edge.','Confusing the envelope (a spectrum) with a time-domain amplitude envelope.']::text[],ARRAY['Building the base spectrum for MPEG-7 audio analysis.','Comparing broad spectral shapes of two recordings.','Preparing spectra before basis/projection dimensionality reduction.']::text[],'intermediate','f_edge(b) = loEdge · 2^(b · r)','Each band edge equals the low edge multiplied by two raised to the band index times the resolution in octaves.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio spectrum envelope');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '66f0838b-0cf2-44de-a7d9-a774e32d77bd','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='66f0838b-0cf2-44de-a7d9-a774e32d77bd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='66f0838b-0cf2-44de-a7d9-a774e32d77bd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '09c11881-3570-4f7c-acf4-a9c8d289fa96','Audio spectrum flatness','An MPEG-7 low-level descriptor (AudioSpectrumFlatness) giving, per frequency band, the ratio of the geometric mean to the arithmetic mean of the power-spectrum coefficients; values near 1 indicate noise-like (flat) spectra and values near 0 indicate tonal spectra.','This measures how flat a sound''s spectrum is. A value near one means the sound is noise-like. A value near zero means the sound is tonal, like a clear note. It is worked out band by band.','It exists to distinguish tonal from noise-like content in each band, which helps detect voicing, hiss, and instrument character.','For a band with power coefficients {4, 1}, geometric mean = sqrt(4·1) = 2 and arithmetic mean = (4+1)/2 = 2.5, so flatness = 2/2.5 = 0.8, a fairly noise-like band.','Spectral Descriptors',ARRAY['Audio spectrum centroid','Audio spectrum spread','Audio spectrum envelope','Audio waveform descriptor']::text[],ARRAY['Reading a high flatness value as loud rather than as noise-like.','Computing one flatness value for the whole spectrum instead of per band.','Using amplitude instead of power coefficients.']::text[],ARRAY['Separating tonal notes from noisy percussion or breath.','Detecting voiced versus unvoiced speech segments.','Flagging hiss or noise contamination in a recording.']::text[],'intermediate','ASF_b = ( Π_{k∈b} P_k )^(1/N_b) / ( (1/N_b) Σ_{k∈b} P_k )','Band flatness is the geometric mean of the band''s power coefficients divided by their arithmetic mean.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio spectrum flatness');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '09c11881-3570-4f7c-acf4-a9c8d289fa96','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='09c11881-3570-4f7c-acf4-a9c8d289fa96') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='09c11881-3570-4f7c-acf4-a9c8d289fa96');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd779dee7-f2ef-4237-8267-481371e2ea2e','Audio spectrum projection','An MPEG-7 low-level descriptor (AudioSpectrumProjection) holding the low-dimensional features obtained by projecting a normalized log-frequency spectrum onto the vectors of an AudioSpectrumBasis, typically alongside a spectral-energy (RMS) envelope term.','These are the compact numbers you get after applying the learned spectral patterns to a sound. They shrink the spectrum to a few features. Those features feed search and classification tools. MPEG-7 is a content-description standard.','It exists to give a compact, decorrelated feature set for sound comparison, indexing, and classification while discarding redundant spectral detail.','An engineer multiplies each frame''s normalized log spectrum by the basis matrix to get a short projection vector, then feeds those vectors to a sound-recognition model.','Spectral Descriptors',ARRAY['Audio spectrum basis','Audio spectrum envelope','Audio-source classification','Audio-content indexing']::text[],ARRAY['Swapping the roles of basis (the patterns) and projection (the resulting features).','Skipping the spectrum normalization step before projecting.','Assuming projections are comparable across incompatible basis sets.']::text[],ARRAY['Generating compact features for a sound classifier.','Indexing large audio archives for similarity search.','Reducing spectrogram size before statistical modeling.']::text[],'advanced','Y = X̃ · V_k','The projection features equal the normalized log spectrum multiplied by the leading basis vectors.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio spectrum projection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd779dee7-f2ef-4237-8267-481371e2ea2e','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d779dee7-f2ef-4237-8267-481371e2ea2e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d779dee7-f2ef-4237-8267-481371e2ea2e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '84148b52-fcb4-4814-aaaa-8f8ecd4e0dc7','Audio spectrum spread','An MPEG-7 low-level descriptor (AudioSpectrumSpread) giving the power-weighted root-mean-square deviation of the log-frequency power spectrum about the AudioSpectrumCentroid, measured in octaves, indicating how concentrated or broadband the spectral energy is.','This shows how spread out a sound''s energy is around its center. A small value means the energy is focused, like a pure tone. A large value means it is broadband, like noise. It is measured in octaves.','It exists to describe spectral width in one number, complementing the centroid to help separate tonal sounds from broadband ones.','For equal-power bins at 500 Hz and 2000 Hz with centroid 0, spread = sqrt(((-1)^2 + (1)^2)/2) = sqrt(1) = 1 octave.','Spectral Descriptors',ARRAY['Audio spectrum centroid','Audio spectrum flatness','Audio spectrum envelope','Audio waveform descriptor']::text[],ARRAY['Interpreting spread as loudness rather than as spectral width.','Computing spread without first computing the centroid it is measured about.','Reporting spread in hertz instead of octaves.']::text[],ARRAY['Distinguishing a pure tone from broadband noise.','Adding a width feature to a timbre classifier.','Characterizing how focused an instrument''s spectrum is.']::text[],'intermediate','ASS = sqrt( ( Σ_k (log2(f_k/1000) − ASC)^2 · P_k ) / ( Σ_k P_k ) )','The spread is the square root of the power-weighted mean squared distance of each coefficient''s log-frequency from the centroid.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio spectrum spread');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '84148b52-fcb4-4814-aaaa-8f8ecd4e0dc7','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='84148b52-fcb4-4814-aaaa-8f8ecd4e0dc7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='84148b52-fcb4-4814-aaaa-8f8ecd4e0dc7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a656139a-9ff1-43d5-9968-7b7fa169e8aa','Audio stream configuration','The set of parameters that a system negotiates before transporting an audio stream — such as sample rate, bit depth or coding format, and channel count — so that sender and receiver agree how to interpret the samples; examples include USB Audio Class AudioStreaming format descriptors and MPEG-4 stream setup data.','This is the setup that describes an audio stream. It states the sample rate, the format, and the channel count. Both ends must agree before sound flows. USB and MPEG-4 both carry such setup data.','It exists so that two devices interpret an audio bitstream identically, preventing wrong pitch, noise, or channel swaps at the receiver.','A technician selects a USB audio interface''s streaming format (for example 48 kHz, 24-bit, two channels) so the host and device exchange samples correctly.','Transport',ARRAY['Audio-specific configuration','Audio source node','Audio-network code-point registry','Audio subframe']::text[],ARRAY['Assuming both ends default to the same sample rate without negotiation.','Confusing stream configuration with the codec''s internal frame layout.','Overlooking channel-count or channel-order mismatches.']::text[],ARRAY['Setting a USB audio device''s streaming format.','Establishing an MPEG-4 audio elementary stream.','Troubleshooting pitch or channel errors from a format mismatch.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio stream configuration');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a656139a-9ff1-43d5-9968-7b7fa169e8aa','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a656139a-9ff1-43d5-9968-7b7fa169e8aa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a656139a-9ff1-43d5-9968-7b7fa169e8aa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '11c48b57-8458-4bbc-bba8-322c47b56a27','Audio stream synchronization tolerance','The permissible timing error between an audio stream and its reference (typically the picture), expressed as maximum allowed advance or delay; ITU-R BT.1359 gives detectability thresholds of about +45 ms (sound leading) to -125 ms (sound lagging), with wider acceptability limits.','This is how far sound can drift from picture before it looks wrong. Sound leading the picture is noticed sooner than sound lagging. Broadcast rules set limits in milliseconds. Staying inside them keeps lips and sound matched.','It exists to keep audio and video (or a common clock) aligned within limits that viewers will accept, protecting the perceived quality of a program.','A technician checks that a broadcast chain keeps audio within roughly +45 ms to -125 ms of video, adding audio delay to compensate for video-processing latency.','Synchronization',ARRAY['Audio sync stream','Audio synchronization word','Audio-sample time identification','Audio track timescale']::text[],ARRAY['Treating audio-lead and audio-lag limits as symmetric when they are not.','Ignoring cumulative delay added by video processors and codecs.','Assuming lip-sync error is fixed rather than drifting through a signal chain.']::text[],ARRAY['Aligning audio and video in a broadcast facility.','Setting lip-sync delay on a video processor or AV receiver.','Diagnosing a program where sound leads the picture.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio stream synchronization tolerance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '11c48b57-8458-4bbc-bba8-322c47b56a27','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='11c48b57-8458-4bbc-bba8-322c47b56a27') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='11c48b57-8458-4bbc-bba8-322c47b56a27');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e7667137-34ed-4a8c-baa4-5721c96be34a','Audio subframe','In the AES3/AES-EBU digital audio interface, a subframe is a 32-time-slot unit carrying one channel''s audio sample: a 4-bit preamble, up to 24 bits of audio (or 20 audio plus 4 auxiliary), and the validity, user, channel-status, and parity bits; two subframes form one frame.','A subframe is one slot of AES3 digital audio. It is 32 bits long and carries one channel''s sample. It also holds a few status and parity bits. Two subframes make a frame, one per channel.','It exists to package a single audio sample plus its housekeeping bits into a fixed structure so two channels can share one serial link reliably.','A technician reading an AES3 analyzer sees each subframe''s 20- or 24-bit audio field plus the validity, user, channel-status, and even-parity bits.','Digital Interface',ARRAY['Audio synchronization word','Audio superframe','Audio sync stream','Audio stream configuration']::text[],ARRAY['Confusing a subframe (one channel sample) with a frame (a stereo pair).','Forgetting that the preamble violates biphase-mark rules and carries no audio.','Assuming all 32 bits are audio when several are status and parity.']::text[],ARRAY['Analyzing an AES3 signal on a bitstream analyzer.','Debugging channel-status or parity errors on a digital link.','Learning the AES/EBU frame structure for certification.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio subframe');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e7667137-34ed-4a8c-baa4-5721c96be34a','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e7667137-34ed-4a8c-baa4-5721c96be34a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e7667137-34ed-4a8c-baa4-5721c96be34a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e97dc465-48d3-4bcf-920b-9bf4479f299b','Audio superframe','In DAB+ digital radio, an audio superframe is a 120 ms structure that carries a rate-dependent number of AAC access units (2, 3, 4, or 6 units depending on core sample rate), protected by a 16-bit Fire-code header and a shortened Reed-Solomon RS(120,110,t=5) code.','A super frame is a fixed bundle of DAB+ radio audio. It always covers 120 milliseconds of sound. It carries several coded audio units together. Error-correction codes protect the bundle from radio noise. DAB means Digital Audio Broadcasting.','It exists to package DAB+ audio into a fixed 120 ms transport unit with strong error protection so digital radio survives a noisy channel.','A broadcast engineer configuring a 48 kHz DAB+ service knows each super frame holds six AAC access units, guarded by the Fire code and Reed-Solomon parity.','Broadcast Transport',ARRAY['Audio subframe','Audio synchronization word','Audio stream configuration','Audio-specific configuration']::text[],ARRAY['Assuming a fixed count of access units regardless of sample rate.','Confusing the DAB+ super frame with the AES3 subframe of the wired interface.','Overlooking the Reed-Solomon and Fire-code error protection.']::text[],ARRAY['Configuring a DAB+ audio encoder.','Diagnosing dropouts on a digital-radio multiplex.','Studying DAB+ transport structure for certification.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio superframe');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e97dc465-48d3-4bcf-920b-9bf4479f299b','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e97dc465-48d3-4bcf-920b-9bf4479f299b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e97dc465-48d3-4bcf-920b-9bf4479f299b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dc65ebb6-8c7c-46b2-9322-614e35b19834','Audio switch node','In the MPEG-4 scene-description (BIFS) framework, the AudioSwitch node selects a subset of the audio channels supplied by its child audio node, passing chosen channels through and muting the rest, so a scene can route or gate audio.','This block chooses which sound channels pass through. It lets some channels play and blocks others. It works inside an MPEG-4 media scene. MPEG-4 means Moving Picture Experts Group standard 4.','It exists to route or gate audio channels within a scene graph, letting an author enable or disable sound sources programmatically.','A technician uses an AudioSwitch node to select a chosen language track from a multichannel source feeding the scene''s Sound node.','Scene Nodes',ARRAY['Audio source node','Audio spatialization node','Audio stream configuration']::text[],ARRAY['Confusing the AudioSwitch scene node with a hardware routing switcher.','Assuming it mixes channels; it selects and passes them.','Forgetting it operates on the channels of its child audio node.']::text[],ARRAY['Selecting a language track in an interactive MPEG-4 scene.','Gating audio sources on or off under user control.','Building an audio sub-graph with conditional routing.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio switch node');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dc65ebb6-8c7c-46b2-9322-614e35b19834','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dc65ebb6-8c7c-46b2-9322-614e35b19834') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dc65ebb6-8c7c-46b2-9322-614e35b19834');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c9b26c75-9e3e-43f0-911c-53052556a47f','Audio sync stream','A reference signal distributed to lock the sample clocks of digital audio equipment; in studio practice this is the AES11 Digital Audio Reference Signal (DARS), an AES3-format stream that carries timing for devices to genlock to, rather than program audio for listening.','This is a timing signal shared across a studio. Gear locks its digital clock to it. It keeps every device sampling in step. In pro audio it is the AES11 reference signal, not music to listen to.','It exists to give every digital device a common sample-clock reference so signals can be combined without clicks, glitches, or slips.','A technician feeds an AES11 DARS from a master clock to each device''s reference input so the whole studio stays sample-locked.','Synchronization',ARRAY['Audio synchronization word','Audio subframe','Audio stream synchronization tolerance','Audio-sample time identification']::text[],ARRAY['Using a reference (DARS) stream as a listening source.','Assuming devices lock automatically without a distributed reference.','Confusing sample-clock sync with lip-sync (audio-to-video) timing.']::text[],ARRAY['Distributing a house sync reference in a studio.','Genlocking digital converters to a master clock.','Eliminating clicks caused by unsynchronized devices.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio sync stream');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c9b26c75-9e3e-43f0-911c-53052556a47f','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c9b26c75-9e3e-43f0-911c-53052556a47f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c9b26c75-9e3e-43f0-911c-53052556a47f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dfd6f36e-1ece-4def-bbbf-00d28483e4d9','Audio synchronization word','A fixed bit pattern that marks the start of an audio frame or block so a decoder can find frame boundaries in a serial stream; examples include the AAC ADTS syncword (12 bits all set) and the AC-3 syncword 0x0B77.','This is a known pattern that flags the start of an audio frame. A decoder searches for it to line up the data. Different formats use different patterns. It lets the receiver find each frame.','It exists so a receiver can achieve and keep frame alignment in a continuous bitstream, even after joining mid-stream or losing sync.','A technician debugging a broadcast feed searches for the 0x0B77 AC-3 syncword to confirm where each coded audio frame begins.','Coding',ARRAY['Audio subframe','Audio superframe','Audio-specific configuration','Audio sync stream']::text[],ARRAY['Confusing a bitstream syncword with the AES3 preamble or a clock reference.','Assuming one universal syncword across all codecs.','Mistaking random data that resembles the pattern for a true frame start without verification.']::text[],ARRAY['Locating coded audio frames in a transport stream.','Recovering sync after a bit error or splice.','Parsing ADTS or AC-3 frames in a stream analyzer.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio synchronization word');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dfd6f36e-1ece-4def-bbbf-00d28483e4d9','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dfd6f36e-1ece-4def-bbbf-00d28483e4d9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dfd6f36e-1ece-4def-bbbf-00d28483e4d9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0c7a837c-574a-4c4a-bc78-8bf73c33f72d','Audio track timescale','In the ISO base media file format, the timescale is the number of time units per second used to express durations and sample times for a track''s media; an audio track''s media header (mdhd) timescale is commonly set to the audio sample rate.','The timescale sets how time is counted in a media file. It is the number of ticks per second. For audio it is often the sample rate. All sample times use these ticks. This is part of the MP4 file format.','It exists to give a track a consistent integer time base so sample durations and timestamps are exact and independent of the file''s overall clock.','With a timescale of 44100, a sample number 88200 corresponds to t = 88200 / 44100 = 2.0 seconds.','File Format',ARRAY['Audio-sample time identification','Audio-format box','Audio stream synchronization tolerance','Audio waveform descriptor']::text[],ARRAY['Confusing the track media timescale with the movie-level timescale.','Assuming the timescale always equals the sample rate.','Mixing units when converting between ticks and seconds.']::text[],ARRAY['Reading durations from an MP4 or MOV file.','Authoring correct sample timing in a container.','Debugging drift caused by a wrong timescale value.']::text[],'intermediate','t = n / timescale','Time in seconds equals the number of time units divided by the timescale.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio track timescale');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0c7a837c-574a-4c4a-bc78-8bf73c33f72d','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0c7a837c-574a-4c4a-bc78-8bf73c33f72d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0c7a837c-574a-4c4a-bc78-8bf73c33f72d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ab29e2e1-95f8-4588-a460-f0e8919d78ee','Audio waveform descriptor','An MPEG-7 low-level descriptor (AudioWaveform) that summarizes a signal''s time-domain shape by storing the minimum and maximum sample values within successive frames, giving a compact envelope for display and coarse comparison.','This is a compact summary of a sound''s shape over time. It stores the smallest and largest sample in each short frame. That gives a quick waveform outline. MPEG-7 is a content-description standard.','It exists to provide a lightweight waveform overview for quick display, browsing, or coarse similarity checks without keeping every sample.','An editor''s scrubbing view draws a waveform from per-frame min and max values rather than reading every sample, giving fast visual navigation.','Basic Descriptors',ARRAY['Audio spectrum envelope','Audio spectrum centroid','Audio-segment descriptor','Audio-content indexing']::text[],ARRAY['Confusing this time-domain descriptor with the AudioSpectrumEnvelope (frequency domain).','Expecting sample-accurate audio to be reconstructable from min/max pairs.','Ignoring the frame length, which sets the coarseness of the outline.']::text[],ARRAY['Drawing a fast waveform overview in an editor.','Providing a thumbnail for audio browsing.','Coarse comparison of two recordings'' shapes.']::text[],'beginner',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio waveform descriptor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ab29e2e1-95f8-4588-a460-f0e8919d78ee','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ab29e2e1-95f8-4588-a460-f0e8919d78ee') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ab29e2e1-95f8-4588-a460-f0e8919d78ee');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0d924bea-01cc-4b23-bb1d-a5c19d008aea','Audio-bound metadata','Descriptive or technical metadata carried within the audio file or stream itself, bound to the essence rather than stored in a separate sidecar; examples include the Broadcast Wave Format bext chunk and embedded core-audio metadata fields.','This is information stored inside the audio file. It travels with the sound, not in a separate file. It can hold the take, timecode, or notes. Broadcast Wave files carry such data in the bext chunk.','It exists so essential information stays attached to the audio through copying and interchange, reducing the risk of losing a separate metadata file.','A field recordist relies on the BWF bext chunk to keep scene, take, and timecode embedded in each WAV file for the editor downstream.','Metadata',ARRAY['Audio-content indexing','Audio-event description','Audio-segment descriptor','Audio-format migration']::text[],ARRAY['Assuming embedded metadata survives every format conversion unchanged.','Confusing embedded (bound) metadata with external sidecar files.','Overwriting or stripping embedded fields during batch processing.']::text[],ARRAY['Embedding timecode and take data in production WAV files.','Preserving descriptive fields through file interchange.','Auditing whether metadata survived a transcode.']::text[],'beginner',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-bound metadata');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0d924bea-01cc-4b23-bb1d-a5c19d008aea','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0d924bea-01cc-4b23-bb1d-a5c19d008aea') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0d924bea-01cc-4b23-bb1d-a5c19d008aea');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ee622c37-6f31-401d-850e-5657649d72b2','Audio-content indexing','The process of analyzing audio to extract descriptors (such as spectral and timbral features) and organizing them into an index that supports content-based search, classification, and retrieval, as framed by the MPEG-7 audio description tools.','This means describing what a sound contains, not just its file name. Software measures features of the audio. Those features build a searchable index. You can then find sounds by how they actually sound. MPEG-7 supports this.','It exists to let large audio collections be searched by content, so users can find sounds by similarity rather than only by filename or tags.','A sound-library engineer extracts MPEG-7 spectral features from every clip so users can query the archive by acoustic similarity.','Metadata',ARRAY['Audio spectrum projection','Audio spectrum basis','Audio-source classification','Audio-segment descriptor']::text[],ARRAY['Confusing content-based indexing with plain text-tag search.','Assuming one feature set suits every retrieval task.','Ignoring segmentation, so whole files are indexed instead of meaningful parts.']::text[],ARRAY['Building a searchable sound-effects database.','Query-by-example retrieval in a music archive.','Auto-tagging a large recording collection.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-content indexing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ee622c37-6f31-401d-850e-5657649d72b2','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ee622c37-6f31-401d-850e-5657649d72b2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ee622c37-6f31-401d-850e-5657649d72b2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dbf5c0d0-f05a-4807-a32e-5bd781beaa56','Audio-event description','Metadata that identifies and characterizes a discrete acoustic event within a recording — its label, time position, and attributes — using MPEG-7 description tools such as the Segment and Event description schemes to attach meaning to portions of audio.','This describes a single thing that happens in a recording. It says what the event is and when it occurs. Examples are a door slam or a spoken word. MPEG-7 provides tools to mark such events.','It exists to attach labeled, time-located meaning to audio so systems can detect, search, and reason about specific sounds within longer recordings.','An analyst marks each gunshot in a surveillance recording with a label and time span so the events can be searched and reviewed later.','Metadata',ARRAY['Audio-segment descriptor','Audio-segment decomposition','Audio-content indexing','Audio-source classification']::text[],ARRAY['Confusing an event (a discrete occurrence) with a whole segment or track.','Omitting precise timing, which makes events hard to locate.','Assuming event labels are standardized across all systems.']::text[],ARRAY['Tagging sound events in surveillance or monitoring audio.','Annotating a soundtrack for searchable events.','Building training data for sound-event detection.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-event description');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dbf5c0d0-f05a-4807-a32e-5bd781beaa56','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dbf5c0d0-f05a-4807-a32e-5bd781beaa56') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dbf5c0d0-f05a-4807-a32e-5bd781beaa56');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9087f22a-eb28-46fd-b2e4-f1adbed17415','Audio-format box','A structural element that declares an audio stream''s coding format inside a container file; in the ISO base media file format this role is filled by the audio sample entry within the Sample Description Box (stsd), which names the codec and basic audio parameters.','This is a part of a media file that names the audio format. It says which codec was used and the basic settings. In MP4 files it lives in the sample description box. A player reads it to pick the right decoder.','It exists so a player can identify the audio coding and parameters and select the correct decoder before playback.','A technician inspecting an MP4 reads the audio sample entry (for example an mp4a entry) to confirm the codec, channel count, and sample rate.','File Format',ARRAY['Audio track timescale','Audio-sample time identification','Audio-specific configuration','Audio stream configuration']::text[],ARRAY['Confusing the format-declaring box with the actual coded audio data.','Assuming the sample-entry parameters override the codec''s own configuration.','Overlooking that container boxes are nested (sample entry sits inside stsd).']::text[],ARRAY['Inspecting codec parameters inside an MP4 file.','Diagnosing a player that cannot decode a track.','Remuxing audio into a new container correctly.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-format box');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9087f22a-eb28-46fd-b2e4-f1adbed17415','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9087f22a-eb28-46fd-b2e4-f1adbed17415') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9087f22a-eb28-46fd-b2e4-f1adbed17415');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e5d17cdb-da02-4a7f-86b2-2d7dbaa03c6b','Audio-format migration','The preservation process of transferring audio content from an obsolete or at-risk format or carrier to a current, sustainable one while safeguarding the essence and its metadata, as set out in IASA digital-preservation guidelines.','This means moving audio to a newer, safer format. It is used when old formats or media are at risk. The goal is to keep the sound and its data intact. Archive guidelines from IASA describe how to do it.','It exists to keep recordings accessible over time as formats, codecs, and storage media become obsolete, protecting long-term access.','An archivist migrates legacy compressed files to a documented, loss-free target format, verifying checksums and carrying metadata across to prevent loss.','Preservation',ARRAY['Audio-bound metadata','Audio-format box','Audio-content indexing','Audio-specific configuration']::text[],ARRAY['Re-encoding lossy to lossy, adding generation loss.','Migrating essence but dropping the associated metadata.','Skipping fixity checks (checksums) to confirm a faithful transfer.']::text[],ARRAY['Moving an archive off an obsolete codec.','Preserving field recordings for long-term access.','Planning a format-obsolescence response in an archive.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-format migration');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e5d17cdb-da02-4a7f-86b2-2d7dbaa03c6b','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e5d17cdb-da02-4a7f-86b2-2d7dbaa03c6b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e5d17cdb-da02-4a7f-86b2-2d7dbaa03c6b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1a133f45-7ddc-4da8-91cc-258dc8f03eab','Audio-network code-point registry','A maintained, published list that assigns unique numeric identifiers (''code points'') used by networked-audio protocols so independent devices agree on their meaning; examples referenced by audio-over-IP standards include IANA registries and Differentiated Services Code Points (DSCP) used to mark and prioritize audio traffic.','This is an official list of numbers used in audio networks. Each number has one agreed meaning. Devices from different makers read the list the same way. Audio-over-network standards use such registries for formats and priority marking.','It exists to keep numeric identifiers unique and unambiguous across vendors, so networked audio devices interoperate and traffic is handled consistently.','An engineer setting up an AES67 system marks media packets with the recommended DSCP code points from the registry so switches give audio the right priority.','Networking',ARRAY['Audio stream configuration','Audio sync stream','Audio synchronization word','Audio-specific configuration']::text[],ARRAY['Inventing local code-point values instead of using registered ones.','Confusing QoS code points (DSCP) with format identifiers.','Assuming every switch honors the marked priority without configuration.']::text[],ARRAY['Configuring QoS marking on an audio-over-IP network.','Ensuring interoperability between different-vendor audio devices.','Assigning consistent identifiers across a networked audio system.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-network code-point registry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1a133f45-7ddc-4da8-91cc-258dc8f03eab','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1a133f45-7ddc-4da8-91cc-258dc8f03eab') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1a133f45-7ddc-4da8-91cc-258dc8f03eab');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9d98eb34-11b1-4847-b16e-f09b3bdd9460','Audio-sample time identification','The mechanism that assigns each audio sample or coded unit a defined decode and presentation time within a container''s timeline, using the time-to-sample tables (and any composition offsets) of the ISO base media file format expressed in the track''s timescale.','This gives every audio sample a known time. It says when each sample should be decoded and played. The file stores tables that map samples to times. Times are counted in the track''s ticks per second.','It exists so a player knows exactly when to render each sample, enabling accurate playback, seeking, and synchronization with other tracks.','A technician seeking to a timestamp uses the time-to-sample table and the track timescale to find which audio sample to start decoding from.','File Format',ARRAY['Audio track timescale','Audio-format box','Audio stream synchronization tolerance','Audio sync stream']::text[],ARRAY['Confusing decode time with presentation (composition) time.','Ignoring the timescale when converting sample counts to seconds.','Assuming constant sample durations when edit lists or gaps exist.']::text[],ARRAY['Seeking accurately within an MP4 audio track.','Synchronizing audio with video in a container.','Debugging timing drift from mis-mapped sample times.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-sample time identification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9d98eb34-11b1-4847-b16e-f09b3bdd9460','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9d98eb34-11b1-4847-b16e-f09b3bdd9460') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9d98eb34-11b1-4847-b16e-f09b3bdd9460');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c298db97-8d4c-4743-a652-68e70959643a','Audio-segment decomposition','An MPEG-7 description-scheme construct that recursively divides an audio segment into constituent sub-segments (typically a temporal decomposition), building a hierarchy that structures a recording into parts for annotation and analysis.','This breaks a recording into smaller parts. Each part can be split again into finer parts. The result is a tree of segments. Each segment can then be described on its own. MPEG-7 defines this structure.','It exists to impose structure on continuous audio, so descriptions and labels can be attached to meaningful parts at several levels of detail.','An analyst decomposes a song into intro, verse, and chorus segments, then describes each part separately for search and navigation.','Metadata',ARRAY['Audio-segment descriptor','Audio-event description','Audio-content indexing','Audio waveform descriptor']::text[],ARRAY['Confusing decomposition (the structuring) with the descriptors attached to segments.','Assuming sub-segments must be gap-free or non-overlapping in all cases.','Treating decomposition as a single flat split rather than a recursive hierarchy.']::text[],ARRAY['Structuring a song into labeled sections.','Building a hierarchical index of a long recording.','Preparing segment-level annotations for retrieval.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-segment decomposition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c298db97-8d4c-4743-a652-68e70959643a','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c298db97-8d4c-4743-a652-68e70959643a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c298db97-8d4c-4743-a652-68e70959643a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f14e25e1-34da-4944-a208-64c8dc530e9f','Audio-segment descriptor','In MPEG-7, an AudioSegment describes a portion of an audio signal — a contiguous or non-contiguous group of samples — to which descriptors, creation information, and time references can be attached; it specializes the general Segment description scheme for audio.','This describes a chosen part of a recording. It marks the samples that belong to the part. Features and notes can be attached to it. MPEG-7 uses it to label sections of audio.','It exists to give a named handle for a piece of audio, so descriptors and metadata can be bound to exactly that portion.','An editor marks a 10-second AudioSegment covering a solo and attaches spectral descriptors and a text note describing it.','Metadata',ARRAY['Audio-segment decomposition','Audio-event description','Audio-content indexing','Audio waveform descriptor']::text[],ARRAY['Assuming a segment must be contiguous in time; it can group non-adjacent samples.','Confusing the segment (the region) with the descriptors placed on it.','Overlooking that segments can be organized hierarchically via decomposition.']::text[],ARRAY['Labeling a solo or section within a track.','Attaching features to a defined region of audio.','Building the nodes of a segment hierarchy.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-segment descriptor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f14e25e1-34da-4944-a208-64c8dc530e9f','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f14e25e1-34da-4944-a208-64c8dc530e9f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f14e25e1-34da-4944-a208-64c8dc530e9f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'abf39175-b097-421d-9c8d-1d7390fa374c','Audio-source classification','The task of automatically assigning a recording or segment to a source category (for example speech, music, or a specific instrument) using extracted audio descriptors and statistical or machine-learning models, as supported by MPEG-7 spectral-basis and projection features.','This means letting software decide what made a sound. It sorts audio into groups like speech, music, or noise. It uses measured features and trained models. MPEG-7 features are often used as the input.','It exists to label audio by its source type automatically, enabling routing, search, and organization of large collections without manual tagging.','An engineer trains a classifier on MPEG-7 projection features so a broadcast logger can separate speech segments from music automatically.','Metadata',ARRAY['Audio spectrum basis','Audio spectrum projection','Audio-content indexing','Audio-event description']::text[],ARRAY['Expecting perfect accuracy on sounds unlike the training data.','Confusing source classification with fundamental-pitch detection.','Using features from an incompatible extraction pipeline.']::text[],ARRAY['Separating speech from music in broadcast logging.','Auto-tagging instruments in a sample library.','Filtering a database by source type.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-source classification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'abf39175-b097-421d-9c8d-1d7390fa374c','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='abf39175-b097-421d-9c8d-1d7390fa374c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='abf39175-b097-421d-9c8d-1d7390fa374c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '69a98885-d137-4016-95c3-97cbff22f14c','Audio-specific configuration','In MPEG-4 Audio (ISO/IEC 14496-3), the AudioSpecificConfig is the setup structure that tells a decoder how to interpret a coded stream; its core fields are the audioObjectType, the samplingFrequencyIndex (or explicit rate), and the channelConfiguration.','This is the setup header for MPEG-4 audio. It tells the decoder the coding type, the sample rate, and the channel layout. The decoder needs it before it can play the stream. It is defined in MPEG-4 Part 3.','It exists so a decoder can configure itself correctly for a coded audio stream before decoding begins, ensuring right rate, channels, and tool set.','A streaming engineer confirms the AudioSpecificConfig advertises audioObjectType 2 (AAC-LC), a 48 kHz sampling index, and stereo channel configuration.','Coding',ARRAY['Audio stream configuration','Audio synchronization word','Audio-format box','Audio superframe']::text[],ARRAY['Confusing the samplingFrequencyIndex with the raw sample rate value.','Assuming defaults when the configuration is missing or wrong.','Mismatching the channelConfiguration to the actual channel count.']::text[],ARRAY['Setting up an AAC stream for playback.','Debugging a decoder that plays at the wrong rate.','Signaling MPEG-4 audio parameters in a transport session.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-specific configuration');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '69a98885-d137-4016-95c3-97cbff22f14c','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='69a98885-d137-4016-95c3-97cbff22f14c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='69a98885-d137-4016-95c3-97cbff22f14c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '096646e9-fbb9-4c52-bf1d-a847c09fb91a','Audio-to-Lyrics Alignment','The music-information-retrieval task of time-aligning a song''s text lyrics to its audio, producing start and end times for words or lines; it is a standard evaluated task in the MIREX Automatic Lyrics-to-Audio Alignment challenge.','This lines up written lyrics with the singing in a song. It gives each word or line a start and end time. It powers synced lyrics and karaoke. It is a well-known music-search research task.','It exists to synchronize text lyrics with sung audio so applications can display timed lyrics, enable search, and support karaoke.','A developer runs an alignment model to timestamp each lyric line, then displays word-synced lyrics that follow the vocal in real time.','Alignment',ARRAY['Audio-to-Score Alignment','Audio-content indexing','Audio-event description','Audio-segment descriptor']::text[],ARRAY['Assuming clean vocals; dense mixes reduce alignment accuracy.','Confusing lyric alignment (to text) with score alignment (to notation).','Ignoring language and pronunciation effects on the aligner.']::text[],ARRAY['Generating synced lyrics for a streaming player.','Building a karaoke display with word timing.','Evaluating aligners in a MIREX-style task.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-to-Lyrics Alignment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '096646e9-fbb9-4c52-bf1d-a847c09fb91a','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='096646e9-fbb9-4c52-bf1d-a847c09fb91a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='096646e9-fbb9-4c52-bf1d-a847c09fb91a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '28c3a2bc-0abb-48e4-bd01-6ea79bea6644','Audio-to-Score Alignment','The music-information-retrieval task of matching a performance''s audio to positions in a symbolic musical score; when done in real time it is called score following, and it is a standard evaluated task in the MIREX Real-time Audio to Score Alignment challenge.','This matches a performance to its written music. It finds where in the score the player currently is. Done live, it is called score following. It powers automatic page turning and accompaniment.','It exists to link a performance to its notation in time, enabling automatic accompaniment, page turning, and performance analysis.','A score-following system tracks a soloist against the score in real time and cues a synchronized backing accompaniment.','Alignment',ARRAY['Audio-to-Lyrics Alignment','Audio-content indexing','Audio-segment descriptor','Audio-event description']::text[],ARRAY['Confusing offline alignment with real-time score following.','Assuming robustness to large tempo changes or improvisation.','Overlooking that errors or repeats in the performance can break tracking.']::text[],ARRAY['Driving automatic accompaniment for a soloist.','Automatic page turning during performance.','Aligning a recording to notation for analysis.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-to-Score Alignment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '28c3a2bc-0abb-48e4-bd01-6ea79bea6644','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='28c3a2bc-0abb-48e4-bd01-6ea79bea6644') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='28c3a2bc-0abb-48e4-bd01-6ea79bea6644');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6460a26b-ca76-4f63-8a18-f0b424fd76c6','Audio-visual synchronization metadata','Data carried alongside a broadcast or streamed program that records or signals the intended relative timing between the audio and the picture, so a receiver or facility can measure and correct lip-sync error. EBU R37 recommends end-to-end sync within about +40 ms (audio early) to -60 ms (audio late), while ITU-R BT.1359-1 puts the detectability threshold at about +45 ms audio lead to -125 ms audio lag.','This is timing data sent with a video program. It tells the system how sound should line up with the picture. It helps fix lip-sync errors so voices match lips. Small offsets are allowed, but big ones look wrong.','It exists so audio and video that pass through separate processing paths can be re-aligned, keeping sound matched to the on-screen action.','A technician uses timing references or embedded offset data to align a feed within the EBU R37 window of about +40 ms early to -60 ms late, well inside the ITU-R BT.1359-1 detectability limits of about +45 ms lead to -125 ms lag.','Sync metadata',ARRAY['Coded audio access unit','Baseband audio','Bitstream payload','Clean audio']::text[],ARRAY['Assuming audio-late and audio-early are equally acceptable; ears tolerate audio arriving late more than early.','Thinking one correction fixes the whole chain, when each device can add its own delay.','Confusing frame-accurate timecode with lip-sync offset metadata.']::text[],ARRAY['Aligning a live sports feed where the video encoder adds delay the audio path does not.','Checking a broadcast meets the ITU-R relative-timing limit before air.','Diagnosing a set-top box that adds audio delay after HDMI processing.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-visual synchronization metadata');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6460a26b-ca76-4f63-8a18-f0b424fd76c6','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6460a26b-ca76-4f63-8a18-f0b424fd76c6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6460a26b-ca76-4f63-8a18-f0b424fd76c6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e6a5337b-9934-44c6-b3a3-e16058cbcc70','AudioBIFS','AudioBIFS is the set of audio scene-description nodes within MPEG-4 BIFS (Binary Format for Scenes), letting a compressed scene mix, delay, filter and spatially place decoded audio sources in a described listening scene. It is specified as part of the MPEG-4 Systems scene-description tools.','AudioBIFS is part of the MPEG-4 media standard. BIFS stands for Binary Format for Scenes. It describes how to mix and place sounds in a scene. It can add delay, filters, and 3D positions to decoded audio.','It lets content authors describe interactive, spatial audio scenes inside a coded bitstream, so playback devices build the final mix rather than shipping a fixed pre-mixed track.','A technician meets AudioBIFS when authoring or debugging MPEG-4 interactive content, wiring audio-source nodes into a scene graph that a compliant player renders.','Scene coding',ARRAY['Base layer','Bitstream payload','Bandwidth-extension coding','Coded audio access unit']::text[],ARRAY['Treating AudioBIFS as an audio codec; it is a scene-description layer above the audio decoders.','Assuming every MPEG-4 player supports the full node set, when profiles limit what is required.','Confusing BIFS scene nodes with the transport that carries them.']::text[],ARRAY['Authoring an interactive MPEG-4 scene where audio position follows an object.','Debugging why a player ignores an audio-effect node in a scene graph.','Explaining how MPEG-4 separates coded audio from scene composition.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='AudioBIFS');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e6a5337b-9934-44c6-b3a3-e16058cbcc70','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e6a5337b-9934-44c6-b3a3-e16058cbcc70') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e6a5337b-9934-44c6-b3a3-e16058cbcc70');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e5cca50c-b0a1-4a0a-ab07-1e8401958a6f','Band-limiting filter','A low-pass (or band-pass) filter that restricts a signal''s spectrum to a defined frequency range, most commonly the anti-alias filter placed before sampling or the reconstruction filter after conversion. Its stopband must sufficiently attenuate energy above the Nyquist frequency, half the sampling rate.','This filter removes frequencies that are too high for the system. Before sampling, it stops content above half the sample rate. That prevents false low tones called aliases. A similar filter smooths the output after conversion.','It exists to keep a signal inside the band a sampler or channel can carry, preventing aliasing on the way in and imaging on the way out.','At a 48 kHz sample rate the Nyquist frequency is 24 kHz, so the anti-alias filter must strongly attenuate energy above 24 kHz before the converter.','Filtering',ARRAY['Baseband audio','Broadband noise','Cascade filter bank','Block companded PCM']::text[],ARRAY['Believing a gentle filter is enough; too little stopband attenuation lets aliases fold into the audio band.','Confusing the anti-alias filter (before sampling) with the reconstruction filter (after conversion).','Assuming oversampling removes the need for any analog band-limiting filter.']::text[],ARRAY['Choosing converter settings so out-of-band energy is removed before sampling.','Explaining why a badly filtered ultrasonic tone appears as a false in-band frequency.','Comparing steep and gentle reconstruction filters for their phase behavior.']::text[],'intermediate','f_c <= f_s / 2','The filter cutoff should sit at or below the Nyquist frequency, which is half the sampling rate.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Band-limiting filter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e5cca50c-b0a1-4a0a-ab07-1e8401958a6f','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e5cca50c-b0a1-4a0a-ab07-1e8401958a6f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e5cca50c-b0a1-4a0a-ab07-1e8401958a6f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b75fed42-0e26-4175-be98-d01a37d5908c','Bandwidth-extension coding','A class of audio-coding tools that transmit the lower spectrum in full while reconstructing the higher spectrum from a compact parametric description, saving bit rate. Spectral Band Replication (SBR), used in HE-AAC, is the best-known example, regenerating high frequencies from the transposed low band plus envelope and noise parameters.','This method saves data by coding only the lower frequencies fully. The higher frequencies are rebuilt from a small set of instructions. Those instructions copy and shape the low band upward. Spectral Band Replication in HE-AAC works this way.','It exists to keep perceived audio bandwidth at low bit rates, where coding the full spectrum directly would sound dull or cost too many bits.','A technician meets it as the SBR layer of HE-AAC streams, where a 48 kHz signal is coded with a core running at half rate plus high-band parameters.','Perceptual coding',ARRAY['Base layer','Bitstream payload','AudioBIFS','Block switching']::text[],ARRAY['Assuming the rebuilt high band is a true copy of the original; it is a parametric estimate.','Thinking bandwidth extension always improves quality, when artefacts can appear on transient or noisy content.','Confusing the low-rate core with the full-rate output it helps reconstruct.']::text[],ARRAY['Streaming voice or music at low bit rates using HE-AAC.','Explaining why a low-rate stream still sounds bright despite few high-band bits.','Diagnosing metallic artefacts on cymbals from aggressive high-band regeneration.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bandwidth-extension coding');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b75fed42-0e26-4175-be98-d01a37d5908c','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b75fed42-0e26-4175-be98-d01a37d5908c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b75fed42-0e26-4175-be98-d01a37d5908c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a4472de5-6328-40a7-a601-413e091cb5af','Base layer','In scalable (layered) coding, the base layer is the self-decodable core stream that delivers a usable, lower-quality version of the audio on its own, with one or more enhancement layers added on top to raise quality or bit rate. It is the mandatory foundation of a scalable bitstream.','A base layer is the core part of a layered stream. It can be decoded by itself for basic quality. Extra layers stack on top to add quality. If those extra layers are lost, the base still plays.','It exists so one encoded stream can serve many conditions: weak links or simple decoders use the base alone, while capable ones add enhancement layers.','A technician relies on it when a network drops enhancement layers under congestion, and the receiver still plays the base layer without dropouts.','Scalable coding',ARRAY['Bandwidth-extension coding','Bitstream payload','Coded audio access unit','AudioBIFS']::text[],ARRAY['Thinking the base layer already carries full quality; it is deliberately the lowest useful tier.','Assuming enhancement layers decode without the base; they depend on it.','Confusing layered scalability with simple bitrate switching between separate files.']::text[],ARRAY['Delivering audio that degrades gracefully on a congested network.','Explaining why a simple decoder ignores enhancement data it cannot use.','Designing a stream that serves both low- and high-capability receivers.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Base layer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a4472de5-6328-40a7-a601-413e091cb5af','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a4472de5-6328-40a7-a601-413e091cb5af') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a4472de5-6328-40a7-a601-413e091cb5af');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3868cbf6-7998-484b-b4b8-25db413735b2','Baseband audio','The audio signal in its original, unmodulated frequency range, occupying roughly its natural spectrum near DC rather than being shifted onto a carrier. It is the form present before modulation for transmission and after demodulation at the receiver.','Baseband audio is the plain audio signal itself. It sits at its natural frequencies, near zero. It is not yet placed on a radio carrier. Radios and links carry it as baseband before and after transmission.','The term distinguishes the raw audio from any modulated or carrier-based form, clarifying where in a signal chain the audio lives.','A technician taps baseband audio at a demodulator output or console bus, before it is modulated onto an RF or optical carrier.','Signal domain',ARRAY['Band-limiting filter','Bitstream payload','Bulk delay','Broadband noise']::text[],ARRAY['Confusing baseband with line level; baseband describes frequency placement, not amplitude.','Assuming baseband must be analog, when it can also be a digital baseband stream.','Thinking baseband and passband are the same signal state.']::text[],ARRAY['Probing the baseband output of an FM demodulator.','Explaining where audio sits before modulation onto a transmitter.','Distinguishing baseband monitoring from an RF measurement.']::text[],'beginner',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Baseband audio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3868cbf6-7998-484b-b4b8-25db413735b2','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3868cbf6-7998-484b-b4b8-25db413735b2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3868cbf6-7998-484b-b4b8-25db413735b2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'abc7af52-b65f-4e8d-bf39-b7dadaa4eed4','Beam pattern','The directional response of a transducer array or microphone/loudspeaker, expressed as relative output versus angle, usually normalized to the on-axis maximum. For a uniform line array it follows the array factor set by element count, spacing and steering.','A beam pattern shows how sensitive an array is by direction. It plots output against angle around the array. A tight beam favors one direction strongly. Element count and spacing set the beam''s shape.','It describes and predicts how an array focuses or rejects sound by direction, guiding coverage, feedback control and interference rejection.','For a uniform line array, a technician predicts the main-lobe width and null angles from the array factor to aim coverage and reject off-axis noise.','Array directivity',ARRAY['Blocking matrix','Broadband noise','Cascade filter bank','Boundary element method']::text[],ARRAY['Treating the beam pattern as frequency-independent, when it narrows as frequency rises.','Ignoring grating lobes that appear when element spacing exceeds half a wavelength.','Reading relative directivity as absolute sensitivity.']::text[],ARRAY['Aiming a line-array loudspeaker to cover seats while avoiding a rear wall.','Designing a microphone array to reject off-axis noise.','Explaining why an array beams tightly at high frequency but broadly at low frequency.']::text[],'advanced','|AF(theta)| = | sin(N*psi/2) / (N*sin(psi/2)) |,  psi = k*d*sin(theta)','The normalized array factor magnitude equals the sine of N times half the inter-element phase, divided by N times the sine of half that phase.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Beam pattern');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'abc7af52-b65f-4e8d-bf39-b7dadaa4eed4','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='abc7af52-b65f-4e8d-bf39-b7dadaa4eed4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='abc7af52-b65f-4e8d-bf39-b7dadaa4eed4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '74a644e6-f591-467b-bf5c-845fca567743','Bel','The bel is the base unit of a logarithmic ratio quantity (a level), equal to the base-10 logarithm of a power ratio. It is rarely used directly; the decibel, one tenth of a bel, is the practical unit, so a level in decibels is ten times the base-10 log of the power ratio.','A bel measures a ratio using a base-10 logarithm. It compares one power to a reference power. One bel means the powers differ by a factor of ten. The decibel is one tenth of a bel and is used in practice.','It gives a compact logarithmic scale for the very wide power and level ranges met in acoustics and electronics, matching how the ear perceives loudness.','A power ratio of 100 is 2 bels, which equals 20 decibels, since a level in decibels is ten times the base-10 logarithm of the ratio.','Units and levels',ARRAY['Broadband noise','Baseband audio','Coherence function','Comfort noise']::text[],ARRAY['Using bels directly in practice; engineers almost always use decibels.','Using the power form (10*log) for a voltage or pressure ratio: power quantities use 10*log, but field quantities like voltage and pressure use the 20*log form.','Forgetting a level always needs a stated reference.']::text[],ARRAY['Explaining why levels use decibels rather than bels.','Converting a power ratio to a level in a report.','Teaching the logarithmic basis of sound and signal levels.']::text[],'beginner','L (bel) = log10(P / P0);  L (dB) = 10*log10(P / P0)','The level in bels is the base-10 logarithm of the power divided by the reference power; multiply by ten for decibels.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bel');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '74a644e6-f591-467b-bf5c-845fca567743','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='74a644e6-f591-467b-bf5c-845fca567743') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='74a644e6-f591-467b-bf5c-845fca567743');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c904a3b6-f899-4d9e-bf4c-07c6494d285f','Bidirectional predictive frame','In MPEG-style video coding, a bidirectionally predicted (B) frame is coded using motion-compensated prediction from both earlier and later reference frames, giving high compression but requiring out-of-order decoding. Audio technicians meet B-frames because they create a picture-decode reordering delay that audio-video sync must account for.','A B-frame is a heavily compressed video frame. It is predicted from frames both before and after it. This saves data but needs frames decoded out of order. That reordering adds video delay that audio timing must match.','B-frames raise video compression efficiency, but the resulting decode reordering is a source of the video delay that audio-video synchronization has to compensate.','When a long group-of-pictures uses many B-frames, a technician adds matching audio delay so lip-sync stays within tolerance despite picture-reorder latency.','Video coding',ARRAY['Audio-visual synchronization metadata','Coded audio access unit','Base layer','Bulk delay']::text[],ARRAY['Assuming decode order equals display order; B-frames break that assumption.','Ignoring that heavy B-frame use lengthens video delay and can pull sound early.','Confusing a B-frame with an independently decodable I-frame.']::text[],ARRAY['Setting audio delay to match encoder latency on a feed with many B-frames.','Explaining why picture and sound drift after a change in encoder GOP structure.','Diagnosing lip-sync error introduced by video re-encoding.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bidirectional predictive frame');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c904a3b6-f899-4d9e-bf4c-07c6494d285f','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c904a3b6-f899-4d9e-bf4c-07c6494d285f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c904a3b6-f899-4d9e-bf4c-07c6494d285f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e92776e2-7ba8-4740-b6c6-bf57460f4b99','Bistream element','A syntactic element of a coded audio bitstream: a defined, self-identifying block of data such as a single-channel element, channel-pair element, low-frequency element, data element or fill element in AAC. Decoders parse a sequence of these elements to reconstruct the audio. (Spelling ''Bistream'' retained as supplied; the standard term is ''bitstream element''.)','A bitstream element is one labeled piece of a coded audio stream. Each element type carries a defined kind of data. Examples in AAC include mono, stereo, and fill elements. The decoder reads elements in order to rebuild the sound.','Elements give the bitstream a modular, self-describing structure, so a decoder knows what each block is and how many channels or what data it carries.','A technician inspecting an AAC stream sees a sequence of elements such as single-channel and channel-pair elements ending in a terminator, revealing the channel layout.','Bitstream syntax',ARRAY['Bitstream payload','Channel element','Channel pair element','Coded audio access unit']::text[],ARRAY['Confusing an element (a syntax block) with a full frame or access unit.','Assuming element order is fixed, when it depends on the program configuration.','Overlooking fill and data elements as if only audio elements exist.']::text[],ARRAY['Reading an AAC stream to confirm its channel configuration.','Explaining how a decoder identifies mono versus stereo blocks.','Debugging a stream that carries an unexpected data element.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bistream element');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e92776e2-7ba8-4740-b6c6-bf57460f4b99','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e92776e2-7ba8-4740-b6c6-bf57460f4b99') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e92776e2-7ba8-4740-b6c6-bf57460f4b99');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '335d1dd1-cc27-4e3b-b04b-2a51a6070620','Bitstream payload','The portion of a coded stream that carries the actual encoded audio data, as opposed to headers, synchronization words and control or configuration fields. In a coded frame the payload holds the quantized, entropy-coded audio; wrapping fields describe how to interpret it.','The payload is the real coded audio data in a stream. It is separate from headers and sync words. Headers tell the decoder how to read the payload. The payload holds the compressed sound itself.','Separating payload from header and control fields lets a decoder first read how the data is formatted, then correctly decode the audio content that follows.','When a frame''s sync word or header is corrupted, a technician sees the decoder unable to interpret an otherwise intact payload and drop or conceal that frame.','Bitstream syntax',ARRAY['Bistream element','Coded audio access unit','Base layer','Channel element']::text[],ARRAY['Treating the whole frame as payload, ignoring header and sync overhead.','Assuming payload size is fixed, when many codecs use variable-length frames.','Confusing transport-packet payload with the coded-audio payload inside it.']::text[],ARRAY['Explaining why a corrupted header ruins a frame whose payload bits are intact.','Estimating overhead by separating payload bits from header bits.','Tracing coded audio through a transport packet''s payload field.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bitstream payload');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '335d1dd1-cc27-4e3b-b04b-2a51a6070620','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='335d1dd1-cc27-4e3b-b04b-2a51a6070620') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='335d1dd1-cc27-4e3b-b04b-2a51a6070620');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a34a497b-b8f6-4dd3-945d-8a113357770f','Block companded PCM','A digital audio scheme in which samples are grouped into short blocks and companded together using one scale factor per block, reducing bit rate while preserving dynamic range. NICAM 728 uses near-instantaneous companding, coding 32 fourteen-bit samples into ten-bit words with a shared scale factor per block.','This method groups audio samples into short blocks. Each block shares one gain setting, called a scale factor. Loud and quiet blocks are scaled to fit fewer bits. NICAM 728 stereo TV sound works this way.','It exists to cut the bit rate of linear PCM while keeping a wide dynamic range, by letting each short block choose the scaling that best fits its level.','In NICAM 728 a technician handles 32-sample blocks where 14-bit samples are companded to 10 bits with a per-block scale factor, halving the data versus linear PCM.','Digital coding',ARRAY['Block floating point','Band-limiting filter','Bitstream payload','Baseband audio']::text[],ARRAY['Confusing per-block near-instantaneous companding with per-sample instantaneous companding.','Assuming companding is perceptual coding; it is a coarser dynamic-range fit.','Thinking the 10-bit words mean only 10-bit dynamic range, ignoring the block scale factor.']::text[],ARRAY['Servicing a NICAM 728 stereo television sound decoder.','Explaining how analog TV added digital stereo sound within limited bandwidth.','Comparing block companding against linear PCM for data rate.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Block companded PCM');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a34a497b-b8f6-4dd3-945d-8a113357770f','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a34a497b-b8f6-4dd3-945d-8a113357770f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a34a497b-b8f6-4dd3-945d-8a113357770f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ba2e5554-5e40-43ab-be17-221c0428c3fd','Block floating point','A numeric representation in which a block of samples or spectral coefficients shares one common exponent (scale factor) while each keeps its own mantissa, giving much of floating-point''s dynamic range at lower storage cost. Transform audio coders such as ATRAC use it on grouped spectral coefficients.','Block floating point stores a group of numbers together. All numbers in the group share one exponent. Each number keeps its own mantissa, or fraction. This gives wide range while saving bits per number.','It captures the large dynamic range of floating point without storing an exponent per value, which suits fixed hardware and audio-coding blocks efficiently.','In a transform coder a technician sees each coefficient block normalized to one shared exponent, so quantization bits track the loudest value in that block.','Numeric representation',ARRAY['Block companded PCM','Block switching','Bitstream payload','Cascade filter bank']::text[],ARRAY['Confusing block floating point with true per-value floating point.','Assuming every sample gets full precision, when the shared exponent is set by the block maximum.','Overlooking that a single large value can coarsen the whole block''s small values.']::text[],ARRAY['Explaining how MiniDisc ATRAC scales grouped spectral coefficients.','Implementing efficient dynamic range on a fixed-point DSP.','Comparing block floating point with block companding.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Block floating point');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ba2e5554-5e40-43ab-be17-221c0428c3fd','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ba2e5554-5e40-43ab-be17-221c0428c3fd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ba2e5554-5e40-43ab-be17-221c0428c3fd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '43c92b95-86e0-453b-8146-a86f2801ae10','Block switching','A technique in transform audio coders that switches between long transform blocks for steady signals and short blocks for transients, so pre-echo from quantization noise stays confined near the transient. AAC switches between long and short windows for exactly this reason.','Block switching changes the size of the analysis window. Long windows suit steady sounds and give good frequency detail. Short windows suit sudden sounds like drum hits. Short windows keep coding noise from spreading before the hit.','It exists to control pre-echo, a burst of quantization noise that a long transform block would smear ahead of a sharp transient.','On a percussive track a technician relies on the coder switching to short blocks at each hit, limiting audible pre-echo before the attack.','Perceptual coding',ARRAY['Block floating point','Bandwidth-extension coding','Cascade filter bank','Base layer']::text[],ARRAY['Thinking short blocks are always better; they cost frequency resolution on steady tones.','Assuming block switching removes pre-echo entirely rather than confining it.','Confusing window length with the codec''s overall frame length.']::text[],ARRAY['Explaining why a coder handles castanets or drums without smeared noise.','Diagnosing pre-echo artefacts on transient-heavy material at low bit rates.','Comparing long-block and short-block behavior in AAC.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Block switching');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '43c92b95-86e0-453b-8146-a86f2801ae10','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='43c92b95-86e0-453b-8146-a86f2801ae10') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='43c92b95-86e0-453b-8146-a86f2801ae10');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a1794d6c-2f58-4257-bb12-fe8ec66d17d2','Blocking matrix','In a generalized sidelobe canceller (a form of adaptive beamformer), the blocking matrix is the fixed transform that removes the desired look-direction signal, producing reference channels containing mainly interference and noise for the adaptive stage to cancel. It enforces the beamformer''s distortionless constraint on the target direction.','A blocking matrix is part of an adaptive microphone-array beamformer. It removes the wanted signal from certain reference channels. Those channels then hold mostly noise and interference. The adaptive filter uses them to cancel that noise from the output.','It separates the wanted, look-direction signal from interference so the adaptive canceller can suppress noise without distorting the target.','In a speech array a technician uses a blocking matrix that nulls the talker direction, giving noise references the adaptive filter subtracts from the beam output.','Adaptive beamforming',ARRAY['Beam pattern','Broadband noise','Cascade filter bank','Coherence function']::text[],ARRAY['Expecting perfect signal blocking, when steering error leaks target into references and causes cancellation.','Confusing the fixed blocking matrix with the adaptive filter that follows it.','Assuming it improves gain rather than enabling interference cancellation.']::text[],ARRAY['Building a speech-enhancement microphone array with a generalized sidelobe canceller.','Explaining target signal cancellation caused by array steering error.','Designing reference channels for adaptive noise cancellation.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Blocking matrix');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a1794d6c-2f58-4257-bb12-fe8ec66d17d2','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a1794d6c-2f58-4257-bb12-fe8ec66d17d2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a1794d6c-2f58-4257-bb12-fe8ec66d17d2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '51ecba0d-45d1-46d1-8a6f-5d80c918cdf8','Boundary element method','A numerical technique for acoustic problems that discretizes only the boundary surfaces (not the whole volume) and solves an integral equation for surface pressure and velocity, from which the field elsewhere is computed. It suits exterior radiation and scattering problems because it naturally satisfies the radiation condition.','The boundary element method predicts sound from a surface. It divides only the object''s surface into small elements. It solves for pressure and motion on that surface. From there it computes the sound field around the object.','It models radiation and scattering efficiently by meshing surfaces only, avoiding the large volume meshes that other methods need for open, exterior acoustic problems.','An acoustic engineer uses boundary element modeling to predict a loudspeaker enclosure''s radiation or a microphone body''s diffraction before building hardware.','Numerical acoustics',ARRAY['Beam pattern','Coincidence frequency','Broadband noise','Cascade filter bank']::text[],ARRAY['Meshing coarsely relative to wavelength, which corrupts results at high frequency.','Ignoring non-uniqueness at certain frequencies without a remedy such as the CHIEF or Burton-Miller method.','Confusing the surface-only boundary method with volume-meshing finite elements.']::text[],ARRAY['Predicting the radiation pattern of a loudspeaker cabinet.','Modeling diffraction around a microphone or head before prototyping.','Choosing a surface-mesh method for an exterior scattering problem.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Boundary element method');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '51ecba0d-45d1-46d1-8a6f-5d80c918cdf8','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='51ecba0d-45d1-46d1-8a6f-5d80c918cdf8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='51ecba0d-45d1-46d1-8a6f-5d80c918cdf8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '85a9fd62-fe21-40f8-9229-e37ca2fc8e78','Broadband noise','Noise whose energy is distributed continuously over a wide, contiguous span of frequencies rather than concentrated at discrete tones. White and pink noise are broadband examples, differing in how energy is spread across the band.','Broadband noise spreads its energy over many frequencies at once. It is not a single tone or a few tones. It sounds like a hiss or rush. White and pink noise are common examples.','The term identifies wideband, non-tonal disturbances or test signals, guiding how they are measured, masked or used to excite a system across its range.','A technician uses broadband pink noise to check a loudspeaker system''s response across the whole audio band in one measurement.','Signal characterization',ARRAY['Comfort noise','Chirp signal','Click train','Bel']::text[],ARRAY['Assuming broadband means flat; pink noise is broadband but not flat per hertz.','Confusing broadband noise with narrowband or tonal interference.','Using an unweighted level without stating the measurement bandwidth.']::text[],ARRAY['Exciting a room with pink noise to measure its response.','Distinguishing broadband hiss from a discrete hum tone.','Specifying a noise floor across the full audio band.']::text[],'beginner',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Broadband noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '85a9fd62-fe21-40f8-9229-e37ca2fc8e78','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='85a9fd62-fe21-40f8-9229-e37ca2fc8e78') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='85a9fd62-fe21-40f8-9229-e37ca2fc8e78');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '348e973d-b92a-447e-86a7-0e033d20ee5d','Bulk delay','A fixed, overall latency applied to or present in a signal path, such as the constant transport delay estimated ahead of an adaptive echo canceller, or a whole-signal delay used to time-align sources. It is a single lump of delay rather than a per-frequency or adaptive one.','Bulk delay is one fixed lump of delay in a path. It shifts the whole signal by a set time. Echo cancellers estimate it before fine adaptation. Engineers also use it to line up sources in time.','It captures or applies a constant path latency, letting a system compensate for transport time before finer, adaptive or frequency-dependent processing.','In line-of-sight alignment a technician might add 10 ms of bulk delay to a nearer loudspeaker so its sound arrives with a farther one.','Timing and delay',ARRAY['Audio-visual synchronization metadata','Baseband audio','Broadband noise','Comfort noise']::text[],ARRAY['Confusing constant bulk delay with frequency-dependent group delay.','Assuming bulk delay alone cancels echo, when adaptive filtering must follow it.','Forgetting that added delay must be matched across all related signals to keep sync.']::text[],ARRAY['Estimating transport delay before an echo canceller adapts.','Time-aligning a delayed loudspeaker to a main array.','Compensating a fixed processing latency in a live path.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bulk delay');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '348e973d-b92a-447e-86a7-0e033d20ee5d','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='348e973d-b92a-447e-86a7-0e033d20ee5d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='348e973d-b92a-447e-86a7-0e033d20ee5d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e4656862-491a-4316-8a54-b3c7ddda43dc','Cascade filter bank','A filter bank built as a series (cascade) of stages, where each stage further splits or refines the signal''s subbands, as in a tree-structured or hierarchical decomposition. Cascading simple two-band splits repeatedly yields many subbands, the basis of wavelet and tree-structured subband coders.','A cascade filter bank splits a signal in stages. Each stage divides bands into smaller bands. Repeating simple splits builds many subbands. Wavelet and subband coders are built this way.','It creates a multi-band or multi-resolution decomposition from repeated simple splits, which is efficient and gives flexible time-frequency resolution for coding and analysis.','A technician meets it in subband coders where a signal is split in a tree of stages, giving finer frequency resolution at low frequencies.','Filter banks',ARRAY['Band-limiting filter','Block switching','Cepstral coefficient','Block floating point']::text[],ARRAY['Assuming cascading is lossless by default; stage design must ensure reconstruction.','Ignoring accumulated delay and ripple across many stages.','Confusing a cascade (series) structure with a parallel bank of independent filters.']::text[],ARRAY['Explaining tree-structured subband decomposition in a coder.','Designing a multi-resolution analysis from repeated two-band splits.','Tracing latency growth through a multi-stage filter bank.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cascade filter bank');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e4656862-491a-4316-8a54-b3c7ddda43dc','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e4656862-491a-4316-8a54-b3c7ddda43dc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e4656862-491a-4316-8a54-b3c7ddda43dc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2f6cdfbd-f178-4842-89a3-9e3d0d54d657','Cepstral coefficient','A coefficient of the cepstrum, obtained by taking the inverse transform of the logarithm of a signal''s spectrum, which separates slowly varying spectral shape from fine periodic structure. Mel-frequency cepstral coefficients are a standard feature in speech and audio analysis.','A cepstral coefficient comes from a two-step transform. First take the spectrum, then its logarithm, then transform again. This separates the overall spectral shape from pitch detail. Speech recognition uses these coefficients as features.','The cepstrum deconvolves source and filter, so cepstral coefficients compactly capture spectral envelope for tasks like speech recognition, pitch estimation and timbre analysis.','A technician computing MFCCs windows the audio, takes a mel-band log spectrum, then a discrete cosine transform, keeping the low coefficients as features.','Signal features',ARRAY['Cascade filter bank','Chirp signal','Coherence function','Broadband noise']::text[],ARRAY['Forgetting the logarithm step, which is essential to separating source and filter.','Confusing the cepstrum''s quefrency axis (time-like) with ordinary frequency.','Assuming raw cepstral coefficients need no mean removal or normalization for recognition.']::text[],ARRAY['Extracting MFCC features for a speech-recognition front end.','Estimating fundamental frequency from a cepstral peak.','Comparing timbres using low-order cepstral coefficients.']::text[],'advanced','c[n] = IDFT{ log |DFT{ x[n] }| }','The real cepstrum is the inverse transform of the logarithm of the magnitude spectrum of the signal.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cepstral coefficient');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2f6cdfbd-f178-4842-89a3-9e3d0d54d657','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2f6cdfbd-f178-4842-89a3-9e3d0d54d657') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2f6cdfbd-f178-4842-89a3-9e3d0d54d657');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7af1dfd0-941d-474c-a177-92304e4dbf19','Channel element','In AAC, a single-channel element (SCE) is the syntactic bitstream element that carries one independent audio channel''s coded data. A stream''s channel layout is assembled from single-channel elements, channel-pair elements and a low-frequency element as needed.','A channel element carries one audio channel in an AAC stream. It is the block for a single mono signal. Mono programs and center or surround channels use it. The decoder reads it to rebuild that one channel.','It provides the bitstream container for one independent channel, letting decoders assemble mono, stereo and multichannel layouts from a defined set of elements.','A technician confirming a 5.1 AAC layout sees single-channel elements for center and surrounds alongside channel-pair elements for the stereo pairs.','Bitstream syntax',ARRAY['Channel pair element','Bistream element','Bitstream payload','Coded audio access unit']::text[],ARRAY['Assuming a channel element always means mono program; it is one channel within a layout.','Confusing a single-channel element with a channel-pair element that carries two channels.','Overlooking that the low-frequency effects channel uses its own element type.']::text[],ARRAY['Verifying the channel map of a multichannel AAC stream.','Explaining how a mono AAC program is carried.','Debugging a decoder that misreads a channel element.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Channel element');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7af1dfd0-941d-474c-a177-92304e4dbf19','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7af1dfd0-941d-474c-a177-92304e4dbf19') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7af1dfd0-941d-474c-a177-92304e4dbf19');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '17a40f12-7f8a-4f09-9ce6-d7f3fe17d0da','Channel pair element','In AAC, a channel-pair element (CPE) is the syntactic bitstream element that carries two audio channels together, typically a stereo pair, and can apply joint-stereo tools such as mid/side and intensity coding across them. It is the container for a coupled channel pair.','A channel pair element carries two channels in an AAC stream. It usually holds a stereo left/right pair. It can share data between the two channels to save bits. This is called joint stereo coding.','It packages two related channels together so the coder can exploit their similarity with joint-stereo tools, improving efficiency over coding each channel alone.','A technician sees the front left/right of a 5.1 AAC stream carried as a channel-pair element that may use mid/side coding to save bits.','Bitstream syntax',ARRAY['Channel element','Bistream element','Bitstream payload','Coded audio access unit']::text[],ARRAY['Assuming a channel-pair element is always plain left/right, ignoring mid/side or intensity coding.','Confusing a channel-pair element with two separate single-channel elements.','Thinking joint-stereo tools are always active within it.']::text[],ARRAY['Checking whether an AAC stereo stream uses joint-stereo coding.','Mapping the front pair of a multichannel AAC layout.','Explaining bitrate savings from mid/side coding in a pair element.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Channel pair element');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '17a40f12-7f8a-4f09-9ce6-d7f3fe17d0da','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='17a40f12-7f8a-4f09-9ce6-d7f3fe17d0da') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='17a40f12-7f8a-4f09-9ce6-d7f3fe17d0da');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f5287705-158f-4f94-847d-c93ebe82e711','Chirp signal','A signal whose instantaneous frequency changes with time, sweeping across a band; a linear chirp increases frequency at a constant rate. Swept sines (chirps) are widely used to measure system frequency response and impulse response.','A chirp is a tone that slides in frequency over time. A linear chirp rises at a steady rate. Engineers sweep a chirp through the audio band. From the response they get frequency and impulse response.','It excites a system across a whole frequency band in one controlled pass, giving high signal-to-noise measurement of response and, with care, separation of distortion.','Sweeping 20 Hz to 20 kHz over 1 s with a linear chirp, the instantaneous frequency at 0.5 s is about 10 kHz, midway through the sweep.','Test signals',ARRAY['Coherence function','Broadband noise','Click train','Cepstral coefficient']::text[],ARRAY['Confusing a linear chirp with a logarithmic (exponential) sweep, which distributes energy differently.','Sweeping too fast for the system to settle, smearing the measured response.','Ignoring that loudspeaker nonlinearity needs the right sweep type to separate distortion.']::text[],ARRAY['Measuring a loudspeaker''s frequency response with a swept sine.','Capturing a room impulse response using an exponential chirp.','Separating harmonic distortion from the linear response in a sweep measurement.']::text[],'intermediate','f(t) = f0 + (B / T) * t','For a linear chirp the instantaneous frequency equals the start frequency plus the sweep rate times elapsed time.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Chirp signal');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f5287705-158f-4f94-847d-c93ebe82e711','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f5287705-158f-4f94-847d-c93ebe82e711') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f5287705-158f-4f94-847d-c93ebe82e711');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '35310196-488a-40bd-a400-7f8b5308d55b','Clean audio','An accessibility audio service that provides a version of a program''s soundtrack with enhanced speech intelligibility, typically by raising dialogue relative to music and effects, for listeners who are hard of hearing. Broadcast standards define it as an alternative or receiver-mixable audio service.','Clean audio is an accessibility sound option. It makes speech easier to hear. It raises the dialogue above music and effects. Hard-of-hearing viewers can select it instead of the normal mix.','It exists to improve dialogue intelligibility for hearing-impaired audiences, delivered either as a separate clean mix or via receiver mixing of a dialogue-enhancement stream.','A technician provisions clean audio as an additional audio service, or as object/metadata a receiver uses to boost dialogue, so viewers can choose clearer speech.','Accessibility service',ARRAY['Audio-visual synchronization metadata','Bitstream payload','Coded audio access unit','Comfort noise']::text[],ARRAY['Confusing clean audio with audio description, which adds narration for blind users.','Assuming clean audio simply removes music, when it rebalances dialogue against it.','Overlooking that some systems deliver it by receiver mixing rather than a full separate mix.']::text[],ARRAY['Adding a clean-audio track for hard-of-hearing viewers on a broadcast.','Configuring dialogue enhancement that a receiver mixes at playback.','Distinguishing clean audio from audio description in an accessibility spec.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Clean audio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '35310196-488a-40bd-a400-7f8b5308d55b','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='35310196-488a-40bd-a400-7f8b5308d55b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='35310196-488a-40bd-a400-7f8b5308d55b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ee12a4f7-57c6-4719-b5c1-76026943c761','Click train','A signal consisting of a regular sequence of short impulses (clicks) at a fixed repetition rate, effectively a periodic impulse train. Its spectrum is a harmonic series spaced at the repetition rate, making it useful for excitation, timing and auditory testing.','A click train is a steady string of short clicks. The clicks repeat at a set rate. In frequency it shows evenly spaced spectral lines. It is used to excite systems and to test hearing.','It provides a periodic, broadband excitation whose harmonics are set by the click rate, useful for measuring responses and for evoked-response hearing tests.','A technician sets a click rate so the resulting harmonic lines fall where a system''s response needs probing, or uses standardized clicks for auditory testing.','Test signals',ARRAY['Chirp signal','Broadband noise','Comfort noise','Coherence function']::text[],ARRAY['Assuming a click train is broadband continuous noise, when its spectrum is discrete harmonic lines.','Ignoring that click polarity and shape affect the measured response.','Confusing click rate (spectral spacing) with click width (spectral extent).']::text[],ARRAY['Driving a system with a periodic impulse train for response testing.','Using standardized clicks in auditory brainstem-response testing.','Explaining the harmonic-line spectrum of a repetitive click.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Click train');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ee12a4f7-57c6-4719-b5c1-76026943c761','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ee12a4f7-57c6-4719-b5c1-76026943c761') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ee12a4f7-57c6-4719-b5c1-76026943c761');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '71c8e718-987c-43f0-a55f-c360b806d3a2','Coded audio access unit','In MPEG systems, an access unit is the smallest individually decodable and independently timestamped unit of a coded stream; for audio it is typically one coded frame carrying a defined number of samples. Access units bear presentation and decoding timestamps used to synchronize playback.','An access unit is the smallest decodable chunk of a coded stream. For audio it is usually one coded frame. It carries timestamps for when to decode and present it. Players use those stamps to keep sound in sync.','It defines the unit that transport and buffering handle and timestamp, so decoders can locate, decode and present coded audio at the correct time.','A technician tracing lip-sync inspects the presentation timestamp on each audio access unit to see whether frames are aligned with video.','Systems transport',ARRAY['Audio-visual synchronization metadata','Bitstream payload','Bistream element','Base layer']::text[],ARRAY['Confusing an access unit with a transport packet; one access unit can span several packets.','Assuming access units are fixed in byte size rather than in samples/frame.','Overlooking the difference between decoding and presentation timestamps.']::text[],ARRAY['Debugging audio-video sync using presentation timestamps on access units.','Explaining how a transport stream carries coded audio frames.','Analyzing buffer behavior at the access-unit level.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coded audio access unit');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '71c8e718-987c-43f0-a55f-c360b806d3a2','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='71c8e718-987c-43f0-a55f-c360b806d3a2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='71c8e718-987c-43f0-a55f-c360b806d3a2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b9da8b3d-d59d-426e-9185-2318a6f3e32c','Coherence function','The (magnitude-squared) coherence between two signals is a normalized, frequency-dependent measure, from 0 to 1, of how linearly one is related to the other, computed from their auto- and cross-spectral densities. A value near 1 indicates a strong linear relationship at that frequency with low noise or nonlinearity.','Coherence measures how well two signals relate at each frequency. It runs from zero to one. A value near one means a clean, linear link. Low values reveal noise, delay error, or nonlinearity.','It quantifies measurement quality and linear dependence versus frequency, flagging where a transfer-function estimate is trustworthy and where noise or nonlinearity corrupts it.','Measuring a loudspeaker, a technician trusts the response where coherence is near 1 and discounts bands where it drops toward 0.','Measurement analysis',ARRAY['Chirp signal','Broadband noise','Cepstral coefficient','Blocking matrix']::text[],ARRAY['Reading low coherence as system failure, when it may be background noise or too few averages.','Forgetting coherence needs averaging over multiple frames to be meaningful.','Assuming coherence near 1 proves accuracy even when levels are far too low.']::text[],ARRAY['Judging which frequency bands of a measured response to trust.','Detecting background noise contaminating a transfer-function measurement.','Checking averaging is sufficient during a dual-channel FFT measurement.']::text[],'advanced','gamma^2_xy(f) = |Gxy(f)|^2 / ( Gxx(f) * Gyy(f) )','Magnitude-squared coherence equals the squared magnitude of the cross-spectrum divided by the product of the two auto-spectra.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coherence function');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b9da8b3d-d59d-426e-9185-2318a6f3e32c','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b9da8b3d-d59d-426e-9185-2318a6f3e32c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b9da8b3d-d59d-426e-9185-2318a6f3e32c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ba17d45f-ace1-40fc-928c-a9a7c9f6c6e0','Coincidence dip','A pronounced drop in a panel''s sound transmission loss near and above its critical frequency, where the bending wavelength in the panel matches the trace wavelength of incident airborne sound, so the panel couples strongly and radiates efficiently. It weakens the mass-law insulation over that region.','A coincidence dip is a weak spot in a wall''s sound blocking. It happens near the panel''s critical frequency. There, bending waves in the panel match the incoming sound''s trace. The panel then passes sound more easily than mass law predicts.','The concept explains why a partition insulates worse than mass law predicts around its critical frequency, guiding material and construction choices for isolation.','A technician facing weak isolation near a wall''s critical frequency uses damping, added mass or dissimilar layers to reduce the coincidence dip.','Sound insulation',ARRAY['Coincidence frequency','Boundary element method','Broadband noise','Beam pattern']::text[],ARRAY['Blaming the dip on mass alone, when it is a bending-wave coincidence effect.','Assuming thicker single panels always help, since stiffness lowers the critical frequency into the audible band.','Ignoring damping, which broadens but reduces the depth of the dip.']::text[],ARRAY['Diagnosing poor speech isolation through a stiff partition at mid frequencies.','Choosing damped or multi-layer walls to limit the coincidence dip.','Interpreting a transmission-loss curve that sags near critical frequency.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coincidence dip');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ba17d45f-ace1-40fc-928c-a9a7c9f6c6e0','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ba17d45f-ace1-40fc-928c-a9a7c9f6c6e0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ba17d45f-ace1-40fc-928c-a9a7c9f6c6e0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6f887bf6-5896-4bd8-ae03-0dff5b5eaff5','Coincidence frequency','The frequency at which the wavelength of free bending waves in a panel equals the trace wavelength of incident airborne sound; the lowest such frequency (at grazing incidence) is the critical frequency. Above it, coincidence lets the panel radiate and transmit sound efficiently.','The coincidence frequency is where a panel''s bending waves match the sound''s trace along it. The lowest one is called the critical frequency. Above it, the panel transmits sound easily. It depends on the panel''s mass and stiffness.','It marks where a partition''s insulation departs from mass law, so designers can push the critical frequency out of the important band by choice of mass and stiffness.','For a panel with surface mass 10 kg/m^2 and bending stiffness 100 N*m, the critical frequency is about 5.9 kHz, using fc = (c^2/2*pi)*sqrt(m/B).','Sound insulation',ARRAY['Coincidence dip','Boundary element method','Broadband noise','Bel']::text[],ARRAY['Confusing the general coincidence frequency with the specific critical (grazing-incidence) frequency.','Assuming stiffer is always better, since higher stiffness lowers the critical frequency into the audible range.','Forgetting that critical frequency scales inversely with panel thickness for a given material.']::text[],ARRAY['Selecting glazing so its critical frequency avoids the speech band.','Explaining why thin, limp panels insulate better across mid frequencies.','Predicting where a partition''s transmission loss will dip.']::text[],'advanced','f_c = (c^2 / (2*pi)) * sqrt(m'''' / B'')','The critical frequency equals the speed of sound squared over two pi, times the square root of surface mass divided by bending stiffness per unit width.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coincidence frequency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6f887bf6-5896-4bd8-ae03-0dff5b5eaff5','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6f887bf6-5896-4bd8-ae03-0dff5b5eaff5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6f887bf6-5896-4bd8-ae03-0dff5b5eaff5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b6631567-a89d-4843-9995-7ce5b1504e73','Comfort noise','Low-level synthetic background noise inserted at a receiver during silence periods when a discontinuous-transmission (DTX) voice system stops sending speech, so the connection does not sound dead. Its spectral shape is set by comfort-noise parameters sent occasionally by the transmitter.','Comfort noise is faint fake background hiss. Voice systems stop sending data during silence to save bandwidth. Total silence sounds like a dropped call. So the receiver plays comfort noise to reassure the listener.','It preserves a natural sense of an open line during silence in bandwidth-saving discontinuous transmission, avoiding the unsettling dead-air effect of true digital silence.','A technician enabling DTX ensures comfort-noise generation is on, so gaps between talkspurts carry matched low-level noise instead of abrupt silence.','Voice transport',ARRAY['Broadband noise','Baseband audio','Bitstream payload','Clean audio']::text[],ARRAY['Thinking comfort noise carries speech; it only fills silence with matched background.','Assuming it is continuously transmitted, when only occasional update parameters are sent.','Confusing comfort noise with residual coding noise or line hiss.']::text[],ARRAY['Configuring VoIP with discontinuous transmission and silence suppression.','Explaining why a muted call still has faint background hiss.','Diagnosing unnatural dead-air when comfort noise is disabled.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Comfort noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b6631567-a89d-4843-9995-7ce5b1504e73','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b6631567-a89d-4843-9995-7ce5b1504e73') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b6631567-a89d-4843-9995-7ce5b1504e73');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4a69f9df-4e66-42f2-84c5-46e5e583611f','Contrast gain control','Contrast gain control is an adaptive process in the auditory system that rescales neural gain according to the variance (contrast) of the sound-level distribution, not just its mean. Higher stimulus contrast lowers gain while lower contrast raises it, keeping neural responses within a usable range.','The hearing system changes how hard it reacts to sound. It watches how much the loudness swings, not just how loud it is. When levels swing a lot, it turns its gain down. This keeps signals from swamping the nerves.','It preserves sensitivity and coding efficiency across changing acoustic scenes by adapting neural gain to the spread of sound levels.','A researcher probing this switches stimuli between high- and low-variance level distributions and measures how quickly cortical gain readjusts.','Auditory Mechanism',ARRAY['Envelope following response','Auditory masking','Dynamic range','Cochlear amplifier']::text[],ARRAY['Confusing it with automatic gain control in an amplifier; this is a neural, not a circuit, process.','Assuming gain depends only on mean level; it also tracks level variance.','Thinking it acts instantly; it adapts over tens to hundreds of milliseconds.']::text[],ARRAY['Modeling how listeners follow speech when background-noise level fluctuates.','Interpreting auditory-cortex recordings under varying stimulus contrast.','Designing hearing-aid compression inspired by biological gain control.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Contrast gain control');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4a69f9df-4e66-42f2-84c5-46e5e583611f','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4a69f9df-4e66-42f2-84c5-46e5e583611f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4a69f9df-4e66-42f2-84c5-46e5e583611f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '65e92394-7c82-4135-b1cb-e05803d1db06','Core coder','In layered audio-coding standards, the core coder is the base codec that reconstructs a usable signal on its own, over which optional enhancement tools add bandwidth or channels. In MPEG-D USAC (ISO/IEC 23003-3) the core coder switches between a linear-prediction speech mode and an MDCT transform mode.','Some audio codecs are built in layers. The core coder is the bottom layer. It can decode sound by itself. Extra tools sit on top to add bandwidth or channels. Modern cores switch between speech and music modes.','It provides the essential decodable audio foundation so scalable or enhancement tools remain optional and backward compatible.','A streaming engineer choosing xHE-AAC relies on its USAC core coder to handle both speech and music efficiently at low bitrate.','Audio Coding',ARRAY['Encoded bitstream','Hybrid filter bank','Frequency-domain audio coding','Decoded audio','Huffman codebook']::text[],ARRAY['Assuming the core always carries full bandwidth; enhancement layers may add the top octaves.','Treating ''core coder'' as one fixed algorithm rather than a switchable structure.','Confusing the core coder with the container or transport format.']::text[],ARRAY['Configuring an xHE-AAC encoder for adaptive-bitrate streaming.','Analyzing how a codec falls back when enhancement layers are dropped.','Comparing speech-versus-music handling in unified codecs.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Core coder');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '65e92394-7c82-4135-b1cb-e05803d1db06','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='65e92394-7c82-4135-b1cb-e05803d1db06') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='65e92394-7c82-4135-b1cb-e05803d1db06');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '91d9a860-81c8-4475-9492-02157e84817c','Cross-correlation lag','The cross-correlation lag is the sample or time offset at which the cross-correlation between two signals reaches its peak, indicating their relative delay. It is the argument that maximizes the cross-correlation sequence.','Cross-correlation slides one signal past another and scores the match at each shift. The lag is the shift that gives the best match. It tells how far apart in time the two signals are. This is how delays are found.','It estimates the time delay between two related signals, such as a source and its echo or two microphone captures.','With two microphones and a correlation peak at a lag of 15 samples at a 48 kHz sample rate, the estimated delay is 15/48000 = 0.31 ms.','Signal Analysis',ARRAY['Generalized cross-correlation','Interchannel coherence','Discrete-time analytic signal','Homomorphic deconvolution']::text[],ARRAY['Reading lag in samples but reporting it as seconds without dividing by the sample rate.','Ignoring that noise and reverberation can shift or split the peak.','Forgetting that the sign of the lag encodes which signal leads.']::text[],ARRAY['Estimating delay between microphone-array channels.','Detecting an echo''s arrival time.','Aligning two recordings of the same event.']::text[],'intermediate','l_hat = argmax_l r_xy[l],  r_xy[l] = sum_n x[n] y[n+l]','The lag estimate is the shift l that maximizes the cross-correlation, where cross-correlation sums the product of one signal with a shifted copy of the other.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cross-correlation lag');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '91d9a860-81c8-4475-9492-02157e84817c','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='91d9a860-81c8-4475-9492-02157e84817c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='91d9a860-81c8-4475-9492-02157e84817c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '45840aa3-8d7b-4616-aff8-3861eddb9e19','Cross-fade window','A cross-fade window is the pair of complementary gain curves applied to two audio segments so one fades out while the other fades in across an overlap region, avoiding clicks at the join. Equal-power cross-fades keep the summed power roughly constant for uncorrelated material.','A cross-fade blends the end of one clip into the start of another. The window sets how fast each side fades. A good window stops clicks and level dips. Equal-power windows keep loudness steady through the blend.','It provides a smooth, artifact-free transition between two audio segments or overlapping coded frames.','An editor splicing two takes uses a 10 ms equal-power cross-fade so the summed level stays roughly constant and no click is heard.','Editing / Coding',ARRAY['Frame loss concealment','Filter bank','Hybrid filter bank','Frequency-domain audio coding']::text[],ARRAY['Using a linear (equal-gain) cross-fade on uncorrelated audio, causing a loudness dip in the middle.','Making the overlap too short, which reintroduces clicks.','Assuming any window shape suppresses spectral leakage equally.']::text[],ARRAY['Splicing edits and comping takes.','Seamless looping of a sample.','Overlap-add reconstruction in transform coders.']::text[],'intermediate','y[n] = g1[n] x1[n] + g2[n] x2[n],  equal power: g1^2[n] + g2^2[n] = 1','The output is the sum of the two segments scaled by fade-out and fade-in gains; for an equal-power cross-fade the squared gains sum to one.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cross-fade window');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '45840aa3-8d7b-4616-aff8-3861eddb9e19','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='45840aa3-8d7b-4616-aff8-3861eddb9e19') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='45840aa3-8d7b-4616-aff8-3861eddb9e19');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9dfa8032-2857-4291-a237-f946e1fcd757','Cross-modulation distortion','Cross-modulation distortion is a nonlinear effect in which the amplitude modulation of a strong unwanted signal is transferred onto a desired carrier passing through the same nonlinear device. It arises mainly from odd-order (notably third-order) nonlinearity.','A nonlinear amp or receiver can let one signal''s loudness pattern leak onto another. The unwanted station''s modulation rides on the wanted one. You hear the interfering program bleed through. It comes from the device not being perfectly linear.','It names and quantifies an interference mechanism engineers must limit in receivers, amplifiers, and RF front ends.','A technician tests a receiver by applying a strong modulated off-channel carrier and measuring how much of its modulation appears on the desired channel.','Nonlinear Distortion',ARRAY['Intermodulation distortion','Harmonic distortion','Adjacent-channel interference','Third-order intercept']::text[],ARRAY['Confusing it with intermodulation, which creates new sum-and-difference frequencies rather than transferring modulation.','Assuming it comes from even-order terms; it is dominated by odd-order nonlinearity.','Thinking it occurs only in radios and not in audio amplifiers.']::text[],ARRAY['Receiver overload in a crowded RF band.','Wireless microphone systems near strong transmitters.','Broadband amplifier interference testing.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cross-modulation distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9dfa8032-2857-4291-a237-f946e1fcd757','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9dfa8032-2857-4291-a237-f946e1fcd757') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9dfa8032-2857-4291-a237-f946e1fcd757');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'df3a1f93-41df-43f1-9d41-e42341f48d08','Cut-off frequency of a filter','The cut-off frequency is the frequency at which a filter''s power output falls to half its passband value, i.e. the -3 dB (half-power) point where voltage gain is 1/sqrt(2) of maximum. For a first-order RC filter it equals 1/(2*pi*R*C).','Every filter has a corner where it starts to cut. The cut-off is where the power drops to half. In decibels that is minus three dB. For a simple RC filter it depends on the resistor and capacitor values.','It marks the boundary between a filter''s passband and stopband and sets where attenuation begins.','An RC low-pass with R = 1.6 kohm and C = 100 nF has f_c = 1/(2*pi*1600*100e-9) which is about 995 Hz.','Filtering',ARRAY['Filter bank','Damping ratio of a resonator','Filter-bank equalizer','Frequency-domain audio coding']::text[],ARRAY['Thinking the filter blocks everything past cut-off; it only reaches -3 dB there and then rolls off.','Confusing the -3 dB (half-power) point with an amplitude-halving (-6 dB) point.','Applying the simple RC formula to higher-order or resonant filters unchanged.']::text[],ARRAY['Setting a high-pass to remove stage rumble.','Designing an anti-alias filter before a converter.','Choosing loudspeaker crossover points.']::text[],'beginner','f_c = 1 / (2 pi R C)   (first-order RC);  |H(f_c)| = (1/sqrt(2)) |H|_max  (-3 dB)','For a first-order RC filter the cut-off frequency is one divided by two pi times resistance times capacitance; at that frequency the response is 3 dB below the passband.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cut-off frequency of a filter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'df3a1f93-41df-43f1-9d41-e42341f48d08','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='df3a1f93-41df-43f1-9d41-e42341f48d08') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='df3a1f93-41df-43f1-9d41-e42341f48d08');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '32c75dcc-b7f8-4e0d-8d11-b37acb3e24d3','Damping ratio of a resonator','The damping ratio (zeta) is a dimensionless measure of how oscillations in a resonant system decay, defined as the actual damping divided by the critical damping. It relates to quality factor by zeta = 1/(2Q); zeta < 1 is underdamped, zeta = 1 critically damped, zeta > 1 overdamped.','A resonator rings when struck. The damping ratio says how fast the ringing dies. A small value rings a long time. A value of one stops without overshoot. Above one it is sluggish and does not oscillate.','It characterizes the decay and stability of any resonant element, from a loudspeaker cone to a filter section.','A resonator with quality factor Q = 5 has damping ratio zeta = 1/(2*5) = 0.1, so it is lightly damped and rings noticeably.','Resonance',ARRAY['Cut-off frequency of a filter','Filter bank','Inharmonicity coefficient','Filter-bank equalizer']::text[],ARRAY['Mixing up the damping ratio with the damping coefficient c, which carries units.','Assuming higher Q means more damping; higher Q means less damping.','Forgetting that zeta = 1 gives the fastest non-oscillating decay.']::text[],ARRAY['Tuning a loudspeaker enclosure''s total Q (Qtc).','Setting the resonance of a filter section.','Analyzing structural vibration decay.']::text[],'intermediate','zeta = c / (2 sqrt(k m)) = 1 / (2 Q)','The damping ratio equals the damping coefficient divided by twice the square root of stiffness times mass, and equals one over twice the quality factor.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Damping ratio of a resonator');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '32c75dcc-b7f8-4e0d-8d11-b37acb3e24d3','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='32c75dcc-b7f8-4e0d-8d11-b37acb3e24d3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='32c75dcc-b7f8-4e0d-8d11-b37acb3e24d3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a25d18d1-dc3c-4d75-90e0-b6c759ac271a','Decibel full scale','dBFS expresses a digital audio level relative to full scale, the largest value the format can represent, so 0 dBFS is the maximum and normal levels are negative. By the AES17 convention a full-scale sine wave measures 0 dBFS, so a full-scale square wave reads about +3.01 dBFS on an RMS scale.','Digital audio has a hard ceiling. That ceiling is zero dBFS. Every normal level sits below it, so numbers are negative. The AES rule sets a full-scale sine to zero dBFS. Going over zero means clipping.','It gives a common reference for digital levels so meters and standards agree on where clipping occurs.','A signal at half of full-scale amplitude reads 20*log10(0.5) = -6.02 dBFS on a peak meter.','Digital Level',ARRAY['Decoded audio','Encoded bitstream','Denormalized number','Dynamic range']::text[],ARRAY['Treating dBFS as an absolute loudness like dB SPL; it is relative to the format ceiling.','Forgetting the AES17 sine reference, so peak and RMS scales differ by about 3 dB.','Expecting positive dBFS values in normal, unclipped audio.']::text[],ARRAY['Setting recording headroom below 0 dBFS.','Reading DAW peak and loudness meters.','Mastering to a true-peak or loudness target.']::text[],'beginner','L_dBFS = 20 log10( |x| / x_FS )','The level in dBFS is twenty times the base-ten logarithm of the sample magnitude divided by the full-scale magnitude.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Decibel full scale');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a25d18d1-dc3c-4d75-90e0-b6c759ac271a','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a25d18d1-dc3c-4d75-90e0-b6c759ac271a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a25d18d1-dc3c-4d75-90e0-b6c759ac271a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8af17fea-c17f-4d2f-a281-374229f9e624','Decoded audio','Decoded audio is the reconstructed pulse-code-modulation (PCM) signal a decoder produces from a coded bitstream, ready for playback or further processing. For lossy codecs it approximates, rather than exactly matches, the original.','A codec squeezes audio into a compact stream. A decoder turns that stream back into normal samples. Those samples are the decoded audio. With lossy codecs it is close but not identical to the source.','It is the usable output stage of a coding chain, delivering samples for converters or mixers.','A playback engineer checks that decoded audio from a file has the intended sample rate and channel layout before sending it to the converters.','Audio Coding',ARRAY['Encoded bitstream','Core coder','Frame loss concealment','Frequency-domain audio coding']::text[],ARRAY['Assuming lossy decoded audio is bit-identical to the source.','Ignoring decoder-added latency when aligning audio to video.','Overlooking that decode settings can change gain or channel order.']::text[],ARRAY['Verifying stream playback in a player.','A/B comparing a lossy decode against the master.','Syncing decoded audio to picture.']::text[],'beginner',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Decoded audio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8af17fea-c17f-4d2f-a281-374229f9e624','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8af17fea-c17f-4d2f-a281-374229f9e624') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8af17fea-c17f-4d2f-a281-374229f9e624');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0c8975e8-f2e9-4c55-ae30-8c1cf1c7cd1a','Decorrelation filter','A decorrelation filter is an allpass-type filter that alters a signal''s phase to reduce its correlation with a reference while preserving spectral magnitude, used to synthesize spatial width in parametric spatial audio. In MPEG Surround it generates a diffuse signal whose blend with the direct downmix is set by interchannel-coherence parameters.','Some codecs rebuild a surround image from one downmix. A decorrelation filter makes a second version that differs in phase but keeps the same tone colour. Mixing the two spreads the sound wider. Coherence data sets the amount.','It recreates spatial diffuseness and image width from a compact downmix plus a few transmitted parameters.','A codec developer tunes the decorrelator so low interchannel coherence yields a wide, enveloping image without smearing transients.','Spatial Audio Coding',ARRAY['Interchannel coherence','Core coder','Hybrid filter bank','Frequency-domain audio coding']::text[],ARRAY['Thinking it changes the spectrum; a good decorrelator is allpass and preserves magnitude.','Confusing decorrelation with a simple delay or reverb.','Ignoring the transient smearing artefacts decorrelators can add.']::text[],ARRAY['MPEG Surround and parametric-stereo decoding.','Upmixing a mono or stereo source.','Controlling perceived image width.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Decorrelation filter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0c8975e8-f2e9-4c55-ae30-8c1cf1c7cd1a','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0c8975e8-f2e9-4c55-ae30-8c1cf1c7cd1a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0c8975e8-f2e9-4c55-ae30-8c1cf1c7cd1a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ce349440-6522-488a-9969-3a54253d467b','Dedicated metadata channel','A dedicated metadata channel is a signal path reserved for carrying descriptive or control data alongside an audio program rather than the audio samples themselves. In professional transport it may use AES3 user and channel-status bits or a discrete data stream carried in the AES3 payload per SMPTE ST 337.','Audio often travels with extra data, like loudness or language tags. A dedicated metadata channel is a lane just for that data. It rides beside the sound but is not sound. Gear reads it to set up playback.','It keeps program control data synchronized with the audio without disturbing the audio samples.','A broadcast engineer routes loudness and dialnorm metadata on a dedicated path so the emission encoder applies the correct settings.','Metadata Transport',ARRAY['Descriptor scheme','Extensible metadata scheme','Encoded bitstream','Decoded audio']::text[],ARRAY['Assuming metadata is embedded in the audio samples themselves.','Losing metadata when re-encoding or format-converting without carrying the channel.','Confusing the carriage of metadata with its authoring.']::text[],ARRAY['Carrying broadcast loudness and dialnorm data.','Tagging multiple language versions.','Passing Dolby E on an AES3 pair.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dedicated metadata channel');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ce349440-6522-488a-9969-3a54253d467b','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ce349440-6522-488a-9969-3a54253d467b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ce349440-6522-488a-9969-3a54253d467b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c8cefb61-2316-4b27-88c0-9f0c448c1145','Denormalized number','A denormalized (subnormal) number is an IEEE 754 floating-point value with the minimum exponent field and no implied leading 1 in the significand, used to represent magnitudes smaller than the smallest normal number and to provide gradual underflow. Its value is (-1)^s * 2^(1-bias) * (0.f).','Floating-point numbers usually assume a hidden leading one. Subnormal numbers drop that rule near zero. This lets the format hold very tiny values instead of jumping to zero. It fills the gap around zero smoothly.','It gives gradual underflow so very small results lose precision slowly instead of collapsing straight to zero.','In audio DSP a decaying reverb tail can drift into subnormal range; engineers add tiny dither or a DC offset to avoid the heavy CPU cost some processors incur on subnormals.','Number Representation',ARRAY['Decibel full scale','Encoded bitstream','Decoded audio','Frequency-domain audio coding']::text[],ARRAY['Assuming every float has a hidden leading 1; subnormals do not.','Ignoring the CPU penalty subnormals can cause in real-time audio processing.','Confusing subnormal underflow with overflow or NaN.']::text[],ARRAY['Reverb and filter tails decaying into subnormal range.','Enabling flush-to-zero on a DSP.','Ensuring numerical stability in recursive filters.']::text[],'advanced','x = (-1)^s * 2^(1 - bias) * (0.f)_2   (exponent field = 0)','A subnormal value is the sign times two raised to the minimum exponent, multiplied by a fraction with no implied leading one.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Denormalized number');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c8cefb61-2316-4b27-88c0-9f0c448c1145','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c8cefb61-2316-4b27-88c0-9f0c448c1145') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c8cefb61-2316-4b27-88c0-9f0c448c1145');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a2fbb62d-9387-4d76-85a8-8b36614b5587','Descriptor scheme','A description scheme (DS) is a structured template in MPEG-7 (ISO/IEC 15938) that specifies how descriptors and other schemes combine to describe multimedia content, with structure and relationships defined using the Description Definition Language. Descriptors carry individual features; schemes organize them.','MPEG-7 is a way to describe media with data. A descriptor holds one feature, like a colour or a tempo. A description scheme sets how many descriptors fit together. It gives the metadata a shape.','It provides a standard structure so tools can share and search rich content descriptions consistently.','An archive engineer tags audio assets with MPEG-7 description schemes so a search system can retrieve clips by their described features.','Metadata Standard',ARRAY['Extensible metadata scheme','Dedicated metadata channel','Encoded bitstream','Decoded audio']::text[],ARRAY['Confusing a descriptor (one feature) with a description scheme (a structure of features).','Assuming MPEG-7 codes the audio; it only describes it.','Treating the Description Definition Language as a codec.']::text[],ARRAY['Media asset management and cataloguing.','Content-based retrieval of clips.','Standardized archival description.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Descriptor scheme');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a2fbb62d-9387-4d76-85a8-8b36614b5587','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a2fbb62d-9387-4d76-85a8-8b36614b5587') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a2fbb62d-9387-4d76-85a8-8b36614b5587');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '92bb60e8-ecba-4b39-bb68-0cccfa231ea4','Diffraction coefficient','A diffraction coefficient quantifies how strongly an edge or obstacle bends sound into the geometric shadow, relating the diffracted field amplitude to the incident field in the geometrical theory of diffraction. It depends on the wedge geometry, frequency, and the incidence and diffraction directions.','Sound bends around edges into shadow zones. The diffraction coefficient measures how much it bends. A bigger value means more sound leaks around the edge. It changes with angle and with frequency.','It lets ray-based acoustic models account for sound reaching listeners hidden behind edges and barriers.','In a geometrical-acoustics room model, an engineer applies an edge diffraction coefficient so a receiver behind a barrier still receives a predicted, reduced level.','Diffraction / Acoustics',ARRAY['Cut-off frequency of a filter','Damping ratio of a resonator','Filter bank']::text[],ARRAY['Assuming low frequencies diffract the same as high; longer wavelengths bend more.','Ignoring diffraction in ray models, which underpredicts level behind barriers.','Confusing diffraction with reflection or scattering.']::text[],ARRAY['Noise-barrier attenuation prediction.','Auralization of sources behind obstacles.','Loudspeaker-cabinet edge diffraction.']::text[],'advanced','p_d = p_i * D * A(s) * e^{-j k s}','The diffracted pressure equals the incident pressure at the edge times a diffraction coefficient, a distance-spreading factor, and a propagation phase term.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diffraction coefficient');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '92bb60e8-ecba-4b39-bb68-0cccfa231ea4','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='92bb60e8-ecba-4b39-bb68-0cccfa231ea4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='92bb60e8-ecba-4b39-bb68-0cccfa231ea4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c9c86eab-1c1e-4bee-934c-a398221d525a','Discrete-time analytic signal','A discrete-time analytic signal is a complex sequence whose real part is the original real signal and whose imaginary part is its discrete Hilbert transform, giving a one-sided (single-sideband) spectrum. Its magnitude is the instantaneous amplitude envelope and its angle is the instantaneous phase.','An analytic signal pairs a real signal with a shifted copy. The copy is its Hilbert transform. Together they form a complex signal with no negative frequencies. This makes the envelope and phase easy to read.','It provides the instantaneous amplitude (envelope) and instantaneous phase or frequency of a real signal.','To get an amplitude envelope, an engineer forms x_a[n] = x[n] + j*H{x[n]} and takes its magnitude |x_a[n]|.','Signal Analysis',ARRAY['Cross-correlation lag','Homomorphic deconvolution','Envelope following response','Generalized cross-correlation']::text[],ARRAY['Computing the envelope by rectifying instead of using the analytic magnitude.','Ignoring edge and transient errors of a finite-length Hilbert transform.','Assuming instantaneous frequency is meaningful for wideband, multicomponent signals.']::text[],ARRAY['Extracting an amplitude envelope.','AM demodulation.','Instantaneous-frequency analysis of a tone.']::text[],'advanced','x_a[n] = x[n] + j * H{ x[n] }','The analytic signal is the original signal plus j times its Hilbert transform, and its magnitude is the amplitude envelope.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Discrete-time analytic signal');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c9c86eab-1c1e-4bee-934c-a398221d525a','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c9c86eab-1c1e-4bee-934c-a398221d525a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c9c86eab-1c1e-4bee-934c-a398221d525a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd626cb53-487d-49bd-be2f-cb9ccc1d5f1e','Drift-corrected clock','A drift-corrected clock is a timing source whose long-term frequency error is continuously measured against a reference and compensated, so its rate stays locked despite oscillator aging and temperature change. Disciplining methods lock the oscillator to a reference such as a house sync signal, GPS, or a network master.','Every clock drifts a little over time. A drift-corrected clock watches a trusted reference. It nudges itself to match, so it does not wander. This keeps devices in step over long runs.','It keeps audio sample clocks aligned across devices to prevent slips, glitches, or slow loss of sync.','A facility disciplines its audio master clock to a house reference so multiple recorders stay sample-aligned over a long session.','Synchronization',ARRAY['Frame loss concealment','Encoded bitstream','Decoded audio']::text[],ARRAY['Confusing slow frequency drift with fast jitter; they are different problems.','Assuming a free-running crystal needs no discipline for long sessions.','Correcting rate in a way that introduces audible resampling artefacts.']::text[],ARRAY['Keeping multiple recorders sample-aligned.','Timing a broadcast plant to house reference.','Disciplining a networked-audio clock via PTP.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Drift-corrected clock');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd626cb53-487d-49bd-be2f-cb9ccc1d5f1e','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d626cb53-487d-49bd-be2f-cb9ccc1d5f1e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d626cb53-487d-49bd-be2f-cb9ccc1d5f1e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '346eff32-c0ed-425e-af24-d45059ffff86','Encoded bitstream','An encoded bitstream is the ordered sequence of bits an audio encoder produces, packaging quantized spectral or predictive data plus side information and headers according to a coding standard''s syntax. A conforming decoder parses this syntax to reconstruct the audio.','An encoder turns audio into a stream of bits. That stream follows strict rules so a decoder can read it. It holds the compressed data plus control info. Only a matching decoder can unpack it.','It is the compact, standard-defined carrier of coded audio for storage or transmission.','A streaming engineer packetizes an AAC encoded bitstream into a transport container for adaptive delivery.','Audio Coding',ARRAY['Core coder','Decoded audio','Huffman codebook','Frequency-domain audio coding']::text[],ARRAY['Confusing the bitstream syntax with the file container that wraps it.','Assuming any decoder reads any bitstream regardless of profile or level.','Editing a bitstream as if it were raw PCM.']::text[],ARRAY['Packetizing coded audio for streaming.','Running bitstream conformance tests.','Transcoding between codecs.']::text[],'beginner',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Encoded bitstream');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '346eff32-c0ed-425e-af24-d45059ffff86','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='346eff32-c0ed-425e-af24-d45059ffff86') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='346eff32-c0ed-425e-af24-d45059ffff86');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1f0b1dfd-9534-4bec-8528-175b7318c8dd','Envelope following response','The envelope following response (EFR) is a scalp-recorded auditory evoked potential that phase-locks to the amplitude envelope of a modulated or periodic sound, reflecting synchronized neural activity mainly from the auditory nerve and brainstem. Its strength is quantified at the stimulus modulation frequency.','When a sound''s loudness wobbles at a steady rate, hearing nerves fire in step. Electrodes on the scalp pick this up. That recorded signal is the envelope following response. It shows how well hearing tracks the loudness pattern.','It gives an objective, non-invasive measure of how the auditory system encodes the temporal envelope of sound.','A researcher presents an amplitude-modulated tone and measures EFR magnitude at the modulation rate to gauge envelope encoding.','Auditory Measurement',ARRAY['Contrast gain control','Discrete-time analytic signal','Cross-correlation lag']::text[],ARRAY['Confusing the neural EFR with an audio envelope-follower circuit.','Assuming the EFR comes from cortex; it is largely subcortical.','Ignoring how stimulus level and modulation rate change the response.']::text[],ARRAY['Objective assessment of hearing.','Research into hearing-aid and implant coding strategies.','Studies of speech-envelope encoding.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Envelope following response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1f0b1dfd-9534-4bec-8528-175b7318c8dd','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1f0b1dfd-9534-4bec-8528-175b7318c8dd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1f0b1dfd-9534-4bec-8528-175b7318c8dd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8168abf1-5d15-4da5-9aff-d4eed30d94c7','Extensible metadata scheme','An extensible metadata scheme is a metadata framework designed to be extended with new properties and vocabularies without breaking existing readers, typically using namespaces and a data model such as RDF. Adobe''s XMP, standardized as ISO 16684-1, is a common example embedded in media files.','Metadata needs vary and grow. An extensible scheme lets you add new fields later. Older software still reads what it knows. XMP is a well-known example built on a flexible data model.','It future-proofs metadata so new descriptive fields can be added without invalidating existing files or tools.','An asset engineer embeds custom rights and project fields in a file''s XMP packet alongside standard properties.','Metadata Standard',ARRAY['Descriptor scheme','Dedicated metadata channel','Encoded bitstream','Decoded audio']::text[],ARRAY['Assuming custom fields are universally understood; readers ignore unknown namespaces.','Confusing the extensible framework with a fixed, closed tag set.','Overwriting an XMP packet and losing another application''s data.']::text[],ARRAY['Digital asset management systems.','Carrying rights and production metadata across tools.','Long-term archival preservation.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Extensible metadata scheme');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8168abf1-5d15-4da5-9aff-d4eed30d94c7','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8168abf1-5d15-4da5-9aff-d4eed30d94c7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8168abf1-5d15-4da5-9aff-d4eed30d94c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3c022521-50e6-443c-a7aa-74f29bc54d34','Filter bank','A filter bank is a set of parallel bandpass filters that split a signal into multiple frequency subbands (analysis) and can later recombine them (synthesis). Critically sampled, perfect-reconstruction banks underpin subband and transform audio coders.','A filter bank splits sound into frequency bands. Each band is handled on its own. A matching bank can join them back together. Many audio codecs are built this way.','It enables per-band processing and efficient coding by separating a signal into frequency components.','An MP3 encoder uses a 32-band polyphase filter bank so quantization noise can be hidden band by band under the masking threshold.','Multirate DSP',ARRAY['Hybrid filter bank','Filter-bank equalizer','Frequency-domain audio coding','Cut-off frequency of a filter']::text[],ARRAY['Assuming any filter bank gives perfect reconstruction; it must be designed for it.','Confusing an analysis bank with a synthesis bank.','Ignoring aliasing between subbands in critically sampled banks.']::text[],ARRAY['Subband and transform audio coding.','Multiband spectral processing.','Loudspeaker crossover networks.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Filter bank');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3c022521-50e6-443c-a7aa-74f29bc54d34','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3c022521-50e6-443c-a7aa-74f29bc54d34') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3c022521-50e6-443c-a7aa-74f29bc54d34');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c25b93de-80c5-4311-987c-e80f02813208','Filter-bank equalizer','A filter-bank equalizer is an equalizer that splits the signal into subbands with an analysis filter bank, applies an independent gain to each band, and recombines them to approximate an arbitrary magnitude response. It trades band resolution and latency against the smoothness of the achievable curve.','This equalizer breaks sound into bands with a filter bank. It sets a gain for each band. Then it adds the bands back together. Using many bands gives a finer tone-shaping curve.','It realizes a desired frequency response by weighting frequency bands rather than cascading many resonant filters.','A DSP engineer implements a filter-bank equalizer so many bands can be adjusted with a modest, uniform delay.','Equalization',ARRAY['Filter bank','Cut-off frequency of a filter','Hybrid filter bank','Damping ratio of a resonator']::text[],ARRAY['Expecting arbitrarily sharp curves from only a few bands.','Ignoring the latency the analysis and synthesis stages add.','Assuming band gains do not interact at band edges.']::text[],ARRAY['Graphic equalizer design.','Multiband shaping in hearing aids.','Room-correction filtering.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Filter-bank equalizer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c25b93de-80c5-4311-987c-e80f02813208','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c25b93de-80c5-4311-987c-e80f02813208') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c25b93de-80c5-4311-987c-e80f02813208');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c59e9f46-4340-4bf6-be68-ce3a2aeb07c4','Frame loss concealment','Frame loss concealment (also packet loss concealment) is a decoder technique that synthesizes a plausible substitute when a coded audio frame is missing or corrupted, masking dropouts by extrapolating from prior frames. Methods range from silence or simple repetition to pitch-based waveform extension.','In streaming, some audio frames arrive late or not at all. Frame loss concealment fills the gap. It guesses the missing sound from what came before. This hides clicks and dropouts.','It preserves perceived audio continuity when frames are lost over unreliable networks.','A VoIP decoder uses pitch-based concealment to extend the last good frame so a single lost packet is barely audible.','Error Concealment',ARRAY['Encoded bitstream','Decoded audio','Cross-fade window','Core coder']::text[],ARRAY['Assuming simple repetition is artefact-free; it can cause a tonal buzz.','Confusing concealment with retransmission or forward error correction.','Expecting long gaps to be concealed convincingly.']::text[],ARRAY['VoIP and streaming dropouts.','Wireless audio links.','Conferencing over lossy networks.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frame loss concealment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c59e9f46-4340-4bf6-be68-ce3a2aeb07c4','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c59e9f46-4340-4bf6-be68-ce3a2aeb07c4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c59e9f46-4340-4bf6-be68-ce3a2aeb07c4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd078fcf6-bf96-4d0a-9a40-af3eba2e2df2','Frequency-domain audio coding','Frequency-domain (transform) audio coding maps blocks of samples into a spectral representation, commonly via the modified discrete cosine transform (MDCT), then quantizes the coefficients under control of a perceptual model. Most modern lossy codecs, including MP3 and AAC, are frequency-domain coders.','This coding turns short blocks of sound into a spectrum. It then keeps the important frequencies and trims the rest. A hearing model decides what can be dropped. MP3 and AAC work this way.','It compresses audio efficiently by quantizing in the frequency domain, where masking hides the quantization noise.','An AAC encoder assigns fewer bits to spectral coefficients that sit below the masking threshold, saving bitrate.','Audio Coding',ARRAY['Filter bank','Hybrid filter bank','Core coder','Huffman codebook','Encoded bitstream']::text[],ARRAY['Confusing transform coding with time-domain waveform coding such as ADPCM.','Assuming more frequency bins always sound better; block length trades time against frequency.','Ignoring pre-echo from long transforms on sharp transients.']::text[],ARRAY['MP3 and AAC encoding.','Perceptual bit allocation.','Block switching to control pre-echo on transients.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frequency-domain audio coding');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd078fcf6-bf96-4d0a-9a40-af3eba2e2df2','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d078fcf6-bf96-4d0a-9a40-af3eba2e2df2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d078fcf6-bf96-4d0a-9a40-af3eba2e2df2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3d4df463-c865-4cd2-ab0e-9fe37ce1d054','Generalized cross-correlation','Generalized cross-correlation (GCC) estimates the time delay between two signals by inverse-transforming their cross-power spectrum after applying a frequency weighting; the phase transform (PHAT) weights by 1/|cross-spectrum| to sharpen the correlation peak. The delay estimate is the lag of the maximum.','Generalized cross-correlation, or GCC, finds the delay between two microphone signals. It compares them in the frequency domain and weights the data first. A weighting called the phase transform, or PHAT, flattens the spectrum to sharpen the match. This keeps delay estimates reliable in echoey rooms.','It gives a robust time-delay estimate for source localization, especially under noise and reverberation.','A two-microphone localizer applies GCC-PHAT and reads the peak lag to estimate source direction in a reverberant room.','Time Delay Estimation',ARRAY['Cross-correlation lag','Interchannel coherence','Discrete-time analytic signal','Filter bank']::text[],ARRAY['Using plain cross-correlation in reverberation where PHAT would give a sharper peak.','Forgetting PHAT can amplify noise in low-energy frequency bands.','Reading the peak lag without accounting for the sample rate.']::text[],ARRAY['Microphone-array direction finding.','Time-difference-of-arrival localization.','Acoustic source tracking.']::text[],'advanced','R(tau) = integral psi(f) G_xy(f) e^{j 2 pi f tau} df;   PHAT: psi(f) = 1 / |G_xy(f)|','The generalized correlation is the inverse Fourier transform of a weighted cross-power spectrum; the PHAT weighting divides by the magnitude of that cross-spectrum.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Generalized cross-correlation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3d4df463-c865-4cd2-ab0e-9fe37ce1d054','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3d4df463-c865-4cd2-ab0e-9fe37ce1d054') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3d4df463-c865-4cd2-ab0e-9fe37ce1d054');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b8e03faa-0ba3-4baf-9a46-f2faee18628f','Homomorphic deconvolution','Homomorphic deconvolution separates convolved components of a signal by mapping the product of their spectra to a sum through the complex logarithm, giving the complex cepstrum where the parts can be windowed (liftered) apart. It is used to split an excitation from a filter, as in speech or echo analysis.','Some signals are one thing convolved with another, like a voice through a room. Taking a log turns that mix into a sum. In this new domain the parts separate. You can then keep one part and discard the other.','It deconvolves signals whose components multiply in the spectral domain, such as a source and a system response.','To recover a room''s impulse response from a recording, an engineer computes the complex cepstrum and lifters away the excitation portion.','Signal Analysis',ARRAY['Discrete-time analytic signal','Filter bank','Cross-correlation lag','Generalized cross-correlation']::text[],ARRAY['Ignoring phase-unwrapping problems in forming the complex cepstrum.','Confusing the real cepstrum (magnitude only) with the complex cepstrum.','Assuming clean separation when components overlap in quefrency.']::text[],ARRAY['Speech source-filter analysis.','Dereverberation and echo removal.','Pitch detection via the cepstrum.']::text[],'advanced','x_hat[n] = IDTFT{ log( DTFT{ x[n] } ) }   (complex cepstrum)','The complex cepstrum is the inverse transform of the complex logarithm of the signal''s Fourier transform, turning convolution into addition.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Homomorphic deconvolution');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b8e03faa-0ba3-4baf-9a46-f2faee18628f','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b8e03faa-0ba3-4baf-9a46-f2faee18628f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b8e03faa-0ba3-4baf-9a46-f2faee18628f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3045e50a-9bb9-4208-89de-455ad9c45861','Huffman codebook','A Huffman codebook is a table of variable-length, prefix-free binary codewords assigned so that more probable symbols receive shorter codes, giving lossless entropy compression close to the source entropy. Audio codecs such as MP3 and AAC use predefined Huffman codebooks for quantized spectral values.','Huffman coding gives common values short codes and rare values long ones. A codebook is the lookup table of these codes. No code is the start of another, so decoding is clean. MP3 and AAC use fixed codebooks for their data.','It losslessly reduces the bits needed to store quantized coefficients by exploiting their uneven probabilities.','An AAC encoder picks, per section, the Huffman codebook that spends the fewest bits on that block''s quantized spectral coefficients.','Entropy Coding',ARRAY['Encoded bitstream','Frequency-domain audio coding','Core coder','Decoded audio']::text[],ARRAY['Thinking Huffman coding is lossy; it is exactly reversible.','Assuming one codebook is optimal for all data.','Forgetting the codebooks must be known to the decoder.']::text[],ARRAY['MP3 and AAC noiseless (entropy) coding.','Selecting codebooks per spectral section.','Designing the entropy stage of a coder.']::text[],'intermediate','L_avg = sum_i p_i l_i,   with H(X) <= L_avg < H(X) + 1','Average codeword length is the sum of each symbol''s probability times its code length, and it is bounded below by the source entropy.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Huffman codebook');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3045e50a-9bb9-4208-89de-455ad9c45861','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3045e50a-9bb9-4208-89de-455ad9c45861') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3045e50a-9bb9-4208-89de-455ad9c45861');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7cdf03f2-5a2f-499b-a8f9-b04f05531319','Hybrid filter bank','A hybrid filter bank cascades two transform stages of different types to obtain resolution neither alone provides. MPEG-1 Layer III (MP3) cascades a 32-band polyphase filter bank with a per-band modified discrete cosine transform to improve frequency resolution.','One filter bank sometimes cannot give fine enough detail. A hybrid stacks two kinds in series. MP3 follows a coarse 32-band split with a finer transform. This sharpens the frequency picture.','It combines two decompositions to reach finer frequency resolution while retaining an existing bank''s structure.','An MP3 decoder inverts the MDCT stage and then the polyphase bank to reconstruct the output samples.','Audio Coding',ARRAY['Filter bank','Frequency-domain audio coding','Core coder','Filter-bank equalizer']::text[],ARRAY['Assuming the two stages are independent; their aliasing interacts and needs correction.','Confusing MP3''s hybrid bank with AAC''s single MDCT.','Ignoring the added complexity a hybrid structure carries.']::text[],ARRAY['MP3 encoding and decoding.','Analyzing legacy codec structure.','Understanding aliasing reduction in layered banks.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hybrid filter bank');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7cdf03f2-5a2f-499b-a8f9-b04f05531319','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7cdf03f2-5a2f-499b-a8f9-b04f05531319') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7cdf03f2-5a2f-499b-a8f9-b04f05531319');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '514bc7eb-85bf-4a6c-8b02-3bb6570c0ceb','Inharmonicity coefficient','The inharmonicity coefficient B quantifies how much a stiff vibrating string''s overtones stretch above exact harmonic frequencies, so the n-th partial follows f_n = n*f0*sqrt(1 + B*n^2). B increases with bending stiffness and decreases with greater length and tension.','A real piano string is stiff, not ideal. Its overtones sit a little sharp of perfect harmonics. The coefficient B says how much they stretch. Thicker, shorter strings stretch more.','It models the stretched overtone series of stiff strings, explaining stretched tuning and characteristic timbre.','With f0 = 220 Hz and B = 0.0004, the 8th partial is 220*8*sqrt(1 + 0.0004*64) = 1760*sqrt(1.0256), about 1782 Hz, roughly 22 Hz sharp of 1760 Hz.','Musical Acoustics',ARRAY['Damping ratio of a resonator','Discrete-time analytic signal','Homomorphic deconvolution']::text[],ARRAY['Assuming string overtones are exactly harmonic; stiffness stretches them sharp.','Thinking B is constant across a piano; it varies from note to note.','Confusing inharmonicity with detuning or beating between unison strings.']::text[],ARRAY['Piano tuning with stretched octaves.','Physical-modelling synthesis of struck strings.','Pitch detection of piano tones.']::text[],'advanced','f_n = n f0 sqrt(1 + B n^2)','The frequency of the n-th partial equals n times the fundamental times the square root of one plus B times n squared.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Inharmonicity coefficient');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '514bc7eb-85bf-4a6c-8b02-3bb6570c0ceb','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='514bc7eb-85bf-4a6c-8b02-3bb6570c0ceb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='514bc7eb-85bf-4a6c-8b02-3bb6570c0ceb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ba3aaae2-fc7b-464e-9844-366c5185cac5','Interchannel coherence','Interchannel coherence (ICC) measures the normalized similarity between two audio channels as a function of frequency, ranging from 1 (identical up to level and phase) to 0 (uncorrelated). In parametric spatial coding (ISO/IEC 23003-1 MPEG Surround) it is a transmitted parameter that controls perceived image width and diffuseness.','Two channels can be alike or different. Interchannel coherence measures how alike, band by band. A value of one means the same signal. A low value means they differ, which sounds wide. Codecs send this to rebuild spatial width.','It parameterizes the diffuseness and width of a stereo or surround image for efficient spatial coding and analysis.','An MPEG Surround decoder sets its decorrelator blend from the transmitted ICC so that low coherence yields a wide image.','Spatial Audio Coding',ARRAY['Decorrelation filter','Core coder','Generalized cross-correlation','Cross-correlation lag']::text[],ARRAY['Confusing coherence with a single-number correlation, ignoring its frequency dependence.','Assuming ICC of 1 means mono; it means identical up to level and phase per band.','Treating ICC as a level parameter rather than a similarity measure.']::text[],ARRAY['MPEG Surround and parametric-stereo decoding.','Controlling upmix image width.','Analyzing stereo image width.']::text[],'advanced','ICC = |Phi_12(f)| / sqrt( Phi_11(f) Phi_22(f) )','Interchannel coherence is the magnitude of the cross-power spectrum divided by the square root of the product of the two auto-power spectra.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Interchannel coherence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ba3aaae2-fc7b-464e-9844-366c5185cac5','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ba3aaae2-fc7b-464e-9844-366c5185cac5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ba3aaae2-fc7b-464e-9844-366c5185cac5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e21d4f3b-0adf-458f-8369-77972067c26e','Joint stereo coding','A stereo bit-saving technique in perceptual audio coders that exploits redundancy and inaudible detail shared between channels, chiefly through mid/side (sum-difference) coding and intensity (channel-coupling) coding, instead of coding left and right independently. It is standardized in the MPEG audio family (ISO/IEC 11172-3 and ISO/IEC 14496-3).','Stereo music often sounds similar in both channels. Joint stereo coding shares that common part instead of storing it twice. It can send a sum signal and a difference signal. This saves data at low bit rates.','To lower the stereo bit rate by removing redundancy and inaudible detail that the two channels share.','Streaming stereo AAC at 96 kbit/s, an engineer enables joint stereo so correlated passages use mid/side coding; for L=1.0 and R=0.6, mid=(1.0+0.6)/√2≈1.131 and side=(1.0−0.6)/√2≈0.283.','Stereo Coding',ARRAY['Perceptual audio coding','Parametric stereo','Sub-band coding','Scale-factor band','Multichannel audio coding']::text[],ARRAY['Assuming joint stereo always means intensity coding; mid/side is a distinct mode.','Believing joint stereo always harms quality; at moderate rates it usually helps.','Confusing mid/side matrixing with Dolby-style matrix surround encoding.']::text[],ARRAY['Choosing encoder settings for a low-bit-rate stereo podcast.','Diagnosing a collapsed stereo image from aggressive intensity coding.','Explaining why a near-mono passage codes more efficiently.']::text[],'intermediate','M = (L + R)/√2 ;  S = (L − R)/√2','The mid signal is the sum of left and right divided by the square root of two; the side signal is their difference divided by the square root of two.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Joint stereo coding');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e21d4f3b-0adf-458f-8369-77972067c26e','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e21d4f3b-0adf-458f-8369-77972067c26e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e21d4f3b-0adf-458f-8369-77972067c26e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5c0dca52-0e13-4166-9315-714fb3d243cc','Linear-phase filter','A filter whose phase response varies linearly with frequency, giving a constant group delay so every frequency component is delayed equally and waveform shape is preserved. Symmetric finite-impulse-response (FIR) filters are the standard way to obtain exact linear phase.','A filter can delay some frequencies more than others. That smears the shape of a signal. A linear-phase filter delays every frequency by the same time. So the waveform keeps its shape.','To filter a signal without phase distortion, preserving transient shape and the relative timing of frequency components.','A mastering engineer picks a linear-phase equalizer to avoid smearing drum transients; a symmetric 101-tap FIR has a constant group delay of (N−1)/2 = (101−1)/2 = 50 samples.','Digital Filtering',ARRAY['Windowing function','Pre-echo','Sub-band coding','Waveform coding']::text[],ARRAY['Thinking linear phase means zero delay; it means constant delay.','Assuming every FIR is linear phase; only symmetric or antisymmetric coefficients guarantee it.','Ignoring the pre-ringing a linear-phase filter can add before transients.']::text[],ARRAY['Choosing a mastering EQ that must not shift phase.','Designing a loudspeaker crossover.','Explaining a pre-ring artifact before a transient.']::text[],'intermediate','φ(ω) = −α·ω ;  τ_g = −dφ/dω = (N − 1)/2','Phase equals minus a constant times angular frequency; the group delay equals half of one less than the filter length, measured in samples.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Linear-phase filter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5c0dca52-0e13-4166-9315-714fb3d243cc','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5c0dca52-0e13-4166-9315-714fb3d243cc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5c0dca52-0e13-4166-9315-714fb3d243cc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '76b0ed42-6854-45f9-9a3f-ee09b5abf466','Long-term average spectrum','The average magnitude or power spectrum of a signal computed over a long duration, typically many seconds of running speech, which smooths moment-to-moment variation to reveal overall spectral balance. It is widely used in voice and speech acoustics.','A single sound frame changes very fast. Averaging many frames over a long time gives a stable picture. This average shows the overall tone of a voice. Researchers use it to compare voices.','To characterize the stable, global spectral distribution of a talker or source, independent of individual speech sounds.','A voice clinician records 30 seconds of connected speech and computes the long-term average spectrum to compare a client''s spectral balance before and after therapy.','Spectral Analysis',ARRAY['Spectral flatness measure','Windowing function','Source-filter model','Mean opinion score']::text[],ARRAY['Computing over too short a sample, so the average stays unstable.','Confusing the long-term average with a single short-time spectrum.','Ignoring microphone and room effects that bias the long-term spectrum.']::text[],ARRAY['Assessing voice quality before and after therapy.','Comparing speakers in forensic phonetics.','Characterizing a singer''s spectral balance.']::text[],'intermediate','S̄(f) = (1/M) Σ_{m=1}^{M} |X_m(f)|²','The long-term spectrum at each frequency is the mean of the squared magnitudes of many short-time spectra taken across the recording.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Long-term average spectrum');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '76b0ed42-6854-45f9-9a3f-ee09b5abf466','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='76b0ed42-6854-45f9-9a3f-ee09b5abf466') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='76b0ed42-6854-45f9-9a3f-ee09b5abf466');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5dfed7cb-1783-499b-89a0-f1c8aceb1d05','Lossless coding mode','A coding mode that reconstructs the original audio samples bit-exactly, with no loss, usually by entropy-coding a decorrelated (predicted) residual. Standardized examples include MPEG-4 Audio Lossless Coding (ALS) in ISO/IEC 14496-3 and open formats such as FLAC.','Some coders remove detail you cannot hear. A lossless mode removes nothing at all. It rebuilds the exact original samples. Files get smaller yet stay perfect.','To compress audio for archiving or distribution while guaranteeing the decoded signal equals the original.','An archivist stores masters in FLAC or MPEG-4 ALS to shrink files by roughly 40–60% while keeping a bit-exact copy for future remastering.','Lossless Coding',ARRAY['Waveform coding','Predictive coding gain','Variable bit-rate coding','Scalable audio coding']::text[],ARRAY['Calling high-bit-rate lossy files ''lossless''.','Assuming lossless always halves size; the ratio depends on the material.','Thinking lossless improves the sound; it only preserves it.']::text[],ARRAY['Archiving studio masters.','Distributing high-resolution downloads.','Verifying a bit-exact file transfer.']::text[],'beginner',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lossless coding mode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5dfed7cb-1783-499b-89a0-f1c8aceb1d05','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5dfed7cb-1783-499b-89a0-f1c8aceb1d05') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5dfed7cb-1783-499b-89a0-f1c8aceb1d05');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2cee2c57-17f2-4496-9571-47d502ad2a25','Matrix decoding','A playback process that recovers extra channels from a smaller number of transmitted channels by combining them with fixed or adaptive amplitude-and-phase relationships, as in 4-2-4 matrix surround. Dolby Surround/Pro Logic decoding is a well-known example; Dolby is a trademark of Dolby Laboratories.','Some systems fold extra channels into just two. A matrix decoder unfolds them again. It uses set mixing rules and phase to steer sound. Dolby Surround works this way.','To deliver surround playback over two-channel media by encoding the extra channels in a recoverable matrix.','A technician feeds a Dolby-Surround-encoded stereo mix to a Pro Logic decoder, which derives centre and surround feeds from the sum and difference of left and right.','Surround Systems',ARRAY['Multichannel audio coding','Parametric stereo','Joint stereo coding','Metadata delivery unit']::text[],ARRAY['Confusing matrix surround with discrete multichannel formats.','Assuming matrix decoding separates channels perfectly; crosstalk remains.','Mixing up mid/side stereo matrixing with 4-2-4 surround matrixing.']::text[],ARRAY['Decoding a legacy Dolby Surround soundtrack.','Selecting a receiver''s matrix upmix mode.','Explaining phantom-centre steering.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Matrix decoding');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2cee2c57-17f2-4496-9571-47d502ad2a25','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2cee2c57-17f2-4496-9571-47d502ad2a25') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2cee2c57-17f2-4496-9571-47d502ad2a25');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'da593a3f-ee36-42b9-80c8-5f3ef5e194e4','Mean opinion score','A subjective quality rating obtained by averaging listeners'' category judgments of processed audio or speech, typically on a five-point absolute-category-rating scale from 1 (bad) to 5 (excellent). It is defined in ITU-T Recommendations P.800 and P.800.1.','You cannot fully judge quality with meters alone. So people rate samples from bad to excellent. Those scores are averaged into one number. That average is the mean opinion score.','To quantify perceived audio or speech quality with a standardized, repeatable listening test.','In a P.800 test, five listeners rate a clip 4, 5, 4, 3, 5; the mean opinion score is (4+5+4+3+5)/5 = 4.2.','Quality Assessment',ARRAY['Perceptual audio coding','Wideband speech coding','Waveform coding','Long-term average spectrum']::text[],ARRAY['Comparing scores from tests with different conditions or listeners.','Treating the score as an absolute physical measure rather than a relative subjective one.','Reporting a score without confidence intervals or listener count.']::text[],ARRAY['Comparing two codecs at 64 kbit/s.','Validating a network''s voice quality.','Setting a codec acceptance threshold.']::text[],'beginner','MOS = (1/N) Σ_{i=1}^{N} r_i','The mean opinion score is the sum of all listener ratings divided by the number of ratings.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mean opinion score');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'da593a3f-ee36-42b9-80c8-5f3ef5e194e4','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='da593a3f-ee36-42b9-80c8-5f3ef5e194e4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='da593a3f-ee36-42b9-80c8-5f3ef5e194e4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0d67b54f-f781-45ba-9dce-25163b7de0d3','Mel-frequency cepstral coefficient','A compact feature describing the short-term spectral envelope of audio, formed by mapping the power spectrum onto the perceptual mel frequency scale, taking logarithms, and applying a discrete cosine transform. MFCCs are a standard front-end feature in speech and audio recognition.','Machines need a small, useful summary of sound. These features bend the frequency axis to match hearing. They then compress the shape of the spectrum. Speech recognizers use these numbers as input.','To give recognizers a low-dimensional, perceptually motivated description of spectral shape.','A developer extracts 13 coefficients per 25 ms frame for a keyword spotter; mapping 1000 Hz gives mel = 2595·log10(1 + 1000/700) ≈ 1000 mel.','Audio Features',ARRAY['Source-filter model','Windowing function','Spectral flatness measure','Long-term average spectrum']::text[],ARRAY['Using too many coefficients and capturing pitch instead of envelope.','Skipping the analysis window before the transform.','Assuming the coefficients are noise-robust without extra processing.']::text[],ARRAY['Building a speech-recognizer front-end.','Speaker identification.','Music genre classification.']::text[],'advanced','m = 2595·log10(1 + f/700)','The mel value equals 2595 times the base-ten logarithm of one plus the frequency in hertz divided by 700.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mel-frequency cepstral coefficient');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0d67b54f-f781-45ba-9dce-25163b7de0d3','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0d67b54f-f781-45ba-9dce-25163b7de0d3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0d67b54f-f781-45ba-9dce-25163b7de0d3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd03d0a92-941f-409f-aa9f-ea855c139019','Multichannel audio coding','Compression of three or more audio channels (for example 5.1) that exploits inter-channel redundancy and shared psychoacoustic irrelevancy to lower total bit rate versus coding each channel alone. Standards include Dolby Digital (AC-3), MPEG-2/4 AAC (ISO/IEC 13818-7, 14496-3) and MPEG Surround (ISO/IEC 23003-1).','Surround sound uses many channels. Coding each one alone wastes data. Multichannel coders share what channels have in common. This fits surround into a small stream.','To deliver surround audio efficiently for broadcast, streaming, and physical media.','An engineer encodes a 5.1 film mix to Dolby Digital at 448 kbit/s, letting the coder couple high frequencies across channels to save bits.','Multichannel Coding',ARRAY['Joint stereo coding','Parametric stereo','Matrix decoding','Scalable audio coding']::text[],ARRAY['Assuming 5.1 needs six times the stereo bit rate.','Confusing discrete multichannel coding with matrix surround.','Overlooking the LFE channel''s limited bandwidth.']::text[],ARRAY['Authoring a surround broadcast stream.','Choosing a surround bit rate.','Diagnosing channel-coupling artifacts.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Multichannel audio coding');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd03d0a92-941f-409f-aa9f-ea855c139019','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d03d0a92-941f-409f-aa9f-ea855c139019') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d03d0a92-941f-409f-aa9f-ea855c139019');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd6fbd214-570d-4dc4-8f24-40cb2d4322ff','Oversampling ratio','The factor by which a converter''s sampling rate exceeds the Nyquist rate of the signal band, equal to the sampling frequency divided by twice the signal bandwidth. High ratios ease anti-alias filtering and, with noise shaping, spread quantization noise over a wider band.','Sampling just fast enough is hard to filter. So converters sample much faster than needed. The oversampling ratio says how much faster. Higher ratios make filtering and noise easier to manage.','To relax anti-alias and reconstruction filters and, with noise shaping, improve in-band signal-to-noise ratio.','For a 24 kHz audio band sampled at 3.072 MHz, the oversampling ratio is f_s/(2·f_B) = 3.072×10⁶ / (2×24000) = 64.','Conversion',ARRAY['Sub-band coding','Waveform coding','Windowing function','Linear-phase filter']::text[],ARRAY['Confusing the sampling rate with the oversampling ratio.','Assuming oversampling alone adds resolution without noise shaping.','Using signal bandwidth and Nyquist rate interchangeably in the formula.']::text[],ARRAY['Specifying a delta-sigma converter.','Explaining DSD sampling rates.','Setting a converter''s digital filter.']::text[],'intermediate','OSR = f_s / (2·f_B)','The oversampling ratio equals the sampling frequency divided by twice the highest signal frequency.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Oversampling ratio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd6fbd214-570d-4dc4-8f24-40cb2d4322ff','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d6fbd214-570d-4dc4-8f24-40cb2d4322ff') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d6fbd214-570d-4dc4-8f24-40cb2d4322ff');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9bc241c3-45df-4cb7-9184-3317c8defcf1','Parametric stereo','A low-bit-rate technique that transmits a mono downmix plus a small set of spatial parameters—inter-channel level, phase or time, and coherence cues—from which the stereo image is reconstructed at the decoder. It is standardized as part of HE-AAC v2 in ISO/IEC 14496-3.','Full stereo needs two coded channels. Parametric stereo sends one channel plus clues. The clues describe how the two sides differ. The decoder rebuilds stereo from them.','To preserve a convincing stereo image at very low bit rates.','A broadcaster streams HE-AAC v2 at 24 kbit/s, sending mono AAC plus parametric-stereo cues so listeners still hear a stereo image.','Stereo Coding',ARRAY['Joint stereo coding','Perceptual audio coding','Multichannel audio coding','Scalable audio coding']::text[],ARRAY['Confusing parametric stereo with mid/side joint stereo.','Expecting full spatial accuracy at very low rates.','Assuming it handles hard-panned or uncorrelated channels well.']::text[],ARRAY['Low-bit-rate mobile streaming.','Digital radio broadcasting.','Conserving bandwidth on constrained links.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Parametric stereo');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9bc241c3-45df-4cb7-9184-3317c8defcf1','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9bc241c3-45df-4cb7-9184-3317c8defcf1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9bc241c3-45df-4cb7-9184-3317c8defcf1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '635369b3-f0da-406f-9deb-2dc423f9f47f','Perceptual audio coding','Lossy compression that discards spectral detail judged inaudible using a psychoacoustic model of masking and hearing thresholds, allocating bits where the ear is most sensitive. It underlies MP3, AAC and most modern lossy formats (ISO/IEC 11172-3, 13818-7, 14496-3).','The ear cannot hear every detail. Loud sounds hide nearby quiet ones. Perceptual coders drop what listeners will not notice. This shrinks files with little audible loss.','To achieve large compression with minimal perceived quality loss by matching bit use to hearing.','Encoding music to 128 kbit/s AAC, the psychoacoustic model raises the noise floor under strong tones, where masking hides the added quantization noise.','Perceptual Coding',ARRAY['Sub-band coding','Scale-factor band','Pre-echo','Joint stereo coding','Spectral flatness measure']::text[],ARRAY['Thinking perceptual coding is lossless.','Assuming higher bit rate always sounds better past transparency.','Ignoring cumulative damage from repeated re-encoding.']::text[],ARRAY['Choosing a streaming bit rate.','Explaining masking to a client.','Diagnosing artifacts after re-encoding.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Perceptual audio coding');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '635369b3-f0da-406f-9deb-2dc423f9f47f','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='635369b3-f0da-406f-9deb-2dc423f9f47f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='635369b3-f0da-406f-9deb-2dc423f9f47f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '28f086b3-6e70-4f68-b772-b63e2cfbe9b6','Perceptual weighting filter','In analysis-by-synthesis speech coders such as CELP, a filter that shapes the coding-error spectrum to concentrate it beneath the formant peaks, where the speech itself masks it, improving perceived quality at a given bit rate. It is derived from the linear-prediction filter, typically W(z)=A(z/γ1)/A(z/γ2).','Coders make errors when they compress speech. Some error is easier to hear than other error. This filter hides the error under strong speech peaks. That makes low-bit-rate speech sound cleaner.','To move quantization noise into frequency regions where the speech signal masks it.','In a CELP coder like ITU-T G.729, the weighting filter uses factors near γ1=0.94 and γ2=0.6 to bury coding error beneath the formants.','Speech Coding',ARRAY['Source-filter model','Wideband speech coding','Predictive coding gain','Waveform coding']::text[],ARRAY['Confusing the weighting filter with the synthesis filter.','Assuming one fixed set of factors suits all speech.','Forgetting that it shapes error, not the output speech.']::text[],ARRAY['Tuning a CELP speech codec.','Explaining noise masking in speech coding.','Comparing weighting-factor settings.']::text[],'advanced','W(z) = A(z/γ1) / A(z/γ2)','The weighting filter is the prediction polynomial with its coefficients scaled by gamma-one, divided by the same polynomial scaled by gamma-two.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Perceptual weighting filter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '28f086b3-6e70-4f68-b772-b63e2cfbe9b6','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='28f086b3-6e70-4f68-b772-b63e2cfbe9b6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='28f086b3-6e70-4f68-b772-b63e2cfbe9b6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2cb68c9b-41af-417b-8ef7-806bfbe1f27a','Pre-echo','A transform-coding artifact in which quantization noise from a coding block spreads backward in time ahead of a sharp transient, becoming audible in the quiet interval before an attack. Coders suppress it with adaptive block switching to shorter analysis windows around transients.','Transform coders work on blocks of sound. A sudden hit adds error across its whole block. Some error lands before the hit, in the near-silence. That faint smear before a sound is a pre-echo.','It names a key failure mode that window switching and temporal noise shaping are designed to prevent.','An encoder detects a castanet transient and switches from long to short MDCT windows, confining quantization noise near the attack to avoid an audible pre-echo.','Coding Artifacts',ARRAY['Windowing function','Sub-band coding','Perceptual audio coding','Scale-factor band','Linear-phase filter']::text[],ARRAY['Confusing pre-echo with an acoustic echo in the room.','Assuming only low bit rates cause it.','Overlooking that linear-phase filters can pre-ring similarly.']::text[],ARRAY['Hearing a smear before a snare hit.','Explaining block switching in an encoder.','Choosing a codec for percussive material.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pre-echo');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2cb68c9b-41af-417b-8ef7-806bfbe1f27a','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2cb68c9b-41af-417b-8ef7-806bfbe1f27a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2cb68c9b-41af-417b-8ef7-806bfbe1f27a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5158570c-d01b-4cc5-9021-142b5cad8daa','Predictive coding gain','The reduction in signal variance achieved by coding a prediction residual instead of the original samples, expressed as the ratio of input variance to residual variance, often in decibels. A higher prediction gain means more redundancy was removed, allowing fewer bits per sample.','Nearby audio samples are similar. A predictor guesses the next sample from past ones. Coding only the small guess error needs fewer bits. Prediction gain measures how much this helps.','To quantify how effectively linear prediction removes sample-to-sample redundancy.','If the input variance is 1.0 and the residual variance is 0.01, the prediction gain is 10·log10(1.0/0.01) = 20 dB.','Predictive Coding',ARRAY['Waveform coding','Lossless coding mode','Source-filter model','Sub-band coding']::text[],ARRAY['Confusing prediction gain with overall compression ratio.','Assuming gain keeps rising with predictor order indefinitely.','Ignoring that gain depends on the signal''s own correlation.']::text[],ARRAY['Designing an ADPCM coder.','Comparing predictor orders.','Explaining why speech predicts well.']::text[],'advanced','G_p = σ_x² / σ_e²   (dB: 10·log10(σ_x²/σ_e²))','Prediction gain is the input-signal variance divided by the prediction-error variance; in decibels take ten times its base-ten logarithm.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Predictive coding gain');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5158570c-d01b-4cc5-9021-142b5cad8daa','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5158570c-d01b-4cc5-9021-142b5cad8daa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5158570c-d01b-4cc5-9021-142b5cad8daa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '28073d06-bd28-41a8-82b7-4a0b05042c5a','Scalable audio coding','A coding structure that produces a layered bitstream from which lower-rate or lower-quality versions can be decoded by discarding enhancement layers, without re-encoding. MPEG-4 Audio defines scalable profiles supporting bit-rate, bandwidth, and complexity scalability (ISO/IEC 14496-3).','One file can serve many needs. A scalable stream has a base layer plus extras. Drop the extras for a smaller, lower-quality version. Keep them for full quality.','To serve varying bandwidths and devices from a single encoded stream.','A server sends only the base layer to a slow connection, then adds enhancement layers as bandwidth allows, all without re-encoding.','Scalable Coding',ARRAY['Multichannel audio coding','Variable bit-rate coding','Perceptual audio coding','Lossless coding mode']::text[],ARRAY['Confusing scalable coding with simple multi-rate transcoding.','Assuming scalability adds no overhead.','Thinking every codec supports layer dropping.']::text[],ARRAY['Adaptive streaming.','Serving mixed device classes.','Graceful degradation on poor links.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Scalable audio coding');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '28073d06-bd28-41a8-82b7-4a0b05042c5a','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='28073d06-bd28-41a8-82b7-4a0b05042c5a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='28073d06-bd28-41a8-82b7-4a0b05042c5a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1b099014-0c25-4d8f-a423-5313a8cec990','Scale-factor band','In AAC and related transform coders, a group of adjacent spectral coefficients that share a single quantization scale factor, with band widths chosen to approximate the ear''s critical bands. Scale factors let the coder control quantization noise per band so it stays masked.','The coder splits the spectrum into bands. Each band gets one scale value. That value sets how finely the band is quantized. The bands roughly follow how the ear groups frequencies.','To set quantization step size per critical-band-like region so noise stays masked.','An AAC encoder raises the scale factor in a band beneath a strong tone, coarsening its quantization because masking hides the added noise there.','Perceptual Coding',ARRAY['Perceptual audio coding','Sub-band coding','Pre-echo','Joint stereo coding']::text[],ARRAY['Confusing scale-factor bands with filterbank sub-bands.','Assuming all bands have equal width.','Thinking a scale factor sets loudness rather than quantization step.']::text[],ARRAY['Analyzing an AAC bitstream.','Explaining critical-band bit allocation.','Debugging band-limited artifacts.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Scale-factor band');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1b099014-0c25-4d8f-a423-5313a8cec990','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1b099014-0c25-4d8f-a423-5313a8cec990') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1b099014-0c25-4d8f-a423-5313a8cec990');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eaff033e-6ffb-46c0-9f3b-94ff08991688','Single-equivalent-level descriptor','A single-number descriptor that represents a time-varying sound by the constant level having the same total energy over the measurement interval—the equivalent continuous sound level, L_eq. It is standardized for sound level meters in IEC 61672-1 and for environmental noise in ISO 1996-1.','Real noise goes up and down over time. It helps to sum it into one number. That number is the steady level with the same energy. Engineers call it the equivalent level.','To summarize fluctuating noise energy as one steady-equivalent level for assessment and limits.','If a sound is 80 dB for half the time and 90 dB for half, L_eq = 10·log10(0.5·10⁸ + 0.5·10⁹) ≈ 87.4 dB.','Acoustic Metrics',ARRAY['Long-term average spectrum','Mean opinion score','Spectral flatness measure']::text[],ARRAY['UNSAFE: Treating a low equivalent level as safe while ignoring brief high peaks that can still damage hearing.','Averaging decibel values arithmetically instead of by energy.','Omitting the time interval, which changes the value.']::text[],ARRAY['Measuring workplace noise exposure.','Assessing an environmental noise limit.','Logging concert sound dose.']::text[],'intermediate','L_eq,T = 10·log10[ (1/T) ∫_0^T p²(t)/p_0² dt ]','The equivalent level equals ten times the log of the time-averaged squared sound pressure divided by the reference pressure squared.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Single-equivalent-level descriptor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eaff033e-6ffb-46c0-9f3b-94ff08991688','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eaff033e-6ffb-46c0-9f3b-94ff08991688') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eaff033e-6ffb-46c0-9f3b-94ff08991688');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1ae9fda0-87df-4e8a-9bf3-78a71ebd39cf','Source-filter model','A model of speech, and some instrument sounds, in which an excitation source—vocal-fold vibration or turbulent noise—passes through a linear filter representing the vocal-tract resonances (formants). It underpins linear-prediction analysis and most speech coders and synthesizers.','Speech has two parts working together. A source makes a raw buzz or hiss. The vocal tract shapes it like a filter. Together they make vowels and consonants.','To separate excitation from resonance so each can be analyzed, coded, or synthesized independently.','A speech coder uses linear prediction to estimate the vocal-tract filter, then codes the source and filter separately for efficient transmission.','Speech Modeling',ARRAY['Perceptual weighting filter','Predictive coding gain','Wideband speech coding','Mel-frequency cepstral coefficient']::text[],ARRAY['Assuming source and filter never interact; some coupling exists.','Treating the model as exact for every sound.','Confusing the source spectrum with the output spectrum.']::text[],ARRAY['Linear-prediction analysis of speech.','Building a vocoder.','Explaining formants to students.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Source-filter model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1ae9fda0-87df-4e8a-9bf3-78a71ebd39cf','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1ae9fda0-87df-4e8a-9bf3-78a71ebd39cf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1ae9fda0-87df-4e8a-9bf3-78a71ebd39cf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e10857df-a8ca-4851-802f-af36270d4b4f','Sparse coding of audio','Representing an audio signal as a weighted sum of only a few elements (atoms) drawn from an overcomplete dictionary, so most coefficients are zero. Sparse representations support efficient coding, denoising, and source separation.','A signal can be built from many building blocks. Sparse coding uses only a few at a time. Most blocks stay unused. This gives a compact, useful description.','To capture signal structure compactly using few active components chosen from a rich dictionary.','A researcher decomposes a recording over a learned dictionary, keeping only the strongest atoms per frame to separate a melody from background noise.','Signal Representation',ARRAY['Waveform coding','Sub-band coding','Spectral flatness measure','Windowing function']::text[],ARRAY['Confusing sparse coding with ordinary transform coding.','Assuming any dictionary yields sparsity.','Ignoring the cost of finding the sparse solution.']::text[],ARRAY['Audio source separation.','Denoising a recording.','Compressed sensing of audio.']::text[],'advanced',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sparse coding of audio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e10857df-a8ca-4851-802f-af36270d4b4f','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e10857df-a8ca-4851-802f-af36270d4b4f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e10857df-a8ca-4851-802f-af36270d4b4f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '05e9d177-143c-4880-a2d8-a7309ed6cc14','Spectral flatness measure','A scalar describing how noise-like versus tone-like a spectrum is, computed as the ratio of the geometric mean to the arithmetic mean of the power spectrum. Values near 1 indicate a flat, noise-like spectrum; values near 0 indicate a peaky, tonal one.','Some sounds are pure tones. Others are broad noise. This measure scores where a sound sits between them. A high value means noise-like; a low value means tonal.','To quantify tonality, useful in psychoacoustic models and in noise or voicing detection.','For power bins [4, 1, 1, 1], the geometric mean is 4^0.25 = 1.414 and the arithmetic mean is 1.75, so the flatness is 1.414/1.75 ≈ 0.81.','Spectral Analysis',ARRAY['Perceptual audio coding','Long-term average spectrum','Sub-band coding','Mel-frequency cepstral coefficient']::text[],ARRAY['Confusing spectral flatness with a flat frequency response.','Applying it to magnitude instead of power without noting the difference.','Forgetting that any zero bin drives the geometric mean to zero.']::text[],ARRAY['Estimating tonality inside a codec.','Making a voiced/unvoiced speech decision.','Keying a noise gate.']::text[],'advanced','SFM = exp( (1/N) Σ ln P_k ) / ( (1/N) Σ P_k )','Spectral flatness is the geometric mean of the power-spectrum bins divided by their arithmetic mean.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral flatness measure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '05e9d177-143c-4880-a2d8-a7309ed6cc14','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='05e9d177-143c-4880-a2d8-a7309ed6cc14') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='05e9d177-143c-4880-a2d8-a7309ed6cc14');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dfdab08b-f182-4930-bab7-f0903ac942d2','Sub-band coding','A coding method that splits the signal into contiguous frequency bands with a filterbank, then quantizes and codes each band separately, allocating bits and step sizes per band. It is central to MPEG-1 Audio Layers I and II (ISO/IEC 11172-3).','The coder divides sound into frequency bands. Each band is coded on its own. Bits go where they matter most. This matches how we hear across frequency.','To allocate bits per frequency region and exploit per-band masking.','An MPEG Layer II encoder splits audio into 32 sub-bands and gives more bits to bands with strong audible content and fewer to masked bands.','Filterbank Coding',ARRAY['Perceptual audio coding','Scale-factor band','Waveform coding','Pre-echo']::text[],ARRAY['Confusing sub-bands with scale-factor bands.','Assuming equal bits for every band.','Ignoring filterbank aliasing that reconstruction must cancel.']::text[],ARRAY['Encoding to MPEG Layer II.','Explaining filterbanks.','Doing per-band bit allocation.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sub-band coding');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dfdab08b-f182-4930-bab7-f0903ac942d2','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dfdab08b-f182-4930-bab7-f0903ac942d2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dfdab08b-f182-4930-bab7-f0903ac942d2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '38fc32b8-216f-41c7-b48b-22db1dc8f940','Variable bit-rate coding','A coding mode in which the number of bits per unit time varies with signal complexity, spending more on demanding passages and fewer on simple ones to hold quality roughly constant. It contrasts with constant-bit-rate coding.','Some parts of music are simple. Others are busy and complex. Variable bit-rate coding spends bits where needed. Quality stays steadier and average size drops.','To keep perceived quality more constant and improve average efficiency versus a constant bit rate.','An engineer encodes an album in variable-bit-rate AAC at a quality target, so quiet solo passages use fewer bits and dense mixes use more.','Rate Control',ARRAY['Perceptual audio coding','Scalable audio coding','Lossless coding mode','Multichannel audio coding']::text[],ARRAY['Assuming variable-bit-rate files have a fixed, predictable size.','Thinking it always beats a high constant rate audibly.','Confusing variable bit rate with variable sample rate.']::text[],ARRAY['Encoding a music library.','Meeting a quality target.','Streaming under a bit-rate cap.']::text[],'beginner',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Variable bit-rate coding');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '38fc32b8-216f-41c7-b48b-22db1dc8f940','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='38fc32b8-216f-41c7-b48b-22db1dc8f940') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='38fc32b8-216f-41c7-b48b-22db1dc8f940');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e3577ee5-9fe2-44de-a4c5-2ce18c04dd9d','Waveform coding','A class of coders that aim to reproduce the original signal waveform sample by sample, minimizing a numerical error such as mean-squared error, rather than modeling how the sound was produced. Examples include PCM, DPCM and ADPCM.','Some coders copy the sound''s shape directly. They try to match each sample closely. They do not model how the sound was made. PCM and ADPCM work this way.','To code general signals faithfully by tracking the waveform, independent of source type.','A technician uses ADPCM, a waveform coder, to roughly halve PCM data while keeping the decoded waveform close to the original.','Waveform Coding',ARRAY['Predictive coding gain','Sub-band coding','Lossless coding mode','Perceptual audio coding']::text[],ARRAY['Confusing waveform coders with parametric or source-model coders.','Assuming waveform coding is always lossless.','Thinking low numerical error always means high perceived quality.']::text[],ARRAY['Choosing PCM versus ADPCM.','Explaining coder families.','Legacy telephony coding.']::text[],'beginner',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Waveform coding');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e3577ee5-9fe2-44de-a4c5-2ce18c04dd9d','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e3577ee5-9fe2-44de-a4c5-2ce18c04dd9d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e3577ee5-9fe2-44de-a4c5-2ce18c04dd9d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2ca9775a-c785-414b-b8c5-28122751d176','Wideband speech coding','Speech coding that spans roughly 50 Hz to 7000 Hz, wider than the traditional 300–3400 Hz telephone band, giving more natural and intelligible speech. ITU-T G.722 (sub-band ADPCM) and G.722.2/AMR-WB (ACELP) are standard examples.','Old phone speech was narrow and dull. Wideband speech adds low and high tones. It covers about 50 to 7000 hertz. Voices sound clearer and more natural.','To improve speech naturalness and intelligibility beyond narrowband telephony.','A VoIP system negotiates G.722 wideband so callers hear 50–7000 Hz speech at 64 kbit/s instead of the old 3.4 kHz band.','Speech Coding',ARRAY['Source-filter model','Perceptual weighting filter','Waveform coding','Mean opinion score']::text[],ARRAY['Calling wideband speech ''HD'' as if it were full-range music.','Assuming both endpoints support it without negotiation.','Confusing G.722 with G.722.2; they are different coders.']::text[],ARRAY['HD voice telephone calls.','Conferencing systems.','Comparing narrowband and wideband quality scores.']::text[],'intermediate',NULL,NULL,'89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wideband speech coding');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2ca9775a-c785-414b-b8c5-28122751d176','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2ca9775a-c785-414b-b8c5-28122751d176') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2ca9775a-c785-414b-b8c5-28122751d176');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '68d97a90-b9f3-4bfc-81ab-6d81a43e24ad','Windowing function','A tapering weight applied to a finite block of samples before spectral analysis or within a filterbank, reducing spectral leakage caused by abrupt block edges at the cost of a wider main lobe. Common windows include Hann, Hamming, and Blackman.','We analyze sound in short blocks. Sharp block edges add false spectral energy. A window fades the edges smoothly. This cuts leakage but slightly blurs frequency detail.','To trade spectral leakage against frequency resolution when analyzing finite blocks.','Applying a Hann window before an FFT, w(n) = 0.5[1 − cos(2πn/(N−1))]; for N=1024 the endpoints weight 0 and the centre weights 1.','Spectral Analysis',ARRAY['Pre-echo','Long-term average spectrum','Sub-band coding','Linear-phase filter','Spectral flatness measure']::text[],ARRAY['Forgetting to compensate window gain in level measurements.','Assuming more tapering is always better; it widens the main lobe.','Using a rectangular window and blaming the FFT for leakage.']::text[],ARRAY['Setting an analyzer''s window type.','Designing an MDCT window.','Measuring a tone close to noise.']::text[],'intermediate','w(n) = 0.5·[1 − cos(2πn/(N − 1))]   (Hann)','The Hann window weight at sample n is one half times one minus the cosine of two pi n divided by one less than the window length.','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Windowing function');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '68d97a90-b9f3-4bfc-81ab-6d81a43e24ad','89abe24e-a92c-4041-a9dd-4ea4a1e3c6a6',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='68d97a90-b9f3-4bfc-81ab-6d81a43e24ad') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='68d97a90-b9f3-4bfc-81ab-6d81a43e24ad');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bfa620d1-5f35-4bcf-9472-37f584891230','Absolute-polarity inversion','Absolute polarity describes whether a positive-going pressure created at the sound source is reproduced as a positive-going pressure at the listener, preserving the sign of the waveform through the whole signal chain. Absolute-polarity inversion is the condition in which this end-to-end sign is reversed, so a compression at the source arrives as a rarefaction at the loudspeaker while the relative timing between channels stays intact.','Every sound begins as a push or a pull of air. Absolute polarity asks whether a push stays a push all the way to the speaker. Inversion flips the whole signal, so pushes become pulls. Both channels flip together, so stereo imaging still lines up.','It lets engineers track whether a full chain keeps or reverses the waveform''s sign, which can subtly affect timbre on asymmetrical waveforms and low-frequency transients.','A technician flips a console or DAW polarity switch to test absolute polarity, listening for a firmer kick-drum attack when the correct sign is restored.','Signal polarity',ARRAY['Polarity','Phase','Relative polarity','Waveform','Pin 2 hot']::text[],ARRAY['Confusing absolute polarity with phase; phase is a frequency-dependent shift, polarity is a whole-signal sign flip.','Assuming polarity inversion is always clearly audible; the effect is often subtle and program-dependent.','Mixing up absolute polarity (whole chain) with relative polarity (one channel versus another).']::text[],ARRAY['Checking that a microphone-to-monitor chain preserves waveform sign.','Diagnosing weak bass when one signal path is inverted.','Setting the polarity button when re-amping or aligning subwoofers.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Absolute-polarity inversion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bfa620d1-5f35-4bcf-9472-37f584891230','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bfa620d1-5f35-4bcf-9472-37f584891230') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bfa620d1-5f35-4bcf-9472-37f584891230');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4f8c19bc-611a-4fda-8bdc-0b308c27716f','Adapted Port Resistance','In wave digital filter (WDF) theory, each port of an element is assigned a port resistance that scales its incident and reflected wave variables. An adapted port resistance is a value chosen so the reflected wave at that port does not depend instantaneously on its own incident wave, removing the delay-free (algebraic) dependence and making the structure computable in real time.','Wave digital filters model circuits as blocks that trade signals back and forth. Each connection gets a resistance value that scales those signals. Choosing the right value can stop a block from feeding itself instantly. That lets the filter run step by step without an unsolvable loop.','Adapting a port removes instantaneous feedback at that connection, so a wave digital filter can be computed in sequence and stays realizable.','A DSP developer sets one port''s resistance to match its neighbour so no delay-free loop forms, then verifies the model runs sample-by-sample without an algebraic-loop error.','Wave digital filters',ARRAY['Algebraic loop','Wave digital filter','Port resistance','Adaptor','Reflection coefficient']::text[],ARRAY['Believing every port can be adapted at once; typically only one port per adaptor can be reflection-free.','Confusing port resistance with a physical resistor value in the modeled circuit.','Ignoring adaptation and then hitting an unsolvable delay-free loop.']::text[],ARRAY['Coding a virtual-analog filter using wave digital filter theory.','Removing an algebraic loop when modeling a nonlinear circuit element.','Connecting WDF sub-networks through a series or parallel adaptor.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Adapted Port Resistance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4f8c19bc-611a-4fda-8bdc-0b308c27716f','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4f8c19bc-611a-4fda-8bdc-0b308c27716f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4f8c19bc-611a-4fda-8bdc-0b308c27716f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f2dab7f8-8574-4d6d-9327-ffa2c2674b66','Album-mode processing','Album-mode processing is a loudness-normalization strategy in which a single gain adjustment, derived from the integrated loudness of a whole album, is applied uniformly to every track, rather than normalizing each track on its own. This preserves the intended loudness relationships between quiet and loud tracks across the album.','Loudness tools can even out volume between songs. Track mode sets each song on its own. Album mode measures the whole album and uses one setting for all songs. That keeps soft songs soft and loud songs loud, as intended.','It lets playback systems match loudness between albums while keeping the dynamic contrast the artist built between tracks within one album.','Using an EBU R128 or ReplayGain tool, an engineer picks album mode so a gentle intro stays quieter than the next anthem, applying one album gain to all files.','Loudness normalization',ARRAY['Integrated loudness','ReplayGain','LUFS','Track normalization','EBU R128']::text[],ARRAY['Assuming album mode makes every track equally loud; it only equalizes the album as a whole.','Mixing album-gain and track-gain values taken from different measurements.','Forgetting that many streaming platforms normalize per track, undoing album relationships.']::text[],ARRAY['Mastering a dynamic album for consistent playback.','Tagging files with ReplayGain album values.','Preparing loudness metadata to EBU R128 for a full record.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Album-mode processing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f2dab7f8-8574-4d6d-9327-ffa2c2674b66','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f2dab7f8-8574-4d6d-9327-ffa2c2674b66') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f2dab7f8-8574-4d6d-9327-ffa2c2674b66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '130e4105-4c0f-4327-a5b4-8f46e0008e9d','Algebraic Loop','An algebraic loop is a closed path in a signal-flow or block diagram in which a signal instantaneously depends on itself, with no delay, memory, or state element in the path. Because the governing equations become implicit, the loop has no direct sequential solution and must be resolved by adding a delay, restructuring the graph, or solving the loop equation.','Picture blocks passing a signal in a circle. An algebraic loop happens when a block''s output feeds back to itself with no delay. The value would need to be known before it is computed. Software cannot run this directly, so you add a delay or rearrange it.','Spotting algebraic loops matters because real-time processors and simulators must compute outputs in order, and an undelayed self-dependence makes that ordering impossible.','In a block-diagram tool such as Simulink, a technician inserts a unit-delay or memory block to break a flagged algebraic loop so the model will compile and run.','Signal-flow theory',ARRAY['Adapted port resistance','Feedback','Unit delay','Wave digital filter','Block diagram']::text[],ARRAY['Confusing an algebraic loop with intended feedback; feedback with a delay is fine, undelayed self-dependence is not.','Adding a delay in the wrong place and changing the intended behavior.','Assuming the compiler can always solve the loop automatically.']::text[],ARRAY['Building a feedback DSP model that fails to compile.','Designing a wave digital filter that needs an adapted port.','Debugging a Simulink model that reports an algebraic-loop error.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Algebraic Loop');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '130e4105-4c0f-4327-a5b4-8f46e0008e9d','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='130e4105-4c0f-4327-a5b4-8f46e0008e9d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='130e4105-4c0f-4327-a5b4-8f46e0008e9d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8e04a4d2-7282-4b8b-bc26-01b68c8825c6','Angular Deviation Loss','Angular deviation loss is the difference, in decibels, between an electroacoustic transducer''s sensitivity level measured on its principal (reference) axis and its sensitivity level measured in a specified off-axis direction. It quantifies how much a microphone''s or loudspeaker''s response falls off as sound arrives from, or is radiated toward, an angle away from the main axis.','A microphone or speaker works best straight ahead, along its main axis. Off to the side, its response is weaker. Angular deviation loss measures that drop in decibels. It compares the on-axis level to the level at a chosen angle.','It gives a standard number for directional falloff, letting engineers compare how tightly a transducer focuses sound toward or from a direction.','If a microphone''s sensitivity level is -40 dB on axis and -46 dB at 90 degrees, its angular deviation loss at 90 degrees is 6 dB; the technician then aims off-axis noise into that reduced-response zone.','Transducer directivity',ARRAY['Directivity index','Polar pattern','Sensitivity level','Off-axis response','Principal axis']::text[],ARRAY['Confusing angular deviation loss with directivity index; the loss is at one angle, the index is an integrated average.','Forgetting the value is frequency-dependent and is reported per band.','Assuming zero loss on axis means flat response at all angles.']::text[],ARRAY['Interpreting a microphone polar plot.','Aiming a loudspeaker so spill lands in a low-response direction.','Comparing directional microphones for rejection at a given angle.']::text[],'intermediate','ADL(theta) = L_M,axis - L_M,theta','Angular deviation loss at an angle equals the sensitivity level on the principal axis minus the sensitivity level in that direction, in decibels.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Angular Deviation Loss');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8e04a4d2-7282-4b8b-bc26-01b68c8825c6','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8e04a4d2-7282-4b8b-bc26-01b68c8825c6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8e04a4d2-7282-4b8b-bc26-01b68c8825c6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '10cf05ce-3c7e-45c0-a2e5-6b1562b7ad13','Angular response data set','An angular response data set is a collection of a loudspeaker''s (or transducer''s) frequency responses measured at many angles around it, typically over a sphere or in the horizontal and vertical planes, so its directional behavior can be reconstructed for any listening angle. Such data underpin balloon plots and the predictive coverage models used in sound-system design.','A speaker sounds different at each angle around it. Engineers measure its response at many angles and store the results together. That collection is the angular response data set. Design software uses it to predict coverage in a room.','It captures a device''s full directivity so acoustic-modeling software can predict how its sound spreads across an audience area.','A system designer loads a loudspeaker''s angular response data (for example a GLL or Common Loudspeaker Format file) into prediction software to map coverage before hanging an array.','Loudspeaker directivity',ARRAY['Directivity','Balloon plot','Common Loudspeaker Format','Polar pattern','Coverage angle']::text[],ARRAY['Assuming a single on-axis response describes a loudspeaker''s coverage.','Using too coarse an angular resolution and missing narrow lobes.','Applying horizontal-only data to a full-sphere prediction.']::text[],ARRAY['Importing manufacturer directivity files into modeling software.','Designing line-array coverage for a venue.','Comparing horn dispersion between loudspeaker models.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Angular response data set');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '10cf05ce-3c7e-45c0-a2e5-6b1562b7ad13','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='10cf05ce-3c7e-45c0-a2e5-6b1562b7ad13') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='10cf05ce-3c7e-45c0-a2e5-6b1562b7ad13');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2a054e85-2c42-4ef7-a732-14b173774bdc','Array manifold','In sensor-array (microphone-array) signal processing, the array manifold is the set of all array response (steering) vectors traced out as a source''s direction of arrival, and any other governing parameters, vary over their full range. Its geometry — set by element positions, spacing, and frequency — governs how well directions can be distinguished and where spatial ambiguities occur.','A microphone array responds differently to sound from each direction. Collect the array''s response for every possible direction. That whole collection forms a shape called the array manifold. Its shape decides how well the array tells directions apart.','It gives the geometric model that direction-finding and beamforming algorithms rely on to relate measured signals to source directions.','When building a beamformer, an engineer computes the array manifold from the element coordinates and frequency, then checks for spatial aliasing before choosing element spacing.','Array processing',ARRAY['Array manifold vector','Steering vector','Beamforming','Direction of arrival','Spatial aliasing']::text[],ARRAY['Confusing the array manifold (the whole set) with a single steering vector (one point on it).','Ignoring that element spacing above half a wavelength creates directional ambiguities.','Assuming the manifold is frequency-independent.']::text[],ARRAY['Designing a microphone array for source localization.','Analyzing spatial aliasing from wide element spacing.','Developing a direction-of-arrival estimator.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Array manifold');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2a054e85-2c42-4ef7-a732-14b173774bdc','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2a054e85-2c42-4ef7-a732-14b173774bdc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2a054e85-2c42-4ef7-a732-14b173774bdc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '133200b7-83dc-4ce1-b44b-962f6e273e97','Array manifold vector','The array manifold vector, also called the steering or array response vector, is the vector of complex responses of each array element to a unit-amplitude plane wave arriving from a specified direction, capturing the relative amplitude and phase seen at every sensor. It is a single point on the array manifold and is the basic building block of beamforming and direction-finding algorithms.','Sound from one direction reaches each microphone at a slightly different time. That gives each microphone a different phase. The array manifold vector lists those phase-and-amplitude values, one per microphone. Algorithms use it to steer the array toward a direction.','It encodes, for one direction, exactly how a plane wave appears across the array, so processors can align or separate signals by direction.','For a uniform line array spaced a half-wavelength apart, a source at 30 degrees gives psi = pi*sin(30) = 1.57 rad (90 degrees); the vector [1, e^-j90, e^-j180, ...] then serves as the steering weights.','Array processing',ARRAY['Array manifold','Steering vector','Beamforming','Uniform linear array','Phase delay']::text[],ARRAY['Confusing the manifold vector (one direction) with the whole manifold (all directions).','Using degrees instead of radians in the phase term.','Omitting the frequency or wavelength dependence of the phase.']::text[],ARRAY['Programming delay-and-sum or MVDR beamformers.','Steering a null toward a noise source.','Computing the spatial response of a uniform linear array.']::text[],'advanced','v(theta) = [1, e^-j*psi, e^-j*2psi, ..., e^-j*(M-1)psi]^T,  psi = (2*pi*d/lambda)*sin(theta)','For a uniform linear array, the manifold vector''s element phases increase in equal steps set by two pi times the spacing over the wavelength, times the sine of the arrival angle.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Array manifold vector');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '133200b7-83dc-4ce1-b44b-962f6e273e97','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='133200b7-83dc-4ce1-b44b-962f6e273e97') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='133200b7-83dc-4ce1-b44b-962f6e273e97');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '75aa823c-54b9-4ded-9dfe-7abaa131cdb9','Ascending method','The ascending method is a psychoacoustic and audiometric procedure for determining a threshold in which the stimulus is first presented below threshold and increased in fixed steps until the subject responds, with the threshold estimated from the levels at which responses begin. In pure-tone audiometry it forms the basis of the standardized method of limits used to find hearing threshold.','To find the softest sound a person can hear, start too quiet to hear. Raise the level in small steps. Note where the listener first says they hear it. Repeat and average to get the threshold.','It gives a repeatable, standardized way to estimate the faintest detectable level while reducing bias from starting above threshold.','Following ISO 8253-1, an audiologist raises a tone in 5 dB steps from inaudible until the patient responds, records that level, and repeats to fix the hearing threshold.','Audiometric method',ARRAY['Hearing threshold','Method of limits','Descending method','Pure-tone audiometry','Threshold of audibility']::text[],ARRAY['Confusing the ascending method with the descending method, which starts audible and lowers the level.','Using steps that are too large and overestimating the threshold.','Failing to randomize timing, letting the subject anticipate the tones.']::text[],ARRAY['Clinical pure-tone hearing tests.','Occupational hearing screening.','Laboratory threshold measurements in psychoacoustics.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ascending method');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '75aa823c-54b9-4ded-9dfe-7abaa131cdb9','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='75aa823c-54b9-4ded-9dfe-7abaa131cdb9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='75aa823c-54b9-4ded-9dfe-7abaa131cdb9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a7000c08-84bf-45d6-b70b-6c153c0ea6ac','Audio Data Interchange Format','The Audio Data Interchange Format (ADIF) is a simple storage format for Advanced Audio Coding (AAC) bitstreams defined within the MPEG-2 and MPEG-4 audio standards, consisting of a single header at the start of the file followed by the raw coded audio data. Unlike the Audio Data Transport Stream (ADTS), it lacks repeated per-frame sync headers, so it suits file storage rather than streaming.','Advanced Audio Coding, or AAC, packs sound into compressed data. ADIF is one way to store that data in a file. It puts one header at the very start, then all the audio. It is meant for whole files, not live streaming.','It provides a lightweight container for storing an AAC stream when mid-stream entry is not needed, saving the overhead of repeated headers.','A developer choosing how to save AAC output picks ADIF for a self-contained file, or ADTS when the stream must be broadcast and joined mid-flow.','Coded-audio format',ARRAY['Advanced Audio Coding','Audio Data Transport Stream','MPEG-4 Audio','Bitstream','Container format']::text[],ARRAY['Confusing ADIF with the Audio Interchange File Format (AIFF); AIFF holds uncompressed PCM, ADIF wraps compressed AAC.','Trying to start playback in the middle of an ADIF file, which has no per-frame sync.','Assuming ADIF is used for broadcast, which ADTS handles instead.']::text[],ARRAY['Storing an encoded AAC track to disk.','Interpreting the outer format of an AAC bitstream.','Deciding between ADIF and ADTS in an encoder.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio Data Interchange Format');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a7000c08-84bf-45d6-b70b-6c153c0ea6ac','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a7000c08-84bf-45d6-b70b-6c153c0ea6ac') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a7000c08-84bf-45d6-b70b-6c153c0ea6ac');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '15469215-f544-4779-952e-82050e4933d9','Audio description scheme','In the MPEG-7 multimedia content description standard, an audio Description Scheme is a standardized structure that organizes audio Descriptors and other Description Schemes into a coherent description of audio content, defining their relationships and semantics. It provides a common framework for describing features such as timbre, melody, and spoken content to support indexing, search, and retrieval.','MPEG-7 is a standard for describing media, not for playing it. It uses small labels called descriptors for audio features. A description scheme groups those labels into a full description. Software can then search sound by its described features.','It gives a standard way to package audio features and metadata so different systems can index, search, and retrieve audio content consistently.','A content-management developer uses an MPEG-7 audio description scheme to store timbre and melody descriptors, enabling query-by-example search over a music archive.','Content description',ARRAY['MPEG-7','Descriptor','Metadata','Audio fingerprint','Description Definition Language']::text[],ARRAY['Confusing an MPEG-7 audio description scheme with broadcast audio description for the visually impaired.','Thinking MPEG-7 encodes or compresses the audio; it only describes it.','Mixing up descriptors (single features) with description schemes (structured groups).']::text[],ARRAY['Building searchable audio archives.','Tagging media assets with standardized feature metadata.','Implementing query-by-humming or fingerprint search.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio description scheme');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '15469215-f544-4779-952e-82050e4933d9','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='15469215-f544-4779-952e-82050e4933d9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='15469215-f544-4779-952e-82050e4933d9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '997fc2c8-a0bf-4ed2-953e-92e0d52eb637','Audio power','Audio power is the electrical power an amplifier delivers to its load (a loudspeaker or a specified resistive load) over the audio-frequency range, commonly stated as a rated continuous (RMS-based) power into a nominal impedance at a defined distortion limit. Its measurement conditions — load impedance, bandwidth, and permitted total harmonic distortion — are fixed by standards such as IEC 60268-3 so that ratings are comparable.','An amplifier sends electrical power to a speaker. Audio power is how much power it delivers into the speaker''s load. Honest ratings state the load, the frequency range, and the allowed distortion. Standards fix these conditions so ratings can be compared.','It quantifies an amplifier''s output capability under defined conditions so users can match amplifiers to loudspeakers and predict achievable levels.','Delivering 28.3 V RMS into an 8-ohm load gives P = V^2/R = 28.3^2/8, about 100 W; a technician checks this against the amplifier''s IEC-rated continuous power before matching a speaker.','Amplifier rating',ARRAY['RMS power','Total harmonic distortion','Load impedance','Headroom','Sensitivity']::text[],ARRAY['Trusting peak or ''PMPO'' figures instead of rated continuous power.','Ignoring the load impedance at which the power is specified.','Assuming double the amplifier power doubles loudness; it adds only about 3 dB.']::text[],ARRAY['Matching an amplifier to loudspeakers.','Comparing amplifier datasheets fairly.','Setting system gain and headroom.']::text[],'intermediate','P = V_rms^2 / R = I_rms^2 * R','Power into a resistive load equals the RMS voltage squared divided by the load resistance, or the RMS current squared times the resistance.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio power');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '997fc2c8-a0bf-4ed2-953e-92e0d52eb637','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='997fc2c8-a0bf-4ed2-953e-92e0d52eb637') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='997fc2c8-a0bf-4ed2-953e-92e0d52eb637');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '79d20006-a0ed-4090-acdf-c6c3ed50b814','Audio-frequency shield behavior','Audio-frequency shield behavior refers to how a cable or enclosure shield attenuates interference across the audio band, where shielding against electric (capacitive) fields stays effective but shielding against low-frequency magnetic fields is comparatively poor, because magnetic shielding effectiveness generally rises with frequency. In balanced interconnects, shield performance also depends on how shield (drain) currents couple into the signal pair, the mechanism behind shield-current-induced noise.','A cable shield blocks unwanted electrical noise. Against electric-field noise it works well across audio frequencies. Against magnetic hum at low frequencies it works poorly. How the shield is grounded and connected strongly affects the result.','Understanding shield behavior across the audio band guides cable choice and grounding so interconnects reject interference without adding noise.','To fight low-frequency hum a technician relies on a twisted balanced pair for magnetic rejection and grounds the shield correctly, rather than trusting the shield alone.','Shielding and grounding',ARRAY['Shield-current-induced noise','Balanced line','Common-mode rejection','Grounding','Electromagnetic interference']::text[],ARRAY['UNSAFE: Lifting a cable shield''s connection to mains safety ground to stop hum; disconnecting protective earth creates a shock hazard and must never be done.','Assuming a shield blocks low-frequency magnetic hum as well as it blocks electric fields.','Grounding a shield at both ends without considering ground-loop and shield-current effects.']::text[],ARRAY['Diagnosing hum in a long microphone run.','Choosing shielded twisted-pair for a noisy environment.','Deciding where to terminate a cable shield.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-frequency shield behavior');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '79d20006-a0ed-4090-acdf-c6c3ed50b814','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='79d20006-a0ed-4090-acdf-c6c3ed50b814') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='79d20006-a0ed-4090-acdf-c6c3ed50b814');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a24f93ce-ccac-48cd-823c-752735529748','Audio-node event','In the W3C Web Audio API, an audio-node event is a DOM event dispatched by an AudioNode object to signal a change in its state, most notably the ''ended'' event fired by a scheduled source node when its playback finishes. Such events let application code react to the audio graph''s progress without polling.','The Web Audio API builds sound in a browser from connected blocks called nodes. A node can announce things by firing an event. For example, a sound source fires an ''ended'' event when it stops. The program listens and reacts, such as starting the next clip.','Events let web applications synchronize their logic with the audio engine''s timeline, for example chaining clips when one finishes.','A developer attaches an ''ended'' listener to a Web Audio source node so the next sound starts automatically when the current one stops.','Web Audio API',ARRAY['AudioNode','Web Audio API','Audio-node routing','AudioContext','Event listener']::text[],ARRAY['Assuming an audio node fires events continuously; most fire only at discrete points such as end of playback.','Confusing Web Audio node events with HTML media-element events.','Forgetting that a one-shot source node cannot be restarted after its ''ended'' event.']::text[],ARRAY['Sequencing clips in a browser audio application.','Freeing resources after a source finishes.','Driving user-interface updates from playback state.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-node event');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a24f93ce-ccac-48cd-823c-752735529748','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a24f93ce-ccac-48cd-823c-752735529748') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a24f93ce-ccac-48cd-823c-752735529748');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b1e76223-7261-4387-9817-f414509e2d6c','Audio-node routing','In the W3C Web Audio API, audio-node routing is the process of connecting AudioNode objects — sources, processors, and destinations — via their connect() method to form a directed audio routing graph through which sample data flows. The graph''s topology determines how signals are mixed, processed, and ultimately sent to the output.','The Web Audio API makes sound from small blocks called nodes. Routing means wiring these blocks together in order. A source connects to effects, then to the output. Changing the wiring changes how the sound is built.','Routing defines the signal path through the audio graph, letting developers combine sources and effects and send the result to the speakers.','A developer routes a source node into a gain node and then to the context destination, so adjusting the gain node controls the final output volume.','Web Audio API',ARRAY['AudioNode','Audio-node event','AudioContext','Signal routing','Gain node']::text[],ARRAY['Forgetting to connect the final node to the destination, so nothing is heard.','Creating unintended feedback by connecting a node back to an earlier one.','Assuming disconnecting one link stops all audio when other paths remain.']::text[],ARRAY['Building an effects chain in a browser application.','Mixing multiple sources to one output.','Rewiring an audio graph at runtime.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-node routing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b1e76223-7261-4387-9817-f414509e2d6c','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b1e76223-7261-4387-9817-f414509e2d6c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b1e76223-7261-4387-9817-f414509e2d6c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dfc65ea2-eec6-4651-add3-2f3019bd78c1','Audio-rate processing','Audio-rate processing is signal computation performed at the full audio sample rate, updating a value for every sample, in contrast to control-rate processing, which updates less often (for example once per processing block). In the Web Audio API this distinction appears as a-rate versus k-rate AudioParam automation, and in synthesis languages it separates fast audio signals from slower control signals.','Digital audio is a stream of samples, tens of thousands per second. Audio-rate processing computes a new value for every single sample. Control-rate processing updates far less often, to save effort. Fast-changing sound needs audio rate; slow controls can use control rate.','Running a parameter or signal at audio rate lets it change smoothly and quickly enough to be heard as sound, at the cost of more computation.','For audible frequency modulation a developer sets an oscillator''s parameter to a-rate so it recalculates every sample, while a slow volume fade can stay at the cheaper control rate.','Digital signal processing',ARRAY['Sample rate','Control rate','AudioParam','Block processing','Modulation']::text[],ARRAY['Using control-rate updates for fast modulation and hearing stepping or zipper noise.','Confusing audio rate (per sample) with the numeric value of the sample rate.','Running everything at audio rate and wasting CPU on slow controls.']::text[],ARRAY['Choosing a-rate versus k-rate in Web Audio automation.','Designing modulation in a software synthesizer.','Optimizing DSP CPU load.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio-rate processing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dfc65ea2-eec6-4651-add3-2f3019bd78c1','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dfc65ea2-eec6-4651-add3-2f3019bd78c1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dfc65ea2-eec6-4651-add3-2f3019bd78c1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e28ee376-d22a-437c-ba3c-c2495d9ba20d','Audiovisual Speech Benefit','Audiovisual speech benefit is the measurable improvement in speech intelligibility that occurs when a listener can see the talker''s face and articulatory movements in addition to hearing the voice, compared with listening alone. The benefit is largest in noisy or degraded acoustic conditions and is often expressed as an increase in percent-correct scores or an equivalent improvement in signal-to-noise ratio.','Watching a talker''s face helps you understand speech. Lip and mouth movements add information the ears miss. This help is called audiovisual speech benefit. It matters most when the room is noisy.','It explains and quantifies how vision aids hearing, informing accessibility, hearing-aid design, and communication in noise.','Testing intelligibility in noise, a researcher compares audio-only and audiovisual scores; a jump from 50 to 80 percent correct shows the audiovisual speech benefit.','Speech perception',ARRAY['Speech intelligibility','Lipreading','McGurk effect','Signal-to-noise ratio','Speech-in-noise']::text[],ARRAY['Assuming the benefit is small; in noise it can be very large.','Confusing audiovisual benefit with the McGurk effect, which is a perceptual illusion.','Ignoring visual cues when designing communication systems for noisy spaces.']::text[],ARRAY['Designing captioning or video for accessibility.','Testing hearing-aid performance in noise.','Evaluating conferencing audio and video together.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audiovisual Speech Benefit');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e28ee376-d22a-437c-ba3c-c2495d9ba20d','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e28ee376-d22a-437c-ba3c-c2495d9ba20d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e28ee376-d22a-437c-ba3c-c2495d9ba20d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6464f16b-ea73-4b51-9f21-72b5d3b71159','Aural Combination Tone','An aural combination tone is a secondary tone perceived when two sufficiently loud primary tones sound together, produced by nonlinearities in the ear rather than being present in the physical stimulus. It may appear as a difference tone, a summation tone, or a higher-order product, and its frequency depends on the primaries (for example the difference frequency, f2 minus f1).','Play two loud pure tones at once. You may hear an extra tone that is not really there. Your ear itself creates it, because hearing is not perfectly linear. A common one has a pitch equal to the gap between the two tones.','The concept explains extra pitches listeners report and reveals the nonlinear nature of the hearing system.','If two loud tones at 1000 and 1200 Hz play together, a technician may hear a 200 Hz difference tone generated in the ear, not distortion from the equipment.','Psychoacoustics',ARRAY['Aural harmonic','Difference tone','Nonlinearity','Intermodulation distortion','Combination tone']::text[],ARRAY['Blaming equipment distortion for a tone the ear itself generates.','Confusing an aural (in-ear) combination tone with electrical intermodulation distortion.','Assuming they appear at quiet levels; they need loud primary tones.']::text[],ARRAY['Interpreting odd pitches during high-level listening tests.','Teaching nonlinear hearing.','Distinguishing perceptual artifacts from real distortion.']::text[],'advanced','f_diff = f2 - f1  (with further products such as 2*f1 - f2)','The simplest aural combination tone has a frequency equal to the higher primary minus the lower primary; other tones arise at further sums and differences.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Aural Combination Tone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6464f16b-ea73-4b51-9f21-72b5d3b71159','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6464f16b-ea73-4b51-9f21-72b5d3b71159') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6464f16b-ea73-4b51-9f21-72b5d3b71159');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ec6f0cd3-08c8-4591-a4f0-eb37d27b5b45','Aural Harmonic','An aural harmonic is a harmonic of a pure tone that a listener perceives even though it is not present in the physical stimulus, arising from nonlinear distortion within the auditory system. When a single loud tone of frequency f is presented, the ear can generate perceived components at 2f, 3f, and so on.','Play one loud pure tone. Your ear may add tones at double and triple its pitch. These extra tones are not in the sound itself. Your hearing makes them, because it is slightly nonlinear.','It documents distortion introduced by the ear itself, separating perceived harmonics from harmonics actually present in the signal.','Hearing faint higher pitches above one loud sine tone, a technician attributes them to aural harmonics in the ear rather than to a faulty oscillator.','Psychoacoustics',ARRAY['Aural combination tone','Harmonic distortion','Nonlinearity','Pure tone','Total harmonic distortion']::text[],ARRAY['Assuming higher pitches over a pure tone prove equipment distortion.','Confusing aural harmonics (in the ear) with harmonics in the source signal.','Expecting them at quiet levels; they need a loud tone.']::text[],ARRAY['High-level pure-tone listening.','Teaching auditory nonlinearity.','Separating perceptual artifacts from measured distortion.']::text[],'advanced','f_n = n * f,  n = 2, 3, 4, ...','Perceived aural harmonics sit at whole-number multiples of the presented tone''s frequency.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Aural Harmonic');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ec6f0cd3-08c8-4591-a4f0-eb37d27b5b45','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ec6f0cd3-08c8-4591-a4f0-eb37d27b5b45') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ec6f0cd3-08c8-4591-a4f0-eb37d27b5b45');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2b098612-91bd-42c2-bb55-04a8c4538967','Author-defined preset','In interactive and immersive audio systems such as MPEG-H 3D Audio, an author-defined preset is a predefined combination of audio elements, gains, and positions specified by the content creator that a listener can select as a ready-made experience (for example a dialogue-enhanced or alternative-commentary mix). It fixes the creator''s intended options while still allowing the user to choose among them.','Some modern audio lets you pick between mixes, like more dialogue or different commentary. The content maker builds these choices in advance. Each ready-made choice is an author-defined preset. You choose one, but the maker set the options.','It lets creators offer controlled, curated listening and accessibility options without giving up artistic control of the mix.','Preparing an MPEG-H broadcast, an engineer defines presets such as ''standard mix'' and ''dialogue enhanced'' so viewers can switch between the creator''s intended options.','Immersive audio',ARRAY['MPEG-H 3D Audio','Audio element','Dialogue enhancement','Metadata','Interactivity']::text[],ARRAY['Confusing author-defined presets with free user mixing; presets are curated fixed options.','Assuming presets alter the coded audio; they select and combine existing elements via metadata.','Overlooking accessibility presets such as dialogue enhancement.']::text[],ARRAY['Authoring next-generation broadcast audio.','Offering dialogue-enhanced accessibility options.','Configuring interactive sports-commentary choices.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Author-defined preset');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2b098612-91bd-42c2-bb55-04a8c4538967','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2b098612-91bd-42c2-bb55-04a8c4538967') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2b098612-91bd-42c2-bb55-04a8c4538967');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c9126847-e703-44f1-ab70-9d5cad79dcfb','Auxiliary sample bits','In the AES3 (IEC 60958) digital audio interface, the auxiliary sample bits are the four bits within each 32-bit subframe (time slots 4 to 7) that sit below the main audio sample word. They can extend the audio word length to 24 bits, or be grouped as a separate low-resolution auxiliary audio channel, for example for talkback or coordination.','AES3 is a standard digital audio connection. Each audio sample sits in a slot with a few spare bits. These four spare bits are the auxiliary sample bits. They can make the main sample longer, or carry a small, low-quality extra audio channel.','They provide flexible extra capacity in the AES3 frame, either widening the main sample or carrying a secondary channel, without changing the interface structure.','Setting up an AES3 link, a technician confirms whether the four auxiliary bits form part of a 24-bit main word or a talkback auxiliary channel, so both ends agree.','Digital audio interface',ARRAY['AES3','Subframe','Channel status','Word length','S/PDIF']::text[],ARRAY['Assuming the auxiliary bits are always part of a 24-bit sample; they may instead carry a separate channel.','Confusing the auxiliary bits with the channel-status or user-data bits.','Expecting full-quality audio from the low-resolution auxiliary channel.']::text[],ARRAY['Configuring AES3 word length between devices.','Carrying talkback over an AES3 link.','Troubleshooting bit-depth mismatches on a digital connection.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auxiliary sample bits');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c9126847-e703-44f1-ab70-9d5cad79dcfb','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c9126847-e703-44f1-ab70-9d5cad79dcfb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c9126847-e703-44f1-ab70-9d5cad79dcfb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e157aaf6-722c-49e2-9d3b-7ad273c2b1da','Availability Bias','Availability bias (the availability heuristic) is a cognitive tendency to judge the likelihood or frequency of an event by how easily relevant examples come to mind, so vivid or recent instances are overweighted. In audio work it can skew subjective evaluations, for example overrating a problem the listener just read about or a device recently discussed.','People guess how common something is by how easily examples pop into mind. Recent or dramatic memories feel more common than they are. This is availability bias. In listening tests it can push judgments toward whatever is fresh in memory.','Naming this bias helps engineers design fairer listening tests and make evidence-based decisions rather than memory-driven ones.','Running a comparison, a technician blinds and randomizes the trials so a recently hyped feature does not bias ratings through availability.','Cognitive bias',ARRAY['Confirmation bias','Blind test','Listening test','Placebo effect','Expectation bias']::text[],ARRAY['Treating one vivid memory as representative data.','Skipping blinding and letting recent talk sway listening judgments.','Confusing availability bias with confirmation bias.']::text[],ARRAY['Designing and interpreting listening tests.','Choosing gear based on recent reviews.','Diagnosing recurring faults without checking records.']::text[],'beginner',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Availability Bias');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e157aaf6-722c-49e2-9d3b-7ad273c2b1da','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e157aaf6-722c-49e2-9d3b-7ad273c2b1da') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e157aaf6-722c-49e2-9d3b-7ad273c2b1da');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '08d6ed40-cc7a-436f-b9a4-28094940ea2b','Average Sound-Pressure Level in a Room','The average sound-pressure level in a room is the level obtained by energetically averaging the mean-square sound pressures measured at several positions (and over time) within the room, expressed in decibels. It represents the overall level of a reasonably diffuse sound field better than any single-point reading and is used in room-acoustics and sound-power measurements.','Sound level changes from spot to spot in a room. To get one representative figure, measure at several places. Then combine them by energy, not by a plain average. The result is the room''s average sound-pressure level.','It provides a single representative level for a diffuse field, needed for reverberation and sound-power methods where one point would be unreliable.','Measuring 78, 80, 82, 79, 81, and 80 dB at six positions, a technician energy-averages them (about 80.2 dB) to report the room''s average sound-pressure level.','Room acoustics',ARRAY['Sound-pressure level','Diffuse field','Reverberation time','Sound power level','Spatial averaging']::text[],ARRAY['Taking a plain arithmetic average of the decibel values instead of energy-averaging.','Using too few positions to represent the field.','Measuring only near a wall or corner, biasing the result.']::text[],ARRAY['Sound-power measurement in a reverberation room.','Assessing background level across a space.','Verifying coverage uniformity in a venue.']::text[],'intermediate','L_p_avg = 10 * log10( (1/N) * sum_{i=1..N} 10^(L_pi/10) )','Convert each level back to relative energy, take the arithmetic mean of those energies, then convert the mean back to decibels.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Average Sound-Pressure Level in a Room');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '08d6ed40-cc7a-436f-b9a4-28094940ea2b','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='08d6ed40-cc7a-436f-b9a4-28094940ea2b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='08d6ed40-cc7a-436f-b9a4-28094940ea2b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7f11187e-a388-412a-940d-c840326165d3','Baffled piston','A baffled piston is the idealized acoustic radiator consisting of a rigid flat circular disc that vibrates uniformly (like a piston) while set in an infinite rigid baffle, used as the standard model for a loudspeaker diaphragm mounted in a large flat wall. Its far-field radiation is nearly omnidirectional at low frequencies and becomes increasingly directional as the disc''s size grows relative to the wavelength.','Engineers model a speaker cone as a flat, stiff disc that moves like a piston. They imagine it set in a huge flat wall called a baffle. This simple model predicts how the speaker radiates sound. It spreads sound widely at low pitches and narrowly at high pitches.','It provides a tractable reference model for predicting a loudspeaker''s radiation, directivity, and beaming behavior versus frequency.','For a 0.1 m-radius woofer at 1 kHz, ka = 2*pi*a/lambda is about 1.8, so the baffled-piston model predicts the response has begun to narrow off-axis (beaming).','Radiation model',ARRAY['Directivity','Beaming','Wavenumber','Loudspeaker','Far field']::text[],ARRAY['Assuming a real cone stays a rigid piston at all frequencies; it breaks up at high frequencies.','Ignoring the infinite-baffle assumption when applying the model to a small enclosure.','Forgetting that directivity depends on size relative to wavelength, not size alone.']::text[],ARRAY['Predicting when a driver begins to beam.','Teaching loudspeaker directivity.','Estimating the high-frequency dispersion of a woofer.']::text[],'advanced','D(theta) = 2 * J1(ka * sin(theta)) / (ka * sin(theta))','The far-field directivity of a baffled circular piston follows twice the first-order Bessel function of the wavenumber times radius times the sine of the angle, divided by that same argument.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Baffled piston');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7f11187e-a388-412a-940d-c840326165d3','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7f11187e-a388-412a-940d-c840326165d3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7f11187e-a388-412a-940d-c840326165d3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '44a27703-af9a-47cf-ab65-702defaa26eb','Building service noise','The airborne noise generated inside a building by its own fixed service installations, such as plumbing, ventilation, heating, lifts, pumps and boilers. It is quantified as a sound pressure level in occupied rooms using a standardized engineering method so installations can be checked against acoustic requirements.','This is the sound made by a building''s own equipment. Think of pipes, fans, lifts, and heaters. Engineers measure it inside rooms where people live or work. Rules set limits so the noise stays low.','It gives a defined, repeatable way to rate intrusive noise from a building''s fixed equipment so designs meet comfort and regulatory limits.','Following ISO 16032, a technician logs the sound pressure level in a bedroom while a bathroom fan runs, then compares it to the local limit, e.g. 32 dB(A) against a 35 dB(A) target.','Building Acoustics',ARRAY['Emission sound pressure level','Background noise level','A-weighting','Sound pressure level','Environmental noise']::text[],ARRAY['Confusing building service noise with outdoor environmental noise from traffic.','Forgetting to record the room''s background level with the equipment switched off.','Assuming one reading represents a source that cycles on and off, like a pump.']::text[],ARRAY['Checking whether a new HVAC unit meets a hotel room noise limit.','Diagnosing complaints about plumbing noise between apartments.','Commissioning a studio''s air handling for quiet operation.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Building service noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '44a27703-af9a-47cf-ab65-702defaa26eb','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='44a27703-af9a-47cf-ab65-702defaa26eb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='44a27703-af9a-47cf-ab65-702defaa26eb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '50c2d7c0-2363-4369-ab56-7b349bbdaf5f','Cardioid response','A first-order directional response whose sensitivity varies with angle as approximately (1 + cos theta)/2, giving full output on-axis and a deep null at the rear (180 degrees). It is the most common microphone directional pattern and also describes the coverage of some directional loudspeaker arrays.','A cardioid pick-up is loudest from the front. It hears almost nothing from directly behind. Its coverage shape looks like a heart. Many stage microphones use this pattern.','It lets a microphone favor a wanted source in front while rejecting sound and feedback arriving from the rear.','A technician aims a cardioid vocal mic so its rear null faces the floor monitor to cut feedback; at theta=90 degrees output is (1+0)/2 = 0.5, about 6 dB down from the front.','Directivity Pattern',ARRAY['Compression driver directivity','Common Loudspeaker Format','Polar pattern','Proximity effect','Directivity index']::text[],ARRAY['Assuming the deepest rejection is at the sides rather than at the rear.','Believing a cardioid rejects rear sound equally at all frequencies.','Ignoring that the pattern narrows and becomes uneven at high frequencies.']::text[],ARRAY['Placing stage monitors relative to a cardioid vocal mic.','Choosing a mic pattern for close-miking a drum.','Describing the coverage of a cardioid subwoofer array.']::text[],'intermediate','E(theta) = (1 + cos theta) / 2','The relative sensitivity equals one plus the cosine of the off-axis angle, divided by two.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cardioid response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '50c2d7c0-2363-4369-ab56-7b349bbdaf5f','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='50c2d7c0-2363-4369-ab56-7b349bbdaf5f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='50c2d7c0-2363-4369-ab56-7b349bbdaf5f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a37ab1f1-dc71-4676-bd93-0356864f4aa9','Common Loudspeaker Format','An openly published, platform-independent data file format for loudspeaker performance that holds directional (polar/balloon) data, on-axis response and sensitivity, so a loudspeaker can be represented in acoustic prediction software. It is maintained by the CLF Group; CLF is the group''s format name.','This is a standard computer file for loudspeaker data. It stores how a speaker aims sound in every direction. Design software reads the file. Engineers then predict coverage in a room before installing.','It provides one consistent, vendor-neutral way to share measured loudspeaker directivity so different modeling programs can use the same data.','A system designer imports a manufacturer''s CLF file into room-modeling software to predict coverage and sound pressure level before installing a line array in a venue.','Loudspeaker Data Format',ARRAY['Compression driver directivity','Cardioid response','Directivity index','Diffuse-field frequency response','Sound pressure level']::text[],ARRAY['Assuming CLF data removes the need for on-site measurement and tuning.','Thinking every loudspeaker brand publishes CLF files, since support varies.','Ignoring the data resolution grade, which affects prediction accuracy.']::text[],ARRAY['Modeling a large-venue PA design before purchase.','Comparing coverage of competing loudspeakers on equal data.','Importing directivity data into acoustic simulation software.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Common Loudspeaker Format');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a37ab1f1-dc71-4676-bd93-0356864f4aa9','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a37ab1f1-dc71-4676-bd93-0356864f4aa9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a37ab1f1-dc71-4676-bd93-0356864f4aa9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ba5ae164-6651-4181-a3ac-48de543aa394','Complex sound source','A sound source that cannot be treated as a single simple (point) radiator because it comprises several partial sources, is physically large, or radiates a non-uniform, direction-dependent field. In noise measurement it is characterized over a measurement surface using multiple positions rather than assuming point-source spreading.','Some sources are not a single small point. A big machine radiates sound from many parts. This makes its sound field uneven. Engineers must measure it from several positions.','The concept warns that simple point-source math and single-point readings can misrepresent large or multi-part sources.','To rate a large printing press, a technician measures over an enclosing surface at many points and averages, instead of using one distance and the inverse-square law.','Sound Source',ARRAY['Emission sound pressure level','Sound power level','Near field','Free field','Building service noise']::text[],ARRAY['Applying inverse-square (point-source) roll-off to a large source in its near field.','Taking one microphone position as representative of a directional source.','Confusing a physically large source with one that is merely loud.']::text[],ARRAY['Measuring the sound power of industrial machinery.','Assessing noise from an HVAC plant with several fans.','Choosing a measurement distance for a large loudspeaker cluster.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Complex sound source');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ba5ae164-6651-4181-a3ac-48de543aa394','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ba5ae164-6651-4181-a3ac-48de543aa394') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ba5ae164-6651-4181-a3ac-48de543aa394');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '62773d88-19d9-40a3-b3a2-2ad226ea47ea','Compression driver directivity','The way a horn-loaded compression driver concentrates its acoustic output into a controlled angular pattern, governed mainly by the coupled horn or waveguide geometry. Coverage typically narrows as frequency rises, which constant-directivity horn designs aim to keep uniform.','A compression driver feeds sound into a horn. The horn controls where the high frequencies go. Higher notes tend to beam more narrowly. Good horns keep the coverage even.','Directivity control lets a loudspeaker aim high-frequency energy at the audience and away from walls, improving clarity and gain before feedback.','A technician picks a 60-by-40 degree horn on a compression driver so the array covers the seating without splashing highs onto reflective side walls.','Loudspeaker Directivity',ARRAY['Common Loudspeaker Format','Cardioid response','Directivity index','Diffuse-field frequency response','Waveguide']::text[],ARRAY['Assuming the driver alone sets directivity and ignoring the horn''s dominant role.','Expecting a constant coverage angle across the whole frequency range.','Confusing high sensitivity with wide, even coverage.']::text[],ARRAY['Choosing a horn coverage angle for a room.','Explaining high-frequency beaming in a PA design.','Comparing constant-directivity horns for an installation.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Compression driver directivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '62773d88-19d9-40a3-b3a2-2ad226ea47ea','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='62773d88-19d9-40a3-b3a2-2ad226ea47ea') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='62773d88-19d9-40a3-b3a2-2ad226ea47ea');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bdd2c8ac-9385-45a6-8d2b-216250efcfe4','Continuous descending method','A psychophysical threshold procedure (a descending series of the method of limits) in which a stimulus is presented clearly above threshold and its level is then reduced, continuously or in small steps, until the listener no longer detects it. The reversal level estimates the detection threshold, contrasting with the ascending method.','This is a way to find the softest sound a person can hear. The test starts with a clear, easy tone. The level then drops step by step. The point where the tone vanishes marks the threshold.','It provides a controlled way to estimate a hearing or detection threshold by approaching it from above.','In a hearing test a technician lowers a 1 kHz tone in 5 dB steps from an audible level until the listener stops responding, noting that level as the descending threshold estimate.','Threshold Method',ARRAY['Hearing threshold','Pure-tone audiometry','Method of limits','Masking','Absolute threshold']::text[],ARRAY['Confusing the descending method with the more common ascending (Hughson-Westlake) method.','Ignoring that a descending series can give slightly lower thresholds from expectation or adaptation.','Assuming one reversal is enough rather than averaging several trials.']::text[],ARRAY['Determining a pure-tone hearing threshold.','Calibrating a psychoacoustic detection experiment.','Comparing threshold-seeking methods in a listening study.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Continuous descending method');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bdd2c8ac-9385-45a6-8d2b-216250efcfe4','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bdd2c8ac-9385-45a6-8d2b-216250efcfe4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bdd2c8ac-9385-45a6-8d2b-216250efcfe4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dfc21429-a74b-43ff-a096-03f82c19c90b','Core experiment','In the collaborative development of media coding standards (as run by ISO/IEC MPEG and ITU-T video/audio groups), a core experiment is a precisely defined, independently reproducible test used by multiple parties to evaluate a proposed coding tool against a common anchor under agreed conditions before it may be adopted.','Standards groups test new coding tools carefully. A core experiment is one agreed, shared test. Several teams run the exact same test. The results decide if a tool enters the standard.','It gives standards committees a fair, repeatable way to verify that a proposed tool truly improves performance before adoption.','An engineer contributing to an audio codec runs the committee''s defined core experiment, comparing bitrate and quality of a new tool against the reference model on the agreed test set.','Standardization Process',ARRAY['Coupled channel','Discrete cosine transform coefficient','Dynamic Range Control','Reference model','Bitstream']::text[],ARRAY['Thinking a core experiment is any informal test rather than a formally specified one.','Assuming positive results automatically guarantee adoption.','Confusing the reference anchor with the tool under test.']::text[],ARRAY['Evaluating a new tool for an MPEG audio standard.','Comparing coding efficiency during a video standard''s development.','Documenting reproducible test conditions for a committee.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Core experiment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dfc21429-a74b-43ff-a096-03f82c19c90b','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dfc21429-a74b-43ff-a096-03f82c19c90b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dfc21429-a74b-43ff-a096-03f82c19c90b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eb2c6263-ffe8-495d-8b3a-a2a6d2f72d50','Coupled channel','In perceptual audio coding, a coupling (coupled) channel is a shared high-frequency channel that carries a combined spectrum for two or more channels above a coupling frequency, with per-channel scale factors used to reconstruct each channel''s high band and save bits. It is used in codecs such as Dolby AC-3 and MPEG AAC.','Audio coders save data at high frequencies. They merge the top band of several channels into one. Each channel keeps only a level factor. The decoder rebuilds the highs from the shared channel.','Channel coupling lowers bitrate by exploiting that the ear localizes high frequencies mainly by envelope, so exact per-channel high-frequency detail can be shared.','A broadcast encoder at a low bitrate couples the surround channels above about 10 kHz, sending one high band plus coupling coordinates instead of a full spectrum for each channel.','Audio Coding',ARRAY['Dynamic Range Control','Core experiment','Discrete cosine transform coefficient','Dual-mono content','Bitrate']::text[],ARRAY['Assuming coupling is lossless for each individual channel.','Confusing channel coupling with simple downmixing to mono.','Thinking coupling affects the whole spectrum rather than only above the coupling frequency.']::text[],ARRAY['Encoding 5.1 audio at a constrained bitrate.','Troubleshooting high-frequency image shifts from aggressive coupling.','Explaining the structure of an AC-3 bitstream.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coupled channel');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eb2c6263-ffe8-495d-8b3a-a2a6d2f72d50','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eb2c6263-ffe8-495d-8b3a-a2a6d2f72d50') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eb2c6263-ffe8-495d-8b3a-a2a6d2f72d50');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2d1bb464-6d87-42f8-9206-bbfadfc575ca','Data-driven room correction','A room-correction approach that derives loudspeaker equalization from measured in-room responses (often many spatial samples or learned models) rather than from a fixed target filter, then applies digital filters to reduce the room''s effect at the listening area. It is a general DSP method rather than a single standardized term; commercial systems implement it in receivers and monitor controllers.','Rooms change how speakers sound. This method measures the sound in the room first. Software then builds filters from those measurements. The filters fix the room''s coloration at the listening spot.','It aims to flatten and time-align the sound a listener actually hears, compensating for room resonances and reflections using real measured data.','A technician runs automated sweeps from several seats; the system computes correction filters that tame a 60 Hz room mode by several dB at the mix position.','Room Correction',ARRAY['Diffuse-field equalization','Energy decay relief','Dead room','Impulse response','Sound pressure level']::text[],ARRAY['Expecting equalization to fix problems caused by strong early reflections or long decay.','Correcting at one point and degrading the response elsewhere in the room.','Boosting a deep null with large gain, which wastes headroom and can overdrive amplifiers.']::text[],ARRAY['Calibrating a home cinema with automated room EQ.','Setting up studio monitor correction.','Reducing a dominant low-frequency room mode.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Data-driven room correction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2d1bb464-6d87-42f8-9206-bbfadfc575ca','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2d1bb464-6d87-42f8-9206-bbfadfc575ca') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2d1bb464-6d87-42f8-9206-bbfadfc575ca');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5ce8638a-e2c9-41d7-b89f-3ba8cddd3aa8','Dead room','An informal term for a room with very high acoustic absorption and little audible reflected sound, so speech and music sound dry and lack liveliness. It has a short reverberation time and low reflected energy, approaching but less rigorously defined than an anechoic chamber.','A dead room soaks up almost all echoes. Sound seems flat and close. Your voice does not ring at all. It can feel like speaking into heavy padding.','The idea describes spaces such as vocal booths or over-treated rooms where reflections are minimized, useful when a very dry recording is wanted.','A technician records dialogue in a dead vocal booth to keep the take dry, then adds artificial reverb later to place it within a scene.','Room Acoustics',ARRAY['Dry sound','Reverberation time','Energy decay relief','Diffuse-field frequency response','Anechoic chamber']::text[],ARRAY['Equating a dead room with a calibrated anechoic chamber.','Assuming a dead room has no low-frequency problems, since bass can still build up.','Thinking ''dead'' means low background noise rather than low reverberation.']::text[],ARRAY['Recording dry dialogue for later processing.','Diagnosing an over-treated, lifeless-sounding studio.','Comparing live versus dead acoustic spaces.']::text[],'beginner',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dead room');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5ce8638a-e2c9-41d7-b89f-3ba8cddd3aa8','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5ce8638a-e2c9-41d7-b89f-3ba8cddd3aa8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5ce8638a-e2c9-41d7-b89f-3ba8cddd3aa8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b51df221-fe9d-4dc4-aa9b-c8bc3cd4210a','Depth of modulation','A measure of how strongly a carrier is modulated, expressed as the modulation index m. For amplitude modulation it equals the peak envelope deviation divided by the average, and can be written from envelope extremes as (A_max - A_min)/(A_max + A_min), often stated as a percentage. A value of 1 (100 percent) means the envelope just reaches zero at troughs.','Modulation changes a signal''s strength over time. Depth of modulation says how big that change is. Full depth means the level dips right down to zero. Small depth means only a gentle wobble.','It quantifies how deeply one signal varies another, which matters for AM transmission, tremolo effects and modulation test signals.','If a test tone swings the envelope between A_max=1.0 and A_min=0.2, then m=(1.0-0.2)/(1.0+0.2)=0.8/1.2, about 0.67, i.e. 67 percent depth.','Signal Modulation',ARRAY['Amplitude modulation','Modulation index','Sideband','Carrier signal','Tremolo']::text[],ARRAY['Confusing modulation depth with modulation frequency (the rate).','Allowing over 100 percent AM depth, which causes envelope distortion.','Mixing up the percentage form and the 0-to-1 form of the index.']::text[],ARRAY['Setting the depth control on a tremolo effect.','Checking an AM broadcast''s modulation percentage.','Generating a modulated test signal for measurement.']::text[],'intermediate','m = (A_max - A_min) / (A_max + A_min)','The modulation depth equals the peak envelope value minus the trough value, divided by their sum.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Depth of modulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b51df221-fe9d-4dc4-aa9b-c8bc3cd4210a','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b51df221-fe9d-4dc4-aa9b-c8bc3cd4210a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b51df221-fe9d-4dc4-aa9b-c8bc3cd4210a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '39d6c264-0ba3-42ac-9206-4bab59e277a3','Diffuse-field equalization','A headphone or earphone equalization target in which the device is adjusted so that its response, measured on an ear simulator, matches the response a listener''s ear would receive in a diffuse (reverberant, all-directions) sound field. It compensates for the ear and coupler transfer function so headphone timbre resembles neutral loudspeaker listening.','Headphones sit right on the ear, which changes their tone. Diffuse-field equalization tunes them to sound like a room full of reflected sound. It is one common headphone target. The goal is natural, balanced tone.','It gives a repeatable reference target so headphones can be voiced to resemble a neutral listening room rather than an arbitrary curve.','A technician compares a headphone''s measured curve to the diffuse-field target on a standard ear simulator, then applies EQ to correct a 3 kHz excess.','Headphone Equalization',ARRAY['Diffuse-field frequency response','Ear canal resonance','Data-driven room correction','Ear simulator','Free-field equalization']::text[],ARRAY['Treating the diffuse-field target as the only correct one, when free-field and preference targets differ.','Ignoring which ear-simulator standard was used, since it changes the curve.','Assuming a flat coupler response should sound neutral without any target.']::text[],ARRAY['Voicing studio reference headphones.','Comparing headphone target curves.','Explaining why ''flat'' headphones can sound bright.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diffuse-field equalization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '39d6c264-0ba3-42ac-9206-4bab59e277a3','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='39d6c264-0ba3-42ac-9206-4bab59e277a3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='39d6c264-0ba3-42ac-9206-4bab59e277a3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c057b916-1d84-43a3-84fd-e47b1440c5ba','Diffuse-field frequency response','The frequency response of a device measured for sound arriving equally from all directions (a diffuse field) rather than from a single frontal direction. For a measurement microphone it is the random-incidence response; for a headphone it is the response referenced to the diffuse-field target.','A diffuse field has sound coming from every direction. This response shows how a device reacts to that spread-out sound. It differs from the response to one frontal source. It matters for room mics and headphones.','It characterizes how a transducer behaves under realistic reverberant conditions where sound is not a single plane wave from the front.','A technician selects a measurement mic with flat diffuse-field (random-incidence) response for reverberant room measurements, rather than a free-field mic aimed at the source.','Frequency Response',ARRAY['Diffuse-field equalization','Random incidence','Free field','Ear simulator','Sound pressure level']::text[],ARRAY['Confusing free-field (frontal) and diffuse-field (random-incidence) microphone response.','Aiming a random-incidence mic directly at the source.','Assuming one response curve applies to both conditions.']::text[],ARRAY['Selecting a measurement mic for reverberant rooms.','Interpreting a headphone''s diffuse-field response.','Calibrating for random-incidence sound.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diffuse-field frequency response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c057b916-1d84-43a3-84fd-e47b1440c5ba','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c057b916-1d84-43a3-84fd-e47b1440c5ba') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c057b916-1d84-43a3-84fd-e47b1440c5ba');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6e802d4b-53ca-4fd7-8531-c207e291e329','Discrete cosine transform coefficient','One of the output values produced by a discrete cosine transform (DCT), representing the amplitude of a particular cosine basis function that, with the others, reconstructs a block of samples. The type-II DCT is widely used in audio and image/video coding because it concentrates signal energy into a few low-order coefficients.','The DCT breaks a block of samples into cosine waves. Each coefficient is the strength of one cosine. Most of the energy lands in a few low coefficients. Coders keep those and discard the rest.','DCT coefficients pack signal energy compactly, letting codecs quantize and drop less important components to compress audio, images and video.','In an MP3-style coder a technician quantizes small high-order (M)DCT coefficients more coarsely, saving bits while keeping the audible low-order coefficients accurate.','Signal Transform',ARRAY['Coupled channel','Dynamic Range Control','Core experiment','Fourier transform','Quantization']::text[],ARRAY['Confusing the DCT with the Fourier transform, though the DCT uses only real cosines.','Assuming coefficients map one-to-one onto musical pitches.','Forgetting that the k=0 (DC) coefficient represents the block''s average.']::text[],ARRAY['Understanding MP3/AAC or JPEG compression.','Analyzing energy compaction in a codec.','Explaining why compression discards fine detail.']::text[],'advanced','X_k = sum_{n=0}^{N-1} x_n * cos[ (pi/N)(n + 1/2) k ],  k = 0..N-1','The k-th coefficient is the sum over all samples of each sample times the cosine of pi over N times k times the sample index plus one half.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Discrete cosine transform coefficient');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6e802d4b-53ca-4fd7-8531-c207e291e329','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6e802d4b-53ca-4fd7-8531-c207e291e329') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6e802d4b-53ca-4fd7-8531-c207e291e329');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2251dc9f-ccfd-423c-bdaa-ae39e1b01608','Dispersion relation','The mathematical relationship between a wave''s angular frequency and its wavenumber, equivalently describing how phase speed varies with frequency. A medium is non-dispersive when omega = c*k (constant speed) and dispersive when phase speed depends on frequency, as for bending waves in plates.','A dispersion relation links a wave''s frequency to its wavelength. In air, all audio frequencies travel at the same speed. In some materials, high notes travel faster than low ones. That spreads a wave out over time.','It tells whether different frequencies travel at the same speed, which governs whether a wave keeps its shape or smears as it propagates.','Analyzing bending waves in a panel, a technician uses its dispersion relation to find that high frequencies travel faster, which sets the panel''s critical (coincidence) frequency.','Wave Propagation',ARRAY['Phase velocity','Group velocity','Wavenumber','Critical frequency','Displacement transducer']::text[],ARRAY['Assuming air is dispersive for audible sound, when it is essentially non-dispersive.','Confusing phase velocity with group velocity.','Treating omega = c*k as universal when it holds only for non-dispersive media.']::text[],ARRAY['Analyzing bending-wave radiation from panels.','Explaining why air preserves waveform shape over distance.','Studying dispersion in structural acoustics.']::text[],'advanced','omega = c*k  (non-dispersive);  generally omega = omega(k)','For a non-dispersive medium the angular frequency equals the wave speed times the wavenumber.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dispersion relation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2251dc9f-ccfd-423c-bdaa-ae39e1b01608','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2251dc9f-ccfd-423c-bdaa-ae39e1b01608') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2251dc9f-ccfd-423c-bdaa-ae39e1b01608');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a4cf9598-6306-472d-84d7-dc3a2a0b2215','Displacement transducer','A sensor that converts mechanical displacement (position or movement) into an electrical signal, using principles such as capacitive, inductive (LVDT), optical or piezoelectric sensing. In acoustics and vibration work it measures the displacement of a surface or structure, complementing velocity and acceleration transducers.','A displacement transducer is a sensor. It measures how far a thing has moved. It turns that shift into a voltage. Engineers use it to track how a part moves. It does not measure speed. It also does not measure acceleration.','It provides a direct electrical measure of position or vibration amplitude for analysis, control and calibration.','A technician mounts an LVDT-type displacement transducer on a shaker to verify that a driver cone''s peak excursion stays within its rated Xmax.','Transducer / Measurement',ARRAY['Dispersion relation','Accelerometer','Excursion','Laser vibrometer','Sound pressure level']::text[],ARRAY['Confusing displacement, velocity and acceleration outputs, which differ by factors of omega.','Ignoring that the transducer''s mass can load the surface under test.','Assuming a displacement sensor is best at high frequencies, where acceleration is often preferred.']::text[],ARRAY['Measuring loudspeaker cone excursion.','Monitoring structural vibration.','Calibrating a shaker system.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Displacement transducer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a4cf9598-6306-472d-84d7-dc3a2a0b2215','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a4cf9598-6306-472d-84d7-dc3a2a0b2215') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a4cf9598-6306-472d-84d7-dc3a2a0b2215');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5b67cf73-16e4-45ae-b0a1-cc0cd83d33a6','Dominant Frequency Region','In pitch perception, the frequency band whose harmonics contribute most strongly to the perceived pitch of a complex tone, typically the lower harmonics in the region of about 500 to 2000 Hz and strongest near 600 to 1000 Hz. The term is also used loosely for the band holding most of a signal''s energy.','A complex tone has many harmonics. Some matter more for the pitch we hear. The lower-middle harmonics dominate that judgment. This band is the dominant frequency region.','It explains why certain harmonics control perceived pitch, guiding pitch models and the understanding of complex-tone hearing.','When tracking the pitch of a bass instrument, a technician knows the ear locks mainly onto the lower harmonics (roughly the 600 to 1000 Hz region), not the fundamental alone.','Pitch Perception',ARRAY['Ear canal resonance','Duplex Theory','Fundamental frequency','Missing fundamental','Harmonic']::text[],ARRAY['Assuming the fundamental always dominates the perceived pitch.','Confusing the dominance region with the loudest part of the spectrum.','Treating the region as one fixed frequency rather than a band.']::text[],ARRAY['Explaining the missing-fundamental effect.','Designing a pitch-detection algorithm.','Understanding the perceived pitch of complex tones.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dominant Frequency Region');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5b67cf73-16e4-45ae-b0a1-cc0cd83d33a6','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5b67cf73-16e4-45ae-b0a1-cc0cd83d33a6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5b67cf73-16e4-45ae-b0a1-cc0cd83d33a6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0cea0485-09be-4f74-a7b0-e5d26e569e70','Dry sound','Sound that contains little or no added reverberation, reflections or effects, i.e. essentially the direct signal alone. A dry recording captures mainly the source''s direct field; the opposite is a wet (reverberant or effected) sound.','Dry sound has no echo or reverb added. It is just the direct signal. It sounds close and bare. Engineers add space to it later if needed.','The distinction lets engineers control apparent space and depth by balancing dry (direct) and wet (reverberant) signal.','A technician records a vocal dry in a treated booth, then blends in a reverb send to set how far back the voice sits in the mix.','Production Term',ARRAY['Dead room','Reverberation','Direct sound','Wet signal','Reverberation time']::text[],ARRAY['Confusing ''dry'' (no reverb) with ''thin'' or lacking bass.','Assuming dry means no processing at all, when EQ and compression can still apply.','Capturing too much room reverb and still calling it dry.']::text[],ARRAY['Recording to allow flexible reverb later.','Setting a dry/wet balance on an effect.','Describing a close, intimate vocal.']::text[],'beginner',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dry sound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0cea0485-09be-4f74-a7b0-e5d26e569e70','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0cea0485-09be-4f74-a7b0-e5d26e569e70') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0cea0485-09be-4f74-a7b0-e5d26e569e70');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '27594bf6-758b-45bf-a602-e8a6f8b3c4ad','Dual-mono content','Audio carried on two channels that hold identical (or intended-identical) monophonic signals, so left and right are the same. It commonly arises when a mono source is placed on a stereo carrier, and differs from true stereo, which carries different left and right signals.','Dual-mono means two channels carry the same sound. Left and right are identical. It is really mono on a stereo pair. True stereo would send different signals to each side.','It lets a mono program travel on a stereo path and play correctly from either channel, keeping playback compatible.','A technician checks a file''s channels: if summing to mono causes no change and the correlation reads +1, the content is dual-mono, not stereo.','Channel Configuration',ARRAY['Coupled channel','Stereo','Mono compatibility','Phase correlation','Downmix']::text[],ARRAY['Assuming two channels always mean stereo.','Panning dual-mono and expecting a stereo image.','Ignoring that identical channels sum about 6 dB higher when combined.']::text[],ARRAY['Checking a delivery for accidental dual-mono.','Routing a mono mic onto a stereo bus.','Verifying broadcast channel content.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dual-mono content');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '27594bf6-758b-45bf-a602-e8a6f8b3c4ad','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='27594bf6-758b-45bf-a602-e8a6f8b3c4ad') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='27594bf6-758b-45bf-a602-e8a6f8b3c4ad');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e50e952d-c17a-4aa5-bb81-99c7a6279b41','Duplex Theory','Lord Rayleigh''s theory that human horizontal sound localization relies on two complementary cues: interaural time differences, dominant at low frequencies, and interaural level differences, dominant at high frequencies where the head shadows sound. The crossover lies near 1.5 kHz, where the head size is comparable to the wavelength.','We locate sound using two ear cues. Low sounds reach each ear at slightly different times. High sounds are louder in the nearer ear. The brain combines both. This is the duplex theory.','It explains how listeners judge left-right direction and underlies stereo, binaural and spatial-audio techniques.','Creating a binaural mix, a technician applies small inter-ear delays for low frequencies and level differences for highs to steer a source''s apparent direction.','Spatial Hearing',ARRAY['Dominant Frequency Region','Ear canal resonance','Interaural time difference','Interaural level difference','Diffuse-field equalization']::text[],ARRAY['Thinking level difference alone explains all localization.','Ignoring that time and level cues dominate different frequency ranges.','Assuming the duplex theory resolves front-back or vertical confusions, which it does not.']::text[],ARRAY['Designing binaural or stereo panning.','Explaining why simple headphone panning images inside the head.','Teaching the basics of sound localization.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Duplex Theory');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e50e952d-c17a-4aa5-bb81-99c7a6279b41','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e50e952d-c17a-4aa5-bb81-99c7a6279b41') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e50e952d-c17a-4aa5-bb81-99c7a6279b41');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bcac66a3-5581-4d06-b95a-9ff0bde8778b','Duration model','In speech synthesis and prosody, a duration model predicts how long each phonetic segment (phone or syllable) should last, from its linguistic context, so that synthesized speech has natural timing and rhythm. Implementations range from rule-based to statistical and neural approaches.','Speech has timing and rhythm. A duration model decides how long each sound lasts. It uses context like stress and position. This keeps synthetic speech from sounding robotic.','It controls the timing of synthetic speech, a key part of natural-sounding prosody in text-to-speech systems.','In a text-to-speech engine, a technician trains a duration model so stressed vowels are lengthened, making the output rhythm sound human.','Speech Synthesis',ARRAY['Prosody','Fundamental frequency','Phoneme','Formant','Speaking rate']::text[],ARRAY['Confusing per-segment duration with overall speaking rate.','Ignoring context and giving every phone the same length.','Assuming duration is independent of stress and phrase position.']::text[],ARRAY['Building a text-to-speech voice.','Tuning prosody for naturalness.','Aligning synthetic speech to a timing constraint.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Duration model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bcac66a3-5581-4d06-b95a-9ff0bde8778b','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bcac66a3-5581-4d06-b95a-9ff0bde8778b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bcac66a3-5581-4d06-b95a-9ff0bde8778b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9fdfd24d-d82a-43db-807f-1c2e703aeb75','Dynamic Range Control','A metadata-driven or processing method that alters a signal''s dynamic range by applying time-varying gain, typically to reduce loud-soft differences for constrained playback such as night listening or small speakers. In modern codecs (ATSC/AC-3, MPEG-D DRC per ISO/IEC 23003-4) gain sequences are carried as metadata and applied at the decoder.','Loud and quiet parts differ a lot in a mix. Dynamic range control shrinks that gap. It lifts quiet parts or lowers loud ones. This helps listening in cars or at night.','It lets one program suit many listening situations by optionally compressing its dynamics at playback, without re-mastering.','A viewer enabling night mode triggers DRC metadata in the AC-3 stream, so the decoder attenuates loud effects and lifts quiet dialogue.','Loudness / Metadata',ARRAY['Loudness normalization','Compressor','Integrated loudness','Night mode','Metadata']::text[],ARRAY['Confusing DRC metadata with permanent compression baked into the mix.','Assuming DRC and loudness normalization are the same thing.','Thinking DRC is always applied, when it is optional at the decoder.']::text[],ARRAY['Enabling night mode on a receiver.','Authoring broadcast audio with DRC profiles.','Explaining why the same file sounds different across devices.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dynamic Range Control');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9fdfd24d-d82a-43db-807f-1c2e703aeb75','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9fdfd24d-d82a-43db-807f-1c2e703aeb75') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9fdfd24d-d82a-43db-807f-1c2e703aeb75');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e3c4e423-dfdb-4070-b204-c185bcf09f48','Ear canal resonance','The acoustic resonance of the ear canal, which behaves roughly as a tube closed at the eardrum and open at the entrance, giving a quarter-wavelength resonance that boosts sound around 2 to 3 kHz (commonly cited near 2.7 kHz). This resonance raises hearing sensitivity in that band.','The ear canal is a short tube closed at the eardrum. Like an organ pipe, it resonates. This lifts sounds around 2 to 3 kHz. It helps us hear speech consonants.','The resonance increases sensitivity in the 2 to 3 kHz range, shaping the ear''s frequency response and headphone or earphone target curves.','Using f=c/(4L) with L about 0.025 m gives 343/(4*0.025), about 3.4 kHz; the measured peak sits lower (near 2.7 kHz) because the effective length is greater, which a technician accounts for when setting earphone EQ.','Auditory Acoustics',ARRAY['Diffuse-field equalization','Duplex Theory','Dominant Frequency Region','Ear simulator','Pinna gain']::text[],ARRAY['Treating the roughly 2.7 kHz peak as identical for everyone, since canal length varies.','UNSAFE: assuming the canal resonance makes 2 to 3 kHz safe to boost loudly, when sustained high sound levels there still risk hearing damage.','Ignoring that inserting an earphone changes the canal''s effective length and its resonance.']::text[],ARRAY['Explaining the ear''s 2 to 3 kHz sensitivity peak.','Setting earphone or hearing-aid frequency response.','Understanding real-ear measurements.']::text[],'intermediate','f ~= c / (4*L)','The first resonance frequency is the speed of sound divided by four times the effective canal length.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ear canal resonance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e3c4e423-dfdb-4070-b204-c185bcf09f48','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e3c4e423-dfdb-4070-b204-c185bcf09f48') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e3c4e423-dfdb-4070-b204-c185bcf09f48');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8a880f10-58cb-40d0-97f5-da07b2873a4f','Effective perceived noise level','A single-number rating of aircraft flyover noise, in EPNdB, that starts from the maximum tone-corrected perceived noise level and adds a duration correction, so it accounts for spectral tones and how long the event lasts. It is the noise-certification metric in ICAO Annex 16 and FAA regulations.','Aircraft noise gets one score for certification. It starts from how annoying the tones sound. It then adds how long the flyover lasts. The result is measured in EPNdB.','It provides a perceptually weighted, duration-aware noise measure so aircraft can be certified against legal noise limits.','For a flyover with PNLTM=95 TPNdB and a duration correction D=+2 dB, EPNL=97 EPNdB, which a technician compares to the aircraft''s certification limit.','Aircraft Noise Metric',ARRAY['Emission sound pressure level','Building service noise','A-weighting','Perceived noise level','Tone correction']::text[],ARRAY['Confusing EPNL with a simple A-weighted level.','Forgetting the tone correction, which penalizes audible pure tones.','Ignoring the duration correction for longer events.']::text[],ARRAY['Certifying an aircraft type for noise.','Comparing the flyover noise of two aircraft.','Explaining airport noise limits.']::text[],'advanced','EPNL = PNLTM + D','The effective perceived noise level equals the maximum tone-corrected perceived noise level plus a duration correction.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Effective perceived noise level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8a880f10-58cb-40d0-97f5-da07b2873a4f','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8a880f10-58cb-40d0-97f5-da07b2873a4f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8a880f10-58cb-40d0-97f5-da07b2873a4f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '97846a8f-1dff-43a1-812e-d5a2a3f2e2e9','Emission sound pressure level','The sound pressure level produced by a specific machine or equipment item at a defined position (typically the operator''s work station), determined under standardized essentially-free-field conditions over a reflecting plane with background and environmental corrections. It is defined and measured per ISO 11201 and referenced to 20 micropascals.','This is how loud one machine is at the operator''s spot. It is measured in a set, repeatable way. Background noise and reflections are corrected out. The result rates the machine''s own noise.','It gives a comparable, machine-specific noise figure for labeling, purchasing decisions and worker-exposure assessment.','Following ISO 11201, a technician measures p=0.2 Pa at the work station; L_pA=10*log10((0.2)^2/(20e-6)^2)=10*log10(1e8)=80 dB.','Machinery Noise',ARRAY['Building service noise','Complex sound source','Sound power level','Sound pressure level','A-weighting']::text[],ARRAY['Confusing emission sound pressure level (at a position) with sound power level (total radiated).','Forgetting the background-noise and environmental corrections.','Assuming it equals a worker''s daily noise exposure.']::text[],ARRAY['Declaring machinery noise on a datasheet.','Comparing two machines'' operator-position noise.','Assessing noise sources in a workshop.']::text[],'intermediate','L_pA = 10*log10( p_A^2 / p_0^2 )','The A-weighted emission level is ten times the base-ten logarithm of the squared A-weighted sound pressure divided by the squared reference pressure.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Emission sound pressure level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '97846a8f-1dff-43a1-812e-d5a2a3f2e2e9','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='97846a8f-1dff-43a1-812e-d5a2a3f2e2e9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='97846a8f-1dff-43a1-812e-d5a2a3f2e2e9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ce4531f0-2e0f-466c-a748-40eaacad1f46','Energy decay relief','A time-frequency representation of how sound energy decays in an impulse response, generalizing Schroeder''s energy decay curve to multiple frequency bands. Introduced by Jot, it shows the remaining energy at each time and frequency, revealing frequency-dependent reverberation decay.','Reverb fades over time. But high and low notes can fade at different rates. Energy decay relief shows the decay at each frequency and time. It is a map of how the tail dies away.','It lets engineers see and design frequency-dependent decay, improving reverberation analysis and artificial-reverb tuning.','A technician computes the energy decay relief of a hall impulse response, sees the highs decaying faster than the lows, and then tunes a reverb''s damping filters to match.','Reverberation Analysis',ARRAY['Dead room','Data-driven room correction','Reverberation time','Schroeder integration','Impulse response']::text[],ARRAY['Confusing the energy decay relief (time-frequency) with the single-band energy decay curve.','Ignoring window length, which trades time against frequency resolution.','Reading one decay time when the decay is frequency-dependent.']::text[],ARRAY['Analyzing frequency-dependent reverberation.','Tuning an algorithmic reverb''s damping.','Characterizing a hall''s impulse response.']::text[],'advanced','EDR(t_n, f_k) = sum_{m>=n} | H(m, k) |^2','The energy decay relief at a time and frequency is the sum, over all later time frames, of the squared magnitude of that frequency bin in the short-time Fourier transform.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Energy decay relief');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ce4531f0-2e0f-466c-a748-40eaacad1f46','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ce4531f0-2e0f-466c-a748-40eaacad1f46') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ce4531f0-2e0f-466c-a748-40eaacad1f46');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '446167f9-ef26-4459-8e71-da4927d481aa','Equal-temperament deviation','Equal-temperament deviation is the difference, expressed in cents, between a sounding pitch''s frequency and the nearest note of the twelve-tone equal-tempered scale referenced to a standard concert pitch. One cent is one hundredth of an equal-tempered semitone, so an octave spans 1200 cents.','Equal temperament splits the octave into twelve equal steps. Each step is a semitone, worth 100 cents. This deviation shows how far a pitch sits from the nearest step. It is measured in cents, a fine pitch unit.','It quantifies tuning error in a scale-independent way so intonation can be compared, corrected, or logged precisely.','A tuner reading a violin A at 445 Hz against A4 = 440 Hz shows about +19.6 cents sharp (1200*log2(445/440)), prompting the player to lower the pitch.','Pitch/tuning',ARRAY['Fundamental-frequency contour','Instantaneous frequency','Frequency-following response']::text[],ARRAY['Assuming cents are a fixed number of hertz; a cent is a ratio, so its hertz size grows with frequency.','Confusing equal temperament with just intonation, whose intervals differ by several cents.','Forgetting that the reference pitch (e.g. A4 = 440 Hz) must be stated for the deviation to mean anything.']::text[],ARRAY['Calibrating an electronic tuner or auto-tune plug-in.','Assessing intonation in a recorded vocal take.','Comparing historical tunings against modern concert pitch.']::text[],'intermediate','n = 1200 * log2(f / f_ref)','The deviation in cents equals twelve hundred times the base-two logarithm of the measured frequency divided by the equal-tempered reference frequency.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Equal-temperament deviation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '446167f9-ef26-4459-8e71-da4927d481aa','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='446167f9-ef26-4459-8e71-da4927d481aa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='446167f9-ef26-4459-8e71-da4927d481aa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '71c1c2e0-be4e-458f-9194-ff21b526e5ac','Equivalent continuous sound level','The equivalent continuous sound level (Leq) is the steady A-weighted sound pressure level that would deliver the same total sound energy as a fluctuating sound over a stated measurement period. It is computed from the time-average of the squared, frequency-weighted sound pressure relative to the reference pressure of 20 micropascals.','Real noise goes up and down over time. Leq is the single steady level with the same energy. It sums the sound''s energy over a set time. Louder moments count far more than quiet ones.','It reduces time-varying noise to one energy-based number so exposure and environmental noise can be assessed and compared.','A workshop at 80 dB(A) for half a shift and 86 dB(A) for the other half gives Leq = 10*log10((10^8.0 + 10^8.6)/2) ~= 84 dB(A).','Noise metric',ARRAY['Fast time weighting','Impulsive noise','Exposure action value']::text[],ARRAY['UNSAFE: Treating a moderate Leq as proof of safety, when brief high-level peaks in the same period can still injure hearing.','Averaging decibels arithmetically instead of on an energy (antilog) basis.','Reporting Leq without its time period or frequency weighting, which makes the value ambiguous.']::text[],ARRAY['Documenting daily noise dose in a workshop.','Measuring environmental noise near a venue for a permit.','Comparing crowd noise across concert nights.']::text[],'intermediate','L_eq,T = 10 * log10( (1/T) * integral_0^T [ p_A^2(t) / p_0^2 ] dt )','The equivalent level equals ten times the base-ten logarithm of the time-averaged squared A-weighted sound pressure divided by the squared reference pressure.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Equivalent continuous sound level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '71c1c2e0-be4e-458f-9194-ff21b526e5ac','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='71c1c2e0-be4e-458f-9194-ff21b526e5ac') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='71c1c2e0-be4e-458f-9194-ff21b526e5ac');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b6f78590-d755-4bfd-988b-f20baba294b5','Error concealment','Error concealment is a set of techniques in a digital audio system that masks the audible effect of data that cannot be corrected, after error detection and correction have failed. Typical methods interpolate across lost samples or briefly mute, so a defect is hidden rather than reproduced as a click or dropout.','Digital audio can lose or corrupt data. First the system tries to correct it. When correction fails, concealment hides the gap. It may estimate missing samples or briefly mute. The listener hears little or no glitch.','It preserves subjective audio quality when uncorrectable errors remain, avoiding harsh clicks, dropouts, or noise bursts.','A CD scratched beyond the reach of its Cross-Interleaved Reed-Solomon Code has the lost samples interpolated, so playback continues smoothly instead of clicking.','Digital audio',ARRAY['Fixed-point audio sample','Error correction','Cross-interleaved Reed-Solomon code','Impulsive noise']::text[],ARRAY['Confusing error concealment (hides uncorrectable errors) with error correction (actually restores the data).','Assuming concealed audio is bit-perfect; it is an approximation, not the original.','Believing concealment can hide long dropouts; it only works for short, sparse losses.']::text[],ARRAY['Playing a scratched CD without audible clicks.','Streaming audio over a lossy network with occasional packet loss.','Recovering a digital tape with dropouts.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Error concealment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b6f78590-d755-4bfd-988b-f20baba294b5','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b6f78590-d755-4bfd-988b-f20baba294b5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b6f78590-d755-4bfd-988b-f20baba294b5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '55e60473-f470-4555-a71d-4e0f97f538b6','Exposure action value','An exposure action value is a daily or weekly noise exposure level at which occupational-noise regulations require specific employer actions. Under the EU Physical Agents (Noise) Directive and the UK Control of Noise at Work Regulations, the lower action value is a daily exposure of 80 dB(A) and the upper action value is 85 dB(A), each with an associated C-weighted peak sound pressure criterion.','Loud workplaces must protect workers'' hearing. Action values are trigger levels for the employer. At 80 dB(A) daily, the lower value, information and hearing protection must be offered. At 85 dB(A), the upper value, controls and protection zones become required.','It sets legally defined thresholds that force graded hearing-protection measures as workplace noise rises.','A live-sound engineer whose daily A-weighted exposure reaches 85 dB(A) must be in a marked hearing-protection zone with protectors provided and worn.','Hearing safety',ARRAY['Equivalent continuous sound level','Impulsive noise','Fast time weighting']::text[],ARRAY['UNSAFE: Assuming the lower action value needs no protection; hearing damage still accumulates below 85 dB(A) over long shifts.','UNSAFE: Treating the action value as a safe ceiling rather than a trigger for control measures.','Confusing the exposure action values (80/85 dB(A)) with the higher exposure limit value of 87 dB(A), which is assessed inside the hearing protector.','Ignoring the separate C-weighted peak criterion for sudden, impulsive sounds.']::text[],ARRAY['Assessing a factory floor for a noise-control programme.','Setting up hearing-protection zones at a concert.','Auditing a drummer''s or DJ''s daily noise dose.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Exposure action value');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '55e60473-f470-4555-a71d-4e0f97f538b6','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='55e60473-f470-4555-a71d-4e0f97f538b6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='55e60473-f470-4555-a71d-4e0f97f538b6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '767c82e9-cafb-4109-9717-0c80bbb7b25f','Extended stereo image','An extended (or widened) stereo image is a perceived stereo scene that appears broader than the physical loudspeaker span, produced by processing that manipulates inter-channel level, phase, or delay differences and the mid/side balance. Common techniques boost the side (difference) signal or add cross-channel, phase-inverted components.','A stereo image is where sounds seem to sit between two speakers. Widening makes that image feel broader than the speakers. It alters the differences between left and right. Overdone, it can hurt mono compatibility.','It creates a more spacious, enveloping soundstage on stereo playback for mixing, mastering, and consumer enhancement.','A mastering engineer raises the side signal in a mid/side processor to widen a mix, then checks it in mono to confirm the centre stays intact.','Stereo imaging',ARRAY['Mid/side processing','First-wavefront law','External-ear transfer function']::text[],ARRAY['Widening by phase inversion that collapses or hollows the sound when the mix sums to mono.','Assuming wider always sounds better; excess width smears the centre image and vocals.','Confusing loudspeaker-based widening with binaural width, which depends on headphones and HRTFs.']::text[],ARRAY['Mastering a track for streaming.','Enhancing a narrow stereo recording.','Checking a widened mix for mono compatibility on a phone speaker.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Extended stereo image');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '767c82e9-cafb-4109-9717-0c80bbb7b25f','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='767c82e9-cafb-4109-9717-0c80bbb7b25f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='767c82e9-cafb-4109-9717-0c80bbb7b25f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '09871dbf-dfe3-4ef7-9dc2-d89f1bb7db5d','External-ear transfer function','The external-ear transfer function describes how the outer ear — pinna, concha, and ear canal — filters incoming sound on its way to the eardrum, as a frequency- and direction-dependent ratio of eardrum pressure to free-field pressure. It supplies the direction-dependent spectral cues embodied in the head-related transfer function.','The outer ear shapes sound before it reaches the eardrum. Its folds and canal boost some frequencies. This shaping depends on the sound''s direction. It gives the brain cues about where sound comes from.','It captures the acoustic filtering of the outer ear that provides spectral localization cues, especially for elevation and front/back.','A binaural-audio designer includes the outer-ear response in HRTF measurements so headphone playback recreates convincing elevation cues.','Psychoacoustics',ARRAY['Free-field method','Frequency Selectivity','First-wavefront law','Extended stereo image']::text[],ARRAY['Treating the outer-ear response as flat; the concha and canal add strong, direction-dependent peaks near 2-4 kHz.','Confusing it with the middle-ear transfer function, which lies past the eardrum.','Assuming one generic response fits everyone; outer-ear filtering is individual.']::text[],ARRAY['Measuring HRTFs for a virtual-reality audio engine.','Designing headphone equalization.','Studying sound-localization cues in psychoacoustics.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='External-ear transfer function');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '09871dbf-dfe3-4ef7-9dc2-d89f1bb7db5d','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='09871dbf-dfe3-4ef7-9dc2-d89f1bb7db5d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='09871dbf-dfe3-4ef7-9dc2-d89f1bb7db5d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '86cf2bb8-7d7f-4fee-a5a6-4f9574115641','Far-field criterion','The far-field criterion states the conditions under which a receiver lies in a source''s far field, where the sound pressure level falls by about 6 dB for each doubling of distance and the wave is locally plane. The distance must greatly exceed the wavelength, the largest source dimension, and that dimension squared divided by the wavelength.','Close to a source, sound behaves in complex ways. Far enough away, it simplifies. There, each doubling of distance drops the level by 6 decibels. The far field starts well beyond the wavelength and the source size.','It tells a measurer how far to stand so free-field inverse-distance behaviour holds and readings are repeatable.','For a 0.3 m loudspeaker at 1 kHz (wavelength ~ 0.34 m), D^2/lambda ~= 0.26 m, so measuring at 2 m places the mic well into the far field, where SPL drops 6 dB per doubling.','Sound field',ARRAY['Free-field method','First-arrival time','Half-power bandwidth']::text[],ARRAY['Measuring too close, in the near field, where level does not follow the inverse-distance law.','Using a single fixed distance for all frequencies; the far-field onset moves with wavelength.','Confusing the acoustic far field with simple line-of-sight distance.']::text[],ARRAY['Choosing a microphone distance for loudspeaker frequency-response measurement.','Verifying inverse-square behaviour outdoors.','Placing a reference mic for a sound-power test.']::text[],'advanced','r >> lambda,  r >> D,  and  r >> D^2 / lambda','The measuring distance must be much greater than the wavelength, than the largest source dimension, and than that dimension squared divided by the wavelength.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Far-field criterion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '86cf2bb8-7d7f-4fee-a5a6-4f9574115641','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='86cf2bb8-7d7f-4fee-a5a6-4f9574115641') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='86cf2bb8-7d7f-4fee-a5a6-4f9574115641');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f757de03-d913-4ac4-b14f-2236318c3377','Fast time weighting','Fast (F) time weighting is a standardized exponential time-averaging applied to the squared sound pressure in a sound level meter, using a time constant of 125 ms. It makes the displayed level respond quickly to short sounds, in contrast with the 1 s Slow (S) weighting.','A sound level meter must smooth a jumpy signal. Fast weighting smooths it only a little. It uses a 125-millisecond time constant. So the reading reacts quickly to short sounds.','It defines a repeatable meter response speed so brief level changes are captured consistently between instruments.','Reading a snare hit on Fast shows a higher, quicker value than Slow, helping an engineer judge short transients during a soundcheck.','Measurement',ARRAY['Equivalent continuous sound level','Impulsive noise','Field calibration']::text[],ARRAY['Comparing readings without stating Fast or Slow; the two disagree on fluctuating sound.','Expecting Fast to capture true peaks; peak hold, not time weighting, measures the instantaneous maximum.','Assuming Fast and Slow differ on steady sound; they agree once the level is constant.']::text[],ARRAY['Setting a sound level meter for live-sound monitoring.','Comparing meter settings during a noise survey.','Judging transients at a soundcheck.']::text[],'intermediate','L_F(t) = 10 * log10( (1/(tau*p_0^2)) * integral_{-inf}^{t} p_A^2(x) * e^{-(t-x)/tau} dx ),  tau = 0.125 s','The Fast level exponentially averages past squared sound pressure with a time constant of 0.125 seconds, then expressed in decibels.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fast time weighting');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f757de03-d913-4ac4-b14f-2236318c3377','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f757de03-d913-4ac4-b14f-2236318c3377') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f757de03-d913-4ac4-b14f-2236318c3377');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '393df460-0b9f-4394-9bec-447fb9c5b4a9','Feature-space maximum-likelihood linear regression','Feature-space maximum-likelihood linear regression (fMLLR), also called constrained MLLR, is a speaker- or environment-adaptation method for hidden Markov model speech recognizers. It estimates a single affine transform — a matrix and offset — applied to the acoustic feature vectors to maximize the likelihood of adaptation data under the existing model.','Speech recognizers work better when tuned to a talker. This method learns one linear transform per talker. It reshapes the sound features, not the model. That shift makes the features match the model better.','It adapts a general acoustic model to a new speaker or channel using little data, improving recognition accuracy.','A 39-dimensional MFCC feature vector is multiplied by an estimated 39x39 matrix and shifted by an offset, adapting the recognizer to one speaker''s voice.','Speech recognition',ARRAY['Gaussian mixture model','Fundamental-frequency contour','Frequency-warping']::text[],ARRAY['Confusing feature-space MLLR (transforms the features) with model-space MLLR (transforms the model means).','Estimating the transform on too little data, which overfits and hurts accuracy.','Assuming one global transform suits every phoneme; regression classes may be needed.']::text[],ARRAY['Adapting a dictation system to a new user.','Compensating for a different microphone or room.','Speaker normalization in a recognition pipeline.']::text[],'advanced','x_hat = A * x + b','Each feature vector is transformed by one estimated matrix and shifted by one estimated offset vector.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Feature-space maximum-likelihood linear regression');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '393df460-0b9f-4394-9bec-447fb9c5b4a9','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='393df460-0b9f-4394-9bec-447fb9c5b4a9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='393df460-0b9f-4394-9bec-447fb9c5b4a9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6289d530-13cf-4860-8872-b597f5260086','Field calibration','Field calibration is the on-site check and adjustment of a sound measurement system''s sensitivity using a portable acoustic calibrator that delivers a known sound pressure level, typically 94 dB at 1 kHz, immediately before and after measurements. It verifies the whole chain — microphone, meter, and settings — under actual conditions.','A sound level meter can drift. Field calibration checks it on site. A small calibrator feeds a known level into the mic. The technician sets the meter to read that level. It is checked again after measuring.','It confirms measurement accuracy at the point of use, catching sensitivity drift or faults before data is trusted.','Before a noise survey, an engineer fits a 94 dB, 1 kHz calibrator over the microphone and adjusts the meter to read 94.0 dB.','Measurement',ARRAY['Fast time weighting','Free-field method','Equivalent continuous sound level']::text[],ARRAY['Skipping the post-measurement check, so an undetected drift invalidates the whole survey.','Using a calibrator that does not match the microphone diameter, giving a level error.','Confusing this quick field check with full laboratory calibration traceable to national standards.']::text[],ARRAY['Starting and ending an occupational noise survey.','Verifying a meter before an environmental measurement.','Documenting calibration for a compliance report.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Field calibration');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6289d530-13cf-4860-8872-b597f5260086','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6289d530-13cf-4860-8872-b597f5260086') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6289d530-13cf-4860-8872-b597f5260086');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ab39e812-eb8d-4e5b-ab82-721c1c7462e2','First-arrival time','The first-arrival time is the instant at which the direct sound from a source first reaches a receiver, before any reflections. In room-acoustic impulse-response measurements it marks the onset of the direct-sound peak and serves as the time reference for later reflections and reverberation.','Sound from a source reaches you by the shortest path first. That moment is the first-arrival time. Reflections from walls come later. It sets the zero point for measuring echoes.','It provides the timing reference that separates direct sound from reflections and anchors delay and reverberation analysis.','In an impulse response, an engineer marks the first-arrival peak, then measures the initial time-delay gap to the first strong reflection.','Room acoustics',ARRAY['First-wavefront law','Free-field method','Far-field criterion']::text[],ARRAY['Mistaking an early strong reflection for the direct sound in a reverberant measurement.','Ignoring the propagation delay when aligning multiple microphones.','Assuming the first arrival is always the loudest; a later reflection can exceed it.']::text[],ARRAY['Time-aligning loudspeakers in a system tuning.','Measuring a room impulse response.','Setting delay on a distributed speaker system.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='First-arrival time');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ab39e812-eb8d-4e5b-ab82-721c1c7462e2','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ab39e812-eb8d-4e5b-ab82-721c1c7462e2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ab39e812-eb8d-4e5b-ab82-721c1c7462e2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'be8a9894-c490-4f63-a868-9839b4794585','First-wavefront law','The law of the first wavefront (the precedence, or Haas, effect) states that when the same sound arrives from several directions within roughly 1-40 ms, the listener localizes it toward the first-arriving wavefront, and later arrivals are largely not heard as separate sources. Delays beyond about 40 ms tend to be perceived as distinct echoes.','The same sound often reaches us from several directions. The first one to arrive sets where we hear it. Later copies within a few tens of milliseconds fuse with it. Much longer delays are heard as echoes.','It explains how the ear localizes sound in reflective spaces and underpins delay-based sound-system design.','A designer delays a nearer fill speaker so its sound arrives just after the main array, keeping the image on stage while adding loudness.','Psychoacoustics',ARRAY['First-arrival time','External-ear transfer function','Foldback level','Extended stereo image']::text[],ARRAY['Confusing the precedence effect with a simple loudness comparison; timing, not just level, sets localization.','Setting delay-fill offsets so large that distinct echoes appear.','Assuming the effect holds for very long delays; beyond about 40 ms echoes become audible.']::text[],ARRAY['Aligning delay-fill loudspeakers in a large venue.','Explaining why reflections do not usually confuse localization.','Designing distributed speech-reinforcement systems.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='First-wavefront law');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'be8a9894-c490-4f63-a868-9839b4794585','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='be8a9894-c490-4f63-a868-9839b4794585') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='be8a9894-c490-4f63-a868-9839b4794585');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '243bb68f-e210-49d3-ab7f-98e8de9e3364','Fixed-point audio sample','A fixed-point audio sample is a digital audio value represented as an integer (or a scaled integer with an implied binary point), such as 16- or 24-bit signed two''s-complement PCM, where the spacing between representable values is uniform. It contrasts with floating-point samples, whose step size scales with amplitude.','Digital audio stores each moment as a number. A fixed-point sample is an integer. Common sizes are 16 or 24 bits. Steps between values are all the same size. That differs from floating-point, whose steps grow with level.','It provides an efficient, hardware-friendly numeric format for storing and transporting PCM audio with a defined dynamic range.','A 16-bit fixed-point sample gives about 6.02*16 + 1.76 ~= 98 dB ideal dynamic range, so the engineer keeps peaks just below 0 dBFS to avoid hard clipping.','Digital audio',ARRAY['Error concealment','Pulse-code modulation','Quantization noise','Impulsive noise']::text[],ARRAY['Assuming fixed-point has the huge headroom of floating-point; fixed-point clips hard at full scale.','Confusing bit depth (dynamic range) with sample rate (bandwidth).','Thinking more bits raise loudness; they lower the noise floor instead.']::text[],ARRAY['Choosing 24-bit fixed-point for a recording session.','Exporting a master to 16-bit for CD.','Setting gain to avoid full-scale clipping.']::text[],'intermediate','DR ~= 6.02 * N + 1.76  (dB, ideal SQNR for full-scale sine, N-bit uniform PCM)','The ideal signal-to-quantization-noise ratio of an N-bit uniform sample is about six decibels per bit plus 1.76 decibels.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fixed-point audio sample');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '243bb68f-e210-49d3-ab7f-98e8de9e3364','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='243bb68f-e210-49d3-ab7f-98e8de9e3364') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='243bb68f-e210-49d3-ab7f-98e8de9e3364');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eb44bb28-bdf3-4950-a424-93a2d7169085','Fletcher-Munson effect','The Fletcher-Munson effect is the dependence of perceived loudness on frequency at a given sound pressure level, first mapped as equal-loudness contours by Fletcher and Munson in 1933. The ear is most sensitive around 2-5 kHz and much less sensitive at low frequencies, and this imbalance lessens as overall level rises; the modern standardized contours are given in ISO 226.','Our ears do not hear all pitches equally loud. Low bass needs more level to match a midrange tone. The ear is most sensitive near 3 kHz. This imbalance shrinks when music is loud. Fletcher and Munson first charted it.','It explains why tonal balance shifts with level and motivates loudness-compensated metering and frequency weighting.','Mixing quietly can make an engineer add too much bass; checking the mix at a moderate, calibrated level avoids this loudness-related error.','Psychoacoustics',ARRAY['Frequency Selectivity','Equivalent continuous sound level','External-ear transfer function']::text[],ARRAY['Assuming A-weighting fully corrects for loudness; it approximates only low-level hearing.','Treating the contours as fixed; the frequency imbalance changes with level.','Citing only the 1933 curves; ISO 226 supersedes them with revised data.']::text[],ARRAY['Explaining why bass seems weak at low playback levels.','Justifying reference monitoring levels.','Designing a loudness-compensation control.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fletcher-Munson effect');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eb44bb28-bdf3-4950-a424-93a2d7169085','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eb44bb28-bdf3-4950-a424-93a2d7169085') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eb44bb28-bdf3-4950-a424-93a2d7169085');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '31002943-f8fc-4b87-b39f-f880fedb10a2','Foldback level','Foldback level is the loudness of the monitor (foldback) feed sent back to performers on stage so they can hear themselves and others, set on the auxiliary sends of a mixing console and reproduced by stage monitors or in-ear systems. It is mixed independently of the front-of-house level heard by the audience.','Performers need to hear themselves on stage. That monitor feed is called foldback. Its level is set on the console''s aux sends. It is separate from the audience mix. Too much foldback risks feedback.','It gives performers a controllable, separate monitor mix so they can stay in time and in tune during a show.','A monitor engineer raises a singer''s vocal in her wedge foldback until she can hear pitch clearly, watching for the onset of feedback.','Live sound',ARRAY['First-wavefront law','Extended stereo image','Equivalent continuous sound level']::text[],ARRAY['UNSAFE: Pushing in-ear or wedge foldback to very high levels, risking hearing damage over a long show.','Confusing foldback (stage monitoring) with the front-of-house mix heard by the audience.','Raising foldback so far that microphones feed back and howl.']::text[],ARRAY['Building monitor mixes at a soundcheck.','Managing in-ear monitor levels on tour.','Reducing stage volume to control feedback.']::text[],'beginner',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Foldback level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '31002943-f8fc-4b87-b39f-f880fedb10a2','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='31002943-f8fc-4b87-b39f-f880fedb10a2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='31002943-f8fc-4b87-b39f-f880fedb10a2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5713a6b6-b426-4ecc-aba9-c902fe0662f4','Free-field method','A free-field method is a measurement or calibration procedure carried out in a sound field free of boundaries and reflections — in practice an anechoic room or open space — so that only the direct sound reaches the receiver. It is used, for example, to determine a microphone''s free-field response or a source''s radiated sound.','A free field has no walls or reflections. Only direct sound reaches the microphone. Anechoic rooms create this condition. The method measures gear or sources cleanly. Reflections cannot corrupt the result.','It removes room reflections so a device''s or source''s true direct-sound behaviour can be measured repeatably.','In an anechoic chamber, an engineer measures a loudspeaker''s on-axis frequency response without reflections colouring the result.','Measurement',ARRAY['Far-field criterion','Field calibration','External-ear transfer function','First-arrival time']::text[],ARRAY['Assuming an ordinary quiet room is a free field; walls still reflect and colour the measurement.','Confusing free-field with diffuse-field response, which assumes sound arriving from all directions.','Ignoring the low-frequency limit where a chamber stops being anechoic.']::text[],ARRAY['Measuring loudspeaker frequency response.','Calibrating a free-field microphone.','Determining a machine''s sound power in an anechoic room.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Free-field method');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5713a6b6-b426-4ecc-aba9-c902fe0662f4','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5713a6b6-b426-4ecc-aba9-c902fe0662f4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5713a6b6-b426-4ecc-aba9-c902fe0662f4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2a860da7-bde8-4120-a875-7263114040f2','Frequency Selectivity','Frequency selectivity is the ear''s (or a filter''s) ability to resolve and separate the individual frequency components of a complex sound. In hearing it arises from the cochlea''s array of overlapping auditory filters, whose bandwidths (critical bands) set how well nearby tones are heard apart and govern masking.','Frequency selectivity is the power to tell pitches apart. The inner ear acts like a bank of filters. Each filter passes a narrow band. Better selectivity keeps close tones separate. It also controls how one sound masks another.','It determines how the auditory system resolves spectral detail and underlies masking, pitch, and timbre perception.','Knowing that a loud tone masks nearby frequencies, a mix engineer carves space with EQ so a vocal is not hidden by a synth.','Psychoacoustics',ARRAY['Fletcher-Munson effect','Half-power bandwidth','Frequency band of interest','External-ear transfer function']::text[],ARRAY['Confusing frequency selectivity (resolving components) with absolute pitch (naming a note).','Assuming auditory filters have equal bandwidth; critical bandwidth widens with frequency.','Treating masking as purely level-based, ignoring the frequency spacing that selectivity sets.']::text[],ARRAY['Explaining masking in a dense mix.','Designing perceptual audio codecs.','Interpreting a listener''s difficulty separating instruments.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frequency Selectivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2a860da7-bde8-4120-a875-7263114040f2','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2a860da7-bde8-4120-a875-7263114040f2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2a860da7-bde8-4120-a875-7263114040f2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2d387b0e-6e2f-421b-a3e7-1dce020ff577','Frequency band of interest','The frequency band of interest is the specified range of frequencies over which a measurement, analysis, or specification applies, bounded by stated lower and upper limits (often standardized octave or one-third-octave bands). Content outside it is excluded from the assessment.','Not every test looks at all frequencies. The band of interest is the range you care about. It has a lower and upper limit. Often these follow octave or third-octave bands. Sound outside it is ignored.','It bounds an analysis to the frequencies relevant to the task, keeping measurements comparable and free of irrelevant content.','For a speech-intelligibility check, an engineer restricts analysis to roughly 125 Hz-8 kHz, the band of interest for speech.','Measurement',ARRAY['Half-power bandwidth','Frequency Selectivity','Equivalent continuous sound level','Free-field method']::text[],ARRAY['Leaving the band unstated, so results cannot be compared across measurements.','Setting the band too narrow and missing relevant energy just outside it.','Confusing the band of interest with the instrument''s full bandwidth.']::text[],ARRAY['Defining the range for an octave-band noise analysis.','Limiting a speech-intelligibility measurement.','Specifying a filter''s evaluation range.']::text[],'beginner',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frequency band of interest');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2d387b0e-6e2f-421b-a3e7-1dce020ff577','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2d387b0e-6e2f-421b-a3e7-1dce020ff577') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2d387b0e-6e2f-421b-a3e7-1dce020ff577');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '061f2066-f60d-4dfd-adef-5bf16c225f52','Frequency-following response','The frequency-following response (FFR) is a sustained auditory evoked potential, recorded from scalp electrodes, whose waveform phase-locks to and mirrors the periodic features of a sound such as its fundamental frequency and harmonics. It is generated mainly in the auditory brainstem and midbrain and is used to study neural encoding of pitch and speech.','The brain''s early hearing centres track a sound''s rhythm. Electrodes on the scalp can record this. The signal follows the sound''s pitch over time. Researchers call it the frequency-following response. It reveals how the brain encodes pitch and speech.','It provides an objective neural measure of how faithfully the auditory system encodes periodic sound, useful in hearing and speech research.','A researcher plays a repeated vowel and averages the scalp response to see whether the brainstem tracks its fundamental frequency.','Audiology',ARRAY['Fundamental-frequency contour','Frequency Selectivity','External-ear transfer function']::text[],ARRAY['Confusing the FFR with the click-evoked auditory brainstem response, which marks timing rather than following pitch.','Assuming the recorded response equals the stimulus; it is a filtered neural version.','Ignoring stimulus polarity, which affects the envelope- versus fine-structure-following parts.']::text[],ARRAY['Studying pitch encoding in musicians.','Assessing speech-sound processing in children.','Auditory neuroscience research on the brainstem.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frequency-following response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '061f2066-f60d-4dfd-adef-5bf16c225f52','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='061f2066-f60d-4dfd-adef-5bf16c225f52') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='061f2066-f60d-4dfd-adef-5bf16c225f52');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '44b7da8a-3a05-4aca-931d-09f71ae50579','Frequency-warping','Frequency warping is a signal-processing technique that non-uniformly stretches or compresses the frequency axis, usually by replacing each unit delay in a filter with a first-order all-pass section. A single warping coefficient controls the mapping, commonly chosen to approximate a perceptual scale such as the Bark scale.','Normal analysis spaces frequencies evenly. Warping bends that axis. It squeezes high frequencies and stretches low ones. One coefficient sets how much. This can match how the ear spaces pitches.','It lets a filter or transform concentrate resolution where it matters perceptually, matching auditory frequency spacing.','A designer sets the all-pass coefficient near 0.7 at 44.1 kHz so a warped filter gives ear-like resolution, with fine detail at low frequencies.','DSP',ARRAY['Frequency Selectivity','Instantaneous frequency','Half-power bandwidth']::text[],ARRAY['Choosing the wrong sign of the coefficient, which warps the axis the opposite way.','Forgetting that warping changes filter phase and group delay, not just magnitude spacing.','Assuming the warped scale is exactly Bark or mel; it only approximates them.']::text[],ARRAY['Building a warped linear-prediction audio coder.','Designing perceptually weighted equalizers.','Feature extraction for speech and music analysis.']::text[],'advanced','w'' = w + 2 * arctan( lambda * sin(w) / (1 - lambda * cos(w)) )','A first-order all-pass filter maps each original frequency to a warped frequency, with the shift set by the warping coefficient.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frequency-warping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '44b7da8a-3a05-4aca-931d-09f71ae50579','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='44b7da8a-3a05-4aca-931d-09f71ae50579') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='44b7da8a-3a05-4aca-931d-09f71ae50579');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '25412e46-6a4d-478f-bc33-519fd50f768b','Fundamental-frequency contour','A fundamental-frequency contour (F0 contour, or pitch contour) is the trajectory of the fundamental frequency of a quasi-periodic sound, such as voiced speech or a sung melody, plotted as it varies over time. It captures intonation, tone, and melodic movement.','Voiced speech and singing have a pitch. That pitch rises and falls over time. Its path is the fundamental-frequency contour. In speech it carries intonation. In music it traces the melody.','It represents how pitch changes over time, supporting analysis of intonation, tone languages, prosody, and melody.','A speech engineer extracts the F0 contour of a sentence to model its rising intonation for a text-to-speech voice.','Speech/pitch',ARRAY['Instantaneous frequency','Equal-temperament deviation','Frequency-following response','Feature-space maximum-likelihood linear regression']::text[],ARRAY['Confusing fundamental frequency (physical rate) with perceived pitch, which can differ.','Reporting octave errors from a tracker that jumps to a harmonic.','Assuming every sound has an F0; unvoiced or noisy sounds have none.']::text[],ARRAY['Building a text-to-speech prosody model.','Analyzing tone in a tonal language.','Correcting pitch in a vocal recording.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fundamental-frequency contour');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '25412e46-6a4d-478f-bc33-519fd50f768b','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='25412e46-6a4d-478f-bc33-519fd50f768b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='25412e46-6a4d-478f-bc33-519fd50f768b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9804a10b-89e4-4ce6-8504-f7d07fc6b2f0','Gaussian mixture model','A Gaussian mixture model (GMM) represents a probability distribution as a weighted sum of several multivariate Gaussian (normal) component densities. Its parameters — mixture weights, mean vectors, and covariance matrices — are typically estimated with the expectation-maximization algorithm, and it is widely used to model acoustic-feature distributions in speech and speaker recognition.','Some data clusters into several groups. A Gaussian mixture models each group with a bell curve. It adds these bell curves with weights. The result fits complex spread. Speech systems use it to model sound features.','It flexibly models complex, multimodal data distributions, serving as a statistical building block in classification and recognition.','A speaker-recognition system models each voice with, say, a 512-component GMM over MFCC features, scoring a test utterance by its likelihood under each model.','Machine learning',ARRAY['Feature-space maximum-likelihood linear regression','Frequency-warping','Fundamental-frequency contour']::text[],ARRAY['Using too many components for the data, which overfits.','Letting a covariance collapse to zero on a single point, giving infinite likelihood.','Assuming components map to meaningful physical clusters; they need not.']::text[],ARRAY['Modeling acoustic features in speaker verification.','Clustering audio segments.','Background modeling in classic recognition systems.']::text[],'advanced','p(x) = sum_{k=1}^{K} w_k * N(x | mu_k, Sigma_k),  with sum_k w_k = 1','The density is a weighted sum of K normal components, and the non-negative weights sum to one.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Gaussian mixture model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9804a10b-89e4-4ce6-8504-f7d07fc6b2f0','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9804a10b-89e4-4ce6-8504-f7d07fc6b2f0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9804a10b-89e4-4ce6-8504-f7d07fc6b2f0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'be1ef142-203d-43f7-8be0-af852cce6462','Generalized sidelobe canceller','A generalized sidelobe canceller (GSC) is an adaptive beamforming structure that separates a linearly constrained spatial-filtering problem into a fixed beamformer aimed at the desired direction and an adaptive path that removes interference. A blocking matrix forms reference signals free of the target, and an adaptive filter subtracts correlated noise from the beamformer output.','A microphone array can steer toward a talker. The GSC does this in two parts. One path points a fixed beam at the target. Another path captures only the noise. It then subtracts that noise from the beam.','It implements linearly constrained adaptive beamforming efficiently, enhancing a wanted signal while adaptively suppressing interference and noise.','A conferencing microphone array uses a GSC to keep a talker''s voice while cancelling a projector fan picked up from other directions.','Array processing',ARRAY['Minimum-variance distortionless response beamformer','Adaptive filter','Free-field method']::text[],ARRAY['Target-signal leakage through an imperfect blocking matrix, which cancels the wanted voice.','Assuming it needs no steering; direction errors degrade performance.','Confusing the fixed beamformer path with the adaptive noise-cancelling path.']::text[],ARRAY['Speech enhancement in a microphone-array conferencing system.','Hearing-aid directional processing.','Noise suppression in a voice front end.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Generalized sidelobe canceller');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'be1ef142-203d-43f7-8be0-af852cce6462','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='be1ef142-203d-43f7-8be0-af852cce6462') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='be1ef142-203d-43f7-8be0-af852cce6462');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '008ecb37-ceaa-4b44-a2a0-6c50940f9a8b','Global motion parameter','A global motion parameter is one coefficient of a parametric motion model (such as translational, affine, or perspective) that describes camera-induced motion of a whole video frame in video coding. In MPEG-4 Visual, such parameters drive global motion compensation and sprite (background) coding, letting one model predict the movement of the entire scene.','Video often moves because the camera moves. That motion affects the whole frame at once. A global motion parameter is one number in a model of that motion. Coders use several to predict the frame. This saves bits versus moving each block.','It compactly captures whole-frame camera motion so a coder can predict and compress background movement efficiently.','During a camera pan, an MPEG-4 encoder estimates a few global motion parameters, warps the previous frame, and codes only the small residual.','Video coding',ARRAY['Motion compensation','Sprite coding','Error concealment']::text[],ARRAY['Confusing global motion (whole frame) with block-level motion vectors (local).','Assuming a translational model suffices; zoom and rotation need affine or perspective terms.','Treating these video parameters as audio parameters; they belong to the visual layer.']::text[],ARRAY['Encoding video with strong camera panning.','Sprite-based background coding in MPEG-4.','Video stabilization using estimated global motion.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Global motion parameter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '008ecb37-ceaa-4b44-a2a0-6c50940f9a8b','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='008ecb37-ceaa-4b44-a2a0-6c50940f9a8b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='008ecb37-ceaa-4b44-a2a0-6c50940f9a8b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2df791c2-5cb5-4562-bc92-826b6bef6307','Half-power bandwidth','The half-power (or -3 dB) bandwidth of a resonance or filter is the frequency span between the two points on either side of the peak where the transmitted power falls to half its maximum, equivalently where the amplitude falls to 1/sqrt(2) (about 70.7%) of the peak. It is inversely related to the quality factor Q by Q = f0/B.','A filter or resonance peaks at one frequency. Its response falls off on both sides. The half-power bandwidth is the width where power halves. There the amplitude is about 71 percent of the peak. A narrow width means a high Q.','It quantifies how sharp or broad a resonance or filter is, and links directly to the quality factor and damping.','A resonance at f0 = 1000 Hz with a -3 dB bandwidth of 100 Hz has Q = f0/B = 10, so it is fairly sharp.','Signal analysis',ARRAY['Frequency Selectivity','Frequency band of interest','Far-field criterion','Instantaneous frequency']::text[],ARRAY['Reading the width at -6 dB instead of -3 dB.','Confusing amplitude (1/sqrt(2)) with power (1/2); they describe the same points.','Assuming bandwidth alone sets Q; the centre frequency matters too.']::text[],ARRAY['Specifying an EQ filter''s Q.','Characterizing a loudspeaker or room resonance.','Measuring a bandpass filter''s width.']::text[],'intermediate','B = f2 - f1, where |H(f1)| = |H(f2)| = |H(f0)|/sqrt(2);   Q = f0 / B','Bandwidth is the gap between the two frequencies where amplitude drops to about seventy-one percent of the peak; Q is centre frequency over bandwidth.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Half-power bandwidth');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2df791c2-5cb5-4562-bc92-826b6bef6307','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2df791c2-5cb5-4562-bc92-826b6bef6307') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2df791c2-5cb5-4562-bc92-826b6bef6307');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5d435cce-fe48-4a39-96c7-ad3475db4947','Impulsive noise','Impulsive noise is noise made up of one or more bursts of sound energy, each of short duration (typically well under one second) and with a high crest factor, such as hammer blows, gunfire, or presses. Standards treat it specially because its high, brief peaks are underrepresented by energy averaging and carry extra hearing-damage risk.','Some noise comes in short, sharp bursts. Examples are hammer blows or gunfire. Each burst is brief but very loud. Energy averages can hide these peaks. Standards flag impulsive noise as especially harmful.','It identifies short, high-peak sounds that need special measurement (peak levels, penalties) because averaged levels understate their risk.','Measuring a stamping press, an engineer records the C-weighted peak as well as the Leq, because the impulsive peaks drive the hearing-damage risk.','Noise metric',ARRAY['Equivalent continuous sound level','Exposure action value','Fast time weighting']::text[],ARRAY['UNSAFE: Judging impulsive noise by Leq alone; brief peaks can injure hearing even when the average looks moderate.','UNSAFE: Omitting the C-weighted peak measurement, which is the criterion for impulse hearing risk.','Confusing impulsive noise with steady broadband noise, which has a low crest factor.']::text[],ARRAY['Assessing hearing risk from gunfire or pyrotechnics.','Surveying a metal press or forge.','Applying an impulsive-noise penalty in an environmental assessment.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Impulsive noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5d435cce-fe48-4a39-96c7-ad3475db4947','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5d435cce-fe48-4a39-96c7-ad3475db4947') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5d435cce-fe48-4a39-96c7-ad3475db4947');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b624d0e2-bf50-4a55-b6eb-fab859ad0095','Insert loss','Insertion loss is the reduction in sound (or signal) level at a receiver caused by inserting an element — such as a silencer, enclosure, barrier, or filter — between the source and receiver, expressed in decibels as the level before insertion minus the level after. It compares two states of the same system rather than a device in isolation.','Add a barrier or muffler between source and listener. The level at the listener drops. That drop, in decibels, is the insertion loss. It is the level before minus the level after. Bigger numbers mean better attenuation.','It quantifies how much a device or barrier attenuates sound in place, guiding noise-control and acoustic-treatment choices.','If an enclosure lowers the level at a point from 90 to 72 dB, its insertion loss is 90 - 72 = 18 dB.','Noise control',ARRAY['Insertion gain','Half-power bandwidth','Free-field method','Far-field criterion']::text[],ARRAY['Confusing insertion loss (in-situ, two-state comparison) with transmission loss (a material property).','Reporting a single figure without the frequency band; insertion loss varies with frequency.','Mixing up insertion loss (attenuation) with insertion gain (amplification).']::text[],ARRAY['Rating a duct silencer.','Assessing a machine enclosure.','Checking a noise barrier''s effectiveness.']::text[],'intermediate','IL = L_before - L_after = 20 * log10(p_before / p_after)  dB','Insertion loss is the receiver level without the element minus the level with it in place, in decibels.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Insert loss');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b624d0e2-bf50-4a55-b6eb-fab859ad0095','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b624d0e2-bf50-4a55-b6eb-fab859ad0095') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b624d0e2-bf50-4a55-b6eb-fab859ad0095');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '35df0777-03f0-428f-961e-7d1604b5fbb7','Insertion gain','Insertion gain is the increase in level, in decibels, produced by inserting an active element such as an amplifier between source and receiver. In audiology, real-ear insertion gain (REIG) is the difference at each frequency between the aided and unaided sound pressure level measured near the eardrum, quantifying the benefit a hearing aid provides.','Insertion gain is the level boost an added device gives. For hearing aids, it is measured in the ear canal. It is the aided level minus the unaided level. It shows how much the aid amplifies at each pitch.','It measures the net amplification an inserted device delivers, and in audiology verifies that a hearing aid meets its prescription.','If the aided ear-canal level at 2 kHz is 95 dB SPL and the unaided level is 75 dB SPL, the insertion gain is 20 dB.','Audiology',ARRAY['Insert loss','External-ear transfer function','Field calibration','Free-field method']::text[],ARRAY['Confusing insertion gain (net benefit, aided minus unaided) with the hearing aid''s coupler gain.','Ignoring the unaided ear-canal resonance, which the aid partly replaces.','UNSAFE: Assuming more insertion gain is always better; over-amplification can be uncomfortable or damaging.']::text[],ARRAY['Verifying a hearing-aid fitting with real-ear measurement.','Comparing aided and unaided responses.','Documenting prescribed gain targets.']::text[],'advanced','REIG(f) = REAG(f) - REUG(f) = L_aided(f) - L_unaided(f)  dB','Real-ear insertion gain is the aided ear-canal level minus the unaided ear-canal level at each frequency.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Insertion gain');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '35df0777-03f0-428f-961e-7d1604b5fbb7','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='35df0777-03f0-428f-961e-7d1604b5fbb7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='35df0777-03f0-428f-961e-7d1604b5fbb7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0f170d7c-3337-4d4f-b530-f6847fc725b4','Instantaneous frequency','The instantaneous frequency of a signal is the rate of change of its phase, defined as the time derivative of the phase of the associated analytic signal divided by 2*pi. For a monocomponent signal it describes how the signal''s frequency varies from moment to moment, as in a chirp or vibrato.','A signal''s frequency can change over time. Instantaneous frequency is its value at each instant. It comes from how fast the phase turns. A steady tone has a constant value. A sweep or vibrato has a changing one.','It gives a moment-by-moment measure of frequency for signals whose frequency varies, underlying chirp, vibrato, and time-frequency analysis.','For a linear chirp with phase phi(t) = 2*pi*(f0*t + (k/2)*t^2), the instantaneous frequency is f0 + k*t, a straight-line sweep in time.','Signal analysis',ARRAY['Fundamental-frequency contour','Frequency-warping','Half-power bandwidth','Equal-temperament deviation']::text[],ARRAY['Applying it to multicomponent signals, where a single instantaneous frequency is ill-defined.','Confusing instantaneous frequency with the Fourier (global) frequency of the whole signal.','Forgetting the 1/(2*pi) factor when converting phase rate to hertz.']::text[],ARRAY['Analyzing a frequency sweep or chirp.','Tracking vibrato in a musical note.','Time-frequency analysis of nonstationary sound.']::text[],'advanced','f_i(t) = (1 / (2*pi)) * d[phi(t)]/dt','Instantaneous frequency is the time derivative of the signal''s phase divided by two pi.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Instantaneous frequency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0f170d7c-3337-4d4f-b530-f6847fc725b4','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0f170d7c-3337-4d4f-b530-f6847fc725b4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0f170d7c-3337-4d4f-b530-f6847fc725b4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0701be88-a8d8-4c4c-aeb0-cbe745ba6ae8','Intensity Discrimination','Intensity discrimination is a listener''s ability to detect a small change in the intensity (level) of a sound. It is quantified as the just-noticeable difference in level, which for broadband sounds at moderate levels is roughly 0.5 to 1 dB.','This is how well your ears notice a sound getting a bit louder or softer. The smallest change most people can hear is about half a decibel. It gets easier to notice at higher levels. It is a basic limit of hearing.','It defines the ear''s resolution for loudness changes, which underlies loudness scaling, level metering practice, and audio coding decisions.','A technician nudging a fader by less than about 0.5 dB will usually make a change no listener can hear, so meaningful gain moves are kept at or above roughly 1 dB.','Psychoacoustics',ARRAY['Masker level','Minimum audible pressure','Interchannel level difference','Level-dependent frequency response']::text[],ARRAY['Assuming the just-noticeable level step is the same at all frequencies and levels.','Believing Weber''s law holds exactly at all levels; it holds well for broadband noise, but for pure tones the Weber fraction decreases slightly with level (the near miss to Weber''s law).','Confusing a detectable level change with a musically useful one.']::text[],ARRAY['Justifying why very small automation moves are inaudible.','Setting the step size of a digital gain control.','Explaining loudness just-noticeable differences in a hearing-science class.']::text[],'intermediate','ΔL = 10 log10((I + ΔI) / I)','The level change in decibels equals ten times the base-ten logarithm of the changed intensity divided by the original intensity.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Intensity Discrimination');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0701be88-a8d8-4c4c-aeb0-cbe745ba6ae8','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0701be88-a8d8-4c4c-aeb0-cbe745ba6ae8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0701be88-a8d8-4c4c-aeb0-cbe745ba6ae8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '83e02f66-6d3b-4b8f-b2e0-4f7acbd0d79c','Intensity stereo','Intensity stereo is a joint-stereo audio-coding tool that codes the higher-frequency bands of a stereo pair as a single shared spectrum plus per-band level (intensity) factors for each channel. It preserves interchannel level differences while discarding fine interchannel phase, exploiting reduced high-frequency phase sensitivity to save bits.','This trick saves data in stereo audio files. It stores one shared signal for the high notes. Then it keeps only the loudness balance between left and right. The ears barely notice the missing phase detail up high.','It reduces the bit rate of stereo material by removing redundant high-frequency phase information that listeners cannot easily detect.','An engineer choosing an AAC or MP3 encoder setting may enable intensity (joint) stereo at low bit rates to keep quality, but disables it for wide, hard-panned mixes where imaging matters.','Audio Coding',ARRAY['Interchannel level difference','Interchannel prediction','Low-complexity profile','Masker level']::text[],ARRAY['Confusing coding intensity stereo with intensity (amplitude) panning at a mix console.','Assuming it is lossless; phase information is discarded.','Using it on material with strong out-of-phase content, causing image collapse.']::text[],ARRAY['Configuring a low-bit-rate AAC stream for broadcast.','Diagnosing collapsed high-frequency stereo image in an encoded file.','Teaching joint-stereo tools in an audio-coding course.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Intensity stereo');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '83e02f66-6d3b-4b8f-b2e0-4f7acbd0d79c','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='83e02f66-6d3b-4b8f-b2e0-4f7acbd0d79c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='83e02f66-6d3b-4b8f-b2e0-4f7acbd0d79c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6f902c99-0881-4af8-94f5-1ab50f49ba4d','Interchannel level difference','Interchannel level difference (ICLD) is the difference in signal level between two audio channels, expressed in decibels. In spatial audio it is a primary panning and localization cue and is a core parameter transmitted by parametric stereo and spatial audio coders.','This is how much louder one channel is than another. It is measured in decibels. In stereo it helps place a sound left or right. Coders send this value to recreate a stereo image cheaply.','It captures the level-based spatial cue between channels so that image position can be described, panned, or efficiently coded.','To pan a source fully to the right speaker a mixer sets a large positive ICLD; a parametric coder might transmit an ICLD of +6 dB to place an element toward one side.','Spatial Audio',ARRAY['Interchannel time difference','Intensity stereo','Interchannel prediction','Intensity Discrimination']::text[],ARRAY['Confusing interchannel (between speakers/channels) with interaural (between ears) level difference.','Assuming level difference alone fully determines perceived position; time cues also contribute.','Ignoring that summed level can change perceived loudness while panning.']::text[],ARRAY['Describing a pan position in a parametric stereo codec.','Setting amplitude panning on a mixing console.','Analyzing stereo image width in a mastering session.']::text[],'intermediate','ICLD = 10 log10(P1 / P2)','The interchannel level difference in decibels equals ten times the base-ten logarithm of the power in channel one divided by the power in channel two.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Interchannel level difference');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6f902c99-0881-4af8-94f5-1ab50f49ba4d','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6f902c99-0881-4af8-94f5-1ab50f49ba4d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6f902c99-0881-4af8-94f5-1ab50f49ba4d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4288ee1c-990f-45fc-8993-e4b9e5310d49','Interchannel prediction','Interchannel prediction is a coding technique that predicts the samples or spectral coefficients of one audio channel from those of another correlated channel, coding only the prediction residual. It removes redundancy between channels and is used in multichannel lossless and parametric coders.','This method saves data by guessing one channel from another. The channels in a recording are often similar. The coder stores only the small guessing error. That takes far fewer bits than storing both channels fully.','It exploits statistical similarity between channels to lower the bit rate needed for stereo or multichannel audio.','In MPEG-4 Audio Lossless (ALS) an engineer can enable interchannel prediction so that a stereo file compresses further when both channels share strong common content.','Audio Coding',ARRAY['Intensity stereo','Interchannel level difference','Karhunen-Loeve transform','Low-complexity profile']::text[],ARRAY['Confusing interchannel prediction with the intra-channel (single-channel) prediction tool in AAC.','Expecting benefit on uncorrelated or hard-panned channels.','Assuming prediction is always lossy; in lossless coders the residual is coded exactly.']::text[],ARRAY['Archiving multichannel masters with a lossless coder.','Explaining redundancy removal in a coding course.','Tuning encoder settings for correlated stereo material.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Interchannel prediction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4288ee1c-990f-45fc-8993-e4b9e5310d49','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4288ee1c-990f-45fc-8993-e4b9e5310d49') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4288ee1c-990f-45fc-8993-e4b9e5310d49');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e7d02a78-7b23-4f62-9f3a-cd54d9361a26','Interchannel time difference','Interchannel time difference (ICTD) is the arrival-time or phase difference of a signal between two audio channels, usually expressed in microseconds or samples. It is a primary spatial cue, especially at low frequencies, and is transmitted by parametric spatial audio coders.','This is the small time gap between the same sound in two channels. At low frequencies this delay tells the ears where a sound sits. Coders send this value to rebuild the stereo image. It works with the level difference.','It represents the time-based spatial cue between channels, allowing position and width to be described, delayed, or efficiently coded.','A spatial coder might send an ICTD of about 0.5 ms to shift an element toward one side, mirroring the interaural time cue the ears use below roughly 1.5 kHz.','Spatial Audio',ARRAY['Interchannel level difference','Intensity stereo','Interchannel prediction','Minimum audible angle']::text[],ARRAY['Confusing interchannel with interaural time difference.','Applying large time offsets that cause comb filtering when channels are summed to mono.','Assuming time cues dominate at all frequencies; level cues take over at high frequencies.']::text[],ARRAY['Setting delay-based panning in a mix.','Coding stereo width parameters in a codec.','Checking mono compatibility of a time-offset stereo track.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Interchannel time difference');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e7d02a78-7b23-4f62-9f3a-cd54d9361a26','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e7d02a78-7b23-4f62-9f3a-cd54d9361a26') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e7d02a78-7b23-4f62-9f3a-cd54d9361a26');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7352dbee-fa5a-4dc0-ab59-c2be9069f31f','Inverse constant-Q transform','The inverse constant-Q transform reconstructs a time-domain signal from a constant-Q transform, in which frequency bins are spaced geometrically and each bin holds a constant quality factor Q equal to centre frequency divided by bandwidth. It inverts the forward analysis so a signal modified in the constant-Q domain can be resynthesized.','The constant-Q transform splits sound into bands that follow musical pitches. Each band keeps the same shape ratio. The inverse version turns those bands back into a normal audio signal. It lets you edit in that domain and hear the result.','It allows a signal analyzed on a logarithmic, music-aligned frequency grid to be turned back into audio after processing.','After pitch-shifting or filtering in the constant-Q domain, a developer applies the inverse constant-Q transform to render the edited signal back to a playable waveform.','Signal Transforms',ARRAY['Mother wavelet','Log-mel spectrogram','Karhunen-Loeve transform','Minimum phase response']::text[],ARRAY['Assuming perfect reconstruction without a properly designed dual/inverse frame.','Confusing the constant-Q transform with the fixed-bandwidth short-time Fourier transform.','Ignoring that geometric spacing gives coarse time resolution at low frequencies.']::text[],ARRAY['Resynthesizing audio after music-domain processing.','Building a pitch-shift tool on a logarithmic frequency grid.','Teaching time-frequency transforms with musical bin spacing.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Inverse constant-Q transform');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7352dbee-fa5a-4dc0-ab59-c2be9069f31f','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7352dbee-fa5a-4dc0-ab59-c2be9069f31f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7352dbee-fa5a-4dc0-ab59-c2be9069f31f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1f57d580-864d-4133-ae5e-e15f25d24606','Iterative closest point registration','Iterative closest point (ICP) registration is an algorithm that aligns two point sets by repeatedly pairing each point with its nearest neighbour in the other set and computing the rigid transform that minimizes the total squared distance. It iterates until the alignment error converges.','This method fits two 3D point clouds together. It links each point to the closest point in the other set. Then it rotates and slides one set to reduce the gaps. It repeats until the fit stops improving.','It provides a way to align measured 3D geometry, such as scanned surfaces or head meshes, to a reference coordinate frame.','When building a personalized head-related transfer function, an engineer uses ICP to align a scanned head-and-ear mesh with a template before computing spatial audio filters.','Geometry Processing',ARRAY['Karhunen-Loeve transform','Minimum phase response','Monaural cue','Interchannel time difference']::text[],ARRAY['Assuming ICP finds the global best fit; it can converge to a wrong local minimum without a good starting pose.','Neglecting outlier rejection, which corrupts the alignment.','Confusing rigid ICP with non-rigid or deformable registration.']::text[],ARRAY['Aligning 3D head scans for personalized spatial audio.','Registering room-geometry scans for acoustic modeling.','Combining overlapping point clouds from multiple sensors.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Iterative closest point registration');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1f57d580-864d-4133-ae5e-e15f25d24606','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1f57d580-864d-4133-ae5e-e15f25d24606') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1f57d580-864d-4133-ae5e-e15f25d24606');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c7bb2520-bc6d-4248-9269-0ad76d135f0b','Karhunen-Loeve transform','The Karhunen-Loeve transform (KLT) is the linear transform whose basis vectors are the eigenvectors of a signal''s covariance matrix. It fully decorrelates the signal and gives optimal energy compaction, packing the most variance into the fewest coefficients; it is the theoretical basis of principal component analysis.','This transform finds the best directions to describe a signal. Those directions come from the signal''s own statistics. It packs most of the energy into a few numbers. That makes it ideal for compression, though it is costly to compute.','It provides the optimal linear basis for decorrelating data and concentrating energy, serving as the benchmark other transforms approximate.','A researcher compressing a set of impulse responses applies the KLT and keeps only the top few components, discarding low-variance ones with minimal audible loss.','Signal Transforms',ARRAY['Interchannel prediction','Inverse constant-Q transform','Mother wavelet','Kurtosis of noise']::text[],ARRAY['Assuming a fixed basis; the KLT basis is signal-dependent and must be recomputed.','Confusing it with the fixed-basis discrete cosine transform, which only approximates it.','Ignoring the cost of estimating and transmitting the covariance-derived basis.']::text[],ARRAY['Dimensionality reduction of feature or response data.','Explaining why the DCT is used as a practical KLT substitute.','Decorrelating multichannel signals before coding.']::text[],'advanced','y = Φᵀ x,  where R x Φ = Φ Λ','The transformed vector equals the transpose of the eigenvector matrix times the input, where the eigenvector matrix diagonalizes the covariance matrix.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Karhunen-Loeve transform');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c7bb2520-bc6d-4248-9269-0ad76d135f0b','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c7bb2520-bc6d-4248-9269-0ad76d135f0b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c7bb2520-bc6d-4248-9269-0ad76d135f0b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'adadfc32-e118-483e-a19e-89fb5e537a50','Kurtosis of noise','Kurtosis of noise is the fourth standardized statistical moment of a noise signal''s amplitude distribution, describing the heaviness of its tails and prominence of its peaks. A Gaussian distribution has a kurtosis of 3 (zero excess kurtosis); higher values indicate a more impulsive, spiky signal.','Kurtosis measures how spiky a noise signal is. Steady random noise sits near a value of three. Noise with sharp bursts scores higher. Engineers use it to tell impulsive noise from smooth background noise.','It gives a single number to distinguish impulsive, peaky noise from smooth Gaussian noise, useful for machine and audio diagnostics.','To detect a clicking fault in a recording, a technician computes kurtosis on the noise; a value well above 3 flags impulsive events that steady hiss would not produce.','Signal Statistics',ARRAY['Maximum length sequence','Masker level','Karhunen-Loeve transform','Maximum sound pressure level']::text[],ARRAY['Confusing kurtosis (value 3 for Gaussian) with excess kurtosis (value 0 for Gaussian).','Assuming kurtosis measures variance or spread rather than tail/peak shape.','Reading high kurtosis as loud; it reflects distribution shape, not level.']::text[],ARRAY['Detecting clicks or impulsive faults in a signal.','Characterizing the statistics of a noise source.','Condition monitoring of machinery via vibration signals.']::text[],'intermediate','β2 = E[(X − μ)⁴] / σ⁴','Kurtosis equals the expected value of the fourth power of the deviation from the mean, divided by the fourth power of the standard deviation.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Kurtosis of noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'adadfc32-e118-483e-a19e-89fb5e537a50','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='adadfc32-e118-483e-a19e-89fb5e537a50') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='adadfc32-e118-483e-a19e-89fb5e537a50');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '774db60c-5f05-4455-ac17-d8d80fa9bb55','Leakage current test','A leakage current (touch current) test measures the small current that flows from the live parts of mains-powered equipment to accessible conductive parts or earth through a standardized body-simulating measuring network. It verifies that this current stays below safe limits under normal and single-fault conditions.','This safety test checks stray current escaping to parts you can touch. A special circuit mimics the human body. The meter reads how much current would flow through a person. The reading must stay under strict limits set by safety standards.','It confirms that a device will not deliver a dangerous electric shock through its touchable surfaces, protecting users and meeting product-safety law.','UNSAFE: A technician tests a mains amplifier with an approved leakage tester and the measuring network of IEC 60990, confirming touch current stays under the 3.5 mA hand-to-foot limit before the unit is released; a failed unit is removed from service, never patched over.','Electrical Safety',ARRAY['Maximum sound pressure level','Level-dependent frequency response','Line source array','Maximum length sequence']::text[],ARRAY['UNSAFE: Bypassing or lifting the protective earth to stop hum without knowing this can raise touch current to lethal levels.','UNSAFE: Touching the equipment enclosure during a live single-fault (open-earth) test instead of using the meter and network.','Confusing leakage current (to accessible parts) with insulation resistance, which is a different high-voltage test.','Assuming battery-only devices need no test while their mains charger still does.']::text[],ARRAY['Production safety testing of a new powered loudspeaker.','Routine portable-appliance testing of touring rack gear.','Certifying audio equipment to IEC 62368-1 before sale.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Leakage current test');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '774db60c-5f05-4455-ac17-d8d80fa9bb55','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='774db60c-5f05-4455-ac17-d8d80fa9bb55') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='774db60c-5f05-4455-ac17-d8d80fa9bb55');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '76e25fd9-1b8b-4d76-840e-5a8274e6aff8','Level-dependent frequency response','Level-dependent frequency response describes how the perceived or actual balance of frequencies changes with sound level. Perceptually it follows the equal-loudness contours of ISO 226, in which low and very high frequencies seem relatively weaker at low listening levels than at high levels.','How we hear tone balance changes with volume. At low volume, bass and extreme treble seem weaker. At high volume they come forward. So a mix can sound different soft versus loud. Some gear also changes its response with level.','It explains why loudness affects tonal balance, guiding monitoring levels, loudness controls, and consistent mix decisions.','A mastering engineer checks a mix at both a low and a calibrated reference level, knowing the ear''s equal-loudness behavior can hide a bass problem at quiet volumes.','Psychoacoustics',ARRAY['Intensity Discrimination','Monitoring reference level','Maximum sound pressure level','Masker level']::text[],ARRAY['Mixing only at very low levels, then finding the bass wrong when played loud.','Assuming the ''loudness'' switch corrects tone at all volumes rather than one target level.','Confusing the perceptual effect with a fault in the loudspeaker.']::text[],ARRAY['Explaining why mixes translate poorly across playback levels.','Designing a loudness-compensation control.','Setting a consistent monitoring level for critical listening.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Level-dependent frequency response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '76e25fd9-1b8b-4d76-840e-5a8274e6aff8','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='76e25fd9-1b8b-4d76-840e-5a8274e6aff8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='76e25fd9-1b8b-4d76-840e-5a8274e6aff8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '99a201a8-936c-4f7d-a4c8-0cb928146323','Line source array','A line source array is a set of loudspeaker elements arranged in a close vertical line so that they combine to radiate an approximately cylindrical wavefront. Within its near field this cylindrical spreading falls off about 3 dB per doubling of distance, less than the 6 dB of a point source, giving longer throw and tighter vertical control.','This is a stack of speakers hung in a tall line. Together they act like one long source. Their sound spreads mostly sideways, not up and down. That lets it carry farther and stay even from front to back of a crowd.','It delivers even coverage over long distances with controlled vertical directivity, which is why it dominates large concert sound reinforcement.','An engineer curves a hung line array so its lower boxes splay more to reach front rows evenly, exploiting the roughly 3 dB per doubling loss in the near field for long throw.','Loudspeakers',ARRAY['Maximum sound pressure level','Level-dependent frequency response','Minimum audible angle','Modulation transfer function']::text[],ARRAY['Assuming the 3 dB-per-doubling falloff holds everywhere; beyond the near field it reverts toward 6 dB.','Ignoring that array length sets the lowest frequency that stays coherent.','Splaying boxes wrongly, creating uneven vertical coverage.']::text[],ARRAY['Designing coverage for a large outdoor concert.','Setting inter-box splay angles for even audience level.','Comparing throw of an array versus a single point-source cabinet.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Line source array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '99a201a8-936c-4f7d-a4c8-0cb928146323','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='99a201a8-936c-4f7d-a4c8-0cb928146323') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='99a201a8-936c-4f7d-a4c8-0cb928146323');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9e2c27af-731d-44d8-ab82-cafc74df840e','Log-area ratio','Log-area ratios (LARs) are a representation of the linear-prediction filter of speech, formed from the logarithm of the ratio of adjacent cross-sectional areas in an acoustic-tube model of the vocal tract. They are derived from the reflection (PARCOR) coefficients and are favoured for quantization because they are less sensitive than raw coefficients near the stability limit.','This is a way to describe the shape of the vocal tract in speech coding. It comes from a tube model of the throat and mouth. It takes the log of how tube sections change size. Coders store these values because they compress and round well.','It gives a robust, well-behaved parameter set for transmitting or quantizing the vocal-tract filter in low-bit-rate speech coders.','In an older LPC-based speech codec, an engineer transmits log-area ratios instead of raw reflection coefficients so that coarse quantization does not push the synthesis filter unstable.','Speech Coding',ARRAY['Karhunen-Loeve transform','Log-mel spectrogram','Lombard effect','Interchannel prediction']::text[],ARRAY['Confusing log-area ratios with line spectral frequencies, a different LPC representation.','Forgetting that reflection coefficients must have magnitude below one for stability.','Assuming the areas are physical measurements rather than model parameters.']::text[],ARRAY['Quantizing vocal-tract parameters in a speech codec.','Explaining tube models of the vocal tract.','Comparing LPC parameter sets for robustness.']::text[],'advanced','gᵢ = log((1 + kᵢ) / (1 − kᵢ))','The log-area ratio equals the logarithm of one plus the reflection coefficient divided by one minus the reflection coefficient.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Log-area ratio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9e2c27af-731d-44d8-ab82-cafc74df840e','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9e2c27af-731d-44d8-ab82-cafc74df840e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9e2c27af-731d-44d8-ab82-cafc74df840e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b0048a27-bb63-4604-84d9-70075a8b2d57','Log-mel spectrogram','A log-mel spectrogram is a time-frequency representation of a signal in which short-time spectral energy is grouped into bands spaced on the perceptual mel scale, and the band energies are taken in logarithmic (decibel-like) units. It approximates the frequency resolution and loudness compression of human hearing.','This is a picture of sound over time. It splits sound into bands that match how ears hear pitch. Then it takes the log of each band''s energy, like loudness. It is a common input for speech and audio machine learning.','It provides a compact, perceptually motivated feature that front-ends for speech recognition and audio machine learning rely on.','Before training a sound classifier, an engineer converts each clip to a log-mel spectrogram, choosing perhaps 64 mel bands so the model sees a hearing-like representation.','Audio Features',ARRAY['Log-area ratio','Inverse constant-Q transform','Mother wavelet','Modulation transfer function']::text[],ARRAY['Confusing a log-mel spectrogram with mel-frequency cepstral coefficients, which add a further transform.','Forgetting to take the log, leaving a linear-energy mel spectrogram.','Assuming mel bands are linearly spaced in hertz.']::text[],ARRAY['Preparing features for a speech-recognition model.','Visualizing perceptual frequency content of a clip.','Comparing audio representations for a classifier.']::text[],'intermediate','m = 2595 log10(1 + f / 700)','The mel value equals 2595 times the base-ten logarithm of one plus the frequency in hertz divided by 700.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Log-mel spectrogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b0048a27-bb63-4604-84d9-70075a8b2d57','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b0048a27-bb63-4604-84d9-70075a8b2d57') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b0048a27-bb63-4604-84d9-70075a8b2d57');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '94cf7f0b-0860-468f-b3b1-5c8aaa160842','Lombard effect','The Lombard effect is the involuntary tendency of talkers to raise their vocal effort and level, and to shift pitch and spectral balance, when speaking in loud background noise. It was described by Étienne Lombard in 1911 and occurs even when the talker cannot hear their own voice normally.','People automatically talk louder in a noisy room. They also raise pitch and stress words more. This reflex is called the Lombard effect. It happens without the speaker deciding to do it.','It names a reflex that helps speech stay intelligible in noise, and it affects how recorded or transmitted speech behaves in loud environments.','A dialogue editor recording an actor next to a running generator expects Lombard-raised, brighter delivery and adjusts mic gain and processing so the noisy-scene voice still cuts through.','Speech Acoustics',ARRAY['Masker level','Log-area ratio','Log-mel spectrogram','Level-dependent frequency response']::text[],ARRAY['Thinking the effect is a conscious choice by the speaker.','Assuming only loudness changes; pitch and spectrum shift too.','Ignoring that Lombard speech complicates automatic speech recognition trained on quiet speech.']::text[],ARRAY['Recording dialogue in a noisy on-location environment.','Explaining why crowd noise makes voices sound strained.','Modeling speech for recognizers used in cars or factories.']::text[],'beginner',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lombard effect');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '94cf7f0b-0860-468f-b3b1-5c8aaa160842','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='94cf7f0b-0860-468f-b3b1-5c8aaa160842') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='94cf7f0b-0860-468f-b3b1-5c8aaa160842');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '95f59777-0db8-4426-b63f-c5a7a51953b2','Low-complexity profile','The Low-Complexity (LC) profile is the most widely used configuration of MPEG Advanced Audio Coding, defined in MPEG-2 and MPEG-4 Audio. It omits the prediction and gain-control tools of the Main profile to reduce computation and memory while retaining most of AAC''s coding efficiency.','AAC-LC is the common form of AAC audio. It leaves out a couple of demanding tools to run more easily. It still sounds very good at modest bit rates. Most streaming and broadcast AAC files use this form.','It offers near-full AAC quality at reduced decoder complexity, making it practical for consumer devices and streaming.','Preparing audio for a streaming service, an engineer encodes to AAC-LC because nearly every playback device decodes it, unlike the heavier Main profile.','Audio Coding',ARRAY['Intensity stereo','Interchannel prediction','Low-frequency effects channel','Interchannel level difference']::text[],ARRAY['Confusing the AAC-LC profile with the newer HE-AAC, which adds spectral band replication.','Assuming ''low complexity'' means low quality.','Thinking it is a bit rate rather than a tool set/profile.']::text[],ARRAY['Choosing an encoding profile for wide device compatibility.','Explaining AAC family variants in a coding course.','Configuring a broadcast audio encoder.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Low-complexity profile');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '95f59777-0db8-4426-b63f-c5a7a51953b2','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='95f59777-0db8-4426-b63f-c5a7a51953b2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='95f59777-0db8-4426-b63f-c5a7a51953b2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2b834b5f-e47f-4ed3-bf21-06cfa22c986a','Low-frequency effects channel','The low-frequency effects (LFE) channel is the ''.1'' channel of surround formats such as 5.1, carrying only low-frequency content, typically band-limited to roughly 20–120 Hz. Per ITU-R BS.775 it is a separate, band-limited channel intended for high-level low-frequency effects and is reproduced with an in-band gain of about 10 dB above the main channels.','The LFE is the deep-bass channel in surround sound. It is the point-one in five-point-one. It carries only very low sounds, like rumbles and explosions. It plays with extra gain so the effects hit hard.','It provides extra low-frequency headroom for impact effects without overloading the full-range main channels.','Mixing a film in 5.1, the engineer routes only sub-bass effects to the LFE and monitors it with the standard +10 dB in-band gain so playback matches theatrical calibration.','Surround Sound',ARRAY['Monitoring reference level','Maximum sound pressure level','Low-complexity profile','Line source array']::text[],ARRAY['Confusing the LFE channel with a subwoofer output; bass management can send main-channel bass to the sub too.','Putting full-range or musical low end into LFE instead of dedicated effects.','Forgetting the +10 dB in-band monitoring gain, mis-judging LFE level.']::text[],ARRAY['Routing effects in a 5.1 film mix.','Calibrating LFE level on a monitoring system.','Explaining the difference between LFE and subwoofer feeds.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Low-frequency effects channel');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2b834b5f-e47f-4ed3-bf21-06cfa22c986a','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2b834b5f-e47f-4ed3-bf21-06cfa22c986a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2b834b5f-e47f-4ed3-bf21-06cfa22c986a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '623c7de4-6bb1-414d-804d-7face60c077e','Low-frequency oscillator rate','Low-frequency oscillator (LFO) rate is the frequency of a modulation oscillator in a synthesizer or effect, usually set below the audio band (roughly 0.1 to 20 Hz). It sets how fast the LFO sweeps a target parameter such as pitch, amplitude, or filter cutoff.','An LFO is a slow wave inside a synth. Its rate is how fast that wave cycles. It usually moves slower than we can hear as a tone. It creates effects like wobble, vibrato, and tremolo.','It controls the speed of periodic modulation used to add movement such as vibrato, tremolo, and filter sweeps.','To add gentle vibrato, a player sets the LFO rate near 5 Hz and routes it to pitch; a slow 0.2 Hz rate instead gives a long, sweeping filter movement.','Synthesis',ARRAY['Modulation transfer function','Maximum length sequence','Log-mel spectrogram','Level-dependent frequency response']::text[],ARRAY['Confusing LFO rate with the depth or amount of modulation.','Assuming an LFO produces audible tone; it usually stays below hearing.','Forgetting tempo-sync, where rate is set in note values instead of hertz.']::text[],ARRAY['Dialing in vibrato or tremolo speed on a synth.','Syncing a filter sweep to song tempo.','Explaining modulation sources in a synthesis lesson.']::text[],'beginner','T = 1 / f_LFO','The modulation period equals one divided by the low-frequency oscillator rate.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Low-frequency oscillator rate');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '623c7de4-6bb1-414d-804d-7face60c077e','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='623c7de4-6bb1-414d-804d-7face60c077e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='623c7de4-6bb1-414d-804d-7face60c077e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5bbd3ed5-b2ee-4584-9b26-bfd34c5e2730','Masker level','Masker level is the sound pressure level of a masking sound used in a masking experiment or perceptual audio coder. It sets how much a nearby target (probe) signal is rendered inaudible, and it shapes the frequency and level extent of the resulting masking.','A masker is a sound that hides another sound. Its masker level is simply how loud that hiding sound is. A louder masker hides more of the quieter target. Audio coders use this idea to drop sounds you would not hear.','It quantifies the strength of a masking sound so masking thresholds and perceptual coding decisions can be predicted.','A perceptual coder estimates the masker level of loud spectral components, then allows quantization noise to rise beneath the resulting masking threshold where it stays inaudible.','Psychoacoustics',ARRAY['Intensity Discrimination','Minimum audible pressure','Intensity stereo','Lombard effect']::text[],ARRAY['Confusing masker level with masking threshold, the level below which the target becomes inaudible.','Assuming masking is symmetric; it spreads more toward higher frequencies at high levels.','Ignoring that masking grows nonlinearly with masker level.']::text[],ARRAY['Setting up a tone-in-noise masking experiment.','Explaining bit allocation in a perceptual coder.','Predicting audibility of quantization noise.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Masker level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5bbd3ed5-b2ee-4584-9b26-bfd34c5e2730','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5bbd3ed5-b2ee-4584-9b26-bfd34c5e2730') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5bbd3ed5-b2ee-4584-9b26-bfd34c5e2730');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2a8f230f-8e38-4033-a351-627e0599a61e','Maximum length sequence','A maximum length sequence (MLS) is a periodic pseudo-random binary sequence generated by a maximal linear-feedback shift register of n stages, with period 2ⁿ − 1. Its nearly flat spectrum and impulse-like circular autocorrelation let a system''s impulse response be recovered by cross-correlation of the output with the sequence.','An MLS is a special random-looking string of ones and zeros. It repeats after two-to-the-n minus one steps. It has an even, flat spectrum. Engineers play it through a system to measure its impulse response.','It provides a robust, energy-efficient stimulus for measuring impulse responses and transfer functions of rooms and equipment.','To measure a room, a technician plays a 16-stage MLS (length 65 535) through a loudspeaker and cross-correlates the recorded signal with it to extract the room impulse response.','Measurement Signals',ARRAY['Modulation transfer function','Kurtosis of noise','Minimum phase response','Line source array']::text[],ARRAY['Assuming an MLS is truly random; it is deterministic and exactly repeatable.','Applying it to time-varying or nonlinear systems, where distortion products corrupt the result.','Confusing MLS measurement with swept-sine measurement, which handles distortion differently.']::text[],ARRAY['Measuring a room impulse response for acoustics work.','Characterizing a loudspeaker''s transfer function.','Teaching correlation-based measurement methods.']::text[],'advanced','L = 2ⁿ − 1','The sequence length equals two raised to the number of shift-register stages, minus one.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Maximum length sequence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2a8f230f-8e38-4033-a351-627e0599a61e','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2a8f230f-8e38-4033-a351-627e0599a61e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2a8f230f-8e38-4033-a351-627e0599a61e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0bade6e7-c732-4f25-8c6f-5a6ff214c6ec','Maximum sound pressure level','Maximum sound pressure level is the highest sound pressure level a device can produce or is rated to reproduce, stated at a defined distance and within a stated distortion or power limit. For loudspeakers it is measured per methods such as IEC 60268-5 and AES2, and it is expressed relative to the 20 µPa reference.','This is the loudest a speaker can safely and cleanly play. It is given at a set distance and distortion limit. Makers use it to show how much level a box can deliver. It is measured in decibels against a fixed reference.','It tells a system designer how much acoustic level a source can deliver before distortion or damage, which sizes systems for a venue.','Choosing speakers for a room, an engineer checks the rated maximum SPL at 1 m, then subtracts distance loss to confirm the box can reach the target level at the back row.','Loudspeaker Specs',ARRAY['Line source array','Level-dependent frequency response','Low-frequency effects channel','Monitoring reference level']::text[],ARRAY['Comparing max-SPL figures without checking the distortion limit and distance used.','Confusing peak and continuous (RMS) maximum SPL ratings.','Assuming the rating holds across all frequencies rather than a stated band.']::text[],ARRAY['Sizing a sound system for a venue.','Comparing loudspeaker datasheets.','Verifying a monitor can reach reference level without strain.']::text[],'intermediate','L_p = 20 log10(p / p₀)','The sound pressure level in decibels equals twenty times the base-ten logarithm of the sound pressure divided by the reference pressure.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Maximum sound pressure level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0bade6e7-c732-4f25-8c6f-5a6ff214c6ec','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0bade6e7-c732-4f25-8c6f-5a6ff214c6ec') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0bade6e7-c732-4f25-8c6f-5a6ff214c6ec');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e86dd5ae-8310-438b-a0fc-7363c8dcce23','Middle-ear transfer function','The middle-ear transfer function describes how efficiently the middle ear transmits sound from the eardrum to the cochlea''s fluid across frequency. It has a broad band-pass shape, most efficient around 0.5–4 kHz, providing impedance matching between air and the inner-ear fluids.','The middle ear passes sound from the eardrum to the inner ear. This function shows how well it does that at each pitch. It works best in the mid frequencies. It matches airborne sound to the fluid inside the ear.','It captures the frequency-dependent efficiency of the ear''s mechanical link, helping explain the shape of hearing sensitivity.','A hearing researcher combines the middle-ear transfer function with ear-canal resonance to model why human hearing is most sensitive in the few-kilohertz region.','Auditory Physiology',ARRAY['Minimum audible field','Minimum audible pressure','Modulation transfer function','Monaural cue']::text[],ARRAY['Confusing the middle-ear transfer function with the outer-ear (ear-canal and pinna) response.','Assuming it is flat rather than band-pass shaped.','Ignoring its role in impedance matching between air and cochlear fluid.']::text[],ARRAY['Modeling the sensitivity of human hearing.','Explaining conductive hearing loss.','Deriving loudness models from ear mechanics.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Middle-ear transfer function');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e86dd5ae-8310-438b-a0fc-7363c8dcce23','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e86dd5ae-8310-438b-a0fc-7363c8dcce23') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e86dd5ae-8310-438b-a0fc-7363c8dcce23');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9e2590aa-4d64-4961-b547-6c5ea510fb55','Minimum audible angle','The minimum audible angle (MAA) is the smallest change in the angular direction of a sound source that a listener can reliably detect. It is smallest, about one to two degrees, for sources directly ahead and degrades for sources to the side and for mid-frequency tones near 1.5–2 kHz.','This is the smallest shift in a sound''s direction you can notice. It is best for sounds right in front of you. There, people can spot a change of about one degree. It gets worse toward the sides.','It sets the resolution of human directional hearing, informing speaker placement, spatial audio, and localization research.','Placing front speakers, a designer knows listeners resolve about one degree ahead, so tiny center-image shifts are audible while side placements can be coarser.','Spatial Hearing',ARRAY['Interchannel time difference','Monaural cue','Minimum audible field','Line source array']::text[],ARRAY['Assuming the same angular resolution to the side as to the front.','Confusing the minimum audible angle with absolute localization accuracy.','Ignoring the mid-frequency worsening where time and level cues overlap.']::text[],ARRAY['Positioning loudspeakers for accurate imaging.','Designing spatial-audio panning resolution.','Studying human sound localization.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Minimum audible angle');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9e2590aa-4d64-4961-b547-6c5ea510fb55','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9e2590aa-4d64-4961-b547-6c5ea510fb55') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9e2590aa-4d64-4961-b547-6c5ea510fb55');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9476142d-1069-4f0b-a4d5-c2dad757b4b5','Minimum audible field','The minimum audible field (MAF) is the threshold of hearing measured as the free-field sound pressure level of a frontally incident sound at the position that the listener''s head would occupy, with the head absent. It is standardized for binaural, frontal free-field listening in ISO 389-7.','This is the quietest sound you can hear in a free open field. It uses both ears and a sound coming from the front. The level is measured where your head would be, but with no head there. It defines normal hearing thresholds.','It provides a reference for the quietest audible sound under free-field listening, used to calibrate audiometry and define hearing thresholds.','An audiometric lab uses ISO 389-7 minimum audible field values to set the free-field reference against which a listener''s frontal hearing thresholds are compared.','Hearing Thresholds',ARRAY['Minimum audible pressure','Middle-ear transfer function','Minimum audible angle','Maximum sound pressure level']::text[],ARRAY['Confusing minimum audible field (free-field, both ears) with minimum audible pressure (at the eardrum, one ear).','Forgetting that MAF is measured with the head absent.','Assuming MAF and MAP give identical thresholds; they differ by several decibels.']::text[],ARRAY['Calibrating free-field audiometry.','Comparing binaural free-field with earphone thresholds.','Defining a hearing-threshold reference curve.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Minimum audible field');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9476142d-1069-4f0b-a4d5-c2dad757b4b5','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9476142d-1069-4f0b-a4d5-c2dad757b4b5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9476142d-1069-4f0b-a4d5-c2dad757b4b5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9422104b-679a-4e2c-b15e-21da66694887','Minimum audible pressure','The minimum audible pressure (MAP) is the threshold of hearing measured as the sound pressure level at or near the eardrum, typically for monaural earphone listening. Because it excludes ear-canal resonance gain and binaural summation, MAP thresholds are several decibels higher than the corresponding free-field minimum audible field.','This is the quietest sound you can hear at the eardrum. It is usually measured with one earphone. It skips the boost the open ear canal adds. So its thresholds read a bit higher than the open-field version.','It defines the hearing threshold measured close to the eardrum, used to calibrate earphone audiometry.','Calibrating supra-aural earphones, an audiometry lab uses minimum audible pressure reference thresholds so an earphone tone at threshold matches a standard listener''s ear.','Hearing Thresholds',ARRAY['Minimum audible field','Middle-ear transfer function','Masker level','Intensity Discrimination']::text[],ARRAY['Confusing minimum audible pressure (eardrum, earphone) with minimum audible field (free field).','Forgetting the roughly 6–10 dB difference between MAP and MAF.','Ignoring the loss of ear-canal resonance gain under earphones.']::text[],ARRAY['Calibrating earphone-based audiometry.','Explaining the MAP versus MAF discrepancy.','Setting reference-equivalent threshold levels for headphones.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Minimum audible pressure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9422104b-679a-4e2c-b15e-21da66694887','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9422104b-679a-4e2c-b15e-21da66694887') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9422104b-679a-4e2c-b15e-21da66694887');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c7b5ca8b-a63a-4722-b96f-925416d46f04','Minimum phase response','A minimum-phase system is a stable, causal linear system whose poles and zeros all lie inside the unit circle (or left half-plane), giving the least possible phase lag and group delay for its magnitude response. Such a system has a stable, causal inverse and concentrates its energy as early as possible.','A minimum-phase system adds the least possible delay for its tone shape. All its math sits in the stable region. That means you can undo it cleanly. Many speakers and filters are close to minimum phase.','It identifies systems whose magnitude and phase are linked and that can be corrected by a stable inverse filter, which matters for equalization.','Correcting a loudspeaker whose response is minimum-phase, an engineer applies an inverse EQ that fixes both magnitude and phase; a non-minimum-phase dip from reflections cannot be fixed this way.','Systems Theory',ARRAY['Modulation transfer function','Maximum length sequence','Inverse constant-Q transform','Karhunen-Loeve transform']::text[],ARRAY['Assuming every response can be inverted; only minimum-phase parts have a stable causal inverse.','Confusing minimum phase with linear phase; they are different properties.','Treating acoustic interference dips as minimum-phase and trying to EQ them out.']::text[],ARRAY['Deciding whether a loudspeaker dip is correctable by EQ.','Designing invertible correction filters.','Explaining the magnitude-phase relationship of filters.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Minimum phase response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c7b5ca8b-a63a-4722-b96f-925416d46f04','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c7b5ca8b-a63a-4722-b96f-925416d46f04') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c7b5ca8b-a63a-4722-b96f-925416d46f04');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5ac3058a-a8c6-4ae5-befb-fd032b0cd46b','Modulation transfer function','In acoustics the modulation transfer function (MTF) describes how well a transmission path preserves the amplitude-modulation depth of a signal as a function of modulation frequency. It underpins the speech transmission index of IEC 60268-16, where reverberation and noise reduce modulation depth and thus intelligibility.','Speech carries slow loudness changes that shape words. The modulation transfer function shows how well a room keeps those changes. Echo and noise flatten them out. Less modulation left means harder-to-understand speech.','It links room reverberation and noise to loss of speech modulation, providing the physical basis for objective intelligibility metrics.','Measuring a hall''s speech transmission index, a technician evaluates the MTF across 7 octave bands and 14 modulation frequencies; a long reverberation time drives the reduction factor down and lowers the score.','Speech Intelligibility',ARRAY['Maximum length sequence','Minimum phase response','Line source array','Masker level']::text[],ARRAY['Confusing the acoustic MTF with the optical MTF used in imaging.','Assuming only noise lowers the MTF; reverberation does too.','Reading the MTF as a frequency response rather than a modulation-depth ratio.']::text[],ARRAY['Assessing speech intelligibility of a PA system.','Computing the speech transmission index of a room.','Comparing reverberation effects on clarity.']::text[],'advanced','m(F) = 1 / sqrt(1 + (2π F · T / 13.8)²)','The reverberation modulation reduction equals one over the square root of one plus the square of two pi times the modulation frequency times the reverberation time divided by 13.8.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Modulation transfer function');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5ac3058a-a8c6-4ae5-befb-fd032b0cd46b','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5ac3058a-a8c6-4ae5-befb-fd032b0cd46b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5ac3058a-a8c6-4ae5-befb-fd032b0cd46b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '75c7f2b4-65ae-4868-bef5-ef4ee05a691a','Monaural cue','A monaural cue is a localization cue available from a single ear, arising mainly from the direction-dependent filtering of the outer ear (pinna) and head. These spectral cues help resolve source elevation and front-back position, which the interaural time and level differences alone cannot disambiguate.','A monaural cue is a clue from just one ear. The outer ear shapes sound depending on its direction. That coloring tells you if a sound is high, low, front, or back. It fills gaps the two-ear timing cues cannot.','It supplies spectral information that lets listeners judge elevation and resolve front-back confusions in localization.','Designing spatial audio over headphones, an engineer applies head-related transfer functions so pinna-based monaural spectral cues place sounds above and behind the listener convincingly.','Spatial Hearing',ARRAY['Minimum audible angle','Interchannel time difference','Interchannel level difference','Iterative closest point registration']::text[],ARRAY['Confusing monaural spectral cues with the binaural time and level cues.','Assuming one ear cannot contribute to localization.','Ignoring how earphone playback that bypasses the pinna weakens these cues.']::text[],ARRAY['Rendering elevation in binaural audio.','Explaining front-back confusion in localization.','Designing personalized HRTFs.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Monaural cue');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '75c7f2b4-65ae-4868-bef5-ef4ee05a691a','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='75c7f2b4-65ae-4868-bef5-ef4ee05a691a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='75c7f2b4-65ae-4868-bef5-ef4ee05a691a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c54e5970-5e7c-4032-92f1-52ff774c60ec','Monitoring reference level','Monitoring reference level is a calibrated acoustic playback level tied to a defined electrical reference, so that a standard test signal produces a known sound pressure level per channel. In theatrical mixing a −20 dBFS pink-noise signal is aligned to about 85 dB SPL (C-weighted) per full-range channel; refined and small-room practice, including the K-System, commonly uses 83 dB SPL.','This is a fixed listening loudness for mixing. A standard test noise is set to a known sound level. Then everyone mixes at the same volume. This keeps tone and loudness choices consistent between rooms.','It standardizes monitoring loudness so mixes translate consistently between studios and match delivery targets.','Calibrating a dubbing stage, an engineer plays −20 dBFS pink noise and adjusts each full-range channel to read 85 dB SPL (C, slow), setting surround channels a few decibels lower per the format.','Monitoring Calibration',ARRAY['Maximum sound pressure level','Level-dependent frequency response','Low-frequency effects channel','Line source array']::text[],ARRAY['Assuming one fixed number fits every room; theatrical (85 dB) and small-room/K-System (83 dB) references differ.','Using A-weighting when the standard calls for C-weighting.','Forgetting that surround channels are aligned a few decibels below the front channels.']::text[],ARRAY['Calibrating a film dubbing stage.','Setting a consistent mix monitoring level in a studio.','Matching monitoring level to a loudness delivery spec.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Monitoring reference level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c54e5970-5e7c-4032-92f1-52ff774c60ec','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c54e5970-5e7c-4032-92f1-52ff774c60ec') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c54e5970-5e7c-4032-92f1-52ff774c60ec');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5fbf7a67-b680-428e-a887-a854d72ea212','Mother wavelet','A mother wavelet is the prototype oscillatory, finite-energy function from which all the analysis functions of a wavelet transform are generated by scaling (dilation) and translation. Choosing the mother wavelet fixes the shape used to match features in the signal and the transform''s time-frequency behaviour.','A mother wavelet is a small wave shape. The wavelet transform stretches and shifts it to scan a signal. Its shape decides what features stand out. Different tasks use different mother wavelets.','It defines the basic waveform of a wavelet analysis, setting how the transform localizes events in both time and frequency.','To detect sharp transients, an engineer picks a compact mother wavelet such as a Daubechies wavelet, then scales and shifts it across the signal to flag clicks.','Signal Transforms',ARRAY['Inverse constant-Q transform','Karhunen-Loeve transform','Log-mel spectrogram','Minimum phase response']::text[],ARRAY['Assuming one mother wavelet suits every signal; the choice shapes the result.','Confusing the mother wavelet with the scaling function of a filter bank.','Forgetting that a valid wavelet must have zero mean and finite energy.']::text[],ARRAY['Choosing a wavelet for transient detection.','Denoising audio with a wavelet transform.','Teaching multiresolution analysis.']::text[],'advanced','ψ_{a,b}(t) = (1/√a) ψ((t − b) / a)','A wavelet at scale a and shift b equals one over the square root of the scale, times the mother wavelet evaluated at the time minus the shift, divided by the scale.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mother wavelet');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5fbf7a67-b680-428e-a887-a854d72ea212','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5fbf7a67-b680-428e-a887-a854d72ea212') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5fbf7a67-b680-428e-a887-a854d72ea212');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '64154597-316b-409a-b3a6-4ba1de43d40e','Multitalker babble','Multitalker babble is a masking sound made by summing the speech of several talkers speaking at once, so individual words become unintelligible and only a steady speech-shaped murmur remains. It is used as a competing background in speech-in-noise intelligibility tests, where its long-term spectrum approximates that of running speech.','Multitalker babble is many voices talking at the same time. Mixed together, no single voice can be understood. It sounds like a crowded, busy room. Testers play it behind speech to measure how well people hear words in noise.','It supplies a realistic, speech-like masker for measuring how noise degrades speech understanding, reproducing the energetic and informational masking of real crowded spaces.','A technician validating an intercom plays speech at a fixed level against multitalker babble, then varies the signal-to-noise ratio to find the intelligibility threshold.','Test signal',ARRAY['Speech Intelligibility Index','Signal-to-noise ratio','Speech-shaped noise','Narrowband noise','Articulation index']::text[],ARRAY['Assuming babble is the same as white or pink noise; its spectrum and fluctuations follow speech.','Confusing energetic masking with informational masking, which babble adds because listeners hear competing words.','Using too few talkers, leaving gaps and intelligible words that weaken the masking.']::text[],ARRAY['Bench-testing noise suppression on a conferencing microphone.','Running a clinical speech-in-noise audiometry test.','Evaluating public-address clarity in a simulated crowded terminal.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Multitalker babble');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '64154597-316b-409a-b3a6-4ba1de43d40e','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='64154597-316b-409a-b3a6-4ba1de43d40e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='64154597-316b-409a-b3a6-4ba1de43d40e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ce359967-641a-44d0-bc7d-f807dbd95f17','Multitrack stem','A stem is a submix of a production that groups related tracks—such as all drums, all vocals, or all dialogue—printed as one mono, stereo, or multichannel file. Stems are made from a full multitrack session so a mix can later be re-balanced, re-mastered, or re-versioned without returning to every original track.','A stem is a group of tracks mixed down into one file. For example, all the drums become a single drum stem. Engineers keep stems so they can adjust a mix later. Film work uses dialogue, music, and effects stems.','Stems preserve the internal balance of part of a mix while reducing many tracks to a few manageable files for mastering, remixing, or delivery.','A mastering engineer receives drum, bass, vocal, and instrument stems, then lifts the vocal stem a little to fix a buried lead without a full remix.','Production workflow',ARRAY['Submix','Bus','Multitrack recording','Dialogue-music-effects','Mixdown']::text[],ARRAY['Confusing a stem (a grouped submix) with a single track or with the final full mix.','Printing stems with master-bus processing that stops later independent adjustment.','Assuming stems always sum exactly to the master when the master chain differs.']::text[],ARRAY['Delivering stems for a film''s final re-recording mix.','Supplying stems to a mastering house for level tweaks.','Creating instrumental and vocal stems for a remix.']::text[],'beginner',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Multitrack stem');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ce359967-641a-44d0-bc7d-f807dbd95f17','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ce359967-641a-44d0-bc7d-f807dbd95f17') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ce359967-641a-44d0-bc7d-f807dbd95f17');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '11587b07-e6b2-473f-b0ec-b7e8e13a5941','Narrowband noise','Narrowband noise is random noise whose energy is confined to a frequency band that is small compared with its center frequency, so its bandwidth-to-center-frequency ratio is much less than one. It is typically produced by band-pass filtering broadband noise and is characterized by its center frequency and bandwidth.','Narrowband noise is random noise limited to a small range of frequencies. It sounds like a rushing sound with a clear pitch region. Engineers make it by filtering wideband noise. It is used to test one part of the spectrum at a time.','It lets a technician probe a system or the ear at a chosen frequency region while keeping the random character of noise, which suits masking and response tests.','To measure masking, an audiologist centers narrowband noise at 1 kHz with a 160 Hz band and raises its level until a 1 kHz tone becomes inaudible.','Test signal',ARRAY['Broadband noise','Pink noise','Critical band','Band-pass filter','Center frequency']::text[],ARRAY['Calling any filtered noise narrowband; the band must be small relative to the center frequency.','Confusing bandwidth in hertz with fractional (percentage) bandwidth.','Assuming narrowband noise has a single frequency like a sine tone.']::text[],ARRAY['Masking experiments in audiology.','Testing a loudspeaker''s response in one octave band.','Exciting a single room mode for study.']::text[],'intermediate','B_rel = Delta_f / f_c ,  narrowband when Delta_f / f_c << 1','Relative bandwidth is the filter bandwidth divided by the center frequency; noise is narrowband when this ratio is much less than one.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Narrowband noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '11587b07-e6b2-473f-b0ec-b7e8e13a5941','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='11587b07-e6b2-473f-b0ec-b7e8e13a5941') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='11587b07-e6b2-473f-b0ec-b7e8e13a5941');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '08f76e87-d53b-4dbf-bb4e-7bdf96ba0fcd','Near-field criterion','The near-field criterion is the set of distance conditions separating a source''s acoustic near field—where sound pressure and particle velocity are not simply related and level does not fall predictably with distance—from the far field, where the wave behaves locally like a plane wave. Far-field conditions generally require the measurement distance to be large compared with the wavelength, large compared with the source''s largest dimension, and such that the product of wavenumber and distance greatly exceeds one.','Close to a source, sound behaves in a complex way. This zone is the near field. Farther out, the sound settles into a simple spreading pattern, the far field. The near-field criterion tells you how far away you must be for simple far-field rules to hold.','It tells a measurer where the inverse-square law and free-field assumptions are valid, so recorded levels and directivity are correct and repeatable.','For a 0.3 m loudspeaker radiating 100 Hz (wavelength about 3.4 m), a technician measures several meters away, so the distance exceeds both the source size and the wavelength.','Acoustic measurement',ARRAY['Far field','Free field','Inverse-square law','Wavenumber','Rayleigh distance']::text[],ARRAY['Assuming the far field starts at a fixed distance regardless of frequency; the wavelength matters.','Measuring loudspeaker response too close, where the near field distorts the result.','Confusing the reactive near field with the geometric near field of a large source.']::text[],ARRAY['Choosing a microphone distance for anechoic speaker measurement.','Deciding standoff distance for sound-power tests.','Explaining why bass measurements need more room than treble.']::text[],'advanced','r >> lambda ,  r >> D ,  and  k r >> 1   (k = 2*pi/lambda)','Far-field conditions hold when the distance is much greater than the wavelength, much greater than the largest source dimension, and the wavenumber times the distance is much greater than one.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Near-field criterion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '08f76e87-d53b-4dbf-bb4e-7bdf96ba0fcd','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='08f76e87-d53b-4dbf-bb4e-7bdf96ba0fcd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='08f76e87-d53b-4dbf-bb4e-7bdf96ba0fcd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '51428292-3020-41a7-9057-87d52ecc374c','Noise criterion curve','A noise criterion (NC) curve is one of a family of reference spectra that specify the maximum octave-band sound pressure levels, from 63 Hz to 8 kHz, permitted for a given single-number NC rating of steady background noise in an occupied space. A room''s NC rating is the lowest curve that lies entirely above its measured octave-band spectrum.','NC curves rate steady background noise in a room. Each curve is a line of allowed loudness across frequency bands. You compare a room''s measured noise to these curves. The lowest curve the noise fits under is the room''s NC number. Lower numbers mean quieter rooms.','NC curves give a single-number target for acceptable HVAC and background noise that accounts for the ear''s changing sensitivity across frequency.','A technician measures octave-band levels in a conference room and finds the spectrum fits just under NC-35, meeting a typical office design goal.','Noise metric',ARRAY['Room criterion (RC)','Noise rating (NR)','Octave band','Background noise','A-weighting']::text[],ARRAY['Reading NC as a single A-weighted number; it is set by the worst-fitting octave band.','Confusing NC curves with the ISO noise rating (NR) curves, which differ.','Assuming a lower NC always costs more without checking the dominant band.']::text[],ARRAY['Specifying HVAC noise limits for a recording space.','Commissioning a classroom''s background noise.','Comparing two rooms'' quietness with one number.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise criterion curve');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '51428292-3020-41a7-9057-87d52ecc374c','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='51428292-3020-41a7-9057-87d52ecc374c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='51428292-3020-41a7-9057-87d52ecc374c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bd1080fc-79e2-4bb2-92b9-1b3f4a9f67f0','Noise-reduction coefficient','The noise-reduction coefficient (NRC) is a single-number rating of a material''s sound absorption, computed as the arithmetic average of its sound absorption coefficients measured in a reverberation room at 250, 500, 1000, and 2000 Hz, rounded to the nearest 0.05. Values range from 0 (fully reflective) to about 1 (fully absorptive).','NRC is one number that rates how well a material soaks up sound. It averages absorption at four mid frequencies. The result runs from 0 to about 1. A higher number means the material absorbs more sound.','It condenses a full absorption curve into one comparison figure so designers can quickly rank acoustic treatments for speech-range noise control.','A panel absorbs 0.55, 0.80, 0.90, and 0.95 at the four bands; the average is 3.20/4 = 0.80, so its NRC is 0.80.','Absorption metric',ARRAY['Sound absorption coefficient','Sound Absorption Average (SAA)','Reverberation time','Reverberation room','Sabine absorption']::text[],ARRAY['Thinking NRC covers deep bass and high treble; it only averages 250-2000 Hz.','Treating NRC above 1.0 as impossible; edge effects can push measured values slightly over 1.','Confusing NRC with the newer Sound Absorption Average (SAA), which uses more bands.']::text[],ARRAY['Selecting ceiling tiles for an open office.','Comparing acoustic panels on a datasheet.','Estimating treatment for a reverberant room.']::text[],'beginner','NRC = (alpha_250 + alpha_500 + alpha_1000 + alpha_2000) / 4 , rounded to nearest 0.05','The noise-reduction coefficient is the average of the sound absorption coefficients at 250, 500, 1000, and 2000 Hz, rounded to the nearest 0.05.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise-reduction coefficient');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bd1080fc-79e2-4bb2-92b9-1b3f4a9f67f0','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bd1080fc-79e2-4bb2-92b9-1b3f4a9f67f0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bd1080fc-79e2-4bb2-92b9-1b3f4a9f67f0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6c139cdc-8f40-4a3d-9576-5367d2358601','Nonlinear distortion measure','A nonlinear distortion measure quantifies the unwanted spectral components a device adds because its transfer characteristic is not perfectly linear. The most common measure, total harmonic distortion (THD), is the ratio of the root-sum-square level of the harmonic components to the level of the fundamental, usually expressed as a percentage or in decibels.','Real gear never treats a signal perfectly. It adds extra tones that were not in the original. A distortion measure puts a number on those extra tones. Total harmonic distortion is the most common one. It compares the added harmonics to the original tone.','These measures let a technician grade how faithfully an amplifier, converter, or transducer reproduces a signal and set pass/fail limits.','Driving an amplifier with a 1 kHz tone, an analyzer reads harmonics whose combined level is 1% of the fundamental, so THD = 1% (about -40 dB).','Distortion metric',ARRAY['Total harmonic distortion','THD+N','Intermodulation distortion','Harmonic','Linearity']::text[],ARRAY['Reporting THD without the test frequency, level, and bandwidth, which all change the result.','Confusing THD with THD+N, which also includes noise.','Assuming a lower THD always sounds better regardless of harmonic order.']::text[],ARRAY['Bench-testing a power amplifier.','Qualifying an A/D converter.','Comparing microphone-preamp linearity.']::text[],'intermediate','THD = sqrt(V2^2 + V3^2 + ... + Vn^2) / V1  (x100%)','Total harmonic distortion is the root-sum-square of the harmonic amplitudes divided by the fundamental amplitude, often shown as a percentage.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Nonlinear distortion measure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6c139cdc-8f40-4a3d-9576-5367d2358601','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6c139cdc-8f40-4a3d-9576-5367d2358601') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6c139cdc-8f40-4a3d-9576-5367d2358601');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a80c9e72-6fe6-48e1-92e9-f358da0104f7','Off-axis response','The off-axis response is the frequency response of a loudspeaker or microphone measured at angles away from its principal (on-axis) direction. Together with on-axis data it defines the device''s directional behavior, revealing how output level and timbre change with angle.','Speakers and microphones do not sound the same in every direction. The off-axis response shows what they do to the side and above or below. It tells how much treble is lost off to the side. This shapes how a room hears the sound.','It characterizes directivity so designers can predict coverage, reflections, and tonal balance for listeners who are not directly in front of the device.','A technician measures a tweeter at 0, 30, and 60 degrees and finds the 10 kHz level drops 6 dB at 60 degrees, guiding speaker aiming for even coverage.','Loudspeaker measurement',ARRAY['On-axis response','Directivity index','Polar pattern measurement','Coverage angle','Off-axis coloration']::text[],ARRAY['Judging a speaker only by its on-axis curve and ignoring off-axis behavior.','Assuming off-axis response is flat when on-axis is flat.','Confusing off-axis level loss with simple distance attenuation.']::text[],ARRAY['Aiming line-array elements for even coverage.','Choosing studio monitors for a wide listening area.','Evaluating a microphone''s rejection of off-axis sources.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Off-axis response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a80c9e72-6fe6-48e1-92e9-f358da0104f7','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a80c9e72-6fe6-48e1-92e9-f358da0104f7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a80c9e72-6fe6-48e1-92e9-f358da0104f7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '538604e4-f562-49d9-825d-4e3c53eb2a30','Overlap-add reconstruction','Overlap-add is a method for reconstructing a continuous signal from overlapping short-time frames after block-based processing such as the short-time Fourier transform. Each processed frame is placed at its original time position and summed with its neighbors; when the analysis windows satisfy the constant-overlap-add condition, the overlaps sum to a constant and the signal is recovered without seams.','Many effects chop audio into short overlapping frames. Each frame is processed on its own. Overlap-add glues the frames back together. It lays each frame in place and adds the overlaps. When the windows are chosen well, the seams disappear.','It lets frequency-domain processing—filtering, noise reduction, pitch shifting—be applied frame by frame and then joined back into a click-free continuous signal.','In a noise reducer using 1024-sample frames with 50% overlap and a Hann window, the processed frames are summed by overlap-add to output seamless audio.','Signal processing',ARRAY['Short-time Fourier transform','Hann window','Constant overlap-add','Hop size','Overlap-save']::text[],ARRAY['Choosing a window and hop that violate the constant-overlap-add condition, causing amplitude ripple.','Confusing overlap-add with overlap-save, which handles convolution edges differently.','Forgetting to compensate window gain, leaving a level change.']::text[],ARRAY['Building a spectral noise-reduction plug-in.','Implementing fast convolution reverb.','Phase-vocoder time-stretching.']::text[],'advanced','y[n] = sum_m ( y_m[n - m*H] ) ,  with COLA: sum_m w[n - m*H] = C','The output is the sum of the processed frames placed at their hop positions; perfect reconstruction requires the shifted windows to add up to a constant.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Overlap-add reconstruction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '538604e4-f562-49d9-825d-4e3c53eb2a30','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='538604e4-f562-49d9-825d-4e3c53eb2a30') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='538604e4-f562-49d9-825d-4e3c53eb2a30');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b484f494-c2bf-41db-af30-60627dadcf46','Peak program meter','A peak programme meter (PPM) is an audio level meter designed to indicate signal peaks using a fast, defined integration time and a deliberately slow return time, so brief high-level transients are captured and held long enough to read. Its dynamic and scale characteristics are standardized so different meters read consistently.','A peak programme meter shows how high the loudest parts of a signal reach. It grabs quick peaks fast, then falls back slowly so you can see them. This helps stop overloads that a slow meter would miss. Broadcasters rely on it to set safe levels.','It guards against overload and clipping by revealing short peaks that average-reading (VU) meters smooth over, giving a consistent reference for level setting.','Following a broadcast standard, an operator sets peaks to reach the reference PPM mark (for example PPM 4), the fast attack and slow decay keeping transients visible.','Metering standard',ARRAY['VU meter','True-peak meter','Loudness metering','Headroom','Quasi-peak']::text[],ARRAY['Treating PPM readings as loudness; a PPM shows peaks, not perceived level.','Assuming a PPM catches every sample peak; classic PPMs have finite integration time and can miss the true peak.','Confusing national PPM scales (BBC, EBU, DIN), which map differently.']::text[],ARRAY['Setting levels for broadcast transmission.','Aligning a studio''s meters to a reference tone.','Preventing digital clipping when mastering for air.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Peak program meter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b484f494-c2bf-41db-af30-60627dadcf46','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b484f494-c2bf-41db-af30-60627dadcf46') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b484f494-c2bf-41db-af30-60627dadcf46');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dd2f64bd-982b-481b-8b09-e5c0a1ef7b4c','Perceptual evaluation of audio quality','Perceptual Evaluation of Audio Quality (PEAQ) is a standardized objective method that estimates the perceived quality of processed music and audio by comparing a reference signal with the system-under-test output through a psychoacoustic ear model. It produces an Objective Difference Grade on a scale from 0 (imperceptible impairment) to -4 (very annoying), approximating a subjective listening-test difference grade.','PEAQ is a computer method that scores audio quality. It compares the original sound with a processed copy. It uses a model of human hearing to judge the difference. The score predicts what listeners would say, without a full listening panel.','It gives codec and equipment developers a repeatable, automated estimate of audio impairment, cutting reliance on slow and costly formal listening tests.','An engineer tuning an audio codec runs PEAQ on a set of tracks and reads an Objective Difference Grade of -0.5, indicating only slightly perceptible impairment.','Quality metric',ARRAY['Objective Difference Grade','Perceptual evaluation of speech quality','Psychoacoustic model','Listening test','Audio codec']::text[],ARRAY['Treating PEAQ as built for speech telephony; it targets wideband music and audio.','Reading the Objective Difference Grade as an absolute quality score rather than a difference from the reference.','Assuming PEAQ fully replaces subjective tests; it estimates them.']::text[],ARRAY['Benchmarking lossy audio codecs.','Regression-testing a DSP change for audible impairment.','Comparing streaming bitrate ladders.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Perceptual evaluation of audio quality');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dd2f64bd-982b-481b-8b09-e5c0a1ef7b4c','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dd2f64bd-982b-481b-8b09-e5c0a1ef7b4c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dd2f64bd-982b-481b-8b09-e5c0a1ef7b4c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a62a1a78-4b4b-4d41-998f-c3482b7abe97','Perceptual evaluation of speech quality','Perceptual Evaluation of Speech Quality (PESQ) is a standardized objective algorithm that predicts the subjective quality of narrowband telephone speech by comparing a reference sample with the degraded output after time alignment and a perceptual model. Its raw output maps to a mean-opinion-score scale, approximating listener ratings of networks and speech codecs.','PESQ is a computer method that scores telephone speech quality. It compares clean speech with the speech that came through a system. It models how people hear to predict a rating. The result is close to what a listening panel would give.','It provides an automated, repeatable estimate of speech quality for testing codecs and networks, standing in for expensive subjective mean-opinion-score panels.','Testing a VoIP path, an engineer sends reference speech, captures the degraded output, and PESQ returns a MOS-equivalent score of 3.8, indicating fair-to-good quality.','Quality metric',ARRAY['Mean opinion score','Perceptual evaluation of audio quality','Narrowband speech','Speech codec','POLQA']::text[],ARRAY['Using PESQ for wideband or super-wideband speech, which its successor POLQA (ITU-T P.863) addresses.','Confusing PESQ (speech) with PEAQ (music and audio).','Reading its raw score directly as MOS without the standardized mapping.']::text[],ARRAY['Qualifying a VoIP gateway.','Comparing mobile speech codecs.','Monitoring call-quality regressions.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Perceptual evaluation of speech quality');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a62a1a78-4b4b-4d41-998f-c3482b7abe97','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a62a1a78-4b4b-4d41-998f-c3482b7abe97') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a62a1a78-4b4b-4d41-998f-c3482b7abe97');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '964fb22c-5a31-4074-bdda-b2a02ade169f','Phantom image','A phantom image is a sound source that a listener localizes at a position where no physical loudspeaker exists, created when two or more speakers reproduce correlated signals with controlled level and/or time differences. In standard stereo, equal signals in the left and right speakers produce a central phantom image between them.','In stereo, sound can seem to come from between the two speakers. No speaker sits there, so the source is a phantom. Equal sound in both speakers places it in the center. Changing the balance moves the phantom left or right.','Phantom imaging lets a small number of loudspeakers paint a continuous stereo or surround stage, forming the basis of amplitude and time panning.','To center a lead vocal, an engineer sends equal level to both stereo speakers; the listener hears a phantom image midway between them.','Spatial audio',ARRAY['Amplitude panning','Interchannel level difference','Sweet spot','Stereo image','Precedence effect']::text[],ARRAY['Assuming the phantom image is as stable and sharp as a real source; it collapses off the sweet spot.','Ignoring that time (phase) differences also shift the image, not only level.','Expecting a solid center image in mono-incompatible material.']::text[],ARRAY['Panning instruments across a stereo mix.','Setting up a stereo monitoring triangle.','Explaining why an off-center listener loses the center image.']::text[],'intermediate','tan(theta)/tan(theta_0) = (g_L - g_R)/(g_L + g_R)','In the stereophonic tangent law, the tangent of the image angle over the tangent of the half loudspeaker angle equals the difference of the channel gains over their sum.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phantom image');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '964fb22c-5a31-4074-bdda-b2a02ade169f','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='964fb22c-5a31-4074-bdda-b2a02ade169f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='964fb22c-5a31-4074-bdda-b2a02ade169f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7afc6b22-8bb8-443f-9b99-64e0426ef653','Phase-locked loop jitter','Phase-locked loop (PLL) jitter is the short-term timing variation in the output clock of a PLL relative to its ideal edges, arising from noise in the reference, oscillator, and loop filter. In digital audio, PLLs recover the sample clock from a serial stream, and their residual jitter modulates the instant at which converters sample the signal.','A phase-locked loop makes a steady clock and locks it to an incoming signal. Its output edges still wobble slightly in time. That wobble is jitter. In audio converters, jitter shifts the sampling moments and can add noise or distortion.','Understanding PLL jitter matters because clock-timing errors at a converter turn into added noise and sidebands that degrade the analog signal.','For a 1 kHz full-scale tone and 1 ns RMS jitter, the sampling error is about 2*pi*1000*1e-9 = 6.3e-6 of full scale, near -104 dB.','Clock and jitter',ARRAY['Jitter','Word clock','Sample clock','Clock recovery','Reclocking']::text[],ARRAY['Assuming any lock means a clean clock; a locked PLL still has jitter.','Confusing wander (slow drift) with jitter (fast variation).','Thinking data-link jitter matters after reclocking; only jitter at the converter clock affects audio.']::text[],ARRAY['Choosing a master clock for a converter array.','Diagnosing distortion sidebands from clock noise.','Evaluating a digital interface''s jitter rejection.']::text[],'advanced','e_rms ~= 2*pi*f*A*J_rms','The root-mean-square sampling error grows with signal frequency, signal amplitude, and the root-mean-square jitter.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phase-locked loop jitter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7afc6b22-8bb8-443f-9b99-64e0426ef653','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7afc6b22-8bb8-443f-9b99-64e0426ef653') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7afc6b22-8bb8-443f-9b99-64e0426ef653');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '57739d56-bddb-4e73-accf-023af8753125','Pinna cue','A pinna cue is a spectral feature—chiefly direction-dependent peaks and notches above roughly 4-5 kHz—imposed on incoming sound by reflections and resonances within the outer ear (pinna). The auditory system uses these cues to judge elevation and to resolve front-back confusions that interaural time and level differences cannot.','The folds of your outer ear shape incoming sound. They add small peaks and dips to the high frequencies. These changes depend on where the sound comes from. Your brain reads them to tell if a sound is high, low, in front, or behind.','Pinna cues supply the elevation and front-back information that horizontal-plane cues lack, and they are central to convincing headphone and 3D audio rendering.','Building a binaural renderer, an engineer applies measured head-related transfer functions so pinna notches place sounds correctly above and behind the listener.','Psychoacoustics',ARRAY['Head-related transfer function','Interaural level difference','Elevation cue','Front-back confusion','Binaural audio']::text[],ARRAY['Assuming interaural time and level differences alone give full 3D localization.','Ignoring individual pinna differences, which make generic HRTFs less accurate.','Thinking pinna cues act at low frequencies; they matter mainly above a few kilohertz.']::text[],ARRAY['Designing headphone spatial audio.','Measuring individual HRTFs.','Explaining elevation perception in a psychoacoustics lesson.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pinna cue');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '57739d56-bddb-4e73-accf-023af8753125','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='57739d56-bddb-4e73-accf-023af8753125') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='57739d56-bddb-4e73-accf-023af8753125');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'aa268bf7-f78e-41d7-9d27-3cabb32bcb12','Point source model','A point source model idealizes a sound source as an infinitesimally small radiator that emits equally in all directions (omnidirectional) in a free field. Under this model, sound intensity falls with the inverse square of distance, and sound pressure level decreases by 6 dB for each doubling of distance.','A point source is an imaginary source with no size that radiates evenly all around. It is a simple model, not a real speaker. With it, sound gets four times weaker each time you double the distance. That is a drop of 6 dB per doubling.','It provides the baseline for predicting how level falls with distance in the free field and underlies sound-power and coverage calculations.','Modeling a small speaker as a point source, a technician predicts that moving from 2 m to 4 m lowers the level by 6 dB.','Acoustic modeling',ARRAY['Inverse-square law','Sound power level','Free field','Spherical spreading','Line source']::text[],ARRAY['Applying the 6 dB-per-doubling rule near a large source, where it fails.','Using it indoors, where reflections flatten the falloff.','Confusing a point source (6 dB/doubling) with a line source (about 3 dB/doubling).']::text[],ARRAY['Estimating SPL at a listener from a small speaker.','Teaching the inverse-square law.','Predicting free-field coverage outdoors.']::text[],'beginner','L_p = L_W - 20*log10(r) - 11 dB  (free field, r in m)','In the free field the sound pressure level equals the sound power level minus twenty times the base-ten log of distance minus about 11 dB.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Point source model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'aa268bf7-f78e-41d7-9d27-3cabb32bcb12','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='aa268bf7-f78e-41d7-9d27-3cabb32bcb12') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='aa268bf7-f78e-41d7-9d27-3cabb32bcb12');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '730d6c75-1f81-4a9f-b1e6-b8e0b8618397','Polar pattern measurement','Polar pattern measurement is the procedure of recording a transducer''s sensitivity or output as a function of the angle of the sound relative to its axis, usually at fixed frequencies, and plotting the result in polar coordinates. For microphones it yields the directional pickup pattern; for loudspeakers it yields the radiation pattern.','This test measures how a microphone or speaker behaves at every angle. You rotate the device and record its output around a circle. The plot shows which directions it favors. It reveals shapes like cardioid or omnidirectional.','It documents directivity so a technician can choose and place microphones for rejection and loudspeakers for coverage.','Rotating a microphone on a turntable in 15-degree steps at 1 kHz, a technician plots the output and confirms a cardioid null at 180 degrees.','Microphone measurement',ARRAY['Cardioid','Directivity index','Off-axis response','Omnidirectional','Figure-of-eight']::text[],ARRAY['Measuring at one frequency and assuming the pattern holds across the spectrum.','Ignoring room reflections that corrupt a non-anechoic polar plot.','Confusing the polar pattern (angle) with the frequency response (frequency).']::text[],ARRAY['Verifying a microphone''s advertised pattern.','Mapping loudspeaker coverage for a design.','Selecting a mic to reject a monitor wedge.']::text[],'intermediate','p(theta) = A + B*cos(theta) ,  with A + B = 1 (cardioid: A = B = 0.5)','A first-order microphone''s directional response is an omnidirectional part plus a bidirectional cosine part; equal parts give a cardioid.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Polar pattern measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '730d6c75-1f81-4a9f-b1e6-b8e0b8618397','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='730d6c75-1f81-4a9f-b1e6-b8e0b8618397') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='730d6c75-1f81-4a9f-b1e6-b8e0b8618397');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8233a361-d0ad-4731-9600-25017eab7877','Quefrency','Quefrency is the independent variable of the cepstrum, which is obtained by taking the inverse transform of the logarithm of a signal''s spectrum. Although derived from frequency-domain data, quefrency has the dimension of time and separates the spectral envelope (low quefrency) from periodic fine structure such as pitch (high quefrency).','The cepstrum is the spectrum of a log spectrum. Its axis is called quefrency, an anagram of frequency. Even though it comes from frequencies, quefrency is measured in time. Low quefrency holds the broad shape; a peak at higher quefrency shows the pitch period.','Quefrency lets an analyst separate a source''s pitch period from vocal-tract or system shaping, which is key to pitch detection and deconvolution.','Finding a talker''s pitch, an engineer computes the cepstrum and reads a peak at 5 ms quefrency, indicating a 200 Hz fundamental (1/0.005 s).','Signal processing',ARRAY['Cepstrum','Liftering','Fundamental frequency','Spectral envelope','Homomorphic filtering']::text[],ARRAY['Reading quefrency as a frequency; it has units of time.','Confusing the real cepstrum with the complex cepstrum.','Expecting a clear pitch peak when the signal is unvoiced or noisy.']::text[],ARRAY['Pitch-tracking a voice.','Separating source and filter in speech analysis.','Detecting an echo via a cepstral peak.']::text[],'advanced','c(tau) = IDFT{ log|DFT{x[n]}| }','The real cepstrum is the inverse transform of the log magnitude of the signal''s spectrum; its axis, quefrency, is measured in time.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Quefrency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8233a361-d0ad-4731-9600-25017eab7877','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8233a361-d0ad-4731-9600-25017eab7877') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8233a361-d0ad-4731-9600-25017eab7877');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fcfce3f2-0db5-4709-b6c6-5d1b11a8c973','Rate-distortion optimization','Rate-distortion optimization is a coding strategy that chooses encoding decisions to minimize a weighted combination of bit rate and reconstruction distortion. It is commonly formulated as minimizing the Lagrangian cost J = D + lambda*R, where D is distortion, R is rate, and the multiplier lambda sets the trade-off, exchanging more bits for less distortion.','A codec must balance file size against quality loss. Rate-distortion optimization makes that balance a math problem. Each choice gets a cost that mixes bits used and error added. One knob sets how much each matters. The encoder picks the lowest-cost option.','It gives encoders a principled way to allocate bits, extracting the best possible quality at a target rate instead of guessing settings.','An encoder testing two quantizers computes J = D + lambda*R for each and keeps the lower-cost one, spending bits only where they cut distortion most.','Coding theory',ARRAY['Rate-distortion theory','Quantization','Lagrange multiplier','Bit allocation','Lossy compression']::text[],ARRAY['Confusing rate-distortion optimization (an encoder method) with rate-distortion theory (the information-theoretic bound).','Assuming one lambda suits all content; it must match the target rate.','Ignoring that the distortion metric may not match perception.']::text[],ARRAY['Tuning a video or audio encoder.','Choosing quantization step sizes.','Comparing encoder efficiency at a fixed bitrate.']::text[],'advanced','minimize J = D + lambda*R','The encoder minimizes a cost equal to the distortion plus a multiplier times the rate, where the multiplier sets the trade-off.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rate-distortion optimization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fcfce3f2-0db5-4709-b6c6-5d1b11a8c973','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fcfce3f2-0db5-4709-b6c6-5d1b11a8c973') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fcfce3f2-0db5-4709-b6c6-5d1b11a8c973');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4b1cedad-134c-42b7-9b33-214f1d20ae37','Region of dominance','The region of dominance (dominance region) is the band of frequencies that most strongly determines the perceived pitch of a complex tone, found experimentally to lie roughly between 500 Hz and 2 kHz for a low fundamental and to correspond to the lower harmonics. Harmonics in this region control the pitch percept even when other harmonics are mistuned.','A complex tone has many harmonics. Not all of them matter equally for pitch. A middle band, around 500 to 2000 Hz, matters most. Harmonics in this band set the pitch you hear. This band is the region of dominance.','It explains which parts of a sound''s spectrum drive pitch, informing pitch models, low-frequency reproduction priorities, and coding.','Predicting the pitch of a bass note, an analyst weights the harmonics near 500-2000 Hz most heavily, since they dominate perception.','Psychoacoustics',ARRAY['Pitch perception','Complex tone','Harmonic','Missing fundamental','Critical band']::text[],ARRAY['Assuming the fundamental frequency always dominates pitch; mid harmonics often do.','Treating the dominance region as a fixed band for all fundamentals; it shifts with pitch.','Confusing the dominance region with the critical band.']::text[],ARRAY['Modeling pitch for audio analysis.','Explaining the missing-fundamental effect.','Setting low-frequency reproduction priorities.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Region of dominance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4b1cedad-134c-42b7-9b33-214f1d20ae37','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4b1cedad-134c-42b7-9b33-214f1d20ae37') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4b1cedad-134c-42b7-9b33-214f1d20ae37');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3fa2cd4d-cc4d-407c-85d8-280b0ce318ae','Residual echo suppression','Residual echo suppression is the final stage of an echo canceller that attenuates the echo remaining after the adaptive filter has subtracted its linear estimate. Because the adaptive filter cannot remove nonlinear or unmodeled echo, a nonlinear processor further suppresses the residual, mainly during single-talk, while trying to preserve near-end speech.','An echo canceller first subtracts a copy of the echo. Some echo always leaks through. Residual echo suppression removes what is left. It turns down the leftover echo, mostly when only the far side talks. It must avoid cutting the local voice.','It cleans up the echo that a linear canceller cannot remove, delivering the low echo levels that hands-free and conferencing standards require.','Meeting an echo-canceller standard, a technician confirms the nonlinear processor lifts total echo attenuation to the required level without clipping double-talk.','Signal processing',ARRAY['Acoustic echo cancellation','Adaptive filter','Nonlinear processor','Double-talk','Echo return loss enhancement']::text[],ARRAY['Suppressing so aggressively that near-end speech is cut during double-talk.','Assuming the adaptive filter alone removes all echo.','Confusing residual echo suppression with simple noise gating.']::text[],ARRAY['Tuning a conferencing device''s echo canceller.','Certifying a hands-free phone.','Debugging echo heard on a far-end call.']::text[],'advanced','ERLE = 10*log10( E[d^2] / E[e^2] )','Echo return loss enhancement is ten times the log of the mean-square echo before cancellation over the mean-square residual after it.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Residual echo suppression');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3fa2cd4d-cc4d-407c-85d8-280b0ce318ae','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3fa2cd4d-cc4d-407c-85d8-280b0ce318ae') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3fa2cd4d-cc4d-407c-85d8-280b0ce318ae');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '76a0009a-1868-44da-81f9-009934d76f2b','Room transfer function','The room transfer function is the complex frequency-domain ratio of the sound pressure at a receiver position to the signal at a source, describing how a room modifies sound between those two points. It is the Fourier transform of the room impulse response and shows the room''s modal peaks and dips in both magnitude and phase.','A room changes sound between a source and a listener. The room transfer function describes that change across frequency. It comes from the room impulse response. It shows peaks and dips caused by room modes and reflections. It depends on where the source and listener sit.','It quantifies a room''s frequency coloring at specific points, guiding equalization, mode control, and monitor placement.','Measuring the room transfer function from monitor to mix position, a technician spots a 60 Hz peak from a room mode and treats or equalizes it.','Room acoustics',ARRAY['Room impulse response','Room mode','Transfer function','Frequency response','Modal density']::text[],ARRAY['Assuming one measured room transfer function describes the whole room; it is position-specific.','Equalizing deep nulls, which wastes energy and rarely fills them.','Ignoring phase and treating the function as magnitude-only.']::text[],ARRAY['Setting up room correction.','Diagnosing bass problems at the mix position.','Validating acoustic treatment before and after.']::text[],'advanced','H(f) = P_receiver(f) / X_source(f) = FT{ h(t) }','The room transfer function is the receiver pressure spectrum divided by the source signal spectrum, equal to the Fourier transform of the room impulse response.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Room transfer function');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '76a0009a-1868-44da-81f9-009934d76f2b','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='76a0009a-1868-44da-81f9-009934d76f2b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='76a0009a-1868-44da-81f9-009934d76f2b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ea361bb9-f675-4906-847d-74b0fcb9166a','Sequency','Sequency is a generalization of frequency for functions that take only the values +1 and -1, such as Walsh functions, defined as one half the average number of sign changes (zero crossings) per unit interval. It orders Walsh functions much as frequency orders sinusoids in Fourier analysis.','Sine waves are ranked by frequency. Square-like Walsh functions are ranked by sequency instead. Sequency counts how often the function flips sign. It is half the number of sign changes per unit time. Higher sequency means faster flipping.','Sequency lets the Walsh-Hadamard transform order its basis functions, giving a frequency-like index for fast, multiply-free signal analysis.','Using a Walsh-Hadamard transform, an engineer sorts components by sequency to separate slow trends from rapidly alternating detail.','Signal processing',ARRAY['Walsh function','Hadamard transform','Zero crossing','Frequency','Walsh-Hadamard transform']::text[],ARRAY['Equating sequency directly with frequency in hertz; they are analogous, not identical.','Forgetting the factor of one half in the sign-change count.','Assuming Walsh functions are sinusoids.']::text[],ARRAY['Applying Walsh-Hadamard transforms in coding.','Teaching non-sinusoidal transforms.','Designing spread-spectrum sequences.']::text[],'advanced','sequency = (number of sign changes over the interval) / 2  per unit interval','Sequency equals half the number of sign changes a function makes over an interval, expressed per unit length of that interval.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sequency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ea361bb9-f675-4906-847d-74b0fcb9166a','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ea361bb9-f675-4906-847d-74b0fcb9166a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ea361bb9-f675-4906-847d-74b0fcb9166a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'db812aab-33b5-4beb-85ef-0dfa3aee4371','Sidelobe level','Sidelobe level is the amplitude of the secondary maxima (sidelobes) of a directional pattern or window''s frequency response, expressed in decibels relative to the peak of the main lobe. A lower (more negative) sidelobe level means less leakage or off-axis response outside the main beam.','A beam or filter has one main peak and smaller bumps beside it. Those smaller bumps are sidelobes. The sidelobe level says how tall the biggest bump is compared to the main peak. It is given in decibels below the peak. Lower sidelobes mean less unwanted response.','It measures how well a window or array concentrates energy in the main lobe and rejects it elsewhere, trading off against main-lobe width.','Choosing an analysis window, a technician picks a Hann window (first sidelobe near -31 dB) over a rectangular window (-13 dB) to cut spectral leakage.','Signal processing',ARRAY['Window function','Main lobe','Spectral leakage','Beamforming','Directivity']::text[],ARRAY['Chasing very low sidelobes without accounting for the wider main lobe they cause.','Confusing sidelobe level (relative height) with sidelobe roll-off (how fast they fall).','Comparing windows by sidelobe level alone, ignoring resolution.']::text[],ARRAY['Selecting an FFT window for spectrum analysis.','Designing a microphone-array beamformer.','Assessing loudspeaker-array lobing.']::text[],'advanced','SLL(dB) = 20*log10( A_sidelobe / A_mainlobe )','The sidelobe level in decibels is twenty times the base-ten log of the sidelobe amplitude divided by the main-lobe peak amplitude.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sidelobe level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'db812aab-33b5-4beb-85ef-0dfa3aee4371','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='db812aab-33b5-4beb-85ef-0dfa3aee4371') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='db812aab-33b5-4beb-85ef-0dfa3aee4371');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '795d22f1-6c91-4651-8abf-a022f7e3e7fb','Sine-sweep measurement','A sine-sweep measurement excites a system with a sinusoid whose frequency is swept continuously across the band of interest, then recovers the impulse response by deconvolving the recorded output against the known sweep. With an exponential (logarithmic) sweep, the harmonic distortion products separate in time from the linear response, allowing a clean impulse response even when the device is nonlinear.','A sine sweep is a tone that glides from low to high in pitch. You play it through a system and record the result. Math then turns the recording into an impulse response. An exponential sweep pushes distortion out of the way. That gives a clean result even from imperfect gear.','It measures frequency response, impulse response, and reverberation with a high signal-to-noise ratio and, using a log sweep, isolates distortion from the linear result.','To capture a room''s impulse response, a technician plays a 20 Hz-20 kHz exponential sweep and deconvolves it, then reads reverberation time from the result.','Acoustic measurement',ARRAY['Impulse response','Deconvolution','Maximum length sequence','Frequency response','Total harmonic distortion']::text[],ARRAY['Using a linear sweep and losing the distortion-separation benefit of a log sweep.','Sweeping too fast for the room, truncating the low-frequency decay.','Forgetting the inverse filter that flattens the sweep''s spectrum before deconvolution.']::text[],ARRAY['Measuring room impulse responses.','Capturing convolution-reverb signatures.','Testing loudspeaker response and distortion together.']::text[],'advanced','f(t) = f1 * (f2/f1)^(t/T)','In an exponential sweep the instantaneous frequency rises from the start frequency to the end frequency as a fixed ratio raised to the fraction of elapsed time.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sine-sweep measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '795d22f1-6c91-4651-8abf-a022f7e3e7fb','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='795d22f1-6c91-4651-8abf-a022f7e3e7fb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='795d22f1-6c91-4651-8abf-a022f7e3e7fb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '42478c26-cee3-4d6f-9cf3-e812de8c2651','Sound exposure level','Sound exposure level (SEL) is the constant sound pressure level that, if held for a reference time of one second, would deliver the same frequency-weighted sound energy as an actual, time-varying noise event. It equals ten times the base-ten logarithm of the time-integrated squared sound pressure divided by the product of the one-second reference time and the squared reference pressure.','A noise event, like a passing truck, changes over time. Sound exposure level squeezes all its energy into one second. It reports the level that one second would need to hold the same energy. This lets you compare short and long events fairly. It is measured in decibels.','SEL provides a single-number, duration-independent measure of the total energy in a noise event, so events of different lengths can be compared and combined for exposure assessment.','A pass-by lasting 4 s at a steady 85 dB(A) has SEL about 85 + 10*log10(4) = 91 dB, since its energy equals roughly 4 seconds at that level.','Noise metric',ARRAY['Equivalent continuous level (Leq)','A-weighting','Noise dose','Sound pressure level','Reference pressure']::text[],ARRAY['UNSAFE: Assuming a low SEL for one event means hearing is safe; cumulative daily exposure and high peak levels can still cause permanent hearing loss and must be limited to protect the ear.','Confusing SEL (normalized to one second) with Leq (averaged over the actual measurement time).','Comparing SEL values that were measured with different frequency weightings.']::text[],ARRAY['Rating aircraft or vehicle pass-by noise.','Assessing the energy of an impulsive event.','Summing multiple events into a daily exposure.']::text[],'intermediate','L_E = 10*log10[ (1/T0) * integral( p^2(t)/p0^2 dt ) ] ,  T0 = 1 s, p0 = 20 uPa','Sound exposure level is ten times the log of the time integral of squared sound pressure, referenced to one second and to the squared reference pressure.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound exposure level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '42478c26-cee3-4d6f-9cf3-e812de8c2651','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='42478c26-cee3-4d6f-9cf3-e812de8c2651') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='42478c26-cee3-4d6f-9cf3-e812de8c2651');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '44f7238f-261f-454f-bd57-3e9623fe2711','Spectral tilt','Spectral tilt is the overall slope of a signal''s magnitude spectrum, describing how energy is distributed from low to high frequencies and usually expressed in decibels per octave. In speech and audio, a steeper downward tilt indicates relatively less high-frequency energy, and the tilt changes with vocal effort, source type, and filtering.','Spectral tilt describes whether a sound leans toward low or high frequencies. It is the slope of the spectrum. A strong downward slope means the sound is dull, with weak highs. A flatter slope means brighter sound. Voices change their tilt with effort.','It gives a compact description of timbral balance, useful for characterizing voices, tracking vocal effort, and matching tonal balance.','Matching two vocal takes, an engineer measures a -9 dB/octave tilt on one and -6 dB/octave on the other, then adds a gentle high shelf to align them.','Signal descriptor',ARRAY['Spectral centroid','Spectral slope','Timbre','Vocal effort','Shelving filter']::text[],ARRAY['Confusing spectral tilt (a slope) with spectral centroid (a center of mass).','Measuring tilt over too narrow a band to represent the whole spectrum.','Assuming tilt is fixed for a source; it varies with level and effort.']::text[],ARRAY['Analyzing vocal effort or emotion.','Matching tonal balance between recordings.','Characterizing microphone or codec coloration.']::text[],'intermediate','tilt = Delta_L / Delta( log2(f) )   (dB per octave)','Spectral tilt is the change in level in decibels divided by the change in frequency measured in octaves, giving a slope in decibels per octave.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral tilt');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '44f7238f-261f-454f-bd57-3e9623fe2711','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='44f7238f-261f-454f-bd57-3e9623fe2711') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='44f7238f-261f-454f-bd57-3e9623fe2711');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'df0dacc6-dfeb-4e67-81f4-65cb34fc98c8','Stationary noise assumption','The stationary noise assumption treats a noise signal as (wide-sense) stationary, meaning its statistical properties—chiefly its mean and autocorrelation, and hence its power spectral density—do not change over the analysis interval. Many noise-reduction and spectral-estimation methods rely on this assumption to estimate and subtract a stable noise spectrum.','Many tools assume the background noise stays the same over time. Its average and its spectrum are treated as fixed. This is the stationary noise assumption. It lets a system learn the noise once and remove it. Real noise that changes breaks the assumption.','It simplifies estimating a noise profile so it can be subtracted, underlying classic spectral-subtraction denoisers and noise-floor estimators.','A denoiser samples a silent gap to learn the noise spectrum, assumes it is stationary, then subtracts that estimate from the whole recording.','Signal processing',ARRAY['Wide-sense stationarity','Power spectral density','Spectral subtraction','Autocorrelation','Noise floor']::text[],ARRAY['Applying stationary-noise methods to non-stationary noise like babble or music, causing artifacts.','Confusing stationarity of the noise with stationarity of the whole signal.','Assuming a single noise estimate stays valid as conditions change.']::text[],ARRAY['Designing a spectral-subtraction denoiser.','Estimating a recording''s noise floor.','Deciding whether adaptive noise tracking is needed.']::text[],'advanced','E[x(t)] = constant  and  R_x(t1,t2) = R_x(t1 - t2)','For wide-sense stationarity the mean is constant in time and the autocorrelation depends only on the time difference, not on absolute time.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Stationary noise assumption');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'df0dacc6-dfeb-4e67-81f4-65cb34fc98c8','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='df0dacc6-dfeb-4e67-81f4-65cb34fc98c8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='df0dacc6-dfeb-4e67-81f4-65cb34fc98c8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eec4b1d8-85fd-454e-be26-c651fdf97e62','Stereo width control','A stereo width control adjusts the perceived spread of a stereo image between mono (fully narrow) and enhanced width by changing the relative levels of the mid (sum, L+R) and side (difference, L-R) components. Increasing the side level widens the image; reducing it toward zero collapses the signal to mono.','A stereo width control makes a mix sound wider or narrower. It works on the mid and side parts of the signal. The mid is what both speakers share. The side is the difference between them. Turning up the side widens the image; turning it down moves toward mono.','It lets an engineer set how broad a stereo image sounds and check mono compatibility, using mid-side balance rather than simple panning.','Encoding to mid-side, an engineer raises the side gain by 3 dB to widen a synth pad, then checks in mono that nothing cancels.','Spatial audio',ARRAY['Mid-side processing','Mono compatibility','Stereo image','Panning','Phase cancellation']::text[],ARRAY['Widening so far that the mix loses mono compatibility and cancels in a fold-down.','Confusing width control with panning; width changes spread, panning changes position.','Assuming more width is always better; excessive side content thins the center.']::text[],ARRAY['Widening or narrowing a stereo bus.','Checking a master''s mono fold-down.','Controlling image on individual tracks.']::text[],'intermediate','M = (L+R)/2 , S = (L-R)/2 ;  L'' = M + w*S , R'' = M - w*S','The mid is half the sum and the side is half the difference of the channels; scaling the side by a width factor before recombining sets the stereo spread.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Stereo width control');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eec4b1d8-85fd-454e-be26-c651fdf97e62','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eec4b1d8-85fd-454e-be26-c651fdf97e62') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eec4b1d8-85fd-454e-be26-c651fdf97e62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5e57746a-f1aa-458f-8c10-3ca2771fe9e0','Syllabic compression','A form of automatic gain control with a fast attack (a few to tens of milliseconds) and a syllable-scale release (roughly 50 to 200 milliseconds), so gain tracks the short-term envelope of speech rather than its long-term average level. It is widely applied in hearing aids and communications compressors to raise soft speech sounds relative to loud ones.','Speech has loud and soft parts within each word. Syllabic compression lifts the quiet parts and eases the loud parts. It reacts fast enough to follow single syllables. Hearing aids use it so soft sounds stay audible.','To improve audibility and comfort by reducing the level gap between loud and soft speech sounds within running speech.','A hearing-aid fitter sets attack near 5 ms and release near 100 ms so a 3:1 ratio lifts a weak consonant without pumping on vowels.','Dynamics Processing',ARRAY['Automatic gain control','Wide dynamic range compression','Attack time','Release time','Compression ratio']::text[],ARRAY['Confusing syllabic (fast) compression with slow automatic volume control that tracks only long-term level.','Assuming faster is always better; very short release times cause audible pumping and distortion.','Thinking compression restores lost frequencies; it only reshapes level over time.']::text[],ARRAY['Fitting a hearing aid to keep quiet consonants audible.','Setting a broadcast voice compressor for consistent loudness.','Explaining pumping artifacts caused by too-short release times.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Syllabic compression');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5e57746a-f1aa-458f-8c10-3ca2771fe9e0','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5e57746a-f1aa-458f-8c10-3ca2771fe9e0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5e57746a-f1aa-458f-8c10-3ca2771fe9e0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '80171c81-ea0f-457f-8869-8203db18f2ed','Time-scale modification','A digital-audio process that changes a signal''s duration (playback speed) while preserving its pitch and spectral envelope, using time-domain methods such as SOLA/WSOLA or frequency-domain phase-vocoder methods. It decouples the timeline from the pitch axis, unlike simple resampling.','Sometimes you want audio to play slower or faster. Time-scale modification changes the length without changing the pitch. Voices stay natural instead of sounding low or high. Editing and transcription tools use it.','To stretch or compress the time axis of audio without the pitch shift that an ordinary speed change would cause.','To fit a 62 s voiceover into a 60 s slot, an editor applies a 0.968 time-scale factor with WSOLA so the pitch is unchanged.','Time-Domain Processing',ARRAY['Weighted overlap-add','Phase vocoder','Pitch shifting','Resampling','Vocoder analysis']::text[],ARRAY['Confusing time-scale modification with resampling, which changes pitch and duration together.','Assuming extreme stretch stays artifact-free; large factors add echo or transient smearing.','Believing it can perfectly separate every overlapping sound.']::text[],ARRAY['Fitting narration to a fixed video duration.','Slowing a solo for practice without dropping its pitch.','Explaining phasiness artifacts in a phase vocoder.']::text[],'advanced','alpha = T_out / T_in','The time-scale factor equals output duration divided by input duration, while the pitch is held constant.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Time-scale modification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '80171c81-ea0f-457f-8869-8203db18f2ed','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='80171c81-ea0f-457f-8869-8203db18f2ed') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='80171c81-ea0f-457f-8869-8203db18f2ed');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '872ce822-9265-4c35-b38d-267e584cec45','Tone-to-noise ratio','In prominent-tone analysis, the level difference in decibels between the power of a discrete tone and the power of the masking noise in the critical band centered on that tone, used to judge whether the tone is subjectively prominent. Procedures are standardized in ECMA-74/ECMA-418, ISO 7779, and ANSI/ASA S1.13.','A steady tone in noise can stand out and annoy listeners. Tone-to-noise ratio compares the tone''s power to nearby noise. A higher value means the tone is easier to hear. Engineers use it to judge product sound quality.','To quantify how far a discrete tone rises above the surrounding noise so annoyance from prominent tones can be assessed.','If a fan tone holds a power level of 60 dB and the critical-band noise is 50 dB, TNR = 10*log10(10^6.0/10^5.0) = 10 dB, exceeding the 8 dB prominence threshold above 1 kHz.','Sound Quality Metric',ARRAY['Prominence ratio','Critical band','Total harmonic distortion plus noise','Signal-to-noise ratio','Masking']::text[],ARRAY['Confusing tone-to-noise ratio with prominence ratio; they use different noise references.','Forgetting that the prominence threshold depends on frequency below 1 kHz.','Treating a high overall signal-to-noise ratio as proof that no single tone is prominent.']::text[],ARRAY['Assessing whistle tones from a computer cooling fan.','Documenting HVAC tonal noise against a spec limit.','Deciding whether a transformer hum counts as prominent.']::text[],'advanced','TNR = 10*log10( P_t / P_n )','The tone-to-noise ratio in decibels is ten times the base-ten logarithm of the tone power divided by the critical-band noise power.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tone-to-noise ratio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '872ce822-9265-4c35-b38d-267e584cec45','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='872ce822-9265-4c35-b38d-267e584cec45') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='872ce822-9265-4c35-b38d-267e584cec45');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd1c270e8-0690-4d6d-953f-e1e30d699f88','Total harmonic distortion plus noise','A measure of signal purity equal to the ratio of the RMS value of all unwanted output components (harmonic distortion products plus noise) left after the fundamental is removed by a notch filter, to the RMS value of the total output signal, within a defined bandwidth. It is specified in IEC 60268-3 and AES17.','A perfect amplifier would output only the signal you feed it. THD+N measures everything extra it adds. That covers distortion and background noise together. A lower number, in percent or decibels, means cleaner sound.','To give a single figure for how much distortion and noise a device adds to a test signal.','If a 1 kHz tone reads 1 V RMS and the notch-filtered residue is 1 mV RMS over a 20 kHz band, THD+N = 0.001/1 = 0.1% (about -60 dB).','Distortion Metric',ARRAY['Total harmonic distortion','Signal-to-noise ratio','Notch filter','Tone-to-noise ratio','Noise floor']::text[],ARRAY['Confusing THD with THD+N; THD+N also includes noise, so it is usually higher.','Ignoring the measurement bandwidth, which strongly affects the noise contribution.','Comparing figures taken at different levels or frequencies as if they were equal.']::text[],ARRAY['Reading an audio interface datasheet.','Bench-testing a power amplifier for distortion.','Comparing two DACs at matched output levels.']::text[],'intermediate','THD+N = V_residue / V_total = sqrt( sum(V_h^2) + V_n^2 ) / V_total','THD+N is the root-mean-square of all harmonic and noise components, divided by the total signal RMS, after the fundamental is removed with a notch filter.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Total harmonic distortion plus noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd1c270e8-0690-4d6d-953f-e1e30d699f88','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d1c270e8-0690-4d6d-953f-e1e30d699f88') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d1c270e8-0690-4d6d-953f-e1e30d699f88');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9b9d744f-6480-41ac-8f36-94af5ba97476','Transient detection','A signal-processing task that locates brief, sudden changes in a signal''s energy or spectrum - onsets such as drum hits or note attacks - usually by building a detection function from the amplitude envelope, spectral flux, or high-frequency content and picking peaks above an adaptive threshold. It underlies onset detection, transient shaping, and time-scale and coding tools.','Music has sudden bursts like a drum hit or a plucked string. Transient detection finds those quick, sharp moments. Software watches for fast jumps in energy or spectrum. Editors and effects use these markers.','To flag the exact moments of sudden onsets so tools can slice, shape, or protect those events.','A beat-slicing tool computes spectral flux, then marks an onset wherever the flux jumps past an adaptive threshold, letting the user quantize each hit.','Signal Analysis',ARRAY['Zero-crossing rate','Onset detection','Spectral flux','Time-scale modification','Envelope follower']::text[],ARRAY['Assuming one fixed threshold fits every track; levels vary, so thresholds must adapt.','Confusing transient detection with pitch detection; they answer different questions.','Expecting clean results on legato material with soft, gradual onsets.']::text[],ARRAY['Slicing a drum loop into individual hits.','Driving a transient shaper to sharpen attacks.','Aligning multi-mic drum tracks by onset.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transient detection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9b9d744f-6480-41ac-8f36-94af5ba97476','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9b9d744f-6480-41ac-8f36-94af5ba97476') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9b9d744f-6480-41ac-8f36-94af5ba97476');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1374be3b-c804-40ee-ac5f-e8143e72ac46','Two-alternative forced choice','A psychophysical test procedure in which a listener must choose which of two presented intervals or options contains the target stimulus, with no ''can''t tell'' response permitted, so that guessing yields 50% correct and true detection raises the score above chance. It is a bias-reducing method used in signal-detection experiments and codec or equipment listening tests.','In a listening test you might not be sure what you heard. This method gives two options and makes you pick one. Guessing alone would score about half right. Scoring higher shows you really heard the difference.','To measure a listener''s sensitivity to a difference while limiting the effect of personal response bias.','To check whether a codec artifact is audible, a tester runs 100 two-interval trials; 75 correct sits well above the 50% chance line, indicating real audibility.','Listening Test Method',ARRAY['ABX test','Signal detection theory','Just-noticeable difference','Psychoacoustics','Threshold of audibility']::text[],ARRAY['Thinking 50% correct proves audibility; that is exactly chance for two choices.','Allowing a third ''no difference'' answer, which breaks the forced-choice design.','Running too few trials to separate skill from luck.']::text[],ARRAY['Validating whether a lossy codec is transparent.','Measuring a listener''s smallest detectable level change.','Comparing two microphones under controlled conditions.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Two-alternative forced choice');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1374be3b-c804-40ee-ac5f-e8143e72ac46','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1374be3b-c804-40ee-ac5f-e8143e72ac46') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1374be3b-c804-40ee-ac5f-e8143e72ac46');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f45644a0-7df0-4827-9c01-0049e2856e31','Virtual bass','A psychoacoustic bass-enhancement technique that creates the impression of low fundamentals a small loudspeaker cannot reproduce by synthesizing or emphasizing their higher harmonics, exploiting the missing-fundamental (residue-pitch) effect so the ear infers the absent low tone. Implementations use nonlinear harmonic generators or phase-vocoder synthesis.','Small speakers cannot move enough air for deep bass. Virtual bass adds the harmonics of those low notes instead. Your brain fills in the missing low pitch. The sound seems to have more bass than the speaker can make.','To give small or band-limited loudspeakers a perceived sense of deep bass without reproducing the actual low frequencies.','On a laptop speaker rolling off below 200 Hz, a virtual-bass block generates harmonics of an 80 Hz kick so listeners still perceive its pitch.','Psychoacoustic Enhancement',ARRAY['Missing fundamental','Residue pitch','Harmonic generation','Wavelength constant','Psychoacoustics']::text[],ARRAY['Believing it adds real low-frequency output; it only adds harmonics that the ear interprets.','Overusing it, which makes bass sound thin, harsh, or buzzy.','Confusing it with an equalizer boost of actual low frequencies.']::text[],ARRAY['Tuning bass on a phone or laptop speaker.','Adding low-end feel to a soundbar without a subwoofer.','Explaining why earbuds seem to have deep bass.']::text[],'intermediate',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Virtual bass');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f45644a0-7df0-4827-9c01-0049e2856e31','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f45644a0-7df0-4827-9c01-0049e2856e31') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f45644a0-7df0-4827-9c01-0049e2856e31');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '55dcc162-e661-48c8-af49-effbbfa4dd91','Vocoder analysis','The analysis stage of a vocoder (voice coder), in which speech is decomposed into a slowly varying description - typically the short-time energy in a bank of frequency bands plus voicing and pitch information - so it can be transmitted or resynthesized at low data rate. It originates with Dudley''s channel vocoder and underlies channel, phase, and LPC vocoders.','A vocoder splits speech into simple control signals. The analysis part measures how much energy sits in each frequency band. It also tracks pitch and whether sound is voiced. These few numbers can rebuild or transform the voice.','To reduce speech to a compact set of band-energy and pitch parameters for efficient coding or creative resynthesis.','A musician routes vocals into a 16-band vocoder''s analysis section; each band''s envelope then controls the matching band of a synth carrier.','Speech Processing',ARRAY['Vocoder','Whisper-mode processing','Linear predictive coding','Zero-crossing rate','Formant']::text[],ARRAY['Confusing the analysis stage with the synthesis stage that rebuilds the sound.','Assuming a vocoder records the voice; it stores only band and pitch parameters.','Mixing up the musical carrier-based vocoder with speech-coding vocoders.']::text[],ARRAY['Setting up a classic robot-voice vocoder effect.','Explaining low-bit-rate speech coding.','Comparing channel, phase, and LPC vocoders.']::text[],'advanced',NULL,NULL,'dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vocoder analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '55dcc162-e661-48c8-af49-effbbfa4dd91','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='55dcc162-e661-48c8-af49-effbbfa4dd91') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='55dcc162-e661-48c8-af49-effbbfa4dd91');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd40eee97-dfa5-4096-ae88-2dc318f0896a','Wavelength constant','The fixed relationship, for a given medium and temperature, between a sound''s wavelength and its frequency: their product equals the constant speed of sound, so wavelength is the wave speed divided by frequency. Because wave speed is essentially constant in a medium, wavelength and frequency are inversely proportional. The quantity wavelength is defined in ISO 80000-8.','Sound travels at a fixed speed in air. That speed equals wavelength times frequency. So high notes have short waves and low notes have long waves. Knowing two of these lets you find the third.','To relate a sound''s physical size (its wavelength) to its frequency using the constant speed of sound in a medium.','In 20 degrees C air (c is about 343 m/s), a 100 Hz tone has wavelength lambda = 343/100 = 3.43 m, guiding bass-trap and room-mode calculations.','Acoustic Relationship',ARRAY['Wavelength','Speed of sound','Frequency','Virtual bass','Room modes']::text[],ARRAY['Assuming the speed of sound is the same in every medium; it changes with material and temperature.','Thinking wavelength depends only on frequency, forgetting the medium''s wave speed.','Mixing meters and feet, or using the speed of light by mistake.']::text[],ARRAY['Sizing an acoustic absorber for a target frequency.','Predicting room modes from room dimensions.','Explaining why bass needs large speakers or space.']::text[],'beginner','lambda = c / f   (equivalently c = lambda * f, constant in a medium)','Wavelength equals the speed of sound divided by frequency; the product of wavelength and frequency stays constant in a given medium.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wavelength constant');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd40eee97-dfa5-4096-ae88-2dc318f0896a','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d40eee97-dfa5-4096-ae88-2dc318f0896a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d40eee97-dfa5-4096-ae88-2dc318f0896a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c03ed832-6b2c-468e-941a-c5d10a005adb','Weighted overlap-add','A short-time Fourier processing method in which a signal is split into overlapping blocks, each windowed (weighted) before and after spectral processing, and the modified blocks are summed so the analysis and synthesis windows overlap-add to a constant, avoiding block-edge discontinuities. It is the standard framework for filter banks, phase vocoders, and time-scale modification.','Long audio is processed in short overlapping chunks. Each chunk is shaped by a smooth window before and after processing. The chunks are then added back together. The smooth overlap hides the joins between blocks.','To process audio block by block in the frequency domain while suppressing the clicks and gaps that hard block boundaries would create.','A phase vocoder uses 1024-sample blocks with 75% overlap and a Hann window so the overlapping synthesis frames sum to a constant, giving click-free output.','Signal Processing Framework',ARRAY['Overlap-add','Time-scale modification','Phase vocoder','Window function','Short-time Fourier transform']::text[],ARRAY['Choosing a window and hop that do not overlap-add to a constant, causing amplitude ripple.','Confusing weighted overlap-add with plain overlap-add convolution.','Assuming any overlap works; too little overlap reintroduces edge artifacts.']::text[],ARRAY['Building a phase-vocoder time-stretch tool.','Implementing an analysis-synthesis filter bank.','Debugging periodic amplitude ripple in framed processing.']::text[],'advanced','sum_m w[n - m*H] = C  (constant for all n)','For artifact-free reconstruction, the overlapping windows shifted by the hop size must sum to a constant at every sample.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Weighted overlap-add');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c03ed832-6b2c-468e-941a-c5d10a005adb','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c03ed832-6b2c-468e-941a-c5d10a005adb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c03ed832-6b2c-468e-941a-c5d10a005adb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '77e47fc5-bd25-4113-9ff4-3a26b8b44a6a','Wet/dry mix ratio','In an audio effect, the proportion of processed (''wet'') signal blended with unprocessed (''dry'') signal at the output, usually set as a percentage or a mix control from fully dry to fully wet. It governs effect depth without changing the effect''s internal parameters.','An effect makes a processed version of your sound. The wet/dry control decides how much of each you hear. Zero percent is the original only. One hundred percent is the effect only.','To control how strongly an effect is heard by balancing processed and unprocessed signal at the output.','On a reverb insert, setting 30% wet means the output is 0.30 of the reverb plus 0.70 of the dry vocal, keeping the words clear.','Effects Control',ARRAY['Dry signal','Wet signal','Send and return','Parallel processing','Reverberation']::text[],ARRAY['Running an insert reverb at 100% wet when parallel blending was intended.','Assuming an aux/send path needs any dry signal; the channel already carries it.','Confusing wet/dry balance with the effect''s own depth or feedback controls.']::text[],ARRAY['Dialing reverb amount on a vocal insert.','Setting up parallel (New York) compression.','Balancing a delay so it supports, not buries, the source.']::text[],'beginner','y = (1 - m)*x_dry + m*x_wet,   0 <= m <= 1','The output is the dry signal scaled by one minus the mix, plus the wet signal scaled by the mix fraction.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wet/dry mix ratio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '77e47fc5-bd25-4113-9ff4-3a26b8b44a6a','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='77e47fc5-bd25-4113-9ff4-3a26b8b44a6a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='77e47fc5-bd25-4113-9ff4-3a26b8b44a6a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '112c26cc-a7d8-4036-8a38-d02a4b67744e','Zero-crossing rate','The rate at which a signal changes sign (crosses zero) within a short analysis frame, usually expressed as sign changes per frame or per second. It gives a low-cost time-domain estimate of dominant frequency and noisiness and helps separate voiced (low rate) from unvoiced (high rate) speech.','A waveform swings above and below zero. Zero-crossing rate counts how often it crosses the zero line. Noisy or high sounds cross more often. It is a fast, simple way to judge a signal.','To provide a very low-cost measure of a signal''s frequency content and noisiness for tasks such as voiced/unvoiced detection.','For a 1000-sample frame at 16 kHz with 200 sign changes, ZCR = 200/1000 = 0.2 per sample; per second that is 3200 crossings, estimating a dominant frequency near 1600 Hz.','Signal Feature',ARRAY['Transient detection','Vocoder analysis','Whisper-mode processing','Short-time energy','Pitch detection']::text[],ARRAY['Reading zero-crossing rate as an exact pitch; it only estimates dominant frequency.','Ignoring that noise and DC offset inflate the count.','Applying it to complex music as if it gave one clear frequency.']::text[],ARRAY['Classifying speech frames as voiced or unvoiced.','Cheaply flagging noisy or high-frequency segments.','Aiding onset or transient detection.']::text[],'intermediate','ZCR = (1/(2N)) * sum_{n=1}^{N-1} | sgn(x[n]) - sgn(x[n-1]) |','The zero-crossing rate is half the average number of times consecutive samples change sign across the frame.','dcb43055-f0ff-4cda-a20f-72e893b14041' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Zero-crossing rate');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '112c26cc-a7d8-4036-8a38-d02a4b67744e','dcb43055-f0ff-4cda-a20f-72e893b14041',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='112c26cc-a7d8-4036-8a38-d02a4b67744e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='112c26cc-a7d8-4036-8a38-d02a4b67744e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4f4d9e65-a69f-4f42-bc8a-b35a0d11f42b','ADM Lookup Chunk','In a BW64/RF64 WAV file, the ADM lookup chunk (the ''chna'' chunk defined in ITU-R BS.2088) is a table that maps each audio track in the file to the Audio Definition Model (ITU-R BS.2076) element identifiers (such as audioTrackUID, audioTrackFormat and audioPackFormat) describing it. It lets a renderer link the raw interleaved tracks to the XML metadata carried in the separate ''axml'' chunk without parsing the entire model.','A BW64 audio file can hold many sound tracks plus metadata. The lookup chunk is a small table inside the file. It links each track number to the labels that describe that sound. A player reads it to know which track is which.','It provides a quick index so a decoder can connect each recorded track to its ADM description of format and position.','Delivering an object-based master, an engineer checks the chna table lists one audioTrackUID per used track so the renderer routes audio correctly.','File Format / Metadata',ARRAY['Absolute object position','Administrative audio metadata','Arbitrary downmix gain','Ambisonics Channel Numbering','Accessibility presentation']::text[],ARRAY['Confusing the chna lookup chunk with the axml chunk that holds the actual XML metadata.','Assuming every track slot needs an entry — unused slots may be left as null.','Thinking the chunk stores position data; it only stores the ID mapping.']::text[],ARRAY['Delivering an ADM BWF master for a Dolby Atmos or MPEG-H broadcast mix.','Debugging why a renderer cannot find metadata for a track.','Building a tool that validates BW64 files before airing.']::text[],'advanced',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='ADM Lookup Chunk');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4f4d9e65-a69f-4f42-bc8a-b35a0d11f42b','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4f4d9e65-a69f-4f42-bc8a-b35a0d11f42b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4f4d9e65-a69f-4f42-bc8a-b35a0d11f42b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0931b3c4-a2ad-4a19-b322-09f946e98c25','Abnormal Growth of Loudness','Abnormal growth of loudness, clinically called loudness recruitment, is a faster-than-normal rise in perceived loudness as sound level increases, characteristic of cochlear (sensorineural) hearing loss. A quiet tone may be inaudible, yet only a moderate increase in level is judged as loud as a normal-hearing listener would judge a much larger increase.','Some damaged ears hear soft sounds poorly but loud sounds almost normally. So loudness climbs very fast over a small range. A small volume rise can suddenly feel too loud. This is common with inner-ear hearing loss.','The concept explains why people with cochlear damage need careful level and dynamic-range control, and it guides hearing-aid compression design.','Setting levels for a listener with recruitment, a technician uses gentler dynamics and avoids sudden loud peaks that feel harsh.','Psychoacoustics / Hearing',ARRAY['Adaptive Psychophysical Method','Anchor loudness','Album loudness','Absolute Gating Threshold']::text[],ARRAY['Thinking recruitment means a more sensitive ear — soft sounds are actually harder to hear.','UNSAFE: Boosting overall gain to help a recruiting listener hear soft detail can push loud passages to painful, hazardous levels.','Confusing loudness recruitment with hyperacusis (reduced tolerance across all levels).']::text[],ARRAY['Fitting or tuning hearing-aid compression.','Explaining why a hearing-impaired listener finds a mix harsh.','Audiology threshold and loudness-balance testing.']::text[],'intermediate',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Abnormal Growth of Loudness');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0931b3c4-a2ad-4a19-b322-09f946e98c25','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0931b3c4-a2ad-4a19-b322-09f946e98c25') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0931b3c4-a2ad-4a19-b322-09f946e98c25');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ff874b4a-86c1-4828-af18-b9f57ebead90','Absolute Gating Threshold','In loudness measurement per ITU-R BS.1770, the absolute gating threshold is a fixed level of -70 LKFS below which 400 ms measurement blocks are excluded from the integrated loudness. It is applied before the relative (-10 LU) gate to remove long silences and very quiet passages from the measurement.','Loudness meters ignore very quiet moments so silence does not lower the reading. Any short block quieter than -70 LKFS is dropped first. Then a second, relative gate removes more quiet parts. What remains sets the program loudness.','It stops silence and near-silence from dragging down measured program loudness, giving a level closer to what listeners notice.','Measuring a film with long quiet scenes, blocks below -70 LKFS are discarded; for example a -55 LKFS dialogue block is kept while a -73 LKFS room-tone block is dropped.','Loudness Measurement',ARRAY['Anchor loudness','Album loudness','Abnormal Growth of Loudness','Arbitrary downmix gain']::text[],ARRAY['Confusing the fixed -70 LKFS absolute gate with the -10 LU relative gate.','Thinking the gate changes momentary or short-term readings — it only affects integrated loudness.','Assuming LKFS and LUFS differ; they are numerically identical units.']::text[],ARRAY['Metering a program to EBU R128 or ATSC A/85.','Explaining why silent gaps do not lower an integrated LUFS reading.','QC of a delivered file against a loudness target.']::text[],'advanced','l_j = -0.691 + 10*log10( sum_c G_c * z_{j,c} );  keep block j iff l_j > Gamma_a,  Gamma_a = -70 LKFS','Each 400 ms block gets a loudness value equal to -0.691 plus ten times the base-ten log of the channel-weighted mean-square K-weighted power. A block is counted only when that value is greater than the absolute gate of -70 LKFS.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Absolute Gating Threshold');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ff874b4a-86c1-4828-af18-b9f57ebead90','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ff874b4a-86c1-4828-af18-b9f57ebead90') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ff874b4a-86c1-4828-af18-b9f57ebead90');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2e949c7e-74a7-4dfd-b37f-3daea1a8f1d4','Absolute object position','In object-based audio, an absolute object position specifies a sound object''s location in fixed, scene- or room-referenced (allocentric) coordinates, rather than relative to the listener or to another object. In the Audio Definition Model (ITU-R BS.2076) object positions are given in a normalized polar (azimuth, elevation, distance) or Cartesian coordinate system tied to the reproduction space.','An audio object is a sound plus data saying where it should be. An absolute position fixes that spot in the room itself. It does not move when the listener turns. The renderer places the sound at that fixed point.','It lets a mix define where a sound sits in space independently of the playback speaker layout, so any system can render it consistently.','Placing a helicopter at a fixed overhead point, the renderer maps that absolute coordinate to whatever speakers or headphones are present.','Object Audio',ARRAY['Actual loudspeaker position','Arbitrary downmix gain','ADM Lookup Chunk','Ambisonics Channel Numbering','Accessibility presentation']::text[],ARRAY['Confusing absolute (allocentric) with listener-relative (egocentric) positioning.','Assuming coordinates are in metres — ADM object positions are normalized to the room boundary.','Thinking an object maps to one speaker; it is rendered by panning across many.']::text[],ARRAY['Authoring a Dolby Atmos or MPEG-H object mix.','Converting a channel bed to objects with fixed positions.','Rendering the same master to 7.1.4 and to binaural headphones.']::text[],'intermediate',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Absolute object position');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2e949c7e-74a7-4dfd-b37f-3daea1a8f1d4','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2e949c7e-74a7-4dfd-b37f-3daea1a8f1d4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2e949c7e-74a7-4dfd-b37f-3daea1a8f1d4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2917d7f9-cf27-414a-99e4-c95c8c7ccf7d','Accessibility presentation','An accessibility presentation is a selectable audio preset built for users with specific needs, for example a version with enhanced or spoken dialogue, audio description for blind and partially sighted users, or a dialogue-boosted mix for the hard of hearing. In next-generation audio systems (ADM, ITU-R BS.2076; MPEG-H 3D Audio, ISO/IEC 23008-3; ATSC A/342) it is signaled as one of several presentations the user can select.','One broadcast can carry several sound versions. An accessibility version helps people with sight or hearing needs. It may add spoken description of the picture or louder speech. The viewer picks it from a menu.','It lets a single delivery serve viewers who need audio description or clearer dialogue, meeting accessibility rules without a wholly separate service.','A broadcaster tags an audio-description mix as an accessibility presentation so viewers can enable it on the receiver.','Immersive Delivery',ARRAY['Alternate-language presentation','Administrative audio metadata','Arbitrary downmix gain','ADM Lookup Chunk','Absolute object position']::text[],ARRAY['Confusing an accessibility presentation with a separate legacy audio-description track.','Thinking it is only closed captions; it is an audio mix, not text.','Assuming all receivers expose every presentation identically.']::text[],ARRAY['Preparing next-gen TV audio (ATSC 3.0) with audio description.','Authoring MPEG-H presets for accessibility.','Meeting regulatory accessibility requirements for broadcast.']::text[],'intermediate',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Accessibility presentation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2917d7f9-cf27-414a-99e4-c95c8c7ccf7d','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2917d7f9-cf27-414a-99e4-c95c8c7ccf7d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2917d7f9-cf27-414a-99e4-c95c8c7ccf7d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e4debd86-bf18-4005-a5c9-851a2fae7957','Acoustic admittance','Acoustic admittance is the reciprocal of acoustic impedance: the complex ratio of acoustic volume velocity to sound pressure at a surface or in a system. Its real part is acoustic conductance and its imaginary part acoustic susceptance; the SI unit is cubic metres per pascal-second (m^3 Pa^-1 s^-1).','Impedance says how much a system resists sound flow. Admittance is the opposite: how easily sound flows. It has a size and a phase. Engineers and audiologists use it to describe how sound moves through a path.','It quantifies how readily an acoustic system accepts volume flow, useful in horn, duct, and middle-ear (tympanometry) analysis.','In tympanometry a probe measures middle-ear admittance versus ear-canal pressure to find the point of peak mobility.','Acoustics',ARRAY['Actual loudspeaker position','Adaptive Psychophysical Method','Abnormal Growth of Loudness']::text[],ARRAY['Confusing acoustic admittance with electrical admittance — the physical quantities differ.','Forgetting it is complex (magnitude and phase), not just a magnitude.','Mixing up specific, acoustic, and mechanical impedance/admittance definitions.']::text[],ARRAY['Tympanometry and middle-ear immittance testing.','Modeling horn or duct loading on a driver.','Acoustic network analysis of a coupled cavity.']::text[],'advanced','Y_a = 1 / Z_a = G_a + j*B_a','Acoustic admittance equals one divided by acoustic impedance, expressed as a real conductance plus an imaginary susceptance.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic admittance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e4debd86-bf18-4005-a5c9-851a2fae7957','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e4debd86-bf18-4005-a5c9-851a2fae7957') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e4debd86-bf18-4005-a5c9-851a2fae7957');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e393e5bc-4ee5-45db-89f3-7e2225f25b8c','Acoustic-scene graph','An acoustic-scene graph is a hierarchical data structure that describes a virtual sound environment — sources, listener, geometry, materials and acoustic properties — as connected nodes for a renderer to traverse. In six-degrees-of-freedom systems such as MPEG-I Immersive Audio (ISO/IEC 23090-4) an equivalent scene description drives how sound is computed as the listener moves.','A scene graph is a tree of objects that describes a virtual world. An acoustic version lists sound sources, room shapes, and surfaces. A renderer walks the tree to compute what you hear. It updates as you move around.','It organizes the spatial and material data a renderer needs so immersive audio can be computed consistently for a moving listener.','A VR sound designer defines rooms, portals, and materials in a scene description that the renderer traverses to place reflections and reverb.','Immersive Rendering',ARRAY['Acoustic-scene navigation','Adjacent listener space','Absolute object position','Actual loudspeaker position']::text[],ARRAY['Confusing the audio scene graph with a visual (graphics) scene graph — they carry different node data.','Assuming it stores audio samples; it stores descriptive metadata and geometry.','Thinking a static channel mix needs one; scene graphs matter for 6DoF.']::text[],ARRAY['Authoring 6DoF audio for VR/AR.','Building an MPEG-I encoder input scene.','Simulating room acoustics for interactive media.']::text[],'advanced',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic-scene graph');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e393e5bc-4ee5-45db-89f3-7e2225f25b8c','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e393e5bc-4ee5-45db-89f3-7e2225f25b8c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e393e5bc-4ee5-45db-89f3-7e2225f25b8c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '31e103df-ebf7-456b-a162-0c2851fbddea','Acoustic-scene navigation','Acoustic-scene navigation is the real-time updating of a rendered sound field as a listener translates and rotates through a virtual acoustic scene (six degrees of freedom), so source directions, distances, occlusion and reverberation change correctly with position. It is a core capability of MPEG-I Immersive Audio (ISO/IEC 23090-4).','In virtual reality you can walk and turn freely. The sound must change as you move. A source gets louder as you approach it. Navigation keeps the audio matched to your position and facing.','It makes immersive audio believable by keeping sound cues consistent with a freely moving listener''s location and orientation.','As a VR user walks toward a virtual band, the renderer raises level, shifts direction, and adjusts reverb per the scene.','Immersive Rendering',ARRAY['Acoustic-scene graph','Adjacent listener space','Actual loudspeaker position','Absolute object position']::text[],ARRAY['Confusing 3DoF (head rotation only) with 6DoF (rotation plus translation) navigation.','Forgetting distance attenuation and occlusion must update, not just direction.','Assuming binaural head rotation alone gives full navigation.']::text[],ARRAY['Designing 6DoF VR/AR audio experiences.','Testing an MPEG-I renderer for smooth movement.','Walking through a virtual venue in a game engine.']::text[],'advanced',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic-scene navigation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '31e103df-ebf7-456b-a162-0c2851fbddea','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='31e103df-ebf7-456b-a162-0c2851fbddea') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='31e103df-ebf7-456b-a162-0c2851fbddea');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '77efa9dc-c5b1-413a-b60e-a4f942a99e3e','Action/Object Paradigm','The action/object paradigm is an ecological framework for describing everyday sounds by the physical event that produced them — an action (such as scraping, dropping or rolling) applied to an object or material (such as metal or wood) — rather than by abstract acoustic features. Introduced in ecological acoustics (Gaver, 1993), it underlies sound-event taxonomies used in machine listening and audio captioning.','People often name a sound by what caused it. We say ''a door slamming,'' not ''80 hertz thump.'' This idea pairs an action with an object. Machine listening systems use it to label sound events.','It gives a human-centred way to categorize and label sound events, guiding taxonomies for sound recognition and description.','Labeling a dataset, an annotator tags a clip as ''action = knock, object = wood door'' to train a sound-event classifier.','Sound Taxonomy / MIR',ARRAY['Acoustic-scene graph','Affinity matrix','Adversarial detection front end','Algorithmic audio']::text[],ARRAY['Treating it as a strict standard rather than a descriptive framework.','Confusing everyday listening (source events) with musical listening (pitch, timbre).','Assuming one clip maps to a single action/object pair — sounds can be layered.']::text[],ARRAY['Designing a sound-event ontology for tagging.','Foley and sound-design description.','Automatic audio captioning research.']::text[],'intermediate',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Action/Object Paradigm');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '77efa9dc-c5b1-413a-b60e-a4f942a99e3e','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='77efa9dc-c5b1-413a-b60e-a4f942a99e3e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='77efa9dc-c5b1-413a-b60e-a4f942a99e3e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bdb68606-9707-4a4d-9e10-3af130b38e94','Actual loudspeaker position','The actual loudspeaker position is the true measured location (azimuth, elevation, distance) of a physical speaker in a room, as opposed to the nominal or ideal position of a standard layout. Immersive renderers such as the ADM renderer (ITU-R BS.2127) use actual positions to correct panning gains and delays so imaging stays accurate on imperfect layouts.','Standard layouts assume speakers sit at exact angles. Real rooms rarely match. The actual position is where a speaker truly is. A good renderer measures it and adjusts levels and timing to fix the image.','Knowing real speaker positions lets a renderer compensate for room constraints so objects still image where intended.','During calibration the engineer enters or measures each speaker''s real angle and distance so the renderer applies correct gains and delays.','Immersive Rendering',ARRAY['Absolute object position','Acoustic-scene navigation','Arbitrary downmix gain','Ambisonics Channel Numbering']::text[],ARRAY['Assuming nominal layout angles equal the real ones.','Ignoring distance differences that require delay compensation.','Confusing speaker calibration with object position metadata.']::text[],ARRAY['Calibrating a 7.1.4 immersive room.','Configuring an ADM renderer for a non-ideal layout.','Home-theatre auto-setup measuring speaker positions.']::text[],'intermediate',NULL,NULL,'5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Actual loudspeaker position');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bdb68606-9707-4a4d-9e10-3af130b38e94','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bdb68606-9707-4a4d-9e10-3af130b38e94') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bdb68606-9707-4a4d-9e10-3af130b38e94');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cfc3799f-eb68-4baf-a357-622929c60acb','Adaptive Psychophysical Method','An adaptive psychophysical method places each trial''s stimulus level based on the listener''s previous responses, converging efficiently on a threshold or a chosen point of the psychometric function. Common forms include transformed up-down (staircase) procedures, PEST, and QUEST; a transformed up-down rule can target specific points such as the 70.7% correct level.','Hearing tests can save time by reacting to answers. If you hear the tone, the next one is softer. If you miss it, it gets louder. The level quickly homes in on your threshold.','It measures perceptual thresholds quickly and precisely by concentrating trials near the level of interest.','A 2-down/1-up staircase lowers level after two correct answers and raises it after one miss, converging near 70.7% correct.','Psychoacoustics / Testing',ARRAY['Abnormal Growth of Loudness','Anchor loudness','Acoustic admittance']::text[],ARRAY['Thinking every staircase targets 50% — transformed rules target other points.','Stopping too early before the staircase settles at its reversals.','Confusing adaptive methods with the fixed method of constant stimuli.']::text[],ARRAY['Measuring hearing or masking thresholds.','Calibrating just-noticeable-difference tests.','Efficient listening tests for codec quality.']::text[],'advanced','2-down/1-up converges at p where p^2 = 1/2, so p ~= 0.707','In a two-down, one-up staircase, level decreases only after two correct responses, so it converges at the level where the squared probability of a correct response equals one half — about 70.7 percent correct.','5529bc9d-4222-4e26-a10a-ccbe7a741d76' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Adaptive Psychophysical Method');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cfc3799f-eb68-4baf-a357-622929c60acb','5529bc9d-4222-4e26-a10a-ccbe7a741d76',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cfc3799f-eb68-4baf-a357-622929c60acb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cfc3799f-eb68-4baf-a357-622929c60acb');
